// ═══════════════════════════════════════════════════════════════════════════
// GP-XBOX-2（2026-09-28 裁决 §4）：RecoveryService 跨进程状态快照通道（只发布）。
// 背景：17:44 RecoveryService 只凭 HWND/WebView 探针失败，就把仍在执行
// `input-host-lifecycle-work`（PREPARE_TARGET persona=elite）的旧 PID 判死并
// TerminateProcess——旧 InputHost 管道被打断、FanHost 跟随退出（约 15 s 风扇中断）。
// 修复要求 native 用一个**独立于 WebView/UI 的轻线程**持续发布生命周期状态，
// RecoveryService 判死前必须先读快照（schema 见 recovery_service.cpp 同名结构，
// 两侧 static_assert 固定字节布局）。本通道：
//   · 命名只读映射 Local\YeManCC.RecoveryState.<pid>，seqlock 原子写；
//   · 带 pid + processStartKey（进程创建时间）防旧状态被新 PID 误读；
//   · **只发布**：不改变手柄帧路径、人格语义、HidHide 策略或 Fan 算法；
//     所有挂点只写本通道的原子/短字符串，不新增日志事件。
// ═══════════════════════════════════════════════════════════════════════════
static constexpr unsigned int kRecoveryStateMagic = 0x534D4359u;   // 'YMCS'
static constexpr unsigned int kRecoveryStateSchemaVersion = 1;
static constexpr DWORD kRecoveryStateHeartbeatMs = 1000;

enum RecoveryStateFanOwner : unsigned int {
    kRecoveryFanOwnerUnknown = 0,
    kRecoveryFanOwnerOwnedByCurrent = 1,
    kRecoveryFanOwnerHandoffPending = 2,
    kRecoveryFanOwnerReleased = 3,
};

// 字节布局 = 跨进程 ABI（recovery_service.cpp 以同值 static_assert 复核）。
struct RecoveryStateSnapshot {
    unsigned int       magic;
    unsigned int       schemaVersion;
    unsigned int       sequence;         // seqlock：写中为奇、稳定为偶
    unsigned int       pid;
    unsigned long long processStartKey;  // FILETIME 创建时间（100ns）
    unsigned long long lastNativeHeartbeat; // 发布时刻 GetTickCount64
    unsigned long long lifecycleStartedAt;  // 忙段起点（0=空闲）
    char               lifecyclePhase[32];
    char               lastHostCommand[32];
    char               persona[32];
    unsigned int       lifecycleBusy;
    unsigned int       fanOwnerState;
    unsigned int       exitIntent;
    unsigned int       reserved0;
};
static_assert(sizeof(RecoveryStateSnapshot) == 152, "GP-XBOX-2 cross-process snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, magic) == 0, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, schemaVersion) == 4, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, sequence) == 8, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, pid) == 12, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, processStartKey) == 16, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, lastNativeHeartbeat) == 24, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, lifecycleStartedAt) == 32, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, lifecyclePhase) == 40, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, lastHostCommand) == 72, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, persona) == 104, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, lifecycleBusy) == 136, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, fanOwnerState) == 140, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, exitIntent) == 144, "snapshot ABI");
static_assert(offsetof(RecoveryStateSnapshot, reserved0) == 148, "snapshot ABI");

static HANDLE g_recoveryStateMapping = nullptr;
static RecoveryStateSnapshot* g_recoveryStateView = nullptr;
static std::mutex g_recoveryStateMx;                        // 保护下方三个短字符串与忙段起点
static std::atomic<int> g_recoveryStateBusyDepth{0};        // 并发忙源计数（worker/start/stop）
static std::string g_recoveryStatePhase = "idle";
static std::string g_recoveryStateLastCommand;
static std::string g_recoveryStatePersona;
static unsigned long long g_recoveryStateBusyStartedAt = 0;
static std::atomic<bool> g_recoveryStateStop{false};
static HANDLE g_recoveryStateStopEvent = nullptr;
static std::thread g_recoveryStateThread;
static unsigned long long g_recoveryStateStartKey = 0;
static std::atomic<bool> g_recoveryStateExitIntent{false};
static std::atomic<bool> g_recoveryFanHandoffPending{false};
static std::atomic<bool> g_recoveryFanEverOwned{false};
static bool g_recoveryStateStarted = false;

static unsigned long long recoveryStateOwnProcessStartKey() {
    FILETIME creation{}, exitTime{}, kernel{}, user{};
    if (!GetProcessTimes(GetCurrentProcess(), &creation, &exitTime, &kernel, &user)) return 0;
    ULARGE_INTEGER value{};
    value.LowPart = creation.dwLowDateTime;
    value.HighPart = creation.dwHighDateTime;
    return value.QuadPart;
}

static void recoveryStateCopyText(char* dst, size_t cap, const std::string& value) {
    if (!dst || cap == 0) return;
    const size_t length = value.size() < cap - 1 ? value.size() : cap - 1;
    if (length) memcpy(dst, value.data(), length);
    dst[length] = '\0';
}

static void recoverySnapNoteCommand(const char* command) {
    if (!g_recoveryStateStarted || !command || !*command) return;
    std::lock_guard<std::mutex> lock(g_recoveryStateMx);
    g_recoveryStateLastCommand = command;
}

static void recoverySnapSetPersona(const std::string& persona) {
    if (!g_recoveryStateStarted) return;
    std::lock_guard<std::mutex> lock(g_recoveryStateMx);
    g_recoveryStatePersona = persona;
}

static void recoverySnapNotePhase(const std::string& phase) {
    if (!g_recoveryStateStarted) return;
    std::lock_guard<std::mutex> lock(g_recoveryStateMx);
    if (g_recoveryStateBusyDepth.load(std::memory_order_acquire) > 0)
        g_recoveryStatePhase = phase;
}

static void recoverySnapLifecycleEnter(const char* phase) {
    if (!g_recoveryStateStarted) return;
    g_recoveryStateBusyDepth.fetch_add(1, std::memory_order_acq_rel);
    std::lock_guard<std::mutex> lock(g_recoveryStateMx);
    if (g_recoveryStateBusyStartedAt == 0) g_recoveryStateBusyStartedAt = GetTickCount64();
    g_recoveryStatePhase = phase && *phase ? phase : "lifecycle";
}

static void recoverySnapLifecycleLeave() {
    if (!g_recoveryStateStarted) return;
    const int depth = g_recoveryStateBusyDepth.fetch_sub(1, std::memory_order_acq_rel) - 1;
    std::lock_guard<std::mutex> lock(g_recoveryStateMx);
    if (depth <= 0) {
        if (depth < 0) g_recoveryStateBusyDepth.store(0, std::memory_order_release);
        g_recoveryStateBusyStartedAt = 0;
        g_recoveryStatePhase = "idle";
    }
}

// RAII：覆盖函数所有 return 路径（含异常），保证深计数守恒。
struct RecoveryStateBusyGuard {
    explicit RecoveryStateBusyGuard(const char* phase) noexcept {
        try { recoverySnapLifecycleEnter(phase); } catch (...) { /* observation cannot abort control */ }
    }
    ~RecoveryStateBusyGuard() noexcept {
        try { recoverySnapLifecycleLeave(); } catch (...) { /* keep completion nonthrowing */ }
    }
    RecoveryStateBusyGuard(const RecoveryStateBusyGuard&) = delete;
    RecoveryStateBusyGuard& operator=(const RecoveryStateBusyGuard&) = delete;
};

static void recoverySnapSetExitIntent() {
    g_recoveryStateExitIntent.store(true, std::memory_order_release);
}

static void recoverySnapSetFanHandoffPending(bool pending) {
    if (pending) {
        g_recoveryFanHandoffPending.store(true, std::memory_order_release);
    } else {
        g_recoveryFanHandoffPending.store(false, std::memory_order_release);
        g_recoveryFanEverOwned.store(true, std::memory_order_release);   // 交接完成 ⇒ released
    }
}

static unsigned int recoveryStateFanOwnerValue() {
    if (g_recoveryFanHandoffPending.load(std::memory_order_acquire)) return kRecoveryFanOwnerHandoffPending;
    if (g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire)) return kRecoveryFanOwnerOwnedByCurrent;
    if (g_recoveryFanEverOwned.load(std::memory_order_acquire)) return kRecoveryFanOwnerReleased;
    return kRecoveryFanOwnerUnknown;
}

static void recoveryStatePublishOnce() {
    RecoveryStateSnapshot* view = g_recoveryStateView;
    if (!view) return;
    std::string phase, lastCommand, persona;
    unsigned long long busyStarted = 0;
    {
        std::lock_guard<std::mutex> lock(g_recoveryStateMx);
        phase = g_recoveryStatePhase;
        lastCommand = g_recoveryStateLastCommand;
        persona = g_recoveryStatePersona;
        busyStarted = g_recoveryStateBusyStartedAt;
    }
    const bool busy = g_recoveryStateBusyDepth.load(std::memory_order_acquire) > 0;
    volatile unsigned int* sequence = &view->sequence;
    const unsigned int startSequence = *sequence;
    *sequence = startSequence + 1;                       // 奇：写中
    std::atomic_thread_fence(std::memory_order_release);
    view->magic = kRecoveryStateMagic;
    view->schemaVersion = kRecoveryStateSchemaVersion;
    view->pid = GetCurrentProcessId();
    view->processStartKey = g_recoveryStateStartKey;
    view->lastNativeHeartbeat = GetTickCount64();
    view->lifecycleStartedAt = busy ? busyStarted : 0;
    recoveryStateCopyText(view->lifecyclePhase, sizeof(view->lifecyclePhase), phase);
    recoveryStateCopyText(view->lastHostCommand, sizeof(view->lastHostCommand), lastCommand);
    recoveryStateCopyText(view->persona, sizeof(view->persona), persona);
    view->lifecycleBusy = busy ? 1u : 0u;
    view->fanOwnerState = recoveryStateFanOwnerValue();
    view->exitIntent = g_recoveryStateExitIntent.load(std::memory_order_acquire) ? 1u : 0u;
    view->reserved0 = ymcc::encodeRecoveryUiPulse(
        g_recoveryUiDispatchPulse.load(std::memory_order_acquire));
    std::atomic_thread_fence(std::memory_order_release);
    *sequence = startSequence + 2;                       // 偶：稳定
}

static void recoveryStatePublisherThreadProc() {
    for (;;) {
        recoveryStatePublishOnce();
        if (g_recoveryStateStop.load(std::memory_order_acquire)) break;
        if (WaitForSingleObject(g_recoveryStateStopEvent, kRecoveryStateHeartbeatMs) == WAIT_OBJECT_0) break;
    }
}

static void recoveryStatePublisherStart() {
    if (g_recoveryStateStarted) return;
    const std::wstring name = L"Local\\YeManCC.RecoveryState." + std::to_wstring(GetCurrentProcessId());
    g_recoveryStateMapping = CreateFileMappingW(INVALID_HANDLE_VALUE, nullptr, PAGE_READWRITE, 0,
                                                sizeof(RecoveryStateSnapshot), name.c_str());
    if (!g_recoveryStateMapping) return;
    g_recoveryStateView = static_cast<RecoveryStateSnapshot*>(
        MapViewOfFile(g_recoveryStateMapping, FILE_MAP_ALL_ACCESS, 0, 0, sizeof(RecoveryStateSnapshot)));
    if (!g_recoveryStateView) {
        CloseHandle(g_recoveryStateMapping);
        g_recoveryStateMapping = nullptr;
        return;
    }
    memset(g_recoveryStateView, 0, sizeof(RecoveryStateSnapshot));
    g_recoveryStateStartKey = recoveryStateOwnProcessStartKey();
    g_recoveryStateStopEvent = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (!g_recoveryStateStopEvent) {
        UnmapViewOfFile(g_recoveryStateView);
        g_recoveryStateView = nullptr;
        CloseHandle(g_recoveryStateMapping);
        g_recoveryStateMapping = nullptr;
        return;
    }
    g_recoveryStateStop.store(false, std::memory_order_release);
    g_recoveryStateStarted = true;   // 先置位：发布点（臂/忙/命令）在启动后立即生效
    recoveryStatePublishOnce();
    g_recoveryStateThread = std::thread(recoveryStatePublisherThreadProc);
}

static void recoveryStatePublisherStop() {
    if (!g_recoveryStateStarted) return;
    g_recoveryStateStop.store(true, std::memory_order_release);
    if (g_recoveryStateStopEvent) SetEvent(g_recoveryStateStopEvent);
    bool joined = false;
    if (g_recoveryStateThread.joinable()) {
        const HANDLE threadHandle = reinterpret_cast<HANDLE>(g_recoveryStateThread.native_handle());
        if (threadHandle && WaitForSingleObject(threadHandle, 3000) == WAIT_OBJECT_0) {
            g_recoveryStateThread.join();
            joined = true;
        } else {
            // 退出专用路径：线程来不及收敛时交给进程回收，绝不在其仍可能写映射时解除映射。
            g_recoveryStateThread.detach();
        }
    } else {
        joined = true;
    }
    if (joined) {
        if (g_recoveryStateView) { UnmapViewOfFile(g_recoveryStateView); g_recoveryStateView = nullptr; }
        if (g_recoveryStateMapping) { CloseHandle(g_recoveryStateMapping); g_recoveryStateMapping = nullptr; }
    }
    if (g_recoveryStateStopEvent) { CloseHandle(g_recoveryStateStopEvent); g_recoveryStateStopEvent = nullptr; }
    g_recoveryStateStarted = false;
}

// A process exit cannot wait forever for a worker that is already inside an
// external API. The normal stop signal is always sent first. When the bounded
// wait expires, detach only while the whole application is terminating; the
// OS tears down that remaining worker with the process, and independent Host
// recovery remains alive outside this process.
static bool joinThreadBoundedForExit(std::thread& thread, DWORD timeoutMs, const char* name) {
    if (!thread.joinable()) return true;
    if (timeoutMs == INFINITE) {
        thread.join();
        return true;
    }
    const HANDLE handle = reinterpret_cast<HANDLE>(thread.native_handle());
    const DWORD wait = handle ? WaitForSingleObject(handle, timeoutMs) : WAIT_FAILED;
    if (wait == WAIT_OBJECT_0) {
        thread.join();
        return true;
    }
    traceLog("exit worker detached name=%s wait=%lu", name ? name : "unknown",
             static_cast<unsigned long>(wait));
    thread.detach();
    return false;
}

static const char* powerLifecycleName(PowerLifecycle state) {
    switch (state) {
    case PowerLifecycle::Ready: return "ready";
    case PowerLifecycle::Suspending: return "suspending";
    case PowerLifecycle::Suspended: return "suspended";
    case PowerLifecycle::Resuming: return "resuming";
    }
    return "ready";
}

static const char* sgSleepModeName(SgSleepMode mode) {
    switch (mode) {
    case SgSleepMode::S3: return "S0/S3";
    case SgSleepMode::S4: return "S4";
    default: return "unknown";
    }
}

static const char* sgRetryKindName(SgRetryKind kind) {
    switch (kind) {
    case SgRetryKind::EntryFailure: return "entry-failure";
    case SgRetryKind::UnexpectedWake: return "unexpected-wake";
    default: return "none";
    }
}

static std::string sgFormatFactFileTime(ULONGLONG value) {
    if (value == 0) return "not-recorded";
    FILETIME fileTime{};
    ULARGE_INTEGER raw{};
    raw.QuadPart = value;
    fileTime.dwLowDateTime = raw.LowPart;
    fileTime.dwHighDateTime = raw.HighPart;
    SYSTEMTIME utc{}, local{};
    if (!FileTimeToSystemTime(&fileTime, &utc) ||
        !SystemTimeToTzSpecificLocalTime(nullptr, &utc, &local))
        return "invalid";
    char text[40]{};
    std::snprintf(text, sizeof(text), "%04u-%02u-%02u %02u:%02u:%02u.%03u",
                  local.wYear, local.wMonth, local.wDay, local.wHour,
                  local.wMinute, local.wSecond, local.wMilliseconds);
    return text;
}

// Telemetry contracts use an ISO-8601 UTC producer timestamp.  The existing
// fact formatter is intentionally local-time and therefore cannot be reused
// for the renderer input stream.  Sensor DateTime values are Windows FILETIME
// ticks, so this helper preserves their source clock instead of inventing a
// browser receipt timestamp.
static std::string sgFormatIsoUtcFileTime(ULONGLONG value) {
    if (value == 0) return {};
    FILETIME fileTime{};
    ULARGE_INTEGER raw{};
    raw.QuadPart = value;
    fileTime.dwLowDateTime = raw.LowPart;
    fileTime.dwHighDateTime = raw.HighPart;
    SYSTEMTIME utc{};
    if (!FileTimeToSystemTime(&fileTime, &utc)) return {};
    char text[40]{};
    std::snprintf(text, sizeof(text), "%04u-%02u-%02uT%02u:%02u:%02u.%03uZ",
                  utc.wYear, utc.wMonth, utc.wDay, utc.wHour,
                  utc.wMinute, utc.wSecond, utc.wMilliseconds);
    return text;
}

static json sgFactSnapshot() {
    json facts = json::array();
    {
        std::lock_guard<std::mutex> lock(g_sgFactMx);
        for (const auto& line : g_sgFacts) facts.push_back(line);
    }
    return {
        {"enabled", g_sgFactMonitorEnabled.load(std::memory_order_acquire)},
        {"logPath", W2U(SG_FACT_LOG)},
        {"subscriptionActive", g_sgKernelPowerSubscription != nullptr},
        {"lifecycle", powerLifecycleName(g_powerLifecycle.load(std::memory_order_acquire))},
        {"generation", g_powerGeneration.load(std::memory_order_acquire)},
        {"guardEnabled", g_guardEnabled},
        {"sleepCycleActive", g_sgSleepCycleActive.load(std::memory_order_acquire)},
        {"gameSuspended", g_sgGameActuallySuspended.load(std::memory_order_acquire)},
        {"taskMode", sgSleepModeName(g_sgTask.mode)},
        {"retryKind", sgRetryKindName(g_sgTask.retryKind)},
        {"retryAttempt", g_sgTask.retryAttempt},
        {"userStandby", {
            {"active", g_sgLastPowerButtonSleepIntentFileTime.load(std::memory_order_acquire) != 0},
            {"reason", g_sgLastKernel506Reason.load(std::memory_order_acquire)},
            {"time", sgFormatFactFileTime(g_sgLastPowerButtonSleepIntentFileTime.load(std::memory_order_acquire))}
        }},
        {"last506", {
            {"reason", g_sgLastKernel506Reason.load(std::memory_order_acquire)},
            {"time", sgFormatFactFileTime(g_sgLastKernel506EventFileTime.load(std::memory_order_acquire))}
        }},
        {"last507", {
            {"reason", g_sgLastKernel507Reason.load(std::memory_order_acquire)},
            {"time", sgFormatFactFileTime(g_sgLastKernel507EventFileTime.load(std::memory_order_acquire))}
        }},
        {"lastAccepted506", sgFormatFactFileTime(g_sgLastPowerButtonSleepIntentFileTime.load(std::memory_order_acquire))},
        {"lastAccepted507", sgFormatFactFileTime(g_sgLastPowerButtonWakeEventFileTime.load(std::memory_order_acquire))},
        {"userInitiatedSleep", {
            {"active", g_sgLastPowerButtonSleepIntentFileTime.load(std::memory_order_acquire) != 0},
            {"time", sgFormatFactFileTime(g_sgLastPowerButtonSleepIntentFileTime.load(std::memory_order_acquire))},
            {"evidence", "Kernel-Power EventID=506 Reason=1 or Reason=3"}
        }},
        {"unexpectedWakeConsumed", g_sgTask.unexpectedWakeConsumed},
        {"facts", facts}
    };
}

static bool hardwareWriteAllowed() {
    if (g_aiFanMockSession.isolated) return false;
    return g_hardwareWriteGate.load(std::memory_order_acquire) &&
           g_powerLifecycle.load(std::memory_order_acquire) == PowerLifecycle::Ready;
}

static unsigned long long currentPowerGeneration() {
    return g_powerGeneration.load(std::memory_order_acquire);
}
// Fan has an actual OS wake receipt even when a non-user UI/game wake is
// filtered. The global write gate and shared resume transaction are unchanged.
static unsigned long long currentFanPowerGeneration() {
    return g_fanPhysicalWake.generation(currentPowerGeneration());
}
static bool fanHostPhysicalWakeCurrent() {
    return !g_exitRequested.load(std::memory_order_acquire) && fanActivityIntentPresent()
        && g_fanPhysicalWake.physical(currentFanPowerGeneration());
}
static bool fanHostPowerMayWrite() {
    const auto g=currentFanPowerGeneration();
    return g_fanPhysicalWake.ready(g) && (hardwareWriteAllowed() || fanHostPhysicalWakeCurrent());
}
static bool fanHostPowerMayResume() {
    const auto phase=g_powerLifecycle.load(std::memory_order_acquire);
    const auto g=currentFanPowerGeneration();
    return g_fanPhysicalWake.ready(g) && (phase==PowerLifecycle::Ready || phase==PowerLifecycle::Resuming
        || fanHostPhysicalWakeCurrent());
}
static bool sleepSteamRecoveryAllows(unsigned long long generation,unsigned long long configEpoch) {
    return g_sleepRecoveryAutoEnabled.load(std::memory_order_acquire) && configEpoch!=0 &&
        configEpoch==g_sleepRecoveryAutoConfigEpoch.load(std::memory_order_acquire) &&
        generation!=0 && generation==currentPowerGeneration() && !g_exitRequested.load();
}
static bool sleepRecoveryAutoAllows(unsigned long long generation,unsigned long long configEpoch) {
    // Preserve the legacy diagnostic/input-owner isolation contract. Steam's
    // coordinator uses its own predicate and never changes this device gate.
    return sleepSteamRecoveryAllows(generation,configEpoch) && !g_aiFanMockSession.isolated;
}


