static void sgMarkSleepTrigger() {
    g_sgTask.generation = currentPowerGeneration();
    g_sgTask.retryKind = SgRetryKind::None;
    g_sgTask.retryAttempt = 0;
    g_sgTask.unexpectedWakeConsumed = false;
    g_sgSleepTriggerTick = GetTickCount64();
    g_sgSleepTriggerEpoch = sgNowEpoch();
    g_sgRepairEligible = g_sgSleepIntentArmed && g_guardEnabled;
    g_sgSleepCycleActive.store(g_sgRepairEligible, std::memory_order_release);
    g_sgGameActuallySuspended.store(false, std::memory_order_release);
    g_sgSleepIntentArmed = false;
    closeJoyXoffAsync("sleep-trigger");
    g_sgLastS0WakeReason = -1;
    g_sgLastS0WakeTick = 0;
    g_sgLastPowerButtonWakeTick = 0;
    // Human wake evidence belongs to every sleep feature. Preserve its
    // high-water mark; chronology, not option toggles, distinguishes a fresh
    // manual sleep from a canceled older transaction.
    // EntryFailure also needs the original intent when the independent
    // unexpected-wake guard is OFF and Windows has not delivered 506 yet.
    // Preserve an existing kernel/event timestamp and never arm an ineligible
    // or hibernate task merely to record this cancellation anchor.
    if (g_sgRepairEligible && g_sgTask.mode == SgSleepMode::S3 &&
        g_sgLastPowerButtonSleepIntentFileTime.load(std::memory_order_acquire) == 0)
        g_sgLastPowerButtonSleepIntentFileTime.store(sgNowFileTime(), std::memory_order_release);
    sgRefreshSleepTriggerOrigin();
    sgArmNonUserWakeGuard("sleep-trigger");
    g_sgRetryInProgress = false;
    g_sgRetryDueTick = 0;
    sgWriteFileAtomic(
        SG_SLEEP_TRIGGER_MARKER,
        "triggerEpoch=" + std::to_string(g_sgSleepTriggerEpoch) + "\n"
    );
    // EntryFailure 仅由本轮 506/507 或查询失败证据推进，不启动静默观察器。
}

