// HC parity: HandheldCompanion keeps two XInput reads separate:
//
//   1) Controller.GetState().Gamepad is the canonical physical
//      ButtonState/AxisState source;
//   2) xinput1_4.dll ordinal #100 is a private XInputStateSecret probe used
//      only for the Xbox Special button.
//
// The two layouts happen to have the same byte size, but they are not the
// same contract.  Treating ordinal #100 as XINPUT_STATE was a YMCC-only
// deviation and made the source claim the wrong provenance for all axes.
struct YmccXInputStateSecret {
    DWORD eventCount;
    WORD wButtons;
    BYTE bLeftTrigger;
    BYTE bRightTrigger;
    SHORT sThumbLX;
    SHORT sThumbLY;
    SHORT sThumbRX;
    SHORT sThumbRY;
};

using YmccXInputGetStateFn = DWORD (WINAPI *)(DWORD, XINPUT_STATE*);
using YmccXInputGetStateSecretFn = DWORD (WINAPI *)(DWORD, YmccXInputStateSecret*);
// 【取证 2026-09-17 用户裁决｜待删除】XInputGetCapabilities 解析（仅取证用：
// 读每槽 VID/PID/subType/flags，判定"虚拟是否在 XInput 内、谁占 slot 0"）。
using YmccXInputGetCapabilitiesFn = DWORD (WINAPI *)(DWORD, DWORD, XINPUT_CAPABILITIES*);

static constexpr WORD YMCC_XINPUT_SPECIAL_XBOX = 1024;
static HMODULE g_ymccXInput14Module = nullptr;
static YmccXInputGetStateFn g_ymccXInputGetState14 = nullptr;
static YmccXInputGetStateSecretFn g_ymccXInputGetStateSecret14 = nullptr;
static YmccXInputGetCapabilitiesFn g_ymccXInputGetCapabilities14 = nullptr;  // 【取证｜待删除】
static std::once_flag g_ymccXInput14Once;
static std::once_flag g_ymccXInputSetState14Once;

static YmccXInputGetStateFn ymccResolveXInputGetState14() {
    std::call_once(g_ymccXInput14Once, [] {
        g_ymccXInput14Module = LoadLibraryW(L"xinput1_4.dll");
        if (!g_ymccXInput14Module) return;
        auto canonicalProc = GetProcAddress(g_ymccXInput14Module, "XInputGetState");
        auto secretProc = GetProcAddress(g_ymccXInput14Module, MAKEINTRESOURCEA(100));
        g_ymccXInputGetState14 = reinterpret_cast<YmccXInputGetStateFn>(canonicalProc);
        g_ymccXInputGetStateSecret14 = reinterpret_cast<YmccXInputGetStateSecretFn>(secretProc);
        // 【取证｜待删除】capabilities 同模块解析（仅取证读每槽身份）。
        g_ymccXInputGetCapabilities14 = reinterpret_cast<YmccXInputGetCapabilitiesFn>(
            GetProcAddress(g_ymccXInput14Module, "XInputGetCapabilities"));
        appendNativeLifecycleLog("gamepad-xinput-api", {
            {"dll", "xinput1_4.dll"},
            {"canonicalEntryPoint", "XInputGetState"},
            {"canonicalResolved", g_ymccXInputGetState14 != nullptr},
            {"secretEntryPoint", "#100"},
            {"secretResolved", g_ymccXInputGetStateSecret14 != nullptr},
            {"secretRole", "xbox-special-only"},
            {"capabilitiesResolved", g_ymccXInputGetCapabilities14 != nullptr}  // 【取证｜待删除】
        });
    });
    return g_ymccXInputGetState14;
}

// C（裁决14 §4.3）：区分 wrapper 尝试与实际进入 DLL 的调用。解析失败（或参数
// 为空）时 wrapper 直接返回，不进入 DLL——该异常路径单独计数；常态路径零成本。
static std::atomic<unsigned long long> g_gpSlotApiUnresolved{0};

static DWORD ymccXInputGetState14(DWORD userIndex, XINPUT_STATE* state) {
    auto getState = ymccResolveXInputGetState14();
    if (!getState || !state) {
        g_gpSlotApiUnresolved.fetch_add(1, std::memory_order_relaxed);
        return ERROR_DEVICE_NOT_CONNECTED;
    }
    return getState(userIndex, state);
}

static DWORD ymccXInputGetStateSecret14(DWORD userIndex, YmccXInputStateSecret* state) {
    auto getState = ymccResolveXInputGetState14();
    if (!getState || !state || !g_ymccXInputGetStateSecret14) {
        g_gpSlotApiUnresolved.fetch_add(1, std::memory_order_relaxed);
        return ERROR_DEVICE_NOT_CONNECTED;
    }
    return g_ymccXInputGetStateSecret14(userIndex, state);
}

// XInput vibration write for the physical source (HC XInputController
// SetVibration parity). XInputSetState targets the physical device's live
// XInput slot; the virtual HIDMaestro endpoint is never used as a vibration
// sink.
using YmccXInputSetStateFn = DWORD (WINAPI *)(DWORD, XINPUT_VIBRATION*);
static YmccXInputSetStateFn g_ymccXInputSetState14 = nullptr;

// Read-only provenance for already resolved entry points. Never initializes
// another XInput module, enumerates a device, or queries controller state.
static json nativeXInputFunctionModuleEvidence(FARPROC function,HMODULE& owner) {
    owner=nullptr;
    json row={{"resolved",function!=nullptr},{"moduleKnown",false},{"modulePathKnown",false},
        {"modulePath",nullptr},{"error",nullptr},{"modulePathTruncated",false}};
    if(!function)return row;
    if(!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(function),&owner)){
        row["error"]=GetLastError();return row;
    }
    row["moduleKnown"]=true;
    wchar_t path[1024]{};const DWORD length=GetModuleFileNameW(owner,path,static_cast<DWORD>(std::size(path)));
    if(!length){row["error"]=GetLastError();return row;}
    if(length>=std::size(path)){row["modulePathTruncated"]=true;row["error"]=ERROR_INSUFFICIENT_BUFFER;return row;}
    row["modulePathKnown"]=true;row["modulePath"]=W2U(std::wstring(path,length));return row;
}

static YmccXInputSetStateFn ymccResolveXInputSetState14() {
    // XInputGetState is probed first at startup and owns g_ymccXInput14Once.
    // SetState must therefore resolve under its own once_flag; sharing the
    // getter's flag would skip this lambda entirely and leave the pointer
    // null, making every vibration fail with ERROR_DEVICE_NOT_CONNECTED.
    std::call_once(g_ymccXInputSetState14Once, [] {
        if (!g_ymccXInput14Module) {
            g_ymccXInput14Module = LoadLibraryW(L"xinput1_4.dll");
            if (!g_ymccXInput14Module) return;
        }
        g_ymccXInputSetState14 = reinterpret_cast<YmccXInputSetStateFn>(
            GetProcAddress(g_ymccXInput14Module, "XInputSetState"));
        // One record per resolver, independent of MOVE frequency. A metadata
        // failure must never turn an otherwise valid output API into a failure.
        try {
            HMODULE readOwner=nullptr,writeOwner=nullptr;
            auto canonical=nativeXInputFunctionModuleEvidence(reinterpret_cast<FARPROC>(g_ymccXInputGetState14),readOwner);
            auto writer=nativeXInputFunctionModuleEvidence(reinterpret_cast<FARPROC>(g_ymccXInputSetState14),writeOwner);
            const bool equalityKnown=readOwner&&writeOwner;
            appendNativeLifecycleLog("gamepad-xinput-output-api",{
                {"canonicalEntryPoint","XInputGetState"},{"outputEntryPoint","XInputSetState"},
                {"canonicalFunction",std::move(canonical)},{"outputFunction",std::move(writer)},
                {"sameFunctionModuleKnown",equalityKnown},
                {"sameFunctionModule",equalityKnown?json(readOwner==writeOwner):json(nullptr)},
                {"loadedModuleExportsOpenXinput",GetProcAddress(g_ymccXInput14Module,"OpenXInputGetDevicePath")!=nullptr},
                {"communicationEnableStateObserved",false},{"motorResponseObserved",false},
                {"scope","resolved-entry-points-only;no-device-probe;not-output-or-motor-proof"}});
        } catch(...) {}
    });
    return g_ymccXInputSetState14;
}

static DWORD ymccXInputSetState14(DWORD userIndex, XINPUT_VIBRATION* vibration) {
    auto setState = ymccResolveXInputSetState14();
    if (!setState || !vibration) return ERROR_DEVICE_NOT_CONNECTED;
    return setState(userIndex, vibration);
}

// ── S61（2026-09-11，HC OpenXInput 槽位指派对齐）────────────────────────
// HC 0.32.4 的 ControllerManager 通过 OpenXInput 代理（Xinput1_4.dll 的
// OpenXInput* 扩展导出）做 XInput 用户槽（slot 0..3）的显式指派：
//   AssignXInputSlot(controller, targetSlot) =
//     OpenXInputSetUserIndex(controller.GetContainerPath(), targetSlot, false)
//     → 成功后对 displaced 控制器与本控制器 CyclePort（ControllerManager.cs:1895-1918）
//   DeviceManager.GetXInputIndex(symLink) =
//     OpenXInputGetUserIndex(path)（路径 = baseContainerDevicePath，即 XUSB
//     接口路径，DeviceManager.cs:867-876）
// YMCC 只在锁死代理 DLL 真正被进程加载（含 OpenXInput* 导出）时才启用该
// 通道；未部署代理（LoadLibrary 命中 System32 官方 DLL）时 IsAvailable=false，
// 与 HC OpenXInput.IsAvailable 探测语义一致，槽位决策回落到现有 CyclePort 路径。
static constexpr DWORD kOpenXInput_ERROR_SUCCESS = 0;
static constexpr DWORD kOpenXInput_ERROR_UNAVAILABLE = 1;
static constexpr DWORD kOpenXInput_ERROR_DEVICE_NOT_CONNECTED = 1167;

using YmccOpenXInputGetUserIndexFn = DWORD (WINAPI *)(const WCHAR* lpDevicePath, BYTE* pUserIndex);
using YmccOpenXInputSetUserIndexFn = DWORD (WINAPI *)(const WCHAR* lpDevicePath, BYTE dwUserIndex, BOOL powerDownOnChange);
using YmccOpenXInputRefreshMappingsFn = DWORD (WINAPI *)();
using YmccOpenXInputGetDevicePathFn = DWORD (WINAPI *)(DWORD dwUserIndex, WCHAR* pDevicePath, DWORD* pCount);

static HMODULE g_ymccOpenXInputModule = nullptr;
static YmccOpenXInputGetUserIndexFn g_ymccOpenXInputGetUserIndex = nullptr;
static YmccOpenXInputSetUserIndexFn g_ymccOpenXInputSetUserIndex = nullptr;
static YmccOpenXInputRefreshMappingsFn g_ymccOpenXInputRefreshMappings = nullptr;
static YmccOpenXInputGetDevicePathFn g_ymccOpenXInputGetDevicePath = nullptr;
static std::once_flag g_ymccOpenXInputOnce;
static std::atomic<bool> g_ymccOpenXInputAvailable{false};

static void ymccResolveOpenXInput() {
    std::call_once(g_ymccOpenXInputOnce, [] {
        // HC OpenXInput.IsAvailable 语义：读取 _isAvailable 时 NativeLibrary
        // 加载 xinput1_4.dll 并 TryGetExport("OpenXInputGetUserIndex")。
        // YMCC 的 LoadLibraryW(L"xinput1_4.dll") 由 ymccResolveXInputGetState14
        // 先行使能；若部署侧把锁死 OpenXInput 代理 DLL 放进了 YeManCC 同目录
        // （DLL 搜索顺序应用目录优先），则同一模块同时携带着 OpenXInput*
        // 扩展导出，XInputGetState 本体仍为代理对系统槽的透传（HC 已验证）。
        HMODULE module = g_ymccXInput14Module;
        bool loadedHere = false;
        if (!module) {
            module = LoadLibraryW(L"xinput1_4.dll");
            if (module) loadedHere = true;
        }
        if (!module) return;
        g_ymccOpenXInputGetUserIndex = reinterpret_cast<YmccOpenXInputGetUserIndexFn>(
            GetProcAddress(module, "OpenXInputGetUserIndex"));
        g_ymccOpenXInputSetUserIndex = reinterpret_cast<YmccOpenXInputSetUserIndexFn>(
            GetProcAddress(module, "OpenXInputSetUserIndex"));
        g_ymccOpenXInputRefreshMappings = reinterpret_cast<YmccOpenXInputRefreshMappingsFn>(
            GetProcAddress(module, "OpenXInputRefreshMappings"));
        g_ymccOpenXInputGetDevicePath = reinterpret_cast<YmccOpenXInputGetDevicePathFn>(
            GetProcAddress(module, "OpenXInputGetDevicePath"));
        g_ymccOpenXInputModule = module;
        const bool available = g_ymccOpenXInputGetUserIndex != nullptr && g_ymccOpenXInputSetUserIndex != nullptr;
        g_ymccOpenXInputAvailable.store(available, std::memory_order_release);
        appendNativeLifecycleLog("gamepad-openxinput-probe", {
            {"dll", "xinput1_4.dll"},
            {"loadedHere", loadedHere},
            {"getUserIndex", g_ymccOpenXInputGetUserIndex != nullptr},
            {"setUserIndex", g_ymccOpenXInputSetUserIndex != nullptr},
            {"refreshMappings", g_ymccOpenXInputRefreshMappings != nullptr},
            {"getDevicePath", g_ymccOpenXInputGetDevicePath != nullptr},
            {"isAvailable", available}
        });
    });
}

static bool ymccOpenXInputAvailable() {
    ymccResolveOpenXInput();
    return g_ymccOpenXInputAvailable.load(std::memory_order_acquire);
}

// HC DeviceManager.GetXInputIndex(symLink)：把设备路径解析为当前 XInput
// 用户槽（0..3），失败返回 byte.MaxValue（DeviceManager.cs:867-876）。
static BYTE ymccOpenXInputGetUserIndex(const std::wstring& devicePath) {
    if (!ymccOpenXInputAvailable() || devicePath.empty()) return 0xFF;
    BYTE userIndex = 0xFF;
    const DWORD result = g_ymccOpenXInputGetUserIndex(devicePath.c_str(), &userIndex);
    return result == kOpenXInput_ERROR_SUCCESS ? userIndex : 0xFF;
}

// HC DeviceManager.GetPathFromUserIndex(userIndex)：返回指定槽的设备路径
// （GetDevicePath 两段式查询），供槽位探测直接使用（DeviceManager.cs:853-864）。
static std::wstring ymccOpenXInputGetDevicePath(DWORD userIndex) {
    if (!ymccOpenXInputAvailable() || !g_ymccOpenXInputGetDevicePath || userIndex > 3)
        return {};
    DWORD count = 0;
    if (g_ymccOpenXInputGetDevicePath(userIndex, nullptr, &count) != kOpenXInput_ERROR_SUCCESS || count == 0)
        return {};
    std::vector<wchar_t> buffer(count + 1, L'\0');
    if (g_ymccOpenXInputGetDevicePath(userIndex, buffer.data(), &count) != kOpenXInput_ERROR_SUCCESS)
        return {};
    return std::wstring(buffer.data());
}

// GP-GBRETURN-2（缺陷B）：映射变更事件 → 请求受影响槽的身份重解析（定义见发现/槽表区）。
static void xinputSlotsRequestIdentityReprobe(DWORD slots, const char* why);

// HC ControllerManager.AssignXInputSlot 等价：通过 OpenXInput 把设备指派到
// 指定槽位，成功后 accept 为 true 由调用方按需 CyclePort（HC 对 displaced
// 与本控制器各执行一次 CyclePort；powerDownOnChange=false 与 HC 一致）。
// 返回 true 表示 SetUserIndex 成功（含已处于目标槽的幂等成功）。
using OpenXInputAssignGuard = bool(*)(void*) noexcept;
static bool ymccOpenXInputAssignSlot(const std::wstring& devicePath, BYTE targetSlot, bool& accept,
        OpenXInputAssignGuard guard = nullptr, void* guardContext = nullptr) {
    accept = false;
    if (!ymccOpenXInputAvailable() || devicePath.empty() || targetSlot > 3) return false;
    const auto mayIssue = [&]() noexcept { return !guard || guard(guardContext); };
    if (!mayIssue()) return false;
    const DWORD result = g_ymccOpenXInputSetUserIndex(devicePath.c_str(), targetSlot, FALSE);
    if (result == kOpenXInput_ERROR_SUCCESS) {
        const BYTE actual = ymccOpenXInputGetUserIndex(devicePath);
        accept = (actual == targetSlot);
        appendNativeLifecycleLog("gamepad-openxinput-assign-slot", {
            {"path", W2U(devicePath)}, {"targetSlot", targetSlot},
            {"result", result}, {"actualSlot", actual}, {"accepted", accept}
        });
        // GP-GBRETURN-2（缺陷B）：指派成功 = 映射变更事件——目标槽的占用者可能已换人
        // （虚拟被搬 slot0 / 物理被挤走）而不产生掉线边沿。旧实现不失效身份缓存 ⇒
        // 槽0连续连接仍沿用旧物理身份。这里只置请求位；实际重解析在采样车道完成。
        xinputSlotsRequestIdentityReprobe(1u << targetSlot, "assign-slot-success");
        return true;
    }
    if (result == kOpenXInput_ERROR_DEVICE_NOT_CONNECTED) return false;
    if (g_ymccOpenXInputRefreshMappings) {
        if (!mayIssue()) return false;
        if (g_ymccOpenXInputRefreshMappings() != kOpenXInput_ERROR_SUCCESS) {
            // 刷新失败：映射结果不确定 ⇒ 仍请求重解析（有界；不逐帧）。
            xinputSlotsRequestIdentityReprobe(1u << targetSlot, "assign-failed-uncertain");
            return false;
        }
        // 映射表重枚举本身就可能改变各槽占用（调用结果无论成败）。
        xinputSlotsRequestIdentityReprobe(0xFu, "refresh-mappings");
        if (!mayIssue()) return false;
        const DWORD retry = g_ymccOpenXInputSetUserIndex(devicePath.c_str(), targetSlot, FALSE);
        if (retry == kOpenXInput_ERROR_SUCCESS) {
            const BYTE actual = ymccOpenXInputGetUserIndex(devicePath);
            accept = (actual == targetSlot);
            appendNativeLifecycleLog("gamepad-openxinput-assign-slot", {
                {"path", W2U(devicePath)}, {"targetSlot", targetSlot},
                {"result", retry}, {"actualSlot", actual}, {"accepted", accept}, {"refreshRetried", true}
            });
            xinputSlotsRequestIdentityReprobe(1u << targetSlot, "assign-slot-success-after-refresh");
            return true;
        }
    }
    xinputSlotsRequestIdentityReprobe(1u << targetSlot, "assign-failed-uncertain");
    return false;
}

static bool g_rawInputRegistered = false;
static bool g_gamepadStatePublished = false;
static bool g_publishedPadConnected = false;
static XINPUT_GAMEPAD g_publishedPad{};
static std::array<XINPUT_GAMEPAD, 4> g_xinputPads{};
static std::array<bool, 4> g_xinputSpecialButtons{};
static DWORD g_xinputConnectedMask = 0;
static DWORD g_xinputPrimarySlot = 0;
static bool g_xinputSpecialButton = false;
static DWORD g_xinputLoggedMask = 0xffffffffu;
// XInput also exposes HIDMaestro's virtual endpoint. Once a virtual target is
// opened, only slots present before target creation remain physical sources.
static bool g_xinputPhysicalSourceLocked = false;
static DWORD g_xinputPhysicalSourceMask = 0;
// HC parity: the physical slot set captured before the virtual target was
// created.  The upstream single-source policy only admits from this set, so a
// virtual XInput endpoint (360 persona) or a brand-new controller can never
// become the "physical" source.
static DWORD g_xinputPreTargetSlots = 0;
// 批113（2026-09-24 实机 RCA，b112 包 17:56:40）：XInput 里同样能枚举到**自家虚拟端点**
// （HIDMaestro 平面；上一代"常驻"或崩溃遗留的虚拟手柄会跨进程存活）。它们不是物理源，
// 但旧的"建塔前捕获"只在同一进程内有效 ⇒ 残留虚拟槽以 preTargetSlots 身份被准入
// （实测 preTargetSlots=2/sourceMask=2/sourceSlot=1 ⇒ 源指向上一代虚拟位 ⇒ 自回声 +
// 物理未被隐藏 ⇒ 消费者看到双手柄）。准入域只认物理端点：连接槽在**连接边沿**解析一次
// 设备路径，命中虚拟标记（HIDMAESTRO/HM-CTL/VIGEM）者永不入选；掉线即失效重解析。
// `g_xinputConnectedMask` 语义**不变**（= 系统视角的原始连接掩码），隔离判定/诊断仍用它——
// 隔离清场谓词（connectedMask & ~sourceMask == 0）必须保持保守，不得被本掩码放宽。
static DWORD g_xinputVirtualEndpointMask = 0;    // 判定为虚拟端点的槽（当前连接内有效）
static DWORD g_xinputVirtualEndpointProbed = 0;  // 本轮连接内已解析过的槽（掉线即复位）
// GP-GBRETURN-2（裁决 §4 缺陷B，T0 优先）：槽身份缓存必须能被**主动映射变更**推翻。
// 旧实现只在"检测到掉线"时复位 probed ⇒ 换槽（AssignSlot/映射刷新）不产生掉线边沿时，
// 槽0连续连接却换了占用者，仍沿用旧物理身份；空路径也被永久当物理
// （CONTINUOUS_SLOT_REMAP_STALE_IDENTITY / EMPTY_PATH_CACHED_AS_NONVIRTUAL）。
//   · g_xinputSlotUnknownMask：路径读不回 ⇒ Unknown，既不算虚拟也**不算物理**；
//   · g_xinputSlotReprobeMask / g_xinputSlotIdentityEpoch：映射变更事件触发的有界重解析请求与映射代；
//   · g_xinputSlotIdentityResolvedEpoch[4]：各槽当前分类是在哪一代解析的（同代复用才算新鲜）。
// 全部只由采样车道（g_gamepadReadMx 内）写；请求位由映射变更事件置（原子）。
static DWORD g_xinputSlotUnknownMask = 0;                    // 采样车道读写
static std::atomic<DWORD> g_xinputSlotReprobeMask{0};
static std::atomic<unsigned> g_xinputSlotIdentityEpoch{1};
static unsigned long long g_feedbackSlotGeneration[4] = {}; // g_gamepadReadMx; prevents stale pulse stops after slot reuse.
static DWORD g_xinputSlotIdentityResolvedEpoch[4] = {0, 0, 0, 0};   // 采样车道读写
static ULONGLONG g_xinputSlotReprobeAt[4] = {0, 0, 0, 0};           // Unknown 的有界重查（采样车道）
static constexpr ULONGLONG kXInputSlotReprobeBackoffMs = 500;
// 非虚拟连接掩码（含 Unknown）：仅用于"是否存在非虚拟占用者"的**保守**判据——未知占位者
// 按"可能是物理"对待（跳过会移动设备/抢占的动作，与旧行为一致）。物理身份判定一律用
// xinputPhysicalConnectedMask()（排除 Unknown）。
static DWORD xinputNonVirtualConnectedMask() {
    return g_xinputConnectedMask & ~g_xinputVirtualEndpointMask;
}
static DWORD xinputPhysicalConnectedMask() {
    // GP-GBRETURN-2：Unknown（路径读不回）不是物理——不并入物理域（旧行为=空路径永久按物理）。
    return xinputNonVirtualConnectedMask() & ~g_xinputSlotUnknownMask;
}
// GP-GBRETURN-2（缺陷B）：槽身份判定（纯函数；采样车道与自测同源）。旧实现只有"首次连接解析一次、
// 空路径也当非虚拟"两态 ⇒ 换槽沿用旧身份（CONTINUOUS_SLOT_REMAP_STALE_IDENTITY）且空路径被永久
// 缓存为物理（EMPTY_PATH_CACHED_AS_NONVIRTUAL）。现将三态显式化：无 OpenXInput 代理 ⇒ 判为物理
// （原行为，零回归）；路径读不回 ⇒ Unknown（不是物理、不是虚拟）；读到路径 ⇒ 按虚拟标记判定。
enum class XInputSlotIdentity : int { Unknown = 0, Virtual = 1, Physical = 2 };
static XInputSlotIdentity xinputSlotIdentityVerdict(bool openXInputAvailable, bool pathReadable,
                                                    bool virtualIdentity) {
    if (!openXInputAvailable) return XInputSlotIdentity::Physical;
    if (!pathReadable) return XInputSlotIdentity::Unknown;
    return virtualIdentity ? XInputSlotIdentity::Virtual : XInputSlotIdentity::Physical;
}

static std::array<ymcc::input::identityRefresh::Slot,4> g_xinputFeedbackIdentity;
// Owned by the existing gamepad-read mutex, populated only by its exact path probe.
static std::array<std::shared_ptr<const std::string>,4> g_axisCalibrationXinputKeys;
static std::array<std::uint64_t,4> g_axisCalibrationXinputGeneration{};
static std::array<bool,4> g_axisCalibrationXinputLtAnalog{},g_axisCalibrationXinputRtAnalog{};
// Identity observed by the existing discovery pass; no extra BUS API calls.
// The lifecycle return observer copies it under g_gamepadReadMx and requires
// the current identity proof and a fresh XInput read window before use.
static std::array<std::wstring,4> g_msiOwnedReturnSlotPaths;
static std::atomic<bool> g_msiOwnedReturnPending{false},g_msiOwnedReturnWorking{false},g_msiOwnedReturnFailed{false};
static std::atomic<unsigned long long> g_msiOwnedReturnMatchedEpisode{0},g_msiOwnedReturnMatchedPower{0};
static std::atomic<unsigned> g_msiOwnedReturnMatchedTopology{0};
static ymcc::msi::ownedReturnOff::Publication g_msiOwnedReturnOffEndpoint;
static bool msiOwnedReturnOffEndpointAbsent();
static std::atomic<unsigned long long> g_msiOwnedReturnSourceEvent{0};
static ymcc::input::identityRefresh::DeferredStop g_xinputDeferredFeedbackStop;
// Sampling owns g_gamepadReadMx. Never acquire g_feedbackPulseMx here.
static bool xinputFeedbackIdentityProbe(DWORD slot,bool available,const std::wstring& path,XInputSlotIdentity kind,
 bool edge,bool requested,bool unknownBefore,unsigned long long epoch,unsigned long long power) {
    using namespace ymcc::input::identityRefresh;
    if(msiClawKnownBoardAuthority())
        g_msiOwnedReturnSlotPaths[slot]=(available&&kind==XInputSlotIdentity::Physical)?path:std::wstring{};
    const auto result=g_xinputFeedbackIdentity[slot].observe({available,edge,requested,unknownBefore,path,
        kind==XInputSlotIdentity::Physical?Kind::Physical:kind==XInputSlotIdentity::Virtual?Kind::Virtual:Kind::Unknown,
        epoch,g_xinputSlotIdentityEpoch.load(std::memory_order_acquire),power,currentPowerGeneration()});
    if(available&&kind==XInputSlotIdentity::Physical&&!path.empty()) {
        const auto key=ascii_lower(W2U(path));
        if(!g_axisCalibrationXinputKeys[slot]||*g_axisCalibrationXinputKeys[slot]!=key)
            g_axisCalibrationXinputKeys[slot]=std::make_shared<const std::string>(key);
    } else g_axisCalibrationXinputKeys[slot].reset();
    if(result.advanceGeneration){
        ++g_feedbackSlotGeneration[slot];
        if(msiClawKnownBoardAuthority() && kind==XInputSlotIdentity::Physical)
            g_msiOwnedReturnSourceEvent.fetch_add(1,std::memory_order_release);
    }
    if(result.notifyStop)if(const auto pending=g_xinputDeferredFeedbackStop.pendingFor(slot))
        (void)gamepadSerialScheduleFeedbackStop(pending,0);
    return result.retry;
}

