static ULONGLONG gamepadUiEditRepeatInterval(ULONGLONG heldMs) {
    const ULONGLONG acceleratedMs = heldMs > GP_UI_EDIT_REPEAT_DELAY_MS
        ? heldMs - GP_UI_EDIT_REPEAT_DELAY_MS : 0;
    const ULONGLONG rampMs = acceleratedMs < GP_UI_EDIT_REPEAT_RAMP_MS
        ? acceleratedMs : GP_UI_EDIT_REPEAT_RAMP_MS;
    return GP_UI_EDIT_REPEAT_START_MS - rampMs *
        (GP_UI_EDIT_REPEAT_START_MS - GP_UI_EDIT_REPEAT_MIN_MS) / GP_UI_EDIT_REPEAT_RAMP_MS;
}
