// ── Controller 族：Legion Tablet/Tablet2 与 Go S 的固定 HC IMU 协议 ──
// Tablet 左右各有独立偏移；byte1 的非 IMU 错位处理不移动这些 IMU 字段。
// 完整性按所选通道的实际报告字节数判断，不用缓冲容量补齐数据。
// BUS 保留单一 selected lease；额外两路证据槽仅观察已到达的合格报告，
// 不选择来源、不运行 GamepadMotion/校准，也不向 Host 发布。
static std::mutex g_legionImuMx;
static ymcc::legion_motion::Lease g_legionMotion;
static ymcc::legion_motion::BankEvidence g_legionBankEvidence;
static std::atomic<uint64_t> g_legionMotionCaptureEpoch{1};
// True source lifetime, independent of output-only left/right selection epochs.
static std::atomic<uint64_t> g_legionMotionProcessorLifetime{1};
// Queue-time cutover, in uptime ms. This is not a firmware sampling clock.
static std::atomic<uint64_t> g_legionMotionEpochStartedAt{0};
static void legionMotionRevoke() noexcept {
    std::lock_guard<std::mutex> lock(g_legionImuMx);
    uint64_t lifetime=g_legionMotionProcessorLifetime.load(std::memory_order_relaxed)+1;
    if(!lifetime)lifetime=1;
    g_legionMotionProcessorLifetime.store(lifetime,std::memory_order_release);
    uint64_t next = g_legionMotionCaptureEpoch.load(std::memory_order_relaxed) + 1;
    if (!next) next = 1;
    g_legionMotionEpochStartedAt.store(GetTickCount64(), std::memory_order_release);
    g_legionMotionCaptureEpoch.store(next, std::memory_order_release);
    g_legionMotion.revoke();
}
