static bool legionMotionSelectSensorIndex(unsigned index, uint64_t revision) {
    if (index > 1) return false;
    std::lock_guard<std::mutex> lock(g_legionImuMx);
    if (revision < g_legionMotionSelectionRevision) return false;
    g_legionMotionSelectionRevision=revision;
    if (index == g_legionMotionSensorIndex.load(std::memory_order_acquire)) return false;
    g_legionMotionSensorIndex.store(index,std::memory_order_release);
    uint64_t next=g_legionMotionCaptureEpoch.load(std::memory_order_relaxed)+1;
    if (!next) next=1;
    g_legionMotionEpochStartedAt.store(GetTickCount64(),std::memory_order_release);
    g_legionMotionCaptureEpoch.store(next,std::memory_order_release);
    g_legionMotion.revoke();
    return true;
}
