static std::atomic<const char*> g_gmSessionResetReason{"persona-transition"};
// HC reading.timestamp = Timestamp.DateTime.TimeOfDay.TotalMilliseconds.
// FILETIME is UTC 100ns ticks; ms-of-day deltas are timezone agnostic, so the
// logged event cadence compares 1:1 against HC's (IMUGyrometer.cs:131).
static double hcSinkTimeOfDayMs(UINT64 ticks100ns) noexcept {
    constexpr UINT64 kTicksPerDay = UINT64(86400) * UINT64(10000000);
    return static_cast<double>((ticks100ns % kTicksPerDay) / UINT64(10000));
}

class InputCaptureSensorSink final {
public:
    std::mutex mx;
    bool gyroOk = false;
    bool accelOk = false;
    double gx = 0, gy = 0, gz = 0, ax = 0, ay = 0, az = 0;
    // A WinRT callback can already be queued when ReadingChanged is removed.
    // Keep the binding generation in the sample itself so a late callback from
    // the previous provider cannot be paired with a fresh provider.
    UINT64 gyroBindingGeneration = 0;
    UINT64 accelBindingGeneration = 0;
    // Admission must reject a pair captured before the latest stop/rebind, even
    // if the two retired sample generations happen to equal one another.
    std::atomic<UINT64> activeBindingGeneration{0};
    // SENSOR_DATA_TYPE_TIMESTAMP is a FILETIME (100-ns ticks). It is
    // diagnostic provenance only: independent typed WinRT callbacks cannot
    // prove a same-provider/same-generation gyro+accel pair.
    UINT64 gyroTimestamp100ns = 0;
    UINT64 accelTimestamp100ns = 0;
    // HC parity: HC stores reading.timestamp = Timestamp.DateTime.TimeOfDay.
    // TotalMilliseconds (IMUGyrometer.cs:131, IMUAccelerometer.cs:128).  The
    // FILETIME source is UTC 100ns ticks; the ms-of-day delta is timezone
    // agnostic, so the logged cadence compares 1:1 against HC's event stream.
    double gyroTimeOfDayMs = 0;
    double accelTimeOfDayMs = 0;
    ULONGLONG gyroReceiptTick = 0;
    ULONGLONG accelReceiptTick = 0;
    // 当前 binding 内最近一次高幅样本；ResetSamples 清零，供本轮 highOngoing
    // 判定使用。下面的 episode 证据跨 WinRT 重建保留，用于动作边沿去重。
    ULONGLONG gyroHighMagLastTick = 0;
    ULONGLONG gyroHighMotionLastTick = 0;
    bool gyroHighMotionActive = false;
    UINT64 gyroHighMotionEpisode = 0;
    // 独立 accel 动作证据：gyro 死透而 accel 仍有事件时可做 rescue trigger。
    ULONGLONG accelMotionLastTick = 0;
    bool accelMotionActive = false;
    UINT64 accelMotionEpisode = 0;
    // 百式判定（2026-09-16 极简版）：判定只看样本计数（gyroSequence），
    // 轴值（是否静止）不再参与——取证见「百式判定数据流程书-20260916」。
    UINT64 gyroSequence = 0;
    UINT64 accelSequence = 0;
    // Per-binding rejected numeric reports, never accepted sensor observations.
    UINT64 gyroRejectedSamples=0, accelRejectedSamples=0;
    static bool AxesUsable(double x,double y,double z) noexcept {
        constexpr double limit=static_cast<double>((std::numeric_limits<float>::max)());
        const auto axis=[limit](double v) { return std::isfinite(v) && v>=-limit && v<=limit; };
        return axis(x) && axis(y) && axis(z);
    }
    void ResetSamples() {
        std::lock_guard<std::mutex> lock(mx);
        gyroOk = accelOk = false;
        gx = gy = gz = ax = ay = az = 0;
        gyroTimeOfDayMs = accelTimeOfDayMs = 0;
        gyroBindingGeneration = accelBindingGeneration = 0;
        activeBindingGeneration.store(0,std::memory_order_release);
        gyroTimestamp100ns = accelTimestamp100ns = 0;
        gyroReceiptTick = accelReceiptTick = 0;
        gyroHighMagLastTick = 0;
        gyroSequence = accelSequence = 0;
        gyroRejectedSamples = accelRejectedSamples = 0;
    }
    void SetBindingGeneration(UINT64 generation) noexcept {
        std::lock_guard<std::mutex> lock(mx);
        if (generation != activeBindingGeneration.load(std::memory_order_relaxed)) {
            gyroOk = accelOk = false; // A new binding is not a sensor observation.
            gyroRejectedSamples = accelRejectedSamples = 0;
        }
        gyroBindingGeneration = accelBindingGeneration = generation;
        activeBindingGeneration.store(generation,std::memory_order_release);
    }
    void OnGyro(const winrt::Windows::Devices::Sensors::GyrometerReadingChangedEventArgs& args, UINT64 generation) noexcept {
        try {
            const auto reading = args.Reading();
            OnRawGyro(reading.AngularVelocityX(), reading.AngularVelocityY(), reading.AngularVelocityZ(),
                static_cast<UINT64>(reading.Timestamp().time_since_epoch().count()), GetTickCount64(), generation);
        } catch (...) {}
    }
    void OnRawGyro(double x, double y, double z, UINT64 ts, ULONGLONG tick, UINT64 generation) noexcept {
        try {
            std::lock_guard<std::mutex> lock(mx);
            if (gyroBindingGeneration != generation) return;
            if (!AxesUsable(x,y,z)) { gyroOk=false; ++gyroRejectedSamples; return; }
            gx = x; gy = y; gz = z; gyroOk = true;
            gyroTimestamp100ns = ts;
            gyroReceiptTick = tick;
            gyroTimeOfDayMs = hcSinkTimeOfDayMs(ts);
            ++gyroSequence;
            // 高幅触发采用 episode（边沿）而不是持续电平：重绑后同一段持续晃动
            // 不会反复触发；安静 ≥1.5s 后的下一次高幅样本才开新 episode。
            const bool high = fabs(x) >= kInputCaptureHighMagDps ||
                fabs(y) >= kInputCaptureHighMagDps ||
                fabs(z) >= kInputCaptureHighMagDps;
            if (high) {
                const bool newEpisode = !gyroHighMotionActive ||
                    (gyroHighMotionLastTick != 0 &&
                     tick - gyroHighMotionLastTick >= kInputCaptureHighMagQuietWindowMs);
                if (newEpisode) ++gyroHighMotionEpisode;
                gyroHighMotionActive = true;
                gyroHighMotionLastTick = tick;
                gyroHighMagLastTick = tick;
            } else if (gyroHighMotionActive && gyroHighMotionLastTick != 0 &&
                       tick - gyroHighMotionLastTick >= kInputCaptureHighMagQuietWindowMs) {
                gyroHighMotionActive = false;
            }
            // 百式判定（2026-09-16 极简版）：热路径只保留上面的 ++gyroSequence；
            // 原先每个样本 3 次 fabs 的"有效样本/无效时刻"统计已删（判定改看段内样本数）。
            // Event cadence evidence rides frame fields (hcTimeOfDayMs/busTick)
            // only; per-event domain-log writes perturb sensor delivery.
        } catch (...) {}
    }
    void OnAccel(const winrt::Windows::Devices::Sensors::AccelerometerReadingChangedEventArgs& args, UINT64 generation) noexcept {
        try {
            const auto reading = args.Reading();
            OnRawAccel(reading.AccelerationX(), reading.AccelerationY(), reading.AccelerationZ(),
                static_cast<UINT64>(reading.Timestamp().time_since_epoch().count()), GetTickCount64(), generation);
        } catch (...) {}
    }
    void OnRawAccel(double x, double y, double z, UINT64 ts, ULONGLONG tick, UINT64 generation) noexcept {
        try {
            std::lock_guard<std::mutex> lock(mx);
            if (accelBindingGeneration != generation) return;
            if (!AxesUsable(x,y,z)) { accelOk=false; ++accelRejectedSamples; return; }
            // 首帧只建立基线，不把 0→重力的初始化跳变误判成用户动作。
            const bool motion = accelOk &&
                ((x - ax) * (x - ax) + (y - ay) * (y - ay) + (z - az) * (z - az) >=
                 kInputCaptureAccelMotionDeltaG * kInputCaptureAccelMotionDeltaG);
            if (motion) {
                const bool newEpisode = !accelMotionActive ||
                    (accelMotionLastTick != 0 &&
                     tick - accelMotionLastTick >= kInputCaptureHighMagQuietWindowMs);
                if (newEpisode) ++accelMotionEpisode;
                accelMotionActive = true;
                accelMotionLastTick = tick;
            } else if (accelMotionActive && accelMotionLastTick != 0 &&
                       tick - accelMotionLastTick >= kInputCaptureHighMagQuietWindowMs) {
                accelMotionActive = false;
            }
            ax = x; ay = y; az = z; accelOk = true;
            accelTimestamp100ns = ts;
            accelReceiptTick = tick;
            accelTimeOfDayMs = hcSinkTimeOfDayMs(ts);
            ++accelSequence;
            // No per-event domain-log write (see OnGyro): cadence evidence rides
            // frame fields only, so the diagnostic cannot perturb delivery.
        } catch (...) {}
    }
};
