// The gyro capture worker is the YMCC equivalent of HC's SensorsManager /
// ControllerManager motion lane.  `enabled` below means that the runtime
// motion coordinator is alive; the durable gyro/target settings still decide
// whether a motion contribution is emitted.  The old marker remains accepted
// as a compatibility receipt for standalone packages, but it is no longer the
// production admission gate.
struct RealStickTestConfig {
    bool enabled = false;
    bool standaloneTestLane = false;
    // HC VirtualManager creates/connects the selected virtual persona before
    // motion is considered.  Keep target lifecycle admission separate from
    // the optional gyro contribution gate below.
    bool virtualTargetEnabled = false;
    std::string virtualTargetPersona = "disabled";
    bool targetGyroEnabled = false;
    bool motionActionEnabled = false;
    bool motionEnabled = false;
    bool autoCalibrate = true;
    bool motionTriggerResolved = true;
    // HC MotionManager semantics: Off means trigger-held, On means active
    // while the trigger is not held, Toggle flips on the trigger press edge.
    std::string motionMode = "off";
    std::string motionTrigger;
    bool motionToggleStatus = false;
    bool motionTogglePressed = false;
    std::string targetStick = "right";
    std::string targetSource = "input.gyroMotion.outputStick";
    std::string motionInput = "local-space";
    // HC Profile.SteeringAxis (Roll/Yaw/Auto). Roll keeps LocalSpace (Z,X);
    // Yaw applies SwapYawRoll so LocalSpace consumes (-Y,X); Auto resolves by
    // sensor family (Windows/SerialUSBIMU -> Yaw, Controller -> accelerometer).
    std::string steeringAxis = "roll";
    double gyroMultiplier = 1.0;
    double accelerometerMultiplier = 1.0;
    double gyroThreshold = 2000.0;
    double motionSensitivityX = 1.0;
    double motionSensitivityY = 1.0;
    std::vector<std::pair<double, double>> motionSensitivityArray;
    double gyroWeight = 1.2;
    std::string velocityMode = "default";
    double velocityScale = 1.0;
    double velocityAccumulatedX = 0.0;
    double velocityAccumulatedY = 0.0;
    double steeringMaxAngle = 30.0;
    double steeringPower = 1.0;
    double steeringDeadzone = 0.0;
    // HC AxisActions stick modifiers applied before the gyro-weight blend
    // (LayoutManager.ProcessGyroActions -> AxisActions.ApplyAxisModifiers):
    // radial inner/outer deadzone, anti-deadzone, then output shape.
    double axisInnerDeadzone = 1.0;
    double axisOuterDeadzone = 0.0;
    double axisAntiDeadzone = 20.0;
    std::string outputShape = "default";
    // HC AxisActions.ResponseCurvePoints (AxisActions.cs:36-44): 6-point [0,1]
    // control curve applied after anti-deadzone, before output shape. Empty =
    // HC default linear identity (no-op).
    std::vector<std::pair<double, double>> responseCurvePoints;
    // HC MotionManager.cs:296-298: aiming trigger held -> output *= multiplier.
    double aimingSightsMultiplier = 1.0;
    std::string aimingSightsTrigger;
    bool aimingSightsTriggerResolved = true;
    bool invertHorizontal = false;
    bool invertVertical = false;
    std::string outputAxis = "xy";
    std::string laneId;
};
