static void inputSignalUpdateGate(bool requested) noexcept {
    // Existing diagnostic owner serializes control calls. Remember a failed
    // disable even if the user re-enables before the next maintenance pass.
    static bool resetOwed=false;
    const bool gate=g_inputSignalEventGate.load(std::memory_order_acquire);
    if(!requested&&(gate||g_inputSignalActivity.enabled()))resetOwed=true;
    if(!resetOwed&&gate==requested&&g_inputSignalActivity.enabled()==requested)return;
    g_inputSignalEventGate.store(false,std::memory_order_release);
    if(resetOwed){
        if(!g_inputSignalActivity.enable(false))return;
        resetOwed=false;
        if(!requested)return;
    }
    if(g_inputSignalActivity.enable(requested))g_inputSignalEventGate.store(requested,std::memory_order_release);
}
