static std::atomic<bool> g_inputHostRequestedPersonaMatchesBound{false};
static void inputHostRefreshPersonaMatchLocked() noexcept;
struct InputHostVirtualIntentMutation {
    InputHostVirtualIntentMutation() noexcept {
        g_inputHostVirtualIntentWriters.fetch_add(1,std::memory_order_acq_rel);
        g_inputHostVirtualIntentRevision.fetch_add(1,std::memory_order_acq_rel);
    }
    ~InputHostVirtualIntentMutation() noexcept {
        g_inputHostVirtualIntentRevision.fetch_add(1,std::memory_order_acq_rel);
        g_inputHostVirtualIntentWriters.fetch_sub(1,std::memory_order_release);
    }
    InputHostVirtualIntentMutation(const InputHostVirtualIntentMutation&)=delete;
    InputHostVirtualIntentMutation& operator=(const InputHostVirtualIntentMutation&)=delete;
};
