        frame.lY  = msiAxisNormalizeToDeclared(js.lY,  g_msiDinput.axisActualMin[1], g_msiDinput.axisActualMax[1], 0, 65535);
        frame.lZ  = msiAxisNormalizeToDeclared(js.lZ,  g_msiDinput.axisActualMin[2], g_msiDinput.axisActualMax[2], 0, 65535);
        frame.lRx = msiAxisNormalizeToDeclared(js.lRx, g_msiDinput.axisActualMin[3], g_msiDinput.axisActualMax[3], 0, 65535);
        frame.lRy = msiAxisNormalizeToDeclared(js.lRy, g_msiDinput.axisActualMin[4], g_msiDinput.axisActualMax[4], 0, 65535);
