static void ymccResolveMachineIdentityOnce() {
    if (g_machineIdentity.attempted) return;
    g_machineIdentity.attempted = true;
    try {
        g_machineIdentity.manufacturer = ymccDmiNormalize(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"BaseBoardManufacturer"));
        g_machineIdentity.product = ymccDmiNormalize(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"BaseBoardProduct"));
        g_machineIdentity.systemProduct = ymccDmiNormalize(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"SystemProductName"));
        g_machineIdentity.processor = ymccDmiNormalize(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",
            L"ProcessorNameString"));
        g_machineIdentity.systemVersion = ymccDmiNormalize(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"SystemVersion"));
        g_machineIdentity.family = YmccFamily::Unknown;
        ymccResolveFamily(g_machineIdentity);
        g_machineIdentity.resolved = g_machineIdentity.family != YmccFamily::Unknown;
        appendNativeLifecycleLog("machine-identity", {
            {"manufacturer", g_machineIdentity.manufacturer},
            {"product", g_machineIdentity.product},
            {"systemProduct", g_machineIdentity.systemProduct},
            {"processor", g_machineIdentity.processor},
            {"systemVersion", g_machineIdentity.systemVersion},
            {"family", ymccFamilyName(g_machineIdentity.family)},
            {"deviceClass", g_machineIdentity.deviceClass},
            {"gyroMatrixId", g_machineIdentity.gyroMatrixId},
            {"accelMatrixId", g_machineIdentity.accelMatrixId},
            {"inputHidKey", g_machineIdentity.inputHidKey},
            {"resolved", g_machineIdentity.resolved}
        });
    } catch (...) {
        // Read-only probe must never break startup or sensor input.
    }
    msiNativeForegroundIdentityReady(); // MSI-only event observer; no I/O for other families
}

// ── 掌机专用键机型库（严格照 HC Devices/*.cs，行号锚定 _hc-pinned-round4）──
// 键排序 = HC ButtonFlags 数值序（专属按钮序）：
//   Special(29) < OEM1(30) < OEM2(31) < OEM3(32) < OEM4(33) < OEM5(34) < OEM6(35)
//   < L4(46) < L5(47) < R4(48) < R5(49) < Special2(62)
// 专用键的界面顺序由机型物理布局决定；不以目录下标重编号 OEM/keyId。
// backIndex 为 YMCC 正面透视图键位（1=左上 2=右上 3=左下 4=右下），与后视图左右相反。
enum class OemKeyForm : int { KeyboardVk, HidButton, WmiEvent, Embedded };
struct OemKeyDef {
    const char* keyId;
    const char* label;
    int backIndex;           // 0 = 非背部
    OemKeyForm form;
    bool clickOnly;          // WMI 一次性事件：仅 press/double
};
struct OemCatalogRef { const OemKeyDef* keys; int count; };

// ROG Ally / Ally X（ROGAlly.cs:160-186 OEMChords；204-205 feature 字节；599-623 ConfigureController；
// 23-32 keyMapping + 431-454 HandleEvent：CC/AC/LIB 为 Click 语义 → clickOnly）
// ASUS RC71L E25271 / RC72LA E25272 manuals p14-15: rear-view M1 is
// left, hence front-view M1 right / M2 left, matching the current output.
static const OemKeyDef kRogKeys[] = {
    {"cc", "CC", 0, OemKeyForm::HidButton, true},     // OEM1，keyMapping 166 Click（ROGAlly.cs:26,160-163,449）
    {"ac", "AC", 0, OemKeyForm::HidButton, true},     // OEM2，keyMapping 56 Click（ROGAlly.cs:28,165-168,448）
    {"m1", "M1", 2, OemKeyForm::KeyboardVk, false},   // OEM3，F18 硬件 feature 重映射（ROGAlly.cs:176-180,204-205）
    {"m2", "M2", 1, OemKeyForm::KeyboardVk, false},   // OEM4，F17（ROGAlly.cs:182-186,204-205）
    {"lib", "LIB", 0, OemKeyForm::HidButton, true},   // OEM5，keyMapping 147 Click（ROGAlly.cs:27,170-173,450）
};

// Xbox Ally 2025 (RC73XA/RC73YA): catalog positions use the existing FRONT
// preview with rear paddles shown through it, not the manual REAR-view order.
// ASUS E27431 RC73XA/YA manual p14/p16: Macro1 is rear-view left (front right).
// Preserve M1=F18, M2=F17, persisted key IDs and the accepted virtual outputs.
static const OemKeyDef kRogXbox2025Keys[] = {
    {"cc", "CC", 0, OemKeyForm::HidButton, true},
    {"ac", "AC", 0, OemKeyForm::HidButton, true},
    {"m1", "M1", 2, OemKeyForm::KeyboardVk, false},   // front-view right
    {"m2", "M2", 1, OemKeyForm::KeyboardVk, false},   // front-view left
    {"lib", "LIB", 0, OemKeyForm::HidButton, true},
};

