// Only reviewed legacy deltas change their coordinate frame. Keep their
// calibration records separate from device-only offsets written by old builds.
static const ymcc::hc_model_motion::Recipe* inputCaptureReviewedCalibrationRecipe() noexcept {
    if (g_machineIdentity.family != YmccFamily::Ayanero && g_machineIdentity.family != YmccFamily::OneXPlayer &&
        g_machineIdentity.family != YmccFamily::Minisforum) return nullptr;
    const auto* recipe = ymcc::hc_model_motion::find(g_machineIdentity.deviceClass);
    return recipe && !recipe->identityGyroMatrixId.empty() ? recipe : nullptr;
}

static const ymcc::hc_model_motion::Recipe* inputCaptureExtendedCalibrationRecipe() noexcept {
    if(const auto* generic=inputCaptureGenericHcMotionRecipe(g_machineIdentity))return generic;
    if(inputCaptureDefaultHcMotionIdentity(g_machineIdentity)) return ymcc::hc_default_motion::find(g_machineIdentity.deviceClass);
    if(inputCaptureReviewedCalibrationRecipe() || !inputCaptureHcWindowsLegacyNeeded(g_machineIdentity,false,false)) return nullptr;
    if(const auto* current=ymcc::hc_model_motion::find(g_machineIdentity.deviceClass)) return current;
    const auto* legacy=ymcc::hc_legacy_motion::find(g_machineIdentity.deviceClass,g_machineIdentity.gyroMatrixId,g_machineIdentity.accelMatrixId);
    if(!legacy || legacy->controllerPreferred) return nullptr;
    static constexpr auto converted=[] {
        std::array<ymcc::hc_model_motion::Recipe,std::size(ymcc::hc_legacy_motion::recipes)> rows{};
        for(std::size_t i=0;i<rows.size();++i){const auto& r=ymcc::hc_legacy_motion::recipes[i];rows[i]={r.deviceClass,r.selectorId,r.gyroMatrixId,r.accelMatrixId,r.sourcePath,r.sourceSha256};}
        return rows;
    }();
    return &converted[legacy-std::begin(ymcc::hc_legacy_motion::recipes)];
}
static bool inputCapturePrivateStandardApiBound(const WindowsSensorView& view) {
    const auto& meta=view.metadata;const auto apis=ymcc::sensors::selection::sourceApis({meta.gyroDeviceId,meta.accelDeviceId});
    if(apis!=std::array<std::string,2>{meta.gyroFamily,meta.accelFamily})return false;
    if(apis==std::array<std::string,2>{"winrt","winrt"})return true;
    if(apis!=std::array<std::string,2>{"sensorapi","sensorapi"}||meta.gyroHcLegacyFields||meta.accelHcLegacyFields||
        view.providers[0].empty()||view.providers[0]!=view.providers[1])return false;
    for(unsigned kind=0;kind<2;++kind)if(view.parts[kind].standardSdkLayout!=ymcc::sensors::selection::standardSdkLayout(kind))return false;
    return true;
}
static const ymcc::hc_model_motion::Recipe* inputCapturePrivateOemCalibrationRecipe() noexcept {
    if(!t_windowsProcessingView||!t_windowsProcessingView->privateSource)return nullptr;
    const auto& view=*t_windowsProcessingView;const auto& meta=view.metadata;
    if(!view.coherent||!ymcc::windows_motion::current(view.submission)||!view.submission.captureLease||
        !meta.gyroPresent||!meta.accelPresent||meta.gyroDeviceId.empty()||meta.accelDeviceId.empty()||
        !inputCapturePrivateStandardApiBound(view))return nullptr;
    const auto* recipe=inputCapturePrivateHcMotionSelectorRecipe();
    bool inherited=false;
    if(!recipe){
        if(g_machineIdentity.family!=YmccFamily::Gpd&&g_machineIdentity.family!=YmccFamily::AsusRogAllyClassic&&
            g_machineIdentity.family!=YmccFamily::AsusRogAllyXClassic)return nullptr;
        recipe=ymcc::hc_oem_windows_motion::findLegacy(g_machineIdentity.deviceClass,
            g_machineIdentity.gyroMatrixId,g_machineIdentity.accelMatrixId);
        inherited=true;
    }
    if(!recipe||!g_machineIdentity.resolved||!inputCaptureMotionSelectorBound()||
        g_machineIdentity.gyroMatrixId!=recipe->gyroMatrixId||g_machineIdentity.accelMatrixId!=recipe->accelMatrixId||
        g_hcMotionSelector.deviceClass!=recipe->deviceClass||g_hcMotionSelector.selectorId!=recipe->selectorId||
        g_hcMotionSelector.gyroMatrixId!=recipe->gyroMatrixId||g_hcMotionSelector.accelMatrixId!=recipe->accelMatrixId||
        g_hcMotionSelector.matrixSourceSha256!=recipe->sourceSha256)return nullptr;
    if(inherited)return recipe;
    if(g_machineIdentity.family==YmccFamily::MsiClaw){
        const auto* capability=ymcc::msi_sensor::motionCapability(g_machineIdentity.deviceClass,g_machineIdentity.product);
        return capability&&capability->frozenMatrixSourcesSha256==recipe->sourceSha256?recipe:nullptr;
    }
    const bool xboxX=recipe->deviceClass=="HandheldCompanion.Devices.XboxROGAllyX";
    if(g_machineIdentity.family!=(xboxX?YmccFamily::AsusRogAllyX:YmccFamily::AsusRogAlly)||
        g_machineIdentity.manufacturer!="ASUSTEK COMPUTER INC."||g_machineIdentity.product!=(xboxX?"RC73XA":"RC73YA")||
        g_hcMotionSelector.dmiManufacturer!=g_machineIdentity.manufacturer||
        g_hcMotionSelector.dmiProduct!=g_machineIdentity.product||g_hcMotionSelector.dmiSystemProduct!=g_machineIdentity.systemProduct)return nullptr;
    return recipe;
}
static const ymcc::hc_model_motion::Recipe* inputCaptureSourceQualifiedCalibrationRecipe() noexcept {
    if(const auto* oem=inputCapturePrivateOemCalibrationRecipe())return oem;
    if(const auto* reviewed=inputCaptureReviewedCalibrationRecipe()) return reviewed;
    return inputCaptureExtendedCalibrationRecipe();
}
static bool inputCaptureSourceQualifiedCalibrationBound() {
    if(inputCapturePrivateOemCalibrationRecipe())return true;
    return inputCaptureReviewedCalibrationRecipe()?inputCaptureNewHcMotionSelectorBound():
        inputCaptureExtendedCalibrationRecipe()&&inputCaptureMotionSelectorBound();
}

// The processing scope carries the exact source. A private native capture is
// independent of the default sensor cache; default scopes still prove that
// their retained cache is the currently published default owner.
static bool inputCaptureWindowsCalibrationFrameCurrent(const ymcc::windows_motion::Stamp& sample) {
    if(!ymcc::windows_motion::current(sample))return false;
    if(t_windowsProcessingStamp){
        if(!ymcc::windows_motion::current(*t_windowsProcessingStamp)||
            !ymcc::windows_motion::same(sample,*t_windowsProcessingStamp))return false;
        if(sample.captureLease)return true;
    }
    return g_inputCaptureSink&&sample.activeBinding.get()==&g_inputCaptureSink->activeBindingGeneration;
}

static bool inputCaptureWindowsSourceCalibrationAdmitted(bool wanted,bool gyro,bool accel,
    bool sameProvider,bool finite,const ymcc::windows_motion::Stamp& sample,UINT64 accelGeneration,
    const InputCaptureSensorMeta& meta) {
    // A complete selected Windows source can train without a live pad. This
    // lease belongs only to calibration; physical/output admission stays separate.
    const bool provider=(meta.gyroFamily=="winrt"&&meta.accelFamily=="winrt") ||
        (meta.gyroFamily=="sensorapi"&&meta.accelFamily=="sensorapi");
    return g_realStickTest.enabled&&wanted&&gyro&&accel&&sameProvider&&finite&&provider&&
        meta.gyroPresent&&meta.accelPresent&&!meta.gyroDeviceId.empty()&&!meta.accelDeviceId.empty()&&
        inputCaptureSourceQualifiedCalibrationRecipe()&&inputCaptureSourceQualifiedCalibrationBound()&&
        inputCaptureWindowsCalibrationFrameCurrent(sample)&&
        sample.bindingGeneration==accelGeneration;
}
static std::string inputCapturePrivateCalibrationRequestedKey(const WindowsSensorView& view,const std::string& deviceId) {
    if(!view.privateSource||!t_windowsProcessingStamp)return {};
    const auto& meta=view.metadata;
    if(!view.coherent||!ymcc::windows_motion::current(view.submission)||!view.submission.captureLease||
        !ymcc::windows_motion::same(view.submission,*t_windowsProcessingStamp)||deviceId.empty()||deviceId!=meta.gyroDeviceId||
        !meta.gyroPresent||!meta.accelPresent||meta.accelDeviceId.empty()||!inputCapturePrivateStandardApiBound(view)||
        !inputCaptureWindowsCalibrationFrameCurrent(view.submission))return {};
    const auto* recipe=inputCaptureSourceQualifiedCalibrationRecipe();
    if(!recipe||!inputCaptureSourceQualifiedCalibrationBound())return {};
    const ymcc::sensors::selection::ModelRecipe model{std::string(recipe->deviceClass),std::string(recipe->gyroMatrixId),std::string(recipe->accelMatrixId),
        std::string(recipe->sourceSha256),std::string(recipe->sourceSha256),true,true};
    if(!model.valid()||view.profile!=ymcc::sensors::selection::fingerprint(model))return {};
    const auto key=ymcc::sensors::selection::calibrationKey(model,{meta.gyroDeviceId,meta.accelDeviceId},ymcc::sensors::selection::TransformPolicy::ExplicitCurrentModel);
    return view.calibrationKey==key?key:std::string{};
}
static std::string inputCapturePrivateCalibrationStorageKey(const std::string& deviceId) {
    if(!t_windowsProcessingView||!t_windowsProcessingView->privateSource||
        !ymcc::sensors::view::current(*t_windowsProcessingView)||!t_windowsProcessingView->submission.processingLease)return {};
    return inputCapturePrivateCalibrationRequestedKey(*t_windowsProcessingView,deviceId);
}
static json inputCaptureExtendedCalibrationSourceIdentity(const std::string& deviceId) {
    if(t_windowsProcessingView&&t_windowsProcessingView->privateSource){
        const auto key=inputCapturePrivateCalibrationStorageKey(deviceId);if(key.empty())return nullptr;
        const auto& view=*t_windowsProcessingView;const auto& meta=view.metadata;
        return {{"schema","ymcc-windows-explicit-v1"},{"profile",view.profile},{"storageKey",key},{"transformPolicy","explicit-current-model"},
            {"gyroDeviceId",ymcc::sensors::probe::canonical(meta.gyroDeviceId)},{"accelDeviceId",ymcc::sensors::probe::canonical(meta.accelDeviceId)},{"gyroFamily",meta.gyroFamily},{"accelFamily",meta.accelFamily}};
    }
    const auto* recipe=inputCaptureExtendedCalibrationRecipe();
    if(!recipe || !inputCaptureSourceQualifiedCalibrationBound()) return nullptr;
    const auto meta=inputCaptureSensorMetaSnapshot();
    if(!meta.gyroPresent||!meta.accelPresent||deviceId.empty()||meta.gyroDeviceId!=deviceId||
        meta.accelDeviceId.empty()||meta.gyroFamily.empty()||meta.gyroFamily!=meta.accelFamily) return nullptr;
    return {{"deviceClass",recipe->deviceClass},{"selectorId",recipe->selectorId},{"matrixSourceSha256",recipe->sourceSha256},
        {"gyroMatrixId",recipe->gyroMatrixId},{"accelMatrixId",recipe->accelMatrixId},
        {"gyroDeviceId",meta.gyroDeviceId},{"accelDeviceId",meta.accelDeviceId},
        {"gyroFamily",meta.gyroFamily},{"accelFamily",meta.accelFamily}};
}

static std::string inputCaptureCalibrationStorageKey(const std::string& deviceId) {
    if(t_windowsProcessingView&&t_windowsProcessingView->privateSource)return inputCapturePrivateCalibrationStorageKey(deviceId);
    if (const auto* recipe = inputCaptureReviewedCalibrationRecipe()) {
        if (deviceId.empty()) return {};
        if (!inputCaptureNewHcMotionSelectorBound()) return {};
        return inputCaptureCalibrationKeyUpper(deviceId) + "|YMCC-HC-RESOURCE-V1|" +
            std::string(recipe->selectorId) + "|" + std::string(recipe->sourceSha256);
    }
    if(inputCaptureExtendedCalibrationRecipe()){
        const auto identity=inputCaptureExtendedCalibrationSourceIdentity(deviceId);
        return identity.is_null()?std::string{}:"YMCC-HC-WINDOWS-SOURCE-V1|"+identity.dump();
    }
    return inputCaptureCalibrationKeyUpper(deviceId);
}
static bool inputCaptureLoadCalibration(const std::string& deviceId,
    float& ox, float& oy, float& oz, int& weight, float& confidence,
    const std::string* retainedKey=nullptr,const json* retainedIdentity=nullptr,
    const ymcc::hc_model_motion::Recipe* retainedRecipe=nullptr) {
    const std::string storageKey = retainedKey?*retainedKey:inputCaptureCalibrationStorageKey(deviceId);
    if (storageKey.empty()) return false;
    std::ifstream f(inputCaptureCalibrationJsonPath());
    if (!f) return false;
    json root;
    try { f >> root; } catch (...) { return false; }
    if (!root.is_object()) return false;
    const auto it = root.find(storageKey);
    if (it == root.end() || !it->is_object()) return false;
    if (const auto* recipe = retainedRecipe?retainedRecipe:inputCaptureSourceQualifiedCalibrationRecipe()) {
        for (const auto field : {"matrixId", "matrixSourceSha256", "deviceClass"})
            if (!it->contains(field) || !(*it)[field].is_string()) return false;
        if ((*it)["matrixId"].get_ref<const std::string&>() != recipe->gyroMatrixId || (*it)["matrixSourceSha256"].get_ref<const std::string&>() != recipe->sourceSha256 ||
            (*it)["deviceClass"].get_ref<const std::string&>() != recipe->deviceClass) return false;
        for (const auto field : {"xOffset", "yOffset", "zOffset", "confidence"})
            if (!it->contains(field) || !(*it)[field].is_number() || !std::isfinite((*it)[field].get<float>())) return false;
        if (!it->contains("weight") || !(*it)["weight"].is_number_integer() ||
            (*it)["weight"].get<double>() < 0 || (*it)["weight"].get<double>() > static_cast<double>(std::numeric_limits<int>::max())) return false;
    }
    if(retainedIdentity||inputCaptureExtendedCalibrationRecipe()||(t_windowsProcessingView&&t_windowsProcessingView->privateSource)){
        const auto identity=retainedIdentity?*retainedIdentity:inputCaptureExtendedCalibrationSourceIdentity(deviceId);
        if(identity.is_null()||!it->contains("sourceIdentity")||!(*it)["sourceIdentity"].is_object()||(*it)["sourceIdentity"]!=identity||
            (*it)["confidence"].get<float>()<0||(*it)["confidence"].get<float>()>1) return false;
    }
    ox = it->value("xOffset", 0.0f); oy = it->value("yOffset", 0.0f); oz = it->value("zOffset", 0.0f);
    weight = it->value("weight", 0);
    confidence = it->value("confidence", 0.0f);
    return true;
}
static ymcc::reviewed_calibration::StorageReceipt inputCaptureWriteReviewedCalibration(
    const std::string& storageKey, const ymcc::hc_model_motion::Recipe& recipe,
    float ox, float oy, float oz, int weight, float confidence,
    const std::function<bool()>& sourceCurrent) {
    using Receipt=ymcc::reviewed_calibration::StorageReceipt;
    Receipt result;
    if (storageKey.empty() || weight<0 || !std::isfinite(ox) || !std::isfinite(oy) ||
        !std::isfinite(oz) || !std::isfinite(confidence) || confidence<0 || confidence>1) {
        result.reason="invalid-record"; return result;
    }
    if (!sourceCurrent()) {result.reason="source-retired";return result;}
    struct FileOwner {
        HANDLE value=INVALID_HANDLE_VALUE;
        ~FileOwner(){if(value!=INVALID_HANDLE_VALUE)CloseHandle(value);}
        bool close(){const auto h=value;value=INVALID_HANDLE_VALUE;return h==INVALID_HANDLE_VALUE||CloseHandle(h)!=FALSE;}
    };
    struct TemporaryOwner {
        std::wstring path; bool owned=false;
        ~TemporaryOwner(){if(owned)DeleteFileW(path.c_str());}
    } cleanup;
    // Close the exclusive temporary handle before cleanup attempts deletion.
    FileOwner lock, temporary;
    try {
        const std::filesystem::path target(inputCaptureCalibrationJsonPath());
        if (!target.is_absolute()) {result.reason="invalid-path";return result;}
        std::error_code directoryError;
        std::filesystem::create_directories(target.parent_path(),directoryError);
        if (directoryError) {result.reason="directory-failed";result.error=directoryError.value();return result;}
        const auto lockPath=target.wstring()+L".reviewed.lock";
        lock.value=CreateFileW(lockPath.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_ALWAYS,
            FILE_ATTRIBUTE_TEMPORARY|FILE_FLAG_DELETE_ON_CLOSE,nullptr);
        if (lock.value==INVALID_HANDLE_VALUE) {result.reason="writer-busy-or-lock-failed";result.error=GetLastError();return result;}
        json root=json::object();
        const DWORD attributes=GetFileAttributesW(target.c_str());
        const DWORD attributeError=attributes==INVALID_FILE_ATTRIBUTES?GetLastError():ERROR_SUCCESS;
        const bool existed=attributes!=INVALID_FILE_ATTRIBUTES;
        if (existed) {
            if(attributes&FILE_ATTRIBUTE_DIRECTORY){result.reason="target-is-directory";return result;}
            std::ifstream input(target,std::ios::binary);
            if(!input){result.reason="existing-unreadable";return result;}
            try {input>>root;}catch(...){result.reason="existing-json-invalid";return result;}
            if(!root.is_object()){result.reason="existing-json-not-object";return result;}
        } else if(attributeError!=ERROR_FILE_NOT_FOUND) {
            result.reason="target-query-failed";result.error=attributeError;return result;
        }
        const json original=root;
        root[storageKey]={{"xOffset",ox},{"yOffset",oy},{"zOffset",oz},{"weight",weight},
            {"confidence",confidence},{"thresholdG",2000.0f},{"thresholdA",4.0f},
            {"matrixId",recipe.gyroMatrixId},{"matrixSourceSha256",recipe.sourceSha256},{"deviceClass",recipe.deviceClass}};
        if(inputCaptureExtendedCalibrationRecipe()||(t_windowsProcessingView&&t_windowsProcessingView->privateSource)){
            const auto deviceId=inputCaptureSensorMetaSnapshot().gyroDeviceId;
            const auto identity=inputCaptureExtendedCalibrationSourceIdentity(deviceId);
            if(identity.is_null() || storageKey!=inputCaptureCalibrationStorageKey(deviceId)){result.reason="source-identity-mismatch";return result;}
            root[storageKey]["sourceIdentity"]=identity;
        }
        const std::string content=root.dump(2);
        if(content.size()>(1u<<20)){result.reason="record-file-too-large";return result;}
        static std::atomic<std::uint64_t> sequence{1};
        cleanup.path=target.wstring()+L".reviewed."+std::to_wstring(GetCurrentProcessId())+L"."+
            std::to_wstring(sequence.fetch_add(1,std::memory_order_relaxed))+L".tmp";
        temporary.value=CreateFileW(cleanup.path.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,
            FILE_ATTRIBUTE_NORMAL|FILE_FLAG_WRITE_THROUGH,nullptr);
        if(temporary.value==INVALID_HANDLE_VALUE){result.reason="temporary-create-failed";result.error=GetLastError();return result;}
        cleanup.owned=true;
        DWORD written=0;
        if(!WriteFile(temporary.value,content.data(),static_cast<DWORD>(content.size()),&written,nullptr)||written!=content.size()){
            result.reason="temporary-write-failed";result.error=GetLastError();return result;
        }
        if(!FlushFileBuffers(temporary.value)){result.reason="temporary-flush-failed";result.error=GetLastError();return result;}
        if(!temporary.close()){result.reason="temporary-close-failed";result.error=GetLastError();return result;}
        const auto readEquals=[](const std::filesystem::path& file,const json& expected){
            try {std::ifstream input(file,std::ios::binary);json value;if(!input)return false;input>>value;return value==expected;}catch(...){return false;}
        };
        if(!readEquals(std::filesystem::path(cleanup.path),root)){result.reason="temporary-readback-failed";return result;}
        if(!sourceCurrent()){result.reason="source-retired-before-replace";return result;}
        const DWORD flags=MOVEFILE_WRITE_THROUGH|(existed?MOVEFILE_REPLACE_EXISTING:0);
        if(!MoveFileExW(cleanup.path.c_str(),target.c_str(),flags)){
            result.reason="replace-failed";result.error=GetLastError();
            // An unusual OS failure is not proof that the old target survived.
            // Keep this owned complete snapshot if the old content cannot be verified.
            // Report only its ASCII basename, relative to the calibration directory.
            if(existed&&!readEquals(target,original)){result.recoveryPath=std::filesystem::path(cleanup.path).filename().string();cleanup.owned=false;}
            return result;
        }
        cleanup.owned=false;result.replaced=true;
        result.verified=readEquals(target,root);result.saved=result.verified;
        result.reason=result.saved?"stored-and-read-back":"target-readback-failed";
        return result;
    } catch(...) {result.reason="storage-exception";return result;}
}


static void inputCaptureStoreCalibration(const std::string& deviceId,
    float ox, float oy, float oz, int weight, float confidence) {
    if(const auto* recipe=inputCaptureSourceQualifiedCalibrationRecipe()) {
        const auto key=inputCaptureCalibrationStorageKey(deviceId);
        (void)inputCaptureWriteReviewedCalibration(key,*recipe,ox,oy,oz,weight,confidence,
            [&]{return !key.empty()&&inputCaptureCalibrationStorageKey(deviceId)==key;});
        return;
    }
    const std::string storageKey = inputCaptureCalibrationStorageKey(deviceId);
    if (storageKey.empty()) return;
    json root = json::object();
    {
        std::ifstream f(inputCaptureCalibrationJsonPath());
        if (f) { try { json j; f >> j; if (j.is_object()) root = j; } catch (...) {} }
    }
    root[storageKey] = {
        {"xOffset", ox}, {"yOffset", oy}, {"zOffset", oz}, {"weight", weight},
        {"confidence", confidence},
        {"thresholdG", 2000.0f}, {"thresholdA", 4.0f}
    };
    if (const auto* recipe = inputCaptureReviewedCalibrationRecipe()) {
        root[storageKey]["matrixId"] = recipe->gyroMatrixId;
        root[storageKey]["matrixSourceSha256"] = recipe->sourceSha256;
        root[storageKey]["deviceClass"] = recipe->deviceClass;
    }
    std::ofstream out(inputCaptureCalibrationJsonPath());
    if (out) out << root.dump(2);
}
static std::string g_calibRestoredDeviceId;   // capture tick 单写

// HC GamepadMotion ctor restores stored offsets for a previously seen device
// BEFORE any ProcessMotion call (IMUCalibration + GamepadMotion.cs:52-71:
// HasCalibration -> SetCalibrationOffset -> SetCalibrationMode). g_gm is
// capture-thread-exclusive, so the restore is replayed here once per device id,
// on the first capture tick that observes the gyroDeviceId, strictly BEFORE the
// first ProcessMotion of that device (frame trace ordering, 2026-09-11).
static ymcc::reviewed_calibration::Context g_reviewedCalibrationContext;
static void inputCaptureReviewedCalibrationNoteApplied(const std::string& deviceId,int weight) {
    auto& owner=g_reviewedCalibrationContext.owner;
    owner.handle=g_gm;owner.session=g_gmSessionStart;
    owner.storageKey=inputCaptureCalibrationStorageKey(deviceId);owner.weight=weight;
}

static bool inputCaptureReviewedCalibrationSourceMatches(const ymcc::reviewed_calibration::Source& source,
    const ymcc::windows_motion::Stamp* frame,const InputCaptureSensorMeta* frameMeta,
    const InputCaptureSensorMeta& currentMeta) {
    const auto* recipe=inputCaptureSourceQualifiedCalibrationRecipe();
    return recipe && source.recipe==recipe && g_gmProcessedThisTick && frame && frameMeta &&
        source.handle==g_gm && source.session==g_gmSessionStart && source.power!=0 && source.power==currentPowerGeneration() &&
        inputCaptureWindowsCalibrationFrameCurrent(*frame) && ymcc::windows_motion::current(source.sample) &&
        ymcc::windows_motion::same(*frame,source.sample) &&
        frame->activeBinding.get()==source.sample.activeBinding.get() && frame->bindingGeneration==source.sample.bindingGeneration &&
        inputCaptureSourceQualifiedCalibrationBound() && !source.calibrationKey.empty() &&
        source.calibrationKey==inputCaptureCalibrationStorageKey(source.gyroId) && currentMeta.gyroPresent && currentMeta.accelPresent &&
        !source.gyroId.empty() && !source.accelId.empty() && !source.gyroFamily.empty() && !source.accelFamily.empty() &&
        frameMeta->gyroDeviceId==source.gyroId && frameMeta->accelDeviceId==source.accelId &&
        frameMeta->gyroFamily==source.gyroFamily && frameMeta->accelFamily==source.accelFamily &&
        currentMeta.gyroDeviceId==source.gyroId && currentMeta.accelDeviceId==source.accelId &&
        currentMeta.gyroFamily==source.gyroFamily && currentMeta.accelFamily==source.accelFamily;
}
static ymcc::reviewed_calibration::Source inputCaptureReviewedCalibrationSource(
    const ymcc::windows_motion::Stamp* frame,const InputCaptureSensorMeta* frameMeta) {
    ymcc::reviewed_calibration::Source result;
    if(!frame||!frameMeta)return result;
    result.handle=g_gm;result.session=g_gmSessionStart;result.recipe=inputCaptureSourceQualifiedCalibrationRecipe();
    result.sample=*frame;result.power=currentPowerGeneration();
    result.gyroId=frameMeta->gyroDeviceId;result.accelId=frameMeta->accelDeviceId;
    result.gyroFamily=frameMeta->gyroFamily;result.accelFamily=frameMeta->accelFamily;
    result.calibrationKey=inputCaptureCalibrationStorageKey(frameMeta->gyroDeviceId);
    return result;
}
static void inputCaptureReviewedCalibrationObserve(const ymcc::windows_motion::Stamp* frame,
    const InputCaptureSensorMeta* frameMeta,const InputCaptureSensorMeta& currentMeta) {
    auto& context=g_reviewedCalibrationContext;
    if(!frame||!frameMeta||!g_gmProcessedThisTick||!ymcc::windows_motion::current(*frame)){
        g_autoStillSince=0;g_autoStillLastSteadyTick=0;context.observed=false;return;
    }
    if(context.observed&&inputCaptureReviewedCalibrationSourceMatches(context.lastSource,frame,frameMeta,currentMeta))return;
    g_autoStillSince=0;g_autoStillLastSteadyTick=0;
    const auto source=inputCaptureReviewedCalibrationSource(frame,frameMeta);
    context.observed=inputCaptureReviewedCalibrationSourceMatches(source,frame,frameMeta,currentMeta);
    if(context.observed)context.lastSource=source;
}


static bool inputCaptureReviewedCalibrationSourceCurrent(const ymcc::reviewed_calibration::Source& source) {
    InputCaptureSensorMeta sampled;
    sampled.gyroPresent=sampled.accelPresent=true;
    sampled.gyroDeviceId=source.gyroId;sampled.accelDeviceId=source.accelId;
    sampled.gyroFamily=source.gyroFamily;sampled.accelFamily=source.accelFamily;
    return inputCaptureReviewedCalibrationSourceMatches(source,&source.sample,&sampled,inputCaptureSensorMetaSnapshot());
}

static bool inputCaptureReviewedCalibrationOwnerMatches(const ymcc::reviewed_calibration::Transaction& transaction) {
    const auto& owner=g_reviewedCalibrationContext.owner;
    return transaction.source.handle==g_gm && transaction.source.session==g_gmSessionStart &&
        owner.handle==g_gm && owner.session==g_gmSessionStart && owner.storageKey==transaction.storageKey;
}
static void inputCaptureReviewedCalibrationFinish(const char* reason,
    const ymcc::reviewed_calibration::StorageReceipt& storage,bool applied,bool sourceCurrent) {
    auto& transaction=g_reviewedCalibrationContext.transaction;
    const bool currentAtFinalize=sourceCurrent&&inputCaptureReviewedCalibrationSourceCurrent(transaction.source);
    if(sourceCurrent&&!currentAtFinalize)reason="source-retired-before-finalize";
    sourceCurrent=currentAtFinalize;
    const bool accepted=storage.saved&&applied&&sourceCurrent;
    bool rolledBack=false;
    if(!accepted&&inputCaptureReviewedCalibrationOwnerMatches(transaction)){
        g_gmSetMode(g_gm,0);
        g_gmSetOffset(g_gm,transaction.prior.x,transaction.prior.y,transaction.prior.z,transaction.prior.weight);
        float x=0,y=0,z=0;g_gmGetOffset(g_gm,&x,&y,&z);
        const auto close=[](float a,float b){return std::isfinite(a)&&fabsf(a-b)<=1e-5f*(1+fabsf(b));};
        rolledBack=close(x,transaction.prior.x)&&close(y,transaction.prior.y)&&close(z,transaction.prior.z);
        g_reviewedCalibrationContext.owner.weight=transaction.prior.weight;
        g_autoCalibTrusted.store(rolledBack&&transaction.priorTrusted,std::memory_order_release);
        g_autoCalibFinished.store(rolledBack&&transaction.priorFinished,std::memory_order_release);
    }
    if(accepted){
        auto& owner=g_reviewedCalibrationContext.owner;
        owner.handle=transaction.source.handle;owner.session=transaction.source.session;
        owner.storageKey=transaction.storageKey;owner.weight=static_cast<int>(g_gyroCalibConfidence*10.0f);
        g_autoCalibTrusted.store(true,std::memory_order_release);g_autoCalibFinished.store(true,std::memory_order_release);
    }
    inputCapturePostCalibStatus(g_autoCalibTrusted.load(std::memory_order_acquire)?3:(transaction.fromAuto?1:0));
    const json event={{"ok",accepted},{"saved",storage.saved},{"applied",accepted},{"applyVerified",applied},{"rolledBack",rolledBack},{"sourceCurrent",sourceCurrent},
        {"storageReplaced",storage.replaced},{"storageReadbackVerified",storage.verified},{"storageReason",storage.reason},
        {"storageError",storage.error},{"recoveryPath",storage.recoveryPath},{"reason",reason},{"sourceQualified",true},
        {"confidence",g_gyroCalibConfidence},{"weight",accepted?static_cast<int>(g_gyroCalibConfidence*10.0f):0},
        {"source",transaction.fromAuto?"auto":"manual"},{"deviceId",transaction.source.gyroId},
        {"bindingGeneration",transaction.source.sample.bindingGeneration},{"powerGenerationAtStart",transaction.source.power},
        {"matrixId",transaction.source.recipe?std::string(transaction.source.recipe->gyroMatrixId):std::string{}},
        {"processedTicks",g_gyroCalibProcessedTicks},
        {"offset",{{"x",g_gyroCalibOx},{"y",g_gyroCalibOy},{"z",g_gyroCalibOz}}}};
    appendNativeLifecycleLog("gyro-calibration-result",event);gamepadSerialPostEvent("gyro.calibrate.result",event);
    // Retain this source through ExitManual even if the selected family changes.
    transaction.active=sourceCurrent;g_calibSourceAuto.store(false,std::memory_order_release);
    g_gyroCalibStageAtomic.store(sourceCurrent?GyroCalibStage::ExitManual:GyroCalibStage::None,std::memory_order_release);
}
static void inputCaptureReviewedCalibrationReject(const char* reason) {
    const bool fromAuto=g_calibSourceAuto.exchange(false);
    const json event={{"ok",false},{"saved",false},{"applied",false},{"reason",reason},
        {"sourceQualified",true},{"source",fromAuto?"auto":"manual"},{"confidence",0.0f},{"weight",0},
        {"offset",{{"x",0.0f},{"y",0.0f},{"z",0.0f}}}};
    appendNativeLifecycleLog("gyro-calibration-result",event);gamepadSerialPostEvent("gyro.calibrate.result",event);
    inputCapturePostCalibStatus(g_autoCalibTrusted.load()?3:0);
}
static void inputCaptureReviewedCalibrationTick(const ymcc::windows_motion::Stamp* frame,
    const InputCaptureSensorMeta* frameMeta,const InputCaptureSensorMeta& currentMeta) {
    using namespace ymcc::reviewed_calibration;
    auto& context=g_reviewedCalibrationContext;auto& transaction=context.transaction;
    const auto current=[&]{return inputCaptureReviewedCalibrationSourceMatches(transaction.source,frame,frameMeta,inputCaptureSensorMetaSnapshot());};
    if(g_gyroCalibStageAtomic.load(std::memory_order_acquire)==GyroCalibStage::ExitManual){
        if(current())inputCaptureSensorThreadPost(SensorThreadRequest::Resubscribe);
        g_gyroCalibStageAtomic.store(GyroCalibStage::None,std::memory_order_release);transaction.active=false;return;
    }
    if(transaction.active&&!current()){
        inputCaptureReviewedCalibrationFinish("source-retired",{},false,false);g_gyroCalibRequested.store(false);return;
    }
    // Coalesce repeated requests while allowing the current transaction to advance.
    if(g_gyroCalibRequested.exchange(false)&&!transaction.active){
        const auto source=inputCaptureReviewedCalibrationSource(frame,frameMeta);
        const std::string key=source.gyroId.empty()?std::string{}:inputCaptureCalibrationStorageKey(source.gyroId);
        const bool ownerCurrent=context.owner.handle==g_gm&&context.owner.session==g_gmSessionStart&&context.owner.storageKey==key;
        if(key.empty()||!ownerCurrent||!inputCaptureReviewedCalibrationSourceMatches(source,frame,frameMeta,currentMeta)){
            inputCaptureReviewedCalibrationReject(key.empty()||!inputCaptureReviewedCalibrationSourceMatches(source,frame,frameMeta,currentMeta)?"source-unavailable":"prior-owner-unavailable");return;
        }
        transaction={};transaction.active=true;transaction.source=source;transaction.storageKey=key;
        transaction.fromAuto=g_calibSourceAuto.load();transaction.priorTrusted=g_autoCalibTrusted.load();transaction.priorFinished=g_autoCalibFinished.load();
        transaction.prior.weight=context.owner.weight;
        g_gmGetOffset(g_gm,&transaction.prior.x,&transaction.prior.y,&transaction.prior.z);
        if(!std::isfinite(transaction.prior.x)||!std::isfinite(transaction.prior.y)||!std::isfinite(transaction.prior.z)){
            transaction.active=false;inputCaptureReviewedCalibrationReject("invalid-prior-offset");return;
        }
        g_gyroCalibConfidence=0;g_gyroCalibOx=g_gyroCalibOy=g_gyroCalibOz=0;g_gyroCalibProcessedTicks=0;
        g_gyroCalibMsiSession=false;g_gyroCalibPollWindowMs=ymcc::gyro_calibration::policy(false).pollWindowMs;
        g_gyroCalibSessionBinding=source.sample.bindingGeneration;g_gyroCalibSessionDeviceId=source.gyroId;
        g_gyroCalibStageAtomic.store(GyroCalibStage::Reset);inputCapturePostCalibStatus(2);
    }
    if(!transaction.active)return;
    switch(g_gyroCalibStageAtomic.load(std::memory_order_acquire)){
    case GyroCalibStage::Reset:
        g_gmResetCal(g_gm);g_gyroCalibStageAtomic.store(GyroCalibStage::EnterFusion);break;
    case GyroCalibStage::EnterFusion:
        g_gmSetMode(g_gm,3);g_gyroCalibDeadline=GetTickCount64()+g_gyroCalibPollWindowMs;
        g_gyroCalibStageAtomic.store(GyroCalibStage::PollWait);break;
    case GyroCalibStage::PollWait:
        ++g_gyroCalibProcessedTicks;g_gyroCalibConfidence=g_gmGetConf(g_gm);
        if(!std::isfinite(g_gyroCalibConfidence)||g_gyroCalibConfidence<0||g_gyroCalibConfidence>1){
            inputCaptureReviewedCalibrationFinish("invalid-confidence",{},false,current());break;
        }
        if(g_gyroCalibConfidence>kCalibTrustedConfidence){
            g_gmGetOffset(g_gm,&g_gyroCalibOx,&g_gyroCalibOy,&g_gyroCalibOz);
            if(!std::isfinite(g_gyroCalibOx)||!std::isfinite(g_gyroCalibOy)||!std::isfinite(g_gyroCalibOz)){
                inputCaptureReviewedCalibrationFinish("invalid-offset",{},false,current());break;
            }
            g_gyroCalibStageAtomic.store(GyroCalibStage::ApplyOffset);
        }else if(GetTickCount64()>=g_gyroCalibDeadline)inputCaptureReviewedCalibrationFinish("confidence-not-trusted",{},false,current());
        break;
    case GyroCalibStage::ApplyOffset:{
        const int weight=static_cast<int>(g_gyroCalibConfidence*10.0f);
        const auto storage=inputCaptureWriteReviewedCalibration(transaction.storageKey,*transaction.source.recipe,
            g_gyroCalibOx,g_gyroCalibOy,g_gyroCalibOz,weight,g_gyroCalibConfidence,current);
        bool sourceCurrent=current(),applied=false;
        if(storage.saved&&sourceCurrent){
            g_gmSetMode(g_gm,0);g_gmSetOffset(g_gm,g_gyroCalibOx,g_gyroCalibOy,g_gyroCalibOz,weight);
            float x=0,y=0,z=0;g_gmGetOffset(g_gm,&x,&y,&z);
            const auto close=[](float a,float b){return std::isfinite(a)&&fabsf(a-b)<=1e-5f*(1+fabsf(b));};
            applied=close(x,g_gyroCalibOx)&&close(y,g_gyroCalibOy)&&close(z,g_gyroCalibOz);sourceCurrent=current();
        }
        inputCaptureReviewedCalibrationFinish(!storage.saved?storage.reason.c_str():!sourceCurrent?"source-retired-after-save":!applied?"apply-readback-failed":"committed",
            storage,applied,sourceCurrent);break;
    }
    default:break;
    }
}


static void inputCaptureExtendedCalibrationInvalidateOnce(const InputCaptureSensorMeta& meta) {
    auto& owner=g_reviewedCalibrationContext.owner;
    if(owner.handle==g_gm&&owner.session==g_gmSessionStart&&owner.storageKey.empty()&&
        !g_autoCalibTrusted.load()&&!g_autoCalibFinished.load()) return;
    g_gmSetMode(g_gm,0);g_gmSetOffset(g_gm,0,0,0,0);
    inputCaptureReviewedCalibrationNoteApplied({},0);
    g_autoCalibTrusted.store(false,std::memory_order_release);g_autoCalibFinished.store(false,std::memory_order_release);
    inputCapturePostCalibStatus(0);
    appendNativeLifecycleLog("gyro-calibration-awaiting-current-source",{{"deviceClass",g_machineIdentity.deviceClass},
        {"deviceId",meta.gyroDeviceId},{"accelDeviceId",meta.accelDeviceId},
        {"sensorFamily",meta.gyroFamily},{"accelSensorFamily",meta.accelFamily},
        {"sourceQualified",true},{"sourceCurrent",false},{"calibrationOwner","none"}});
}

static void inputCaptureReviewedCalibrationRestoreOnce(const ymcc::hc_model_motion::Recipe& recipe) {
    const InputCaptureSensorMeta meta=inputCaptureSensorMetaSnapshot();
    const bool extended=inputCaptureExtendedCalibrationRecipe()!=nullptr;
    if(!meta.gyroPresent||meta.gyroDeviceId.empty()||!inputCaptureSourceQualifiedCalibrationBound()){
        if(extended)inputCaptureExtendedCalibrationInvalidateOnce(meta);return;
    }
    const bool sourceIdentity=extended||(t_windowsProcessingView&&t_windowsProcessingView->privateSource);
    const json identity=sourceIdentity?inputCaptureExtendedCalibrationSourceIdentity(meta.gyroDeviceId):json(nullptr);
    const std::string currentKey=sourceIdentity&&identity.is_null()?std::string{}:inputCaptureCalibrationStorageKey(meta.gyroDeviceId);
    if(currentKey.empty()){if(sourceIdentity)inputCaptureExtendedCalibrationInvalidateOnce(meta);return;}
    static std::string restoredDevice;
    static const ymcc::hc_model_motion::Recipe* restoredRecipe=nullptr;
    static std::chrono::steady_clock::time_point restoredSession{};
    const auto scopedFrame=t_windowsProcessingStamp?*t_windowsProcessingStamp:ymcc::windows_motion::Stamp{};
    const bool scoped=t_windowsProcessingStamp!=nullptr;
    if((!scoped||inputCaptureWindowsCalibrationFrameCurrent(scopedFrame))&&
        restoredDevice==meta.gyroDeviceId&&restoredRecipe==&recipe&&restoredSession==g_gmSessionStart&&
        g_reviewedCalibrationContext.owner.handle==g_gm&&g_reviewedCalibrationContext.owner.session==g_gmSessionStart&&
        g_reviewedCalibrationContext.owner.storageKey==currentKey)return;
    const auto retainedOwner=g_inputCaptureSink;
    const auto binding=retainedOwner?retainedOwner->activeBindingGeneration.load(std::memory_order_acquire):0;
    const auto handle=g_gm;const auto session=g_gmSessionStart;const auto power=currentPowerGeneration();
    const auto priorOwner=g_reviewedCalibrationContext.owner;
    const auto ownerUnchanged=[&]{const auto& owner=g_reviewedCalibrationContext.owner;return handle==g_gm&&session==g_gmSessionStart&&
        owner.handle==priorOwner.handle&&owner.session==priorOwner.session&&owner.storageKey==priorOwner.storageKey&&owner.weight==priorOwner.weight;};
    const auto current=[&]{return ownerUnchanged()&&
        (scoped?inputCaptureWindowsCalibrationFrameCurrent(scopedFrame):
            retainedOwner&&retainedOwner==g_inputCaptureSink&&binding!=0&&
            retainedOwner->activeBindingGeneration.load(std::memory_order_acquire)==binding)&&
        power!=0&&currentPowerGeneration()==power&&inputCaptureSourceQualifiedCalibrationRecipe()==&recipe&&
        inputCaptureCalibrationStorageKey(meta.gyroDeviceId)==currentKey;};
    const auto retire=[&]{if(ownerUnchanged()&&(extended||scoped))inputCaptureExtendedCalibrationInvalidateOnce(inputCaptureSensorMetaSnapshot());};
    const bool requireCurrent=extended||scoped;
    if(requireCurrent&&!current()){retire();return;}
    float ox=0,oy=0,oz=0,confidence=0;int weight=0;
    const bool loaded=sourceIdentity?inputCaptureLoadCalibration(meta.gyroDeviceId,ox,oy,oz,weight,confidence,&currentKey,&identity,&recipe):
        inputCaptureLoadCalibration(meta.gyroDeviceId,ox,oy,oz,weight,confidence);
    if(requireCurrent&&!current()){retire();return;}
    g_gmSetOffset(g_gm,loaded?ox:0.0f,loaded?oy:0.0f,loaded?oz:0.0f,loaded?weight:0);g_gmSetMode(g_gm,0);
    if(requireCurrent&&!current()){retire();return;}
    auto& owner=g_reviewedCalibrationContext.owner;
    owner.handle=handle;owner.session=session;owner.storageKey=currentKey;owner.weight=loaded?weight:0;
    const bool trusted=loaded&&(confidence>kCalibTrustedConfidence||weight>=10);
    g_autoCalibTrusted.store(trusted,std::memory_order_release);g_autoCalibFinished.store(trusted,std::memory_order_release);
    inputCapturePostCalibStatus(trusted?3:0);
    appendNativeLifecycleLog(loaded?"gyro-calibration-restored":"gyro-calibration-awaiting-current-recipe",{
        {"deviceId",meta.gyroDeviceId},{"matrixId",recipe.gyroMatrixId},{"matrixSourceSha256",recipe.sourceSha256},
        {"sourceQualified",true},{"loaded",loaded},{"weight",loaded?weight:0},{"confidence",loaded?confidence:0.0f}});
    restoredDevice=meta.gyroDeviceId;restoredRecipe=&recipe;restoredSession=session;
}
static void inputCaptureGyroCalibrationRestoreOnce() {
    if (!g_gm || !g_gmSetOffset || !g_gmSetMode)
        return;
    if (const auto* recipe = inputCaptureSourceQualifiedCalibrationRecipe()) {
        inputCaptureReviewedCalibrationRestoreOnce(*recipe);
        return;
    }
    const InputCaptureSensorMeta meta = inputCaptureSensorMetaSnapshot();
    if (!meta.gyroPresent || meta.gyroDeviceId.empty() ||
        meta.gyroDeviceId == g_calibRestoredDeviceId)
        return;
    float ox = 0.0f, oy = 0.0f, oz = 0.0f;
    int w = 0;
    float conf = 0.0f;
    if (inputCaptureLoadCalibration(meta.gyroDeviceId, ox, oy, oz, w, conf)) {
        g_gmSetOffset(g_gm, ox, oy, oz, w);
        g_gmSetMode(g_gm, 0);               // Manual
        appendNativeLifecycleLog("gyro-calibration-restored", {
            {"deviceId", meta.gyroDeviceId},
            {"offset", {{"x", ox}, {"y", oy}, {"z", oz}}}, {"weight", w},
            {"confidence", conf}
        });
        if (conf > kCalibTrustedConfidence || w >= 10) {
            g_autoCalibTrusted.store(true, std::memory_order_release);
            g_autoCalibFinished.store(true, std::memory_order_release);
            inputCapturePostCalibStatus(3);
        }
    }
    g_calibRestoredDeviceId = meta.gyroDeviceId;
}

// capture tick 内非阻塞推进 HC Calibrate 流程（see commit above）：与
// SensorsManager.Calibrate 同序，但每 tick 一步（不 Sleep、超时用 tick
// 计数），g_gm 保持 capture 线程独占，避免独立校准线程与 bus tick 并发。
static void inputCaptureGyroCalibrationTick(
    const ymcc::windows_motion::Stamp* reviewedFrame=nullptr,const InputCaptureSensorMeta* reviewedMeta=nullptr) {
    if (!g_gm || !g_gmResetCal || !g_gmSetMode || !g_gmGetConf ||
        !g_gmGetOffset || !g_gmSetOffset)
        return;
    // 7.44 修订（2026-09-11）：T2b 消费——persona 切换置位后在此（g_gm
    // capture 线程独占上下文）执行 HC GamepadMotion.Reset 等价复位
    // （ResetGamepadMotion；Madgwick 复位 = Y-2 ymccMadgwickResetOrientation，
    // 等价 HC GamepadMotion.cs:79-82 Reset 同时复位 _madgwick）。置位在
    // lifecycle 线程（persona 转换 inputHostStopLocked 前），消费仅此一处，无竞态。
    if (g_gmResetMotionApi && g_gmSessionResetRequested.exchange(false)) {
        inputCaptureWindowsProcessingRetire(false);
        g_gmResetMotionApi(g_gm);
        g_gmProcessedThisTick=false;g_calibRestoredDeviceId.clear();
        g_reviewedCalibrationContext.owner.storageKey.clear();g_reviewedCalibrationContext.owner.weight=0;
        g_autoCalibTrusted.store(false);g_autoCalibFinished.store(false);
        ymccMadgwickResetOrientation();
        // F7-c（批90 附带）：reason 携带置位方详情（persona-transition / sensor-rebind）。
        const char* resetReason = g_gmSessionResetReason.load(std::memory_order_acquire);
        appendNativeLifecycleLog("gamepad-motion-session-reset", {
            {"reason", resetReason ? resetReason : "unknown"},
            {"hcParity", "GamepadMotion.Reset ResetGamepadMotion + Madgwick reset"}
        });
    }
    // HC ctor restore (SetCalibrationOffset + Manual) 已前移：由
    // inputCaptureGyroCalibrationRestoreOnce() 在首个 ProcessMotion 之前执行，
    // 保证首帧即带校准（HC GamepadMotion.cs:52-71 构造顺序）。
    // 自动校准：没放稳不开始、不扣次数；每轮 5 分钟窗口最多 3 次真正校准；
    // >99% 才存；MSI 最长采样 15s，其余仍为 5s。成功后不再自动打。
    const GyroCalibStage preStage = g_gyroCalibStageAtomic.load(std::memory_order_acquire);
    const bool calibBusy = preStage != GyroCalibStage::None ||
        g_gyroCalibRequested.load(std::memory_order_acquire);
    // Do not overwrite an in-flight calibration with a stale trusted status.
    if (!calibBusy && g_autoCalibTrusted.load(std::memory_order_acquire))
        inputCapturePostCalibStatus(3);
    const InputCaptureSensorMeta autoMeta = inputCaptureSensorMetaSnapshot();
    if(inputCaptureSourceQualifiedCalibrationRecipe() &&
        ((g_realStickTest.autoCalibrate&&!g_autoCalibFinished.load()&&!g_autoCalibTrusted.load())||calibBusy))
        inputCaptureReviewedCalibrationObserve(reviewedFrame,reviewedMeta,autoMeta);
    if (preStage == GyroCalibStage::None &&
        g_realStickTest.autoCalibrate &&
        !g_autoCalibFinished.load(std::memory_order_acquire) &&
        !g_autoCalibTrusted.load(std::memory_order_acquire) &&
        !g_gyroCalibRequested.load(std::memory_order_acquire) &&
        autoMeta.gyroPresent &&
        g_gmProcessedThisTick) {
        const ULONGLONG nowTick = GetTickCount64();
        if (g_autoCalibWindowStart == 0) g_autoCalibWindowStart = nowTick;
        // 滚动窗口（用户裁决 2026-09-29）：原实现窗口到期即 g_autoCalibFinished=true
        // 永久锁死本进程，实测（2026-09-28 导出日志：raw==calOut、无
        // gyro-auto-calibrate-start、UI 恒为「未校准」）导致「打开 YMCC 静止放置一次
        // 就能校准成功」的契约永远无法达成。改为到期即重置预算开下一轮，直到成功。
        if (nowTick - g_autoCalibWindowStart > kAutoCalibWindowMs) {
            g_autoCalibWindowStart = nowTick;
            g_autoCalibAttempts.store(0, std::memory_order_release);
            g_autoStillSince = 0;
            g_autoStillLastSteadyTick = 0;
        }
        const int attempts = g_autoCalibAttempts.load(std::memory_order_acquire);
        if (attempts >= kAutoCalibMaxAttempts) {
            // 本轮预算用尽：保持「未校准」，等窗口滚动后重开一轮（不永久锁死）。
            g_autoStillSince = 0;
            g_autoStillLastSteadyTick = 0;
            inputCapturePostCalibStatus(0);
        } else {
            // g_gmIsSteady（DLL GetAutoCalibrationIsSteady）仅在
            // Stillness|SensorFusion（校准）模式下有意义；本 tick 常态是 HC 默认
            // Manual 模式，该接口恒为 false ⇒ 原实现下 steady 永远不成立、自动校准
            // 永不启动。用已校准三轴幅值之和作启动判据；MSI 静止噪声放宽至
            // <4.0°/s，其余维持 <2.5°/s；3s/250ms/>99% 保存保护不变。
            float sx = 0, sy = 0, sz = 0;
            bool magnitudeSteady = false;
            if (g_gmGetCal) {
                g_gmGetCal(g_gm, &sx, &sy, &sz);
                magnitudeSteady = std::isfinite(sx) && std::isfinite(sy) && std::isfinite(sz) &&
                    (fabsf(sx) + fabsf(sy) + fabsf(sz)) <
                        ymcc::gyro_calibration::policy(g_machineIdentity.family==YmccFamily::MsiClaw).stillMagnitudeDps;
            }
            const bool steady = (g_gmIsSteady && g_gmIsSteady(g_gm)) || magnitudeSteady;
            if (steady) {
                if (g_autoStillSince == 0) g_autoStillSince = nowTick;
                g_autoStillLastSteadyTick = nowTick;
                inputCapturePostCalibStatus(1);
                if (nowTick - g_autoStillSince >= kAutoCalibStillMs) {
                    g_autoCalibAttempts.store(attempts + 1, std::memory_order_release);
                    g_calibSourceAuto.store(true, std::memory_order_release);
                    g_gyroCalibRequested.store(true, std::memory_order_release);
                    g_autoStillSince = 0;
                    g_autoStillLastSteadyTick = 0;
                    appendNativeLifecycleLog("gyro-auto-calibrate-start", {
                        {"attempt", attempts + 1}, {"windowMs", nowTick - g_autoCalibWindowStart}
                    });
                }
            } else if (g_autoStillLastSteadyTick != 0 &&
                       nowTick - g_autoStillLastSteadyTick <= kAutoCalibStillGraceMs) {
                // 抖动容错：瞬时失稳（<=250ms）不重置静止计时。
                inputCapturePostCalibStatus(1);
            } else {
                g_autoStillSince = 0;
                g_autoStillLastSteadyTick = 0;
                inputCapturePostCalibStatus(1);
            }
        }
    } else if (preStage == GyroCalibStage::None &&
               !g_gyroCalibRequested.load(std::memory_order_acquire) &&
               !g_autoCalibTrusted.load(std::memory_order_acquire)) {
        g_autoStillSince = 0;
        g_autoStillLastSteadyTick = 0;
        if (!g_realStickTest.autoCalibrate || !autoMeta.gyroPresent)
            inputCapturePostCalibStatus(0);
    }
    if(inputCaptureSourceQualifiedCalibrationRecipe()||g_reviewedCalibrationContext.transaction.active){
        inputCaptureReviewedCalibrationTick(reviewedFrame,reviewedMeta,autoMeta);
        return;
    }
    if (g_gyroCalibRequested.exchange(false)) {
        g_gyroCalibStageAtomic.store(GyroCalibStage::Reset, std::memory_order_release);
        g_gyroCalibConfidence = 0.0f;
        g_gyroCalibProcessedTicks = 0;
        g_gyroCalibMsiSession = g_machineIdentity.family==YmccFamily::MsiClaw;
        g_gyroCalibPollWindowMs = ymcc::gyro_calibration::policy(g_gyroCalibMsiSession).pollWindowMs;
        g_gyroCalibSessionBinding = g_gyroCalibBindingThisTick;
        g_gyroCalibSessionDeviceId = autoMeta.gyroDeviceId;
        inputCapturePostCalibStatus(2);
    }
    const GyroCalibStage stage = g_gyroCalibStageAtomic.load(std::memory_order_acquire);
    switch (stage) {
        case GyroCalibStage::Reset:
            g_gmResetCal(g_gm);
            g_gyroCalibStageAtomic.store(GyroCalibStage::EnterFusion, std::memory_order_release);
            break;
        case GyroCalibStage::EnterFusion:
            g_gmSetMode(g_gm, 1 | 2);               // Stillness | SensorFusion
            g_gyroCalibDeadline = GetTickCount64() + g_gyroCalibPollWindowMs;
            g_gyroCalibStageAtomic.store(GyroCalibStage::PollWait, std::memory_order_release);
            break;
        case GyroCalibStage::PollWait: {
            const bool sampleUsable = g_gmProcessedThisTick && (!g_gyroCalibMsiSession ||
                (g_gyroCalibFreshPairThisTick && g_gyroCalibSessionBinding!=0 &&
                 g_gyroCalibBindingThisTick==g_gyroCalibSessionBinding &&
                 autoMeta.gyroDeviceId==g_gyroCalibSessionDeviceId));
            if (sampleUsable) ++g_gyroCalibProcessedTicks;
            g_gyroCalibConfidence = (!g_gyroCalibMsiSession || sampleUsable) ? g_gmGetConf(g_gm) : 0.0f;
            if (g_gyroCalibConfidence > kCalibTrustedConfidence || GetTickCount64() >= g_gyroCalibDeadline) {
                g_gmGetOffset(g_gm, &g_gyroCalibOx, &g_gyroCalibOy, &g_gyroCalibOz);
                g_gyroCalibStageAtomic.store(GyroCalibStage::ApplyOffset, std::memory_order_release);
            }
            break;
        }
        case GyroCalibStage::ApplyOffset: {
            const bool sameMsiPair = !g_gyroCalibMsiSession ||
                (g_gmProcessedThisTick && g_gyroCalibFreshPairThisTick && g_gyroCalibSessionBinding!=0 &&
                 g_gyroCalibBindingThisTick==g_gyroCalibSessionBinding &&
                 autoMeta.gyroDeviceId==g_gyroCalibSessionDeviceId && g_gyroCalibProcessedTicks>0);
            const bool trusted = g_gyroCalibConfidence > kCalibTrustedConfidence && sameMsiPair;
            const int weight = static_cast<int>(g_gyroCalibConfidence * 10.0f);
            const bool fromAuto = g_calibSourceAuto.load(std::memory_order_acquire);
            // 用户裁决（2026-09-16）：大于 99% 才存、才套用偏移；不到不覆盖旧零点。
            if (trusted) {
                g_gmSetOffset(g_gm, g_gyroCalibOx, g_gyroCalibOy, g_gyroCalibOz, weight);
                const InputCaptureSensorMeta meta = inputCaptureSensorMetaSnapshot();
                if (meta.gyroPresent && !meta.gyroDeviceId.empty())
                    inputCaptureStoreCalibration(meta.gyroDeviceId, g_gyroCalibOx, g_gyroCalibOy, g_gyroCalibOz, weight, g_gyroCalibConfidence);
                g_autoCalibTrusted.store(true, std::memory_order_release);
                g_autoCalibFinished.store(true, std::memory_order_release);
                inputCapturePostCalibStatus(3);
            } else if (fromAuto) {
                // 自动校准未达 >99%（用户裁决 2026-09-29）：不永久锁死本进程。
                // 本轮预算由 tick 内的滚动窗口管理，这里回到「等待放稳」继续等下一轮。
                inputCapturePostCalibStatus(1);
            } else {
                inputCapturePostCalibStatus(g_autoCalibTrusted.load(std::memory_order_acquire) ? 3 : 0);
            }
            appendNativeLifecycleLog("gyro-calibration-result", {
                {"ok", true}, {"saved", trusted}, {"confidence", g_gyroCalibConfidence}, {"weight", weight},
                {"source", fromAuto ? "auto" : "manual"},
                {"offset", {{"x", g_gyroCalibOx}, {"y", g_gyroCalibOy}, {"z", g_gyroCalibOz}}},
                {"hcFlow", "Reset->Fusion->Poll->Offset->Manual"},
                {"pollWindowMs", g_gyroCalibPollWindowMs}, {"processedTicks", g_gyroCalibProcessedTicks},
                {"sensorPairCurrent", sameMsiPair}, {"msiPolicy", g_gyroCalibMsiSession}
            });
            gamepadSerialPostEvent("gyro.calibrate.result", {{"ok", true},
                {"saved", trusted},
                {"source", fromAuto ? "auto" : "manual"},
                {"confidence", g_gyroCalibConfidence}, {"weight", weight},
                {"offset", {{"x", g_gyroCalibOx}, {"y", g_gyroCalibOy}, {"z", g_gyroCalibOz}}}});
            g_calibSourceAuto.store(false, std::memory_order_release);
            g_gyroCalibStageAtomic.store(GyroCalibStage::ExitManual, std::memory_order_release);
            break;
        }
        case GyroCalibStage::ExitManual:
            g_gmSetMode(g_gm, 0);                   // Manual
            // E4（五十五批 ⑥）：校准成功后重订阅半程——置 Manual 后追加
            // 「仅重订阅不释放」刷新（= E3 Resume 半程，Resubscribe 请求由
            // 专职 STA sensor 线程执行，对象保留）。防御源于 YMCC 冷启动
            // 流退化（校准期 ReadingChanged 可能已 deregistered，offset 不生效），
            // HC 无对应物（SensorsManager.Calibrate 后数据流天然持续）。
            // 批93 回滚：v3 曾改为 Rebind（完全断开重绑）导致回归，恢复 Resubscribe。
            // 验收：校准后 30s 内帧 matrix.gz ≈ raw gz − offset 即时成立。
            inputCaptureSensorThreadPost(SensorThreadRequest::Resubscribe);
            g_gyroCalibStageAtomic.store(GyroCalibStage::None, std::memory_order_release);
            break;
        default:
            break;
    }
}

static void inputCaptureLoadGamepadMotion() {
    if (g_gm) return;
    const std::wstring path = POWER_CONTROL_DIR + L"\\handheldcompanion-runtime\\YMCC-DEVICECORE-20261018-v1\\GamepadMotion.dll";
    g_gmDll = LoadLibraryW(path.c_str());
    if (!g_gmDll) return;
    auto create = (GmCreate)GetProcAddress(g_gmDll, "CreateGamepadMotion");
    g_controllerGmCreate = create;
    g_controllerGmDelete = (GmDelete)GetProcAddress(g_gmDll, "DeleteGamepadMotion");
    g_gmSetMode = (GmSetMode)GetProcAddress(g_gmDll, "SetCalibrationMode");
    g_gmStartCal = (GmStartCal)GetProcAddress(g_gmDll, "StartContinuousCalibration");
    g_gmPauseCal = (GmStartCal)GetProcAddress(g_gmDll, "PauseContinuousCalibration");
    g_gmResetCal = (GmStartCal)GetProcAddress(g_gmDll, "ResetContinuousCalibration");
    g_gmSetOffset = (GmSetOffset)GetProcAddress(g_gmDll, "SetCalibrationOffset");
    g_gmProcess = (GmProcess)GetProcAddress(g_gmDll, "ProcessMotion");
    g_gmGetCal = (GmGet3)GetProcAddress(g_gmDll, "GetCalibratedGyro");
    g_gmGetGravity = (GmGet3)GetProcAddress(g_gmDll, "GetGravity");
    g_gmGetProcessedAcceleration = (GmGet3)GetProcAddress(g_gmDll, "GetProcessedAcceleration");
    g_gmGetOrientation = (GmGet4)GetProcAddress(g_gmDll, "GetOrientation");
    g_gmPlayer = (GmGetSpace)GetProcAddress(g_gmDll, "GetPlayerSpaceGyro");
    g_gmWorld = (GmGetSpace)GetProcAddress(g_gmDll, "GetWorldSpaceGyro");
    g_gmGetOffset = (GmGetOffset)GetProcAddress(g_gmDll, "GetCalibrationOffset");
    g_gmGetConf = (GmGetConf)GetProcAddress(g_gmDll, "GetAutoCalibrationConfidence");
    g_gmIsSteady = (GmIsSteady)GetProcAddress(g_gmDll, "GetAutoCalibrationIsSteady");
    g_gmResetMotionApi = (GmResetGamepadMotionFn)GetProcAddress(g_gmDll, "ResetGamepadMotion");
    if (!create || !g_gmProcess || !g_gmGetCal || !g_gmGetGravity ||
        !g_gmGetProcessedAcceleration || !g_gmGetOrientation ||
        !g_gmSetMode || !g_gmResetCal || !g_gmSetOffset || !g_gmGetOffset) {
        FreeLibrary(g_gmDll); g_gmDll = nullptr; g_gmProcess = nullptr; return;
    }
    g_gm = create();
    if (!g_gm) return;
    // HC TimerManager.Start 于停表启动时开始计时；GM 会话创建即停表启动点。
    g_gmSessionStart = std::chrono::steady_clock::now();
    g_gmLastTick = g_gmSessionStart;
    g_gmLastTickSet = false;
    // GamepadMotion starts in HC's default Manual mode.  Manual mode is a
    // valid runtime state even when no user calibration has been stored; HC
    // does not block MotionManager output until an explicit calibration dialog
    // has completed.  Keep the internal gate open for that zero-offset/manual
    // state and reserve the auto-calibration fields for a future explicit
    // calibration transaction.
    g_gmLocked = true;
    g_gmCalStart = 0;
    g_gmCalibrationStartTick = 0;
    g_gmCalibrationStarted = false;
    g_gmStillCount = 0;
    g_gmCalTimeoutLogged = false;
    g_gmPairUnprovenLogged = false;
    // HC only resets and enters Stillness|SensorFusion from its explicit
    // SensorsManager.Calibrate session after the user is asked to place the
    // device. YMCC has no admitted T11 calibration transaction/identity
    // proof, so loading the DLL must not silently begin calibration.
}

static bool inputCaptureWindowsProcessingRecipeMatches(const ymcc::sensors::processing::Recipe& r) {
    return r.bound&&inputCaptureMotionSelectorBound()&&r.deviceClass==inputCaptureMotionDeviceClass()&&
        r.selector==g_hcMotionSelector.selectorId&&r.gyro==g_hcMotionSelector.gyroMatrixId&&
        r.accel==g_hcMotionSelector.accelMatrixId&&r.digest==g_hcMotionSelector.matrixSourceSha256;
}
static bool inputCaptureWindowsProcessingMetadataMatches(const ymcc::sensors::processing::Metadata& m,const InputCaptureSensorMeta& meta) noexcept {
    return meta.gyroPresent&&meta.accelPresent&&ymcc::sensors::processing::sameId(m.gyroId,meta.gyroDeviceId)&&
        ymcc::sensors::processing::sameId(m.accelId,meta.accelDeviceId)&&m.gyroApi==meta.gyroFamily&&m.accelApi==meta.accelFamily&&
        m.gyroLegacy==(meta.gyroFamily=="sensorapi"&&meta.gyroHcLegacyFields)&&
        m.accelLegacy==(meta.accelFamily=="sensorapi"&&meta.accelHcLegacyFields);
}
// BUS publishes immutable source/model metadata. STA never borrows mutable
// selector state or a GamepadMotion handle. Rebuild only on binding changes.
static void inputCaptureWindowsSelectionPublishContext(const WindowsSensorView* suppliedDefault) {
    using namespace ymcc::sensors;
    try {
        std::optional<WindowsSensorView> owned;if(!suppliedDefault)owned=inputCaptureWindowsDefaultViewSnapshot(false);
        const auto& raw=suppliedDefault?*suppliedDefault:*owned;const auto power=currentPowerGeneration();
        const auto lifetime=g_windowsSourceModuleLifetime.load(std::memory_order_acquire);
        const auto prior=std::atomic_load_explicit(&g_windowsSelectionWorkerContext,std::memory_order_acquire);
        const auto& meta=raw.metadata;const bool admitted=g_inputCaptureReady&&raw.coherent&&ymcc::windows_motion::current(raw.capture)&&
            g_powerLifecycle.load(std::memory_order_acquire)==PowerLifecycle::Ready&&!inputCaptureLegionControllerMotionRoute()&&inputCaptureMotionSelectorBound();
        if(prior&&prior->active->load(std::memory_order_acquire)==admitted&&prior->capture.power==power&&prior->lifetime==lifetime&&
            ymcc::windows_motion::same(prior->capture.binding,raw.capture)&&prior->deviceClass==inputCaptureMotionDeviceClass()&&
            prior->selector==g_hcMotionSelector.selectorId&&prior->gyro==g_hcMotionSelector.gyroMatrixId&&
            prior->accel==g_hcMotionSelector.accelMatrixId&&prior->digest==g_hcMotionSelector.matrixSourceSha256&&
            prior->metadata.gyroDeviceId==meta.gyroDeviceId&&prior->metadata.accelDeviceId==meta.accelDeviceId&&
            prior->metadata.gyroFamily==meta.gyroFamily&&prior->metadata.accelFamily==meta.accelFamily&&
            prior->metadata.gyroHcLegacyFields==meta.gyroHcLegacyFields&&prior->metadata.accelHcLegacyFields==meta.accelHcLegacyFields&&
            prior->metadata.gyroPresent==meta.gyroPresent&&prior->metadata.accelPresent==meta.accelPresent)return;
        if(prior){prior->active->store(false,std::memory_order_release);inputCaptureWindowsSelectionRevokePublication();}
        auto next=std::make_shared<WindowsSelectionWorkerContext>();next->capture={raw.capture,power};next->lifetime=lifetime;next->metadata=meta;
        next->deviceClass=inputCaptureMotionDeviceClass();next->selector=g_hcMotionSelector.selectorId;next->gyro=g_hcMotionSelector.gyroMatrixId;
        next->accel=g_hcMotionSelector.accelMatrixId;next->digest=g_hcMotionSelector.matrixSourceSha256;
        next->revision=prior?prior->revision+1:1;next->active->store(admitted&&next->revision!=0,std::memory_order_release);
        auto pinned=raw;pinned.submission=ymcc::windows_motion::guarded(raw.capture,raw.choice);
        const view::ProcessingScope<InputCaptureSensorMeta> pinDefault(pinned,t_windowsProcessingMeta,t_windowsProcessingStamp,&t_windowsProcessingView);
        InputCaptureSensorMeta prospective;prospective.gyroFamily=prospective.accelFamily="winrt";
        next->model=inputCaptureWindowsSelectionEvidence(json::object(),inputCaptureMotionCapabilityReceipt(prospective,false),
            inputCaptureCandidateMatrixReceipt(prospective),GetTickCount64()).model;
        next->defaultKey=inputCaptureCalibrationStorageKey(meta.gyroDeviceId);
        next->defaultProfile="YMCC-WINDOWS-DEFAULT-OWNER-V1|"+json{{"class",next->deviceClass},{"selector",next->selector},
            {"gyro",next->gyro},{"accel",next->accel},{"digest",next->digest},{"gyroApi",meta.gyroFamily},{"accelApi",meta.accelFamily},
            {"gyroLegacy",meta.gyroFamily=="sensorapi"&&meta.gyroHcLegacyFields},{"accelLegacy",meta.accelFamily=="sensorapi"&&meta.accelHcLegacyFields}}.dump();
        std::atomic_store_explicit(&g_windowsSelectionWorkerContext,std::shared_ptr<const WindowsSelectionWorkerContext>(next),std::memory_order_release);
    }catch(...){const auto prior=std::atomic_load_explicit(&g_windowsSelectionWorkerContext,std::memory_order_acquire);if(prior)prior->active->store(false,std::memory_order_release);inputCaptureWindowsSelectionRevokePublication();}
}
static bool inputCaptureWindowsProcessingInputMatches(const WindowsSensorView& view) {
    const auto& owner=g_windowsProcessingOwner;const auto& id=owner.identity;
    return owner.valid&&owner.lease&&owner.lease->load(std::memory_order_acquire)&&owner.handle==g_gm&&owner.session==g_gmSessionStart&&
        id.power!=0&&id.power==currentPowerGeneration()&&id.privateSource==view.privateSource&&
        id.captureRequest==view.captureRequestId&&id.choiceRequest==view.choiceRequestId&&
        ymcc::windows_motion::sameInput(owner.raw,view.submission)&&inputCaptureWindowsProcessingRecipeMatches(id.recipe)&&
        inputCaptureWindowsProcessingMetadataMatches(id.metadata,view.metadata)&&
        (!view.privateSource||(id.profile==view.profile&&id.key==view.calibrationKey));
}
static bool inputCaptureWindowsProcessingFrameCurrent(const WindowsSensorView& view) noexcept {
    try{return view.coherent&&ymcc::windows_motion::current(view.submission)&&inputCaptureWindowsProcessingInputMatches(view)&&
        ymcc::windows_motion::sameOwner(view.submission.processingLease,g_windowsProcessingOwner.identity.source.processingLease)&&
        (!view.privateSource||view.processingOwnerAccepted);}catch(...){return false;}
}
static void inputCaptureWindowsProcessingAbortCalibration(const char* reason) {
    const bool requested=g_gyroCalibRequested.exchange(false,std::memory_order_acq_rel);
    const bool staged=g_gyroCalibStageAtomic.load(std::memory_order_acquire)!=GyroCalibStage::None;
    if(g_reviewedCalibrationContext.transaction.active)inputCaptureReviewedCalibrationFinish(reason,{},false,false);
    else if(requested||staged)inputCaptureReviewedCalibrationReject(reason);
    g_gyroCalibStageAtomic.store(GyroCalibStage::None,std::memory_order_release);
    g_calibSourceAuto.store(false,std::memory_order_release);
}
static bool inputCaptureWindowsProcessingAdopt(WindowsSensorView& view) noexcept {
    try {
        g_windowsProcessingOwner.hasPending=false;
        const auto unavailable=[&]{view.processingOwnerAccepted=false;const bool wasLive=g_windowsProcessingOwner.valid;
            inputCaptureWindowsProcessingRetire();if(wasLive)inputCaptureWindowsProcessingAbortCalibration("processing-source-unavailable");return false;};
        if(!view.coherent||!ymcc::windows_motion::current(view.submission)||!inputCaptureWindowsCalibrationFrameCurrent(view.submission)||
            !view.metadata.gyroPresent||!view.metadata.accelPresent||view.metadata.gyroDeviceId.empty()||view.metadata.accelDeviceId.empty()||
            !g_gm||!g_gmProcess||!g_gmGetCal||!g_gmSetMode||!g_gmSetOffset||!currentPowerGeneration()||!inputCaptureMotionSelectorBound())return unavailable();
        // Fallback declarations establish no hardware freshness. Require a
        // complete same-provider current dps/g pair before this new route can
        // acquire processing; established exact-model routes keep their policy.
        if(inputCaptureGenericHcMotionRecipe(g_machineIdentity)){
            const auto& gyro=view.parts[0];const auto& accel=view.parts[1];
            const auto provider=view.privateSource?view.providers[0]:inputCaptureSensorProviderKey(view.metadata.gyroDeviceId);
            if(provider.empty()||provider!=(view.privateSource?view.providers[1]:inputCaptureSensorProviderKey(view.metadata.accelDeviceId))||
                view.metadata.gyroFamily!=view.metadata.accelFamily||
                (view.metadata.gyroFamily!="winrt"&&view.metadata.gyroFamily!="sensorapi")||
                !gyro.usable||!accel.usable||gyro.generation!=view.submission.bindingGeneration||
                accel.generation!=view.submission.bindingGeneration||!gyro.timestamp100ns||!accel.timestamp100ns||
                !ymcc::gyro_calibration::freshPair(GetTickCount64(),gyro.receipt,accel.receipt,gyro.sequence,accel.sequence))return unavailable();
            for(const auto& part:view.parts)for(const double axis:part.axes)if(!std::isfinite(axis))return unavailable();
        }
        if(view.privateSource){
            if(!view.submission.captureLease)return unavailable();
            for(const auto& part:view.parts)if(!part.usable||part.generation!=view.submission.bindingGeneration||
                !std::isfinite(part.axes[0])||!std::isfinite(part.axes[1])||!std::isfinite(part.axes[2]))return unavailable();
        }
        if(inputCaptureWindowsProcessingInputMatches(view)){
            view.submission=ymcc::windows_motion::forProcessing(view.submission,g_windowsProcessingOwner.identity.source.processingLease);
            view.processingOwnerAccepted=view.privateSource;return inputCaptureWindowsProcessingFrameCurrent(view);
        }
        // Only raw snapshots can acquire another CPU owner; an old decoration is never replaced.
        if(view.submission.processingLease)return unavailable();
        std::string key=view.privateSource?inputCapturePrivateCalibrationRequestedKey(view,view.metadata.gyroDeviceId):
            inputCaptureCalibrationStorageKey(view.metadata.gyroDeviceId);
        if(view.privateSource&&key.empty())return unavailable();
        const auto& prior=g_windowsProcessingOwner;
        const bool sameSession=prior.handle==g_gm&&prior.session==g_gmSessionStart;
        const bool changedRecipe=!inputCaptureWindowsProcessingRecipeMatches(prior.identity.recipe)||
            !inputCaptureWindowsProcessingMetadataMatches(prior.identity.metadata,view.metadata);
        const bool handoff=view.privateSource||prior.identity.privateSource||prior.mustReset||
            (prior.lease&&(!sameSession||(prior.everProcessed&&changedRecipe)));
        const bool resetNative=(handoff&&sameSession)||view.privateSource;
        if(resetNative&&(!g_gmResetMotionApi||!g_gmResetCal))return unavailable();
        ymcc::sensors::processing::Owner next;auto& id=next.identity;
        id.recipe={inputCaptureMotionDeviceClass(),g_hcMotionSelector.selectorId,g_hcMotionSelector.gyroMatrixId,
            g_hcMotionSelector.accelMatrixId,g_hcMotionSelector.matrixSourceSha256,true};
        id.metadata={view.metadata.gyroDeviceId,view.metadata.accelDeviceId,view.metadata.gyroFamily,view.metadata.accelFamily,
            view.metadata.gyroFamily=="sensorapi"&&view.metadata.gyroHcLegacyFields,
            view.metadata.accelFamily=="sensorapi"&&view.metadata.accelHcLegacyFields};
        id.profile=view.privateSource?view.profile:"YMCC-WINDOWS-DEFAULT-OWNER-V1|"+json{{"class",id.recipe.deviceClass},
            {"selector",id.recipe.selector},{"gyro",id.recipe.gyro},{"accel",id.recipe.accel},{"digest",id.recipe.digest},
            {"gyroApi",id.metadata.gyroApi},{"accelApi",id.metadata.accelApi},{"gyroLegacy",id.metadata.gyroLegacy},{"accelLegacy",id.metadata.accelLegacy}}.dump();
        id.key=std::move(key);id.privateSource=view.privateSource;id.power=currentPowerGeneration();
        id.epoch=g_windowsProcessingEpoch+1;if(!id.epoch)return unavailable();
        id.captureRequest=view.captureRequestId;id.choiceRequest=view.choiceRequestId;
        next.raw=view.submission;next.lease=std::make_shared<std::atomic<bool>>(false);
        id.source=ymcc::windows_motion::forProcessing(next.raw,next.lease);
        if(!id.source.processingLease)return unavailable();
        next.receipt=std::make_shared<ymcc::sensors::processing::ReceiptCache>(id);
        // Everything which allocates is prepared before changing GM or the old calibration.
        inputCaptureWindowsProcessingRetire(false);
        if(handoff){
            inputCaptureWindowsProcessingAbortCalibration("processing-source-changed");
            if(resetNative){g_gmSessionResetRequested.exchange(false,std::memory_order_acq_rel);g_gmResetMotionApi(g_gm);g_gmResetCal(g_gm);}
            ymccMadgwickResetOrientation();
            g_gmSetMode(g_gm,0);g_gmSetOffset(g_gm,0,0,0,0);
            g_reviewedCalibrationContext={};g_calibRestoredDeviceId.clear();
            g_autoCalibTrusted.store(false);g_autoCalibFinished.store(false);g_autoCalibAttempts.store(0);
            g_autoCalibWindowStart=0;g_autoStillSince=0;g_autoStillLastSteadyTick=0;
            g_gyroCalibFreshPairThisTick=false;g_gyroCalibBindingThisTick=0;g_gyroCalibSessionBinding=0;g_gyroCalibSessionDeviceId.clear();
            g_gyroCalibDeadline=0;g_gyroCalibProcessedTicks=0;g_gyroCalibConfidence=0;
            g_gyroCalibOx=g_gyroCalibOy=g_gyroCalibOz=0;g_gmProcessedThisTick=false;
            if(resetNative){g_gmSessionStart=std::chrono::steady_clock::now();g_gmLastTick=g_gmSessionStart;g_gmLastTickSet=false;}
            inputCapturePostCalibStatus(0);
        }
        if(id.power!=currentPowerGeneration()||!ymcc::windows_motion::current(next.raw)||!inputCaptureWindowsProcessingRecipeMatches(id.recipe))return unavailable();
        next.handle=g_gm;next.session=g_gmSessionStart;next.valid=true;
        next.everProcessed=!handoff&&prior.everProcessed;
        g_windowsProcessingEpoch=id.epoch;g_windowsProcessingOwner=std::move(next);
        g_windowsProcessingOwner.lease->store(true,std::memory_order_release);
        view.submission=g_windowsProcessingOwner.identity.source;view.processingOwnerAccepted=view.privateSource;
        return inputCaptureWindowsProcessingFrameCurrent(view);
    }catch(...){view.processingOwnerAccepted=false;inputCaptureWindowsProcessingRetire();return false;}
}
static bool inputCaptureWindowsProcessingProcess(const WindowsSensorView& view,float gx,float gy,float gz,float ax,float ay,float az,float delta) noexcept {
    try {
        auto& owner=g_windowsProcessingOwner;owner.hasPending=false;
        if(!inputCaptureWindowsProcessingFrameCurrent(view)||!g_gmProcess||!std::isfinite(gx)||!std::isfinite(gy)||!std::isfinite(gz)||
            !std::isfinite(ax)||!std::isfinite(ay)||!std::isfinite(az)||!std::isfinite(delta)||delta<0)return false;
        g_gmProcess(g_gm,gx,gy,gz,ax,ay,az,delta);
        if(!inputCaptureWindowsProcessingFrameCurrent(view)){inputCaptureWindowsProcessingRetire();return false;}
        const auto& gyro=view.parts[0];const auto& accel=view.parts[1];
        owner.pending={GetTickCount64(),gyro.sequence,accel.sequence,gyro.receipt,accel.receipt,gyro.timestamp100ns,accel.timestamp100ns,view.submission.publication};
        owner.hasPending=true;return true;
    }catch(...){inputCaptureWindowsProcessingRetire();return false;}
}
static void inputCaptureWindowsProcessingNoteFrame(const WindowsSensorView& view,bool processed) noexcept {
    try {
        if(!inputCaptureWindowsProcessingFrameCurrent(view)){inputCaptureWindowsProcessingRetire(g_windowsProcessingOwner.valid);return;}
        auto& owner=g_windowsProcessingOwner;
        const bool pending=owner.hasPending;owner.hasPending=false;
        if(!processed||!pending)return;
        if(view.privateSource&&(g_reviewedCalibrationContext.owner.handle!=g_gm||g_reviewedCalibrationContext.owner.session!=g_gmSessionStart||
            g_reviewedCalibrationContext.owner.storageKey!=owner.identity.key)){inputCaptureWindowsProcessingRetire();return;}
        const auto& gyro=view.parts[0];const auto& accel=view.parts[1];
        const auto& proof=owner.pending;
        if(!gyro.usable||!accel.usable||!gyro.sequence||!accel.sequence||!gyro.receipt||!accel.receipt||!gyro.timestamp100ns||!accel.timestamp100ns||
            proof.gyroSequence!=gyro.sequence||proof.accelSequence!=accel.sequence||proof.gyroReceipt!=gyro.receipt||proof.accelReceipt!=accel.receipt||
            proof.gyroTimestamp!=gyro.timestamp100ns||proof.accelTimestamp!=accel.timestamp100ns)return;
        owner.receipt->publish(proof);
        if(!inputCaptureWindowsProcessingFrameCurrent(view)){inputCaptureWindowsProcessingRetire();return;}
        owner.everProcessed=true;
        std::atomic_store_explicit(&g_windowsProcessingReceipt,std::shared_ptr<const ymcc::sensors::processing::ReceiptCache>(owner.receipt),std::memory_order_release);
    }catch(...){inputCaptureWindowsProcessingRetire();}
}
static json inputCaptureWindowsProcessingReceiptSnapshot() {
    const auto cache=std::atomic_load_explicit(&g_windowsProcessingReceipt,std::memory_order_acquire);
    const auto receipt=cache?cache->read(GetTickCount64(),currentPowerGeneration()):std::nullopt;
    json result={{"schema",1},{"recorded",bool(cache)},{"currentSamplingAndProcessingLease",bool(receipt)},
        {"verificationScope","actual-processed-input;not-host-or-game-consumption"},{"modelBindingCurrent",nullptr}};
    result["sourcePublicationAllowed"]=nullptr;
    if(receipt){const auto& id=receipt->identity;const auto& frame=receipt->frame;
        auto processedSource=id.source;processedSource.publication=frame.publication;
        result["sourcePublicationAllowed"]=ymcc::windows_motion::currentForOutput(processedSource);
        result["privateSource"]=id.privateSource;result["profile"]=id.profile;result["calibrationKey"]=id.key;
        result["modelClassAtProcessing"]=id.recipe.deviceClass;result["processorEpoch"]=id.epoch;result["powerGeneration"]=id.power;
        result["captureRequestId"]=id.captureRequest;result["choiceRequestId"]=id.choiceRequest;
        result["processedUptimeMs"]=frame.processedTick;result["gyroSequence"]=frame.gyroSequence;result["accelSequence"]=frame.accelSequence;
        result["gyroReceiptUptimeMs"]=frame.gyroReceipt;result["accelReceiptUptimeMs"]=frame.accelReceipt;
    }return result;
}

