static void inputCaptureRetainEvent(HANDLE handle) noexcept {
    if(!handle)return;
    for(auto& value:g_captureRetainedEvents)if(value==handle)return;
    for(auto& value:g_captureRetainedEvents)if(!value){value=handle;return;}
    // The current worker creates at most an MM event plus one waitable timer.
    // An unexpected extra owner is a debt, never permission to claim closure.
    g_captureEventOverflow.store(true,std::memory_order_release);
}
// HC PrecisionTimer executes its action directly from the multimedia-timer
// callback and uses Snapshot.Take/Release to prevent callback re-entry. Keep
// the existing Coordinator tick on that same callback path; the worker thread
// remains only the lifecycle owner and must never become a second scheduler.
static std::mutex g_inputCaptureBusTickMx;
static unsigned long long g_inputCaptureBusTickCount = 0;
// Failed callback try-lock increments outside BUS; window collection is atomic.
static std::atomic<unsigned long long> g_inputCaptureBusBusySkips{0};
static std::chrono::steady_clock::time_point g_inputCaptureBusWindowStart{};
// Monotonic per-tick sequence written into every capture sample (busTick), so
// the tick cadence and any BusySkips gap are directly readable from the
// capture instead of being inferred from the 4x-decimated timestamps.
// Single-writer (capture thread inside inputCaptureBusTick), no lock needed.
static unsigned long long g_inputCaptureBusTickGlobal = 0;

#include "input_timer_evidence.h"
