// GP-BACKKEY-CAPABILITY-2 C3：GPD 背键诊断（只在 BUS tick 帧边界调用；仅 GPD Win5
// profile 生效）。读取 hook 线程写入的纯原子快照，按状态变化边沿触发，落三条白名单
// 事件（gpd-back-chord-state = 物理命中/门变化边沿、gpd-back-chord-match = 语义命中边沿、
// virtual-pad-backbuttons = 最终背键输出边沿）。无周期刷日志：仅边沿。
// C3(R2)：gpdBound/gpdEnabled 写真实状态（此前写死 true）；接口门自身变化亦记录一条
// gpd-back-chord-state（reason=gate-*），使门单独变化可观测。
// 说明：virtual-pad-backbuttons 是 native 帧装配边界观测值，不代表 Host 已提交/
// HIDMaestro 已发送/Steam 已收到。
static const char* gpdChordGateEdgeReason(bool enabledChanged, bool boundChanged,
                                          bool enabled, bool bound) {
    if (enabledChanged && !enabled) return "gate-disabled";
    if (enabledChanged && enabled)  return "gate-enabled";
    if (boundChanged && !bound)     return "gate-iface-lost";
    if (boundChanged && bound)      return "gate-rebound";
    return nullptr;
}
static const char* gpdChordEdgeReason(bool suppressed, int value) {
    if (value != 0) return "press";
    return suppressed ? "masked" : "release";
}
static void gpdChordDiagnosticsTick(int backButtons) {
    static int lastPhysical = 0;
    static int lastState = 0;
    static int lastBackButtons = -1;
    static bool lastEnabled = false;
    static bool lastBound = false;
    static unsigned long long seq = 0;
    if (g_oemBackProfileId.load(std::memory_order_acquire) !=
        static_cast<int>(OemChordProfileId::GpdWin5)) {
        // 非 GPD Win5：复位观测基线，避免切回时误报边沿。
        lastPhysical = 0;
        lastState = 0;
        lastBackButtons = -1;
        lastEnabled = false;
        lastBound = false;
        return;
    }
    const int physical = g_gpdChordSnapPhysical.load(std::memory_order_acquire);
    const uint32_t baseKey = g_gpdChordSnapBaseKey.load(std::memory_order_acquire);
    const uint32_t prefix = g_gpdChordSnapPrefix.load(std::memory_order_acquire);
    const int backState = oemBackMergedDisplayState();
    const bool bound = g_gpdBackIfaceReady.load(std::memory_order_acquire);
    const bool enabled = g_gpdBackEnabledSnap.load(std::memory_order_acquire);
    // C4-R1：键盘通道发布戳是否已过期——用于把"因接口失效而屏蔽"与"真实释放"分开。
    const bool suppressed = g_gpdChordPubGen.load(std::memory_order_acquire) !=
                            g_gpdBackIfaceGen.load(std::memory_order_acquire);
    const char* persona = inputHostPersona();
    const bool enabledChanged = (enabled != lastEnabled);
    const bool boundChanged = (bound != lastBound);
    if (enabledChanged || boundChanged) {
        const char* reason = gpdChordGateEdgeReason(enabledChanged, boundChanged,
                                                    enabled, bound);
        appendNativeLifecycleLog("gpd-back-chord-state", {
            {"deviceClass", g_machineIdentity.deviceClass},
            {"profile", static_cast<int>(OemChordProfileId::GpdWin5)},
            {"gpdBound", bound},
            {"gpdEnabled", enabled},
            {"baseKey", static_cast<unsigned int>(baseKey)},
            {"prefixMask", static_cast<unsigned int>(prefix)},
            {"physicalState", physical},
            {"backState", backState},
            {"backButtons", backButtons},
            {"persona", persona ? persona : ""},
            {"sequence", ++seq},
            {"reason", reason ? reason : "gate-edge"}
        });
    }
    if (physical != lastPhysical) {
        lastPhysical = physical;
        appendNativeLifecycleLog("gpd-back-chord-state", {
            {"deviceClass", g_machineIdentity.deviceClass},
            {"profile", static_cast<int>(OemChordProfileId::GpdWin5)},
            {"gpdBound", bound},
            {"gpdEnabled", enabled},
            {"baseKey", static_cast<unsigned int>(baseKey)},
            {"prefixMask", static_cast<unsigned int>(prefix)},
            {"physicalState", physical},
            {"backState", backState},
            {"backButtons", backButtons},
            {"persona", persona ? persona : ""},
            {"sequence", ++seq},
            {"reason", "physical-edge"}
        });
    }
    if (backState != lastState) {
        lastState = backState;
        appendNativeLifecycleLog("gpd-back-chord-match", {
            {"deviceClass", g_machineIdentity.deviceClass},
            {"profile", static_cast<int>(OemChordProfileId::GpdWin5)},
            {"gpdBound", bound},
            {"gpdEnabled", enabled},
            {"baseKey", static_cast<unsigned int>(baseKey)},
            {"prefixMask", static_cast<unsigned int>(prefix)},
            {"physicalState", physical},
            {"backState", backState},
            {"backButtons", backButtons},
            {"persona", persona ? persona : ""},
            {"sequence", ++seq},
            {"reason", gpdChordEdgeReason(suppressed, backState)}
        });
    }
    if (backButtons != lastBackButtons) {
        lastBackButtons = backButtons;
        appendNativeLifecycleLog("virtual-pad-backbuttons", {
            {"deviceClass", g_machineIdentity.deviceClass},
            {"profile", static_cast<int>(OemChordProfileId::GpdWin5)},
            {"gpdBound", bound},
            {"gpdEnabled", enabled},
            {"baseKey", static_cast<unsigned int>(baseKey)},
            {"prefixMask", static_cast<unsigned int>(prefix)},
            {"physicalState", physical},
            {"backState", backState},
            {"backButtons", backButtons},
            {"persona", persona ? persona : ""},
            {"sequence", ++seq},
            {"reason", gpdChordEdgeReason(suppressed, backButtons)}
        });
    }
    lastEnabled = enabled;
    lastBound = bound;
}

// 批130：档位 → profile 身份的静态映射（建塔期 / bound 期 / 回执共用同一张表）。
static const char* inputHostProfileIdentityOf(const std::string& persona) {
    return ymcc::controllerPersona::profileIdentity(persona);
}
static const char* inputHostProfileIdentity() {
    return inputHostProfileIdentityOf(inputHostConfiguredPersona());
}
// HC tears down the currently bound vTarget before constructing the next
// persona. During teardown settings may already name the next persona, but
// the Host tuple must remain the old one until RELEASE_TARGET/Dispose ends.
// 批130（挖掘回函 §C-①）：会话身份档 = 建塔期"本轮请求档" → 稳态 bound（生效档）
// → 无塔时 live。**回执 / UI / 信封 / tuple 校验读同一份**——消解"回执读 live、
// 建塔读 bound"的双源（缺陷 ①）；建塔成功后 bound = 本轮请求档（缺陷 ② 的修法）。
// 返回 thread_local 缓冲：调用方一律立即拷贝（json、转义器、比较均如此）。
// 批134（裁决令第②项：返回**安全快照**、消除悬空指针，**不引入第二把锁**）：
// 旧实现在兜底分支直接返回 `g_inputHostBoundPersona.c_str()`（**未持锁**），而写者走的是
// `g_inputHostMx`（clear 与绑定写）⇒ 并发 clear 会让调用方手持的指针悬空。
// 现在：读一律在既有 **`g_inputHostPersonaMx`** 内拷进 thread_local 缓冲再返回 c_str()，
// 无塔无建塔时返回**静态字面量**；调用点零改动。锁序 = `g_inputHostMx → g_inputHostPersonaMx`
// （写者先持前者）；反向不存在（持 `g_inputHostPersonaMx` 的代码不再去取 `g_inputHostMx`）。
static const char* inputHostBoundOrCurrentPersona() {
    static thread_local std::string snapshot;
    bool haveBuild = false, haveBound = false;
    {
        std::lock_guard<std::mutex> lock(g_inputHostPersonaMx);
        haveBuild = !g_inputHostBuildPersona.empty();
        haveBound = !g_inputHostBoundPersona.empty();
        if (haveBuild) snapshot = g_inputHostBuildPersona;
        else if (haveBound) snapshot = g_inputHostBoundPersona;
    }
    if (haveBuild || haveBound) return snapshot.c_str();
    return inputHostPersona();          // 锁已释放 ⇒ 其内部自取该锁，不会自锁
}
static const char* inputHostBoundOrCurrentProfileIdentity() {
    static thread_local std::string snapshot;
    bool haveBuild = false, haveBound = false;
    {
        std::lock_guard<std::mutex> lock(g_inputHostPersonaMx);
        haveBuild = !g_inputHostBuildPersona.empty();
        haveBound = !g_inputHostBoundPersona.empty();
        if (haveBuild) snapshot = inputHostProfileIdentityOf(g_inputHostBuildPersona);
        else if (haveBound) snapshot = inputHostProfileIdentityOf(g_inputHostBoundPersona);
    }
    if (haveBuild || haveBound) return snapshot.c_str();
    return inputHostProfileIdentity();
}
// 批134：value 版（给"是否为空"语义或需长期持有的调用方用；同样在锁内拷贝）。
static std::string inputHostBoundPersonaValue() {
    std::lock_guard<std::mutex> lock(g_inputHostPersonaMx);
    return g_inputHostBoundPersona;
}
// 批134：写侧统一入口（**在同一把锁内**赋/清，与读侧同源；调用方仍持各自的 `g_inputHostMx`）。
static void inputHostRefreshPersonaMatchLocked() noexcept {
    g_inputHostRequestedPersonaMatchesBound.store(!g_inputHostBoundPersona.empty() &&
        g_inputHostBoundPersona == g_realStickTest.virtualTargetPersona, std::memory_order_release);
}
static void inputHostSetBoundPersona(const std::string& persona) {
    std::lock_guard<std::mutex> lock(g_inputHostPersonaMx);
    g_inputHostBoundPersona = persona;
    inputHostRefreshPersonaMatchLocked();
}
static void inputHostClearBoundPersona() {
    std::lock_guard<std::mutex> lock(g_inputHostPersonaMx);
    g_inputHostBoundPersona.clear();
    inputHostRefreshPersonaMatchLocked();
}
