enum class InputHostPublicationStage : unsigned {
    Unknown, TargetDisabled, HostUnavailable, PowerNotAdmitted, SourceAbsent,
    MsiSourcePending, ShortcutRecording, NotRunning, BackendFaultHold,
    FreshNeutralWait, Submitting, Rejected, Accepted, NeutralCleanupAccepted
};
static std::atomic<InputHostPublicationStage> g_inputHostPublicationStage{InputHostPublicationStage::Unknown};
static const char* inputHostPublicationStageName(InputHostPublicationStage stage) {
    switch(stage) {
        case InputHostPublicationStage::TargetDisabled:return "virtual-target-disabled";
        case InputHostPublicationStage::HostUnavailable:return "focus-isolation-host-unavailable";
        case InputHostPublicationStage::PowerNotAdmitted:return "power-not-admitted";
        case InputHostPublicationStage::SourceAbsent:return "physical-source-absent";
        case InputHostPublicationStage::MsiSourcePending:return "msi-main-source-unconfirmed";
        case InputHostPublicationStage::ShortcutRecording:return "shortcut-recording";
        case InputHostPublicationStage::NotRunning:return "host-not-running";
        case InputHostPublicationStage::BackendFaultHold:return "backend-fault-hold";
        case InputHostPublicationStage::FreshNeutralWait:return "opening-fresh-neutral";
        case InputHostPublicationStage::Submitting:return "submit-in-flight";
        case InputHostPublicationStage::Rejected:return "host-submit-rejected";
        case InputHostPublicationStage::Accepted:return "host-submit-accepted";
        case InputHostPublicationStage::NeutralCleanupAccepted:return "neutral-only-submit-accepted";
        default:return "unknown";
    }
}
static void msiControllerRepairAppendIdleFields(json& row) {
    if (!msiControllerRepairScope()) return;
    row["freshNeutralAdmitted"]=g_inputHostFreshNeutralAdmitted;
    row["freshNeutralFrames"]=g_inputHostFreshNeutralFrames;
    row["freshNeutralFramesRequired"]=kInputHostFreshNeutralFramesRequired;
    row["freshNeutralMask"]=g_inputHostFreshNeutralMask;
    row["latestPublicationStage"]=inputHostPublicationStageName(g_inputHostPublicationStage.load(std::memory_order_relaxed));
    row["latestPublicationStageScope"]="latest MSI producer decision, not whole-window delivery or external visibility proof";
    const auto rear=g_msiRearAudit.take();
    json held=json::object();
    for(unsigned i=0;i<rear.heldRearStage.size();++i)if(rear.heldRearStage[i])
        held[inputHostPublicationStageName(static_cast<InputHostPublicationStage>(i))]=rear.heldRearStage[i];
    row["msiRearWindow"]={
        {"enabled",rear.enabled},{"physicalSamples",rear.samples},
        {"sourceGenerationFirst",rear.firstGeneration},{"sourceGenerationLast",rear.lastGeneration},
        {"mixedSourceGeneration",rear.mixedGeneration},{"droppedUpdates",rear.dropped},
        {"physicalDownM1M2",rear.physicalDown},{"logicalDownM1M2",rear.logicalDown},
        {"pressEdgesM1M2",rear.press},{"releaseEdgesM1M2",rear.release},
        {"unassignedButtonIndices",{12,13,14}},{"unassignedDown",rear.extraDown},
        {"unassignedPressEdges",rear.extraPress},{"unassignedReleaseEdges",rear.extraRelease},
        {"heldRearDecisions",held},{"submitAttempts",rear.attempts},
        {"submitAccepted",rear.accepted},{"submitRejected",rear.rejected},
        {"attemptRearSlots",rear.attemptRear},{"acceptedRearSlots",rear.acceptedRear},
        {"rearSlotSemantics","Host bit0/bit1;physical side and M1/M2 identity are NOT inferred"},
        {"scope","window aggregates and Host ACK only;not encoded bytes or external delivery"}
    };
}
static json inputHostFreshNeutralAdmissionReceipt(DWORD connectedMask) {
    json row={{"connectedMask",connectedMask},{"frames",g_inputHostFreshNeutralFrames},{"status","admitted"}};
    if (msiControllerRepairScope())
        row["neutralPolicy"]="msi-existing-canonical-admission-only;raw-output-unchanged";
    return row;
}
static void inputHostNotePublicationStage(InputHostPublicationStage stage) {
    // One atomic store at an already-existing producer boundary, no I/O or
    // timers on the BUS. Exposed only by the gated low-rate idle audit.
    if (msiControllerRepairScope()) {
        g_inputHostPublicationStage.store(stage,std::memory_order_relaxed);
        g_msiRearAudit.stage(static_cast<unsigned>(stage),g_msiDinputBackBits.load(std::memory_order_acquire));
    }
}
// Analog admission is governed by the lifecycle neutral gate below. HC emits
// the current ControllerState on every TimerManager tick; it does not wait
// for several identical analog frames before publishing a moving stick.
static XINPUT_GAMEPAD g_inputHostAnalogAnchor{};
static bool g_inputHostAnalogAnchorInitialized = false;
static int g_inputHostAnalogStableFrames = 0;
// Receipt telemetry only.  A release-unproven result is not yet a complete
// quarantine gate; the lifecycle page keeps that recovery boundary UNENCLOSED.
static bool g_inputHostReleaseQuarantined = false;
static std::string g_inputHostLifecycle = "none";
// Set when the open receipt is durable; the publication loop re-emits a lazy
// open receipt once per Host epoch on the first successful frame if the start
// path's receipt was not observed, so every admitted session always leaves an
// audit line (HC surfaces each Connect/status transition).
static std::atomic<uint64_t> g_inputHostOpenReceiptEpoch{0};
// C44.6 virtual-endpoint/backend-fault parity: after a frame-receipt fault no
// automatic rebuild is allowed. Only an explicit intent (user toggles the
// virtual target, or a real power rearm) lifts this hold; stopping the
// repeating 6 s open/stop cycle the Null Driver rebind used to feed.
static std::atomic<bool> g_inputHostFaultHoldsStart{false};
// E4（2026-09-13 用户批）：usbip 后端缺失/装失败提示。0=无 1=缺安装器 2=装失败。
// 只由 PREPARE_TARGET 拒绝明细写入；发布进 gamepad.state，前端弹窗消费后自记 dismissed。
static std::atomic<int> g_backendInstallPrompt{0};
static bool g_inputHostSourceCandidateLogged = false;
static std::string g_inputHostSourceSuppressLoggedRunId;
static ULONGLONG g_inputHostLastPhysicalIdentityCheckTick = 0;
// HC parity (ControllerManager.XUsbDeviceArrived: IsHidden -> Hide(false)):
// a reconnected physical source is re-hidden from the connect path. This
// cooldown bounds re-apply retries after a failed or repeated re-enumeration.
static ULONGLONG g_inputHostReapplyHideLastTick = 0;
static constexpr ULONGLONG kInputHostReapplyHideCooldownMs = 1500;
// 批133（照 CTW `[ClawHideWatchdog] repair {0}/{1}` → `giving up after {0}` 口径；回函 ② 数值
// EverySeconds=5 / MaxRepairs=3）：我方等价物 = 重连物理源的"再隐藏"重打。
// GP-MSIG3E-6 LC-R1（2026-10-03 裁决 YG-LC-04）更正：旧注释称"我方超限只**记账 + 播报**、
// 仍保持 1.5 s 廉价重打"**与实际代码不符**。现行实现为有界停止——预算（每 episode：
// epoch + visibility transaction）耗尽后即置 exhausted 并停写（retryCadence=stopped，
// 不再写第 5 次），仅保留节流只读观察；详见下方重打执行门与 S3 episode 复位注释。
// 因此不再主张与 CTW"超限后停手并粘滞"的分歧：二者超限均停手，差别仅在复位口径。
static int g_inputHostReapplyHideRepairs = 0;
static unsigned long long g_inputHostReapplyHideRepairsEpoch = 0;
static constexpr int kInputHostReapplyGuardMaxRepairs = 4;
// GP-926 S3（裁决 2026-09-26）：预算属于**一次连续可见性失效 episode**（绑定 epoch + visibility
// transaction），不是整个 epoch；只在实际发起过补隐操作时计数（旧实现按"检查次数"记账，且冷却在
// 未执行路径上被反复推迟）。耗尽后停手且只能由"已证健康"或"真实新意图/新受理事务"解除。
static std::string g_inputHostReapplyHideEpisodeKey;
static bool g_inputHostReapplyHideExhausted = false;
static ULONGLONG g_inputHostLastQuarantineProbeTick = 0;
using InputHostMutex = ymcc::inputHost::TransactionMutex<>;
static InputHostMutex g_inputHostMx;
// Host process/driver lifecycle is a blocking side effect. BUS decides that
// reconciliation is needed, then the lifecycle owner executes it after the
// timer callback returns. This keeps HC's 8 ms publication path free of pipe,
// HidHide and PnP waits while preserving one Coordinator owner.
static std::atomic<bool> g_inputHostLifecycleWorkRequested{false};
static std::atomic<bool> g_inputHostLifecycleWorkInFlight{false};
static std::atomic<unsigned long long> g_inputHostPresentationWorkGeneration{0};
static std::mutex g_inputHostLifecycleWorkMx;
static std::deque<std::string> g_inputHostLifecycleWorkQueue;

// ── 批129（operator 裁决 2026-09-25）：切换审计「五值同行」────────────────────
// 只观测，不改切换行为（bind/queue 语义修复等 HC/CT 挖掘结论）。
// 缺陷（本机 2026-09-25 08:57:44.274 实证）：回执 input-host-started 读 **live**
// 配置（inputHostPersona），而建塔信封读 **bound**（inputHostBoundOrCurrentPersona）
// ⇒ 回执会报出从未建出的档（persona:elite 与 PREPARE profile=steam-deck-composite
// 同窗）。判据自此改为五值：请求 / 入队 / 出队 / 下发 profile / 实物 persona。
// 事件级：每轮切换 ≤6 行（request / enqueue / dequeue / throttled / dispatch / settled）。
struct InputHostSwitchAudit {
    std::mutex mx;
    std::string requestedFrom, requestedTo, requestedBound;
    ULONGLONG requestedTick = 0;
    unsigned long long requestedEpoch = 0;
    ULONGLONG enqueuedTick = 0;
    long enqueuedCount = 0;
    ULONGLONG dequeuedTick = 0;
    long deferredCount = 0;
    ULONGLONG dispatchedTick = 0;
    std::string dispatchedPersona, dispatchedProfile;
    // 批130：出队时重读的请求档（"末值合并"的取值时刻）+ 本轮是否尚未收口 + 节流次数。
    std::string requestedAtDequeue;
    bool cycleAwaitingOutcome = false;
    long throttledCount = 0;
    // settle 放回"每项一条"的去重键（settings 线程与 worker 线程都会清 ⇒ 必须同锁）。
    std::string settleLoggedReason;
    ULONGLONG throttleLoggedWindow = 0;
};
static InputHostSwitchAudit g_switchAudit;
static bool inputHostSwitchSettleLogFirst(const std::string& reason) {
    std::lock_guard<std::mutex> lock(g_switchAudit.mx);
    if (g_switchAudit.settleLoggedReason == reason) return false;
    g_switchAudit.settleLoggedReason = reason;
    return true;
}
static void inputHostSwitchSettleLogReset() {
    std::lock_guard<std::mutex> lock(g_switchAudit.mx);
    g_switchAudit.settleLoggedReason.clear();
}
static bool inputHostSwitchAuditApplies(const std::string& reason) {
    return reason == "persona-transition" || reason == "initial-target-admission" ||
        reason == "virtual-target-disabled";
}
// 批130（照挖掘回函 §C-③ 的 targetLabel + vendorId/productId 两列）：档位 → 目标身份 + VID/PID。
// 依据：本仓注释（Elite 045E:0B00 / Edge 054C:0DF2）+ HC VirtualManager.cs:472/476/480 同档常量。
static void inputHostSwitchAuditTargetIds(const std::string& persona, const char** label, const char** vidPid) {
    if (persona == "steamdeck") { *label = "steam-deck-composite"; *vidPid = "28DE:1205"; return; }
    if (persona == "elite") { *label = "xbox-elite-v2"; *vidPid = "045E:0B00"; return; }
    if (persona == "dualsense-edge") { *label = "dualsense-edge"; *vidPid = "054C:0DF2"; return; }
    *label = "disabled"; *vidPid = "";
}
// 批130（挖掘回函 §C-②）：本轮被**跳过**（塔已在请求档上，HC VirtualManager.cs:437-444 同形短路）
// —— 只在本轮是开关类取件（cycleAwaitingOutcome）时落一条，防每次 admission 都写。
static void inputHostSwitchAuditSkipped(const char* reason) {
    std::string requestedAtDequeue;
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        if (!g_switchAudit.cycleAwaitingOutcome) return;
        g_switchAudit.cycleAwaitingOutcome = false;
        requestedAtDequeue = g_switchAudit.requestedAtDequeue;
    }
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "skipped"}, {"reason", reason ? reason : "already-effective"},
        {"requestedAtDequeue", requestedAtDequeue}, {"livePersona", inputHostPersona()},
        {"policy", "hc-idempotent-short-circuit"}
    });
}
// 批130（照挖掘回函 §C-③ 的 throwKind）：本轮**失败**收口（开塔被拒 / 隔离保持）。
static void inputHostSwitchAuditRejected(const char* throwKind) {
    std::string requestedAtDequeue;
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        if (!g_switchAudit.cycleAwaitingOutcome) return;
        g_switchAudit.cycleAwaitingOutcome = false;
        requestedAtDequeue = g_switchAudit.requestedAtDequeue;
    }
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "reject"}, {"throwKind", throwKind ? throwKind : "unknown"},
        {"requestedAtDequeue", requestedAtDequeue},
        {"boundPersona", inputHostBoundOrCurrentPersona()},
        // 批131（照挖掘回函 §C-③"失败"拍 + CT 的有界/终态口径）：YMCC 是"一次尝试 + 故障保持"，
        // 保持 = 需显式换档/重开，因此 attempt=1 / maxAttempts=1 / terminal=true 如实表达。
        {"phase", "open"}, {"stage", throwKind ? throwKind : "unknown"},
        {"attempt", 1}, {"maxAttempts", 1}, {"terminal", true},
        {"policy", "explicit-rearm-required"}
    });
}
// ── 批131：开启/关闭专项九拍（照挖掘回函 §C-③；全部为新增常开行，**不改机制**）──
// 关·拆塔拍（HC `VIIPER device removed (bus,dev)` / CT `VIIPER torn down` 的对应物）。
static void inputHostSwitchAuditDeviceRemoved(const char* reason, const std::string& personaBefore,
                                              ULONGLONG ms, const std::string& disposition,
                                              bool quarantined) {
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "device-removed"}, {"phase", "close"}, {"reason", reason ? reason : "unknown"},
        {"boundPersona", personaBefore.empty() ? std::string("none") : personaBefore},
        {"ms", ms}, {"disposition", disposition}, {"quarantined", quarantined},
        {"plane", "hidmaestro-hid"}   // SteamDeck 走 usbip 复合根；bus/dev 编号无对应（见登记 §105）
    });
}
// 关·正向断言拍（回函 §C-③"关·可见性"，答 §17.5-Q4）：physicalVisible 由**三个实时事实**导出。
static void inputHostSwitchAuditToggleResult(const char* reason, bool ok, ULONGLONG ms,
                                             bool hidhideRestored, bool cloakOn,
                                             unsigned long long connectedMask,
                                             unsigned long long sourceMask) {
    const bool physicalPresent = (connectedMask & sourceMask) != 0;
    const bool physicalVisible = physicalPresent && hidhideRestored && !cloakOn;
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "toggle-result"}, {"phase", "close"}, {"reason", reason ? reason : "unknown"},
        {"ok", ok}, {"ms", ms},
        {"physicalPresent", physicalPresent},
        {"connectedMask", connectedMask}, {"sourceMask", sourceMask},
        {"hidhideRestored", hidhideRestored}, {"cloakOn", cloakOn},
        {"physicalVisible", physicalVisible},
        {"policy", "derived-from-live-facts-not-consumer-proof"}
    });
}
// 开·隐藏拍（照 CT `--cloak-on` / `suppression re-arm` 口径；子步骤明细仍在 hidhide.* 行族）。
