// Host 身份单次快照：try_lock（绝不在持 Host 锁的线程上等锁，也不反向嵌套）。
static bool inputHostSwitchAuditHostContext(std::string* boundOut, unsigned long long* epochOut,
                                            std::string* hostInstanceOut) {
    std::unique_lock<InputHostMutex> lock(g_inputHostMx, std::try_to_lock);
    if (!lock.owns_lock()) return false;
    { const std::string boundSnap = inputHostBoundPersonaValue();   // 批134：同锁快照
        *boundOut = boundSnap.empty() ? std::string("none") : boundSnap; }
    *epochOut = g_inputHostEpoch;
    *hostInstanceOut = g_inputHostHostInstanceId.empty() ? std::string("none")
                                                         : g_inputHostHostInstanceId;
    return true;
}
// ① 请求拍：UI 把新档写进 live 配置的瞬间（早于 BUS 检测与入队）。
static void inputHostSwitchAuditRequest(const std::string& from, const std::string& to) {
    std::string bound = "busy"; unsigned long long epoch = 0; std::string hostInstance = "busy";
    inputHostSwitchAuditHostContext(&bound, &epoch, &hostInstance);
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        g_switchAudit.requestedFrom = from;
        g_switchAudit.requestedTo = to;
        g_switchAudit.requestedBound = bound;
        g_switchAudit.requestedTick = GetTickCount64();
        g_switchAudit.requestedEpoch = epoch;
        g_switchAudit.enqueuedTick = 0;
        g_switchAudit.enqueuedCount = 0;
        g_switchAudit.dequeuedTick = 0;
        g_switchAudit.deferredCount = 0;
        g_switchAudit.dispatchedTick = 0;
        g_switchAudit.dispatchedPersona.clear();
        g_switchAudit.dispatchedProfile.clear();
        g_switchAudit.settleLoggedReason.clear();
    }
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "request"},
        // 批131（照挖掘回函 §C-③"请求"拍）：显式开/关分类 + 原因（关=persona→disabled）。
        {"phase", to == "disabled" ? "close" : "open"},
        {"reason", to == "disabled" ? "persona-disabled" : "persona-set"},
        {"requestedMode", to},
        {"from", from}, {"to", to},
        {"boundPersona", bound}, {"epoch", epoch}, {"hostInstanceId", hostInstance},
        // 批130（照 HC SettingsManager.cs:131 "Settings {0} set to {1}"）：写入点与值同列。
        {"settingsName", "input.outputTarget.persona"}, {"settingsValue", to},
        {"policy", "ui-or-test-config-write"}
    });
}
// ② 入队拍：切换类工作进入生命周期队列（排队不拒绝）。
static void inputHostSwitchAuditEnqueue(const std::string& reason, size_t queueDepth) {
    if (!inputHostSwitchAuditApplies(reason)) return;
    const ULONGLONG now = GetTickCount64();
    ULONGLONG requestedTick = 0; long count = 0;
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        if (g_switchAudit.enqueuedCount == 0) g_switchAudit.enqueuedTick = now;
        ++g_switchAudit.enqueuedCount;
        count = g_switchAudit.enqueuedCount;
        requestedTick = g_switchAudit.requestedTick;
        g_switchAudit.cycleAwaitingOutcome = true;
    }
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "enqueue"}, {"reason", reason},
        {"enqueueCount", count}, {"queueDepth", (unsigned long long)queueDepth},
        {"sinceRequestMs", requestedTick == 0 ? 0ULL : (unsigned long long)(now - requestedTick)}
    });
}
// ③ 出队拍：只有"真的等过"（被 settle 放回）才单写一条；否则信息全在 settled 行。
static void inputHostSwitchAuditDequeued(const std::string& reason) {
    if (!inputHostSwitchAuditApplies(reason)) return;
    const ULONGLONG now = GetTickCount64();
    // 批130（挖掘回函 §C-②"末值合并"的取值时刻）：出队即重读一次请求档——本轮实际要建的
    // 档 = 这一刻的值（排队期间换目标自然折叠成"直接下一轮"，不打断、不丢件）。
    const std::string requestedAtDequeue = std::string(inputHostPersona());
    ULONGLONG enqueuedTick = 0; long deferredCount = 0;
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        g_switchAudit.dequeuedTick = now;
        g_switchAudit.requestedAtDequeue = requestedAtDequeue;
        enqueuedTick = g_switchAudit.enqueuedTick;
        deferredCount = g_switchAudit.deferredCount;
        g_switchAudit.settleLoggedReason.clear();
    }
    if (deferredCount == 0) return;
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "dequeue"}, {"reason", reason},
        {"waitedMs", enqueuedTick == 0 ? 0ULL : (unsigned long long)(now - enqueuedTick)},
        {"deferCount", deferredCount}, {"requestedAtDequeue", requestedAtDequeue}
    });
}
static void inputHostSwitchAuditNoteDefer() {
    std::lock_guard<std::mutex> lock(g_switchAudit.mx);
    ++g_switchAudit.deferredCount;
}
// ④ 准入节流拍：2 s 一次准入尝试的静默跳过（旧形状：请求被无声延后 ≤2 s）。
static void inputHostSwitchAuditThrottled(const char* reason, ULONGLONG waitMs, ULONGLONG windowTick) {
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        if (windowTick != 0 && g_switchAudit.throttleLoggedWindow == windowTick) return;
        g_switchAudit.throttleLoggedWindow = windowTick;
        ++g_switchAudit.throttledCount;
    }
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "throttled"}, {"reason", reason ? reason : "unknown"},
        {"waitMs", waitMs}, {"policy", "one-admission-attempt-per-2s"}
    });
}
// ⑤ 下发拍：PREPARE_TARGET 信封里真正上线的 persona/profile（建塔档的唯一权威值）。
static void inputHostSwitchAuditDispatch(const std::string& persona, const std::string& profile) {
    const ULONGLONG now = GetTickCount64();
    ULONGLONG requestedTick = 0, enqueuedTick = 0;
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        g_switchAudit.dispatchedPersona = persona;
        g_switchAudit.dispatchedProfile = profile;
        g_switchAudit.dispatchedTick = now;
        requestedTick = g_switchAudit.requestedTick;
        enqueuedTick = g_switchAudit.enqueuedTick;
    }
    const char* targetLabel = nullptr; const char* targetVidPid = nullptr;
    inputHostSwitchAuditTargetIds(persona, &targetLabel, &targetVidPid);
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "dispatch"}, {"command", "PREPARE_TARGET"},
        {"persona", persona}, {"profile", profile},
        {"appliedPersona", persona}, {"targetLabel", targetLabel ? targetLabel : "unknown"},
        {"vidPid", targetVidPid ? targetVidPid : "unknown"},
        {"sinceRequestMs", requestedTick == 0 ? 0ULL : (unsigned long long)(now - requestedTick)},
        {"sinceEnqueueMs", enqueuedTick == 0 ? 0ULL : (unsigned long long)(now - enqueuedTick)}
    });
}
// ⑥ 落定拍（五值同行）：回执处调用——builtPersona/builtProfile 是**实物**（信封取值），
// livePersona 是**此刻的请求**，drift = 两者不等（该轮未收敛，需下一轮纠偏）。
// R10-R2 M0（诊断身份补强，不改控制流）：本行必须同时记录**真实 Host 进程 PID**（与
// release receipt 的 hostPid 同一语义）与 run/owner token。native emitter 的通用 `pid`
// （由 appendNativeLifecycleLog 注入 = YMCC 本进程 PID）保持不变；二者语义不同，禁止互比
// （R10-R1 的 39 settled 只能判 ORDER_ONLY 正是缺此字段）。
static void inputHostSwitchAuditSettled(const char* outcome, const std::string& builtPersona,
                                        const std::string& builtProfile, const std::string& livePersona,
                                        unsigned long long epoch, const std::string& hostInstance,
                                        unsigned long long hostPid, const std::string& runId) {
    const ULONGLONG now = GetTickCount64();
    std::string requestedFrom, requestedTo, dispatchedPersona, dispatchedProfile, requestedAtDequeue;
    ULONGLONG requestedTick = 0, enqueuedTick = 0, dispatchedTick = 0;
    long enqueuedCount = 0, deferredCount = 0, throttledCount = 0;
    {
        std::lock_guard<std::mutex> lock(g_switchAudit.mx);
        requestedFrom = g_switchAudit.requestedFrom;
        requestedTo = g_switchAudit.requestedTo;
        dispatchedPersona = g_switchAudit.dispatchedPersona;
        dispatchedProfile = g_switchAudit.dispatchedProfile;
        requestedAtDequeue = g_switchAudit.requestedAtDequeue;
        requestedTick = g_switchAudit.requestedTick;
        enqueuedTick = g_switchAudit.enqueuedTick;
        dispatchedTick = g_switchAudit.dispatchedTick;
        enqueuedCount = g_switchAudit.enqueuedCount;
        deferredCount = g_switchAudit.deferredCount;
        throttledCount = g_switchAudit.throttledCount;
        g_switchAudit.cycleAwaitingOutcome = false;
        g_switchAudit.settleLoggedReason.clear();
    }
    // 批130（挖掘回函 §C-③ busyGate 列）：这一轮被哪道门推迟过（settle / 2 s 准入节流 / 无线）。
    const char* busyGate = deferredCount > 0 ? "settle"
        : (throttledCount > 0 ? "throttle" : "none");
    appendNativeLifecycleLog("input-host-switch-audit", {
        {"beat", "settled"}, {"outcome", outcome ? outcome : "started"},
        {"requestedFrom", requestedFrom}, {"requestedTo", requestedTo},
        {"requestedAtDequeue", requestedAtDequeue},
        {"enqueuedCount", enqueuedCount}, {"deferredCount", deferredCount},
        {"throttledCount", throttledCount}, {"busyGate", busyGate},
        {"dispatchedPersona", dispatchedPersona}, {"dispatchedProfile", dispatchedProfile},
        {"builtPersona", builtPersona}, {"boundPersona", builtPersona},
        {"appliedPersona", builtPersona}, {"builtProfile", builtProfile},
        {"livePersona", livePersona}, {"personaDrift", builtPersona != livePersona},
        // 批130：物理抑制面（CT 的 suppressionTarget）**不由本行承载**——YMCC 的对应物是既有
        // hidhide.* 事件族与 input-host-open-result{physicalVisibility}；本函数位于其声明之前，
        // 不在审计行内重复（字段映射表见登记 §103）。
        {"requestToDispatchMs", (requestedTick != 0 && dispatchedTick != 0)
            ? (unsigned long long)(dispatchedTick - requestedTick) : 0ULL},
        {"dispatchToSettleMs", dispatchedTick != 0 ? (unsigned long long)(now - dispatchedTick) : 0ULL},
        {"waitedMs", enqueuedTick != 0 ? (unsigned long long)(now - enqueuedTick) : 0ULL},
        {"epoch", epoch}, {"hostInstanceId", hostInstance},
        // R10-R2 M0：真实 Host 进程 PID（0 = 本刻无 Host 进程句柄）+ run/owner token。
        // 缺失的 owner token 显式写 UNBOUND（不得留空或沿用上一代）。
        {"hostPid", hostPid},
        {"runId", runId.empty() ? std::string("UNBOUND") : runId},
        {"hostPidSemantics", "host-process-pid-not-native-pid"}
    });
}
// 2026-09-23 W3 批 103（裁决 D-27）：终态闸门状态。终态 = 本进程已进入退出流程
// （beginAsyncExit 首次成功置位 g_exitRequested 之后）：此后**只允许** release / unhide /
// 清理 / 可观测性读取，拒绝新建 Host（新 epoch / PREPARE_TARGET）、重新隐藏物理源、
// persona 重建与普通生命周期任务。
static std::atomic<bool> g_inputHostExitFence{false};
static std::atomic<unsigned long long> g_inputHostExitFenceRefusals{0};
static std::atomic<unsigned long long> g_inputHostExitFenceRefusalRows{0};
// 拒绝行的常开上限：前 N 条逐条落盘（可归因到具体咽喉），其后只累计计数（退出瞬间不刷屏）。
static constexpr unsigned long long kInputHostExitFenceRefusalRowMax = 8;
static bool inputHostExitFenceRaised() {
    return g_inputHostExitFence.load(std::memory_order_acquire);
}
// 终态期间**允许**入队/执行的工作 = 拆塔与恢复类（release / unhide / 清理）；白名单宁可小：
// 不在表内的（keepalive / wake-* / tuple-* / persona-* / initial-target-admission /
// late-hide-after-source-return / power-* / physical-source-reconcile / debug-*）终态一律拒绝。
static bool inputHostLifecycleWorkIsCleanup(const std::string& reason) {
    return reason == "virtual-target-disabled" ||
        reason == "startup-owned-return" ||
        reason == "quarantine-endpoint-absent" ||
        reason == "frame-receipt-fault" ||
        reason.rfind("fault-stop:", 0) == 0;
}
// 终态闸门判定（**纯函数**，生产路径与离线自测共用同一实现，避免自测断言与生产执行漂移）。
static bool inputHostExitFenceBlocks(bool fenceRaised, const std::string& reason) {
    return fenceRaised && !inputHostLifecycleWorkIsCleanup(reason);
}
// 终态拒绝行（常开、事件级）。path = 拒绝发生在哪个咽喉（判据按点核对，避免"某处仍在建"不可见）。
static void inputHostExitFenceLogRefusal(const char* reason, const char* path) {
    const unsigned long long total =
        g_inputHostExitFenceRefusals.fetch_add(1, std::memory_order_acq_rel) + 1;
    if (g_inputHostExitFenceRefusalRows.fetch_add(1, std::memory_order_acq_rel) >=
        kInputHostExitFenceRefusalRowMax) {
        return;
    }
    appendNativeLifecycleLog("input-host-exit-fence", {
        {"phase", "refused"},
        {"reason", reason ? reason : "unknown"},
        {"path", path ? path : "unknown"},
        {"refusals", total},
        {"rowCap", (unsigned long long)kInputHostExitFenceRefusalRowMax},
        {"exitSessionId", g_exitSessionId}   // 批138：拒绝行归属本次退出
    });
}
static bool inputHostLifecycleBusy() {
    return g_inputHostLifecycleWorkRequested.load(std::memory_order_acquire) ||
        g_inputHostLifecycleWorkInFlight.load(std::memory_order_acquire);
}
// Stack-only metadata publication, used only by the registered/armed MSI route.
// The queue owner cannot dequeue this work before its pending token is committed.
struct InputHostLateHideEpisodeKey;
struct InputHostLateHidePublication {
    const InputHostLateHideEpisodeKey* episode;
    const std::string* tuple;
    bool withTupleKey;
    unsigned long long token = 0;
    bool alreadyCompleted = false;
};
static bool inputHostLateHideReuseQueuedPublication(InputHostLateHidePublication* publication,
    bool hasQueuedNotification);
static void inputHostLateHideCommitQueuedPublication(InputHostLateHidePublication* publication);
static bool inputHostQueueLifecycleWorkInternal(const char* reason, bool* coalescedOut,
    InputHostLateHidePublication* msiPublication = nullptr);
// GP-MSIG3E-4F M1：拆机/恢复窗口的 episode 压制（定义在 late-hide 状态层，前向声明供恢复路径使用）。
static void inputHostLateHideSuppressCurrentEpisode(const char* reason);

static bool inputHostQueueLifecycleWork(const char* reason) {
    return inputHostQueueLifecycleWorkInternal(reason, nullptr);
}

// GP-MSIG3E-4F §5：入队结果的**可观测**口径（队尾合并时本函数返回 true 但不新增队列项）。
// coalescedOut（可空）区分"新入队"与"与队尾合并"，供 late-hide-enqueue 事件行使用。
#include "msi_frontkey_observation_runtime.h"

#include "virtual_controller_queued_start_runtime.h"

static bool inputHostQueueLifecycleWorkInternal(const char* reason, bool* coalescedOut,
    InputHostLateHidePublication* msiPublication) {
    if (coalescedOut) *coalescedOut = false;
    const std::string original = reason ? reason : "bus-reconcile";
    const std::string requested = ymcc::inputHost::queuedPlayerStart::bind(original);
    // An expired player start is refused, never enqueued as unbound policy work.
    if (requested.empty()) return false;
    // 2026-09-23 W3 批 103（D-27 终态闸门）：终态后只允许清理类入队；其余在**入队处**拒绝，
    // 并且不写"requested"行（避免出现"排了却没执行"的假象——旧包最迷惑人的形状）。
    if (!msiNativeRearIntentCurrent(original) && inputHostExitFenceBlocks(inputHostExitFenceRaised(), original)) {
        inputHostExitFenceLogRefusal(requested.c_str(), "lifecycle-work-queue");
        return false;
    }
    size_t queueDepth = 0;
    {
        std::lock_guard<std::mutex> lock(g_inputHostLifecycleWorkMx);
        if (msiPublication != nullptr && inputHostLateHideReuseQueuedPublication(msiPublication,
                std::find(g_inputHostLifecycleWorkQueue.begin(), g_inputHostLifecycleWorkQueue.end(),
                    requested) != g_inputHostLifecycleWorkQueue.end())) {
            // Same MSI episode already has a queue or worker owner. Do not
            // rotate its token or create a second transaction during Hide.
            if (coalescedOut) *coalescedOut = !msiPublication->alreadyCompleted;
            return true;
        }
        // Preserve ordered power/source transitions.  A single latest-reason
        // slot could overwrite RELEASE with REARM before the lifecycle owner
        // observed it, leaving an old virtual target alive across sleep.
        if (g_inputHostLifecycleWorkQueue.empty() ||
            g_inputHostLifecycleWorkQueue.back() != requested) {
            g_inputHostLifecycleWorkQueue.push_back(requested);
        } else if (coalescedOut) {
            // 队尾已是同一 reason：不新增队列项，但语义上仍是"已受理"（既有行为不变）。
            *coalescedOut = true;
        }
        queueDepth = g_inputHostLifecycleWorkQueue.size();
        if (msiPublication != nullptr) {
            // Publish under the SAME short queue lock. Even when the BUS is
            // preempted at the clock/pending commit, the owner cannot dequeue
            // an empty item. Preserve notification if metadata copying throws.
            // Lock order is queue -> late-hide state; neither leaf does I/O.
            g_inputHostLifecycleWorkRequested.store(true, std::memory_order_release);
            inputHostLateHideCommitQueuedPublication(msiPublication);
        }
    }
    g_inputHostLifecycleWorkRequested.store(true, std::memory_order_release);
    // 批129「入队拍」：只对切换类工作落行（其余理由保持零审计开销）。
    inputHostSwitchAuditEnqueue(original, queueDepth);
    return true;
}

// GP-MSIG3E-3-R1（R5c）：MSI 模式写**意图**提交。BUS/pump 不再同步做 HID 模式写（那会与事务锁
// 及"切到虚拟目标"的过程交错）——改为把"意图"（含提交时的 Host 代际）交给既有生命周期串行器，
// 由其在生命周期线程按序执行。gen==0（无 Host 会话）时直接拒绝，不入队。
// 绑代际：执行时与当前镜像代际比对，stop/exit 后（或跨代）的过期写入必须拒绝。
// reason 前缀 `msi-mode-write:` 不匹配 inputHostSwitchSettleApplies ⇒ 不会被 settle 延期路径吞掉。
static bool msiDinputObservedXinputReturnAdmitted(ULONGLONG now) {
    ymcc::msi::ModeRecoveryFacts f;
    f.knownBoard=msiClawKnownBoardAuthority();
    f.targetEnabled=g_realStickTest.enabled && g_realStickTest.virtualTargetEnabled;
    f.routeArmed=g_msiDinputRouteDinputArmed.load(std::memory_order_acquire);
    f.routeConfirmed=g_msiDinputRouteConfirmed.load(std::memory_order_acquire);
    f.modeWriteOwned=g_msiDinputReturnOwed.load(std::memory_order_acquire);
    f.exitFence=inputHostExitFenceRaised();
    f.hostEpoch=inputHostEpochToken();
    f.confirmedEpoch=g_msiModeRecoveryConfirmedEpoch.load(std::memory_order_acquire);
    f.observedEpoch=g_msiModeRecoveryObservedEpoch.load(std::memory_order_acquire);
    f.observedTick=g_msiModeRecoveryObservedTick.load(std::memory_order_acquire);
    f.now=now;
    return ymcc::msi::observedXinputReturnAdmitted(f);
}

static ymcc::msi::VirtualWakeFacts msiVirtualWakeFacts(ULONGLONG now) {
    ymcc::msi::VirtualWakeFacts f;
    f.knownBoard=msiClawKnownBoardAuthority();
    f.targetEnabled=g_realStickTest.enabled && g_realStickTest.virtualTargetEnabled;
    f.powerReady=g_inputReady.load(std::memory_order_acquire) &&
        g_powerLifecycle.load(std::memory_order_acquire)==PowerLifecycle::Ready &&
        sgVirtualWriterAllowedNow() && !g_inputHostPowerAdmissionRevoked.load(std::memory_order_acquire);
    f.exitFence=inputHostExitFenceRaised();
    f.generation=g_msiVirtualWakeGeneration.load(std::memory_order_acquire);
    f.currentGeneration=currentPowerGeneration();
    f.armTick=g_msiVirtualWakeArmTick.load(std::memory_order_acquire);f.now=now;
    return f;
}
static bool msiVirtualWakeWaitSource(ULONGLONG now) {
    const auto f=msiVirtualWakeFacts(now);
    return ymcc::msi::virtualWakeMayWaitSource(f,g_msiDinputRouteDinputArmed.load(std::memory_order_acquire),inputHostEpochToken());
}
static MsiDinputRouteWindowAction msiDinputRouteWindowDecideForWake(bool armed,bool confirmed,
    bool resent,ULONGLONG waited,bool observed,ULONGLONG now) {
    const auto action=msiDinputRouteWindowDecide(armed,confirmed,resent,waited,observed);
    if(action!=MsiDinputRouteWindowAction::Revert)return action;
    // VC-LIFECYCLE-20261020-R3 is the sole player-intent deadline. The MSI
    // route's legacy 10s probe window must not switch our physical source back
    // to XInput while that same admitted ON request still awaits DInput.
    // This permits only the existing bounded read/poll path: no mode resend,
    // target create, source publication, fallback quota or deadline is added.
    const auto player=g_virtualStartProtection.view(now);
    const bool playerPending=player.locked && player.requestId && !player.persona.empty() &&
        player.persona!="disabled" && (player.phase=="pending" || player.phase=="verifying");
    if(playerPending && msiClawKnownBoardAuthority() && g_realStickTest.enabled &&
       g_realStickTest.virtualTargetEnabled && !inputHostExitFenceRaised() &&
       !g_exitRequested.load(std::memory_order_acquire) && !g_inputCaptureStop.load(std::memory_order_acquire)) {
        static std::atomic<std::uint64_t> lastRequest{0};
        if(lastRequest.exchange(player.requestId,std::memory_order_acq_rel)!=player.requestId) {
            try {appendNativeLifecycleLog("msi-virtual-start-source-wait",{
                {"lifecycleVersion",ymcc::VirtualStartProtection::lifecycleVersion},
                {"requestId",player.requestId},{"persona",player.persona},
                {"hostEpoch",inputHostEpochToken()},{"waitedMs",waited},
                {"requestElapsedMs",player.elapsedMs},{"remainingMs",player.remainingMs},
                {"modeRetryAdded",false},{"publicationGranted",false},
                {"policy","current-r3-intent-bounded-source-wait"}});}catch(...){}
        }
        return MsiDinputRouteWindowAction::Poll;
    }
    // A wake that preceded this player request cannot lend its separate 60s
    // budget to an expired player intent. A later genuine wake remains owned
    // by its existing power generation and retains its original checks below.
    if(player.requestId && player.phase=="expired") {
        const auto wake=msiVirtualWakeFacts(now);
        const auto admittedAt=now>=player.elapsedMs ? now-player.elapsedMs : now;
        if(!wake.armTick || admittedAt>=wake.armTick)return action;
    }
    if(!msiVirtualWakeWaitSource(now))return action;
    const auto generation=g_msiVirtualWakeGeneration.load(std::memory_order_acquire);
    if(g_msiVirtualWakeSourceWaitLoggedGeneration.exchange(generation,std::memory_order_acq_rel)!=generation)
        appendNativeLifecycleLog("msi-virtual-wake-source-wait",{{"generation",generation},
            {"hostEpoch",inputHostEpochToken()},{"waitedMs",waited},
            {"wakeBudgetMs",ymcc::msi::virtualWakeMaxAgeMs},{"modeRetryAdded",false},
            {"publicationGranted",false},{"policy","authorized-msi-current-wake-bounded-source-wait"}});
    return MsiDinputRouteWindowAction::Poll;
}

static bool msiDinputSubmitModeWriteIntent(bool dinput, const char* reason) {
    const unsigned long long gen = g_inputHostEpochMirror.load(std::memory_order_acquire);
    const char* why = reason != nullptr ? reason : "unspecified";
    if (gen == 0) {
        appendNativeLifecycleLog("msi-claw-gamepad-mode", {
            {"action", "mode-write-intent-refused"},
            {"mode", dinput ? 2 : 1},
            {"reason", why},
            {"generation", 0ULL},
            {"ownerToken", inputHostOwnerToken()},
            {"hostEpoch", inputHostEpochToken()},
            {"policy", "lifecycle-serialized-no-bus-sync-hid-write"}
        });
        return false;
    }
    ymcc::msi::modeTicket::Ticket ticket;
    ticket.dinput=dinput;ticket.host=gen;ticket.power=currentPowerGeneration();
    ticket.mode=g_msiFeedbackModeGeneration.load(std::memory_order_acquire);ticket.reason=why;
    {std::lock_guard<std::mutex> sample(g_msiSampleGate.mutex);ticket.source=g_msiSampleGate.gen;}
    const std::string intent = ymcc::msi::modeTicket::encode(ticket);
    const bool queued = inputHostQueueLifecycleWork(intent.c_str());
    appendNativeLifecycleLog("msi-claw-gamepad-mode", {
        {"action", "mode-write-intent"},
        {"mode", dinput ? 2 : 1},
        {"reason", why},
        {"generation", gen},
        {"ticketVersion", 2}, {"ticketPowerGeneration", ticket.power},
        {"ticketSourceGateGeneration", ticket.source}, {"ticketModeGeneration", ticket.mode},
        {"queued", queued},
        {"ownerToken", inputHostOwnerToken()},
        {"hostEpoch", inputHostEpochToken()},
        {"policy", "lifecycle-serialized-no-bus-sync-hid-write"}
    });
    return queued;
}

// 终态抬闸（幂等，只有第一次生效）：清空已排队的**非清理**工作（清理类保留，让 release/unhide
// 仍能跑完），并落一条常开结果行（含被丢弃任务计数与原因，可归因"谁排的、排了什么"）。
static void inputHostRaiseExitFence(const char* trigger) {
    if (g_inputHostExitFence.exchange(true, std::memory_order_acq_rel)) return;
    unsigned long long dropped = 0;
    unsigned long long keptCleanup = 0, keptSlotCancellation = 0;
    std::string droppedReasons;
    {
        std::lock_guard<std::mutex> lock(g_inputHostLifecycleWorkMx);
        std::deque<std::string> kept;
        for (auto& item : g_inputHostLifecycleWorkQueue) {
            // Keep only an already queued slot-step so its serial owner can
            // cancel the in-memory plan. New slot work remains fence-rejected.
            if (inputHostLifecycleWorkIsCleanup(item)) {
                kept.push_back(item);
                ++keptCleanup;
                continue;
            }
            if (item == "slot0-handoff-step") {
                kept.push_back(item);
                ++keptSlotCancellation;
                continue;
            }
            ++dropped;
            if (droppedReasons.size() < 160) {
                if (!droppedReasons.empty()) droppedReasons += "|";
                droppedReasons += item;
            }
        }
        g_inputHostLifecycleWorkQueue.swap(kept);
        g_inputHostLifecycleWorkRequested.store(!g_inputHostLifecycleWorkQueue.empty(), std::memory_order_release);
    }
    appendNativeLifecycleLog("input-host-exit-fence", {
        {"phase", "raised"},
        {"trigger", trigger ? trigger : "unknown"},
        {"droppedQueued", dropped},
        {"keptCleanupQueued", keptCleanup},
        {"keptSlotCancellationQueued", keptSlotCancellation},
        {"droppedReasons", droppedReasons},
        {"refusals", 0ULL},
        {"exitSessionId", g_exitSessionId}   // 批138：与退出/fan 行同 ID
    });
}

// Fresh-process static state is open. Delayed capture init must never reopen an app-exit fence.
static void inputHostResetExitFence(const char* owner) {
    // The process default is open. Capture initialization may reset diagnostic
    // counters, but must never reopen a terminal fence raised by app exit.
    const bool previousRaised = g_inputHostExitFence.load(std::memory_order_acquire);
    if (previousRaised) {
        appendNativeLifecycleLog("input-host-exit-fence", {
            {"phase", "reset-refused"}, {"reason", "terminal-process-exit"},
            {"previousRaised", true}, {"owner", owner ? owner : "unknown"},
            {"refusals", g_inputHostExitFenceRefusals.load(std::memory_order_acquire)}
        });
        return;
    }
    g_inputHostExitFenceRefusals.store(0, std::memory_order_release);
    g_inputHostExitFenceRefusalRows.store(0, std::memory_order_release);
    appendNativeLifecycleLog("input-host-exit-fence", {
        {"phase", "reset"},
        {"resetScope", "diagnostic-counters-only"},
        {"previousRaised", previousRaised},
        {"owner", owner ? owner : "unknown"},
        {"refusals", 0ULL}
    });
}

