static bool physicalReleaseWindowDutySourceFactsMatch(unsigned sourceSlot, bool pathResolvesToSlot,
                                                      bool noPathEvidence, DWORD physicalMask,
                                                      DWORD sourceMask, DWORD resolvedEpoch,
                                                      unsigned currentEpoch);
static std::vector<std::wstring> hidHideCarriedClaimTargets(const std::vector<std::wstring>& owned,
                                                            const std::vector<std::wstring>& beforeHidden);
static int hidHideCarriedMergeList(std::vector<std::wstring>& owned,
                                   const std::vector<std::wstring>& add);
static bool inputHostRequestAdopted(const char* command, const json& payload, const char* expectedStatus,
                                    DWORD timeoutMs, json* responseOut);
// 注意：默认实参在 15202 的首次声明处给出，此处（更早）声明不重复默认值；自测调用传全参。
static bool inputHostRequestLocked(const char* command, const json& payload, const char* expectedStatus,
                                   DWORD timeoutMs, json* responseOut, bool advanceSequence,
                                   inputHostSelfTestRules::ReceiptObservation* receiptObservationOut);
// GP-GBRETURN-2（B）：后置 helper——关闭刷新在途时 slot0 交接计划只等待（定义在计划结构之后）。
