// ── GP-926R17 R17-1/2/3/4：T1 判定函数（纯逻辑；定义前置，生产路径与离线自测共用同一实现）──
// 延期收回待办：sleep 零设备写（不 Ready=Wait）；fence/Off 由取消分支处理（这里 None）。
enum class PhysicalReleaseWindowDeferredDecision : int { None = 0, Wait = 1, Consume = 2 };
static PhysicalReleaseWindowDeferredDecision physicalReleaseWindowDeferredConsumeDecision(
        int stage, bool deferred, bool powerReady, bool revoked, bool fence, bool targetDisabled,
        ULONGLONG now, ULONGLONG retryAt) {
    if (!deferred || (stage != 1 && stage != 2)) return PhysicalReleaseWindowDeferredDecision::None;
    if (fence || targetDisabled) return PhysicalReleaseWindowDeferredDecision::None;
    if (!powerReady || revoked) return PhysicalReleaseWindowDeferredDecision::Wait;
    if (retryAt != 0 && now < retryAt) return PhysicalReleaseWindowDeferredDecision::Wait;
    return PhysicalReleaseWindowDeferredDecision::Consume;
}
// 取消分类：1=已在窗口（直接清）；2=收回在途（在途 Close 自己收尾，只撤待办/中性）；
// 3=开启在途（标记取消，open 完成处丢弃并清内存）；其余=None。
enum class PhysicalReleaseWindowCancelAction : int {
    None = 0, Cleared = 1, WaitInFlight = 2, AbortInFlightOpen = 3
};
static PhysicalReleaseWindowCancelAction physicalReleaseWindowCancelFromStage(
        int stage, int transition, bool deferred) {
    if (stage == 1) return PhysicalReleaseWindowCancelAction::Cleared;
    if (stage == 2 && transition == 2)
        return deferred ? PhysicalReleaseWindowCancelAction::Cleared
                        : PhysicalReleaseWindowCancelAction::WaitInFlight;
    if (stage == 2 && transition == 1) return PhysicalReleaseWindowCancelAction::AbortInFlightOpen;
    return PhysicalReleaseWindowCancelAction::None;
}
// R17-4 纯逻辑：去重 + 归属校验（(target, root) 已解析；root 空=未解析）。
struct PhysicalReleaseCyclePlan {
    std::vector<std::wstring> send;
    int duplicateSuppressed = 0;
    int unresolved = 0;
    int foreign = 0;
};
static PhysicalReleaseCyclePlan physicalReleaseWindowCyclePlan(
        const std::vector<std::pair<std::wstring, std::wstring>>& targetRoots,
        const std::wstring& ownedRoot) {
    PhysicalReleaseCyclePlan plan;
    for (const auto& entry : targetRoots) {
        const std::wstring& root = entry.second;
        if (root.empty()) { ++plan.unresolved; continue; }
        if (!ownedRoot.empty() && _wcsicmp(root.c_str(), ownedRoot.c_str()) != 0) { ++plan.foreign; continue; }
        bool dup = false;
        for (const auto& s : plan.send) {
            if (_wcsicmp(s.c_str(), root.c_str()) == 0) { dup = true; break; }
        }
        if (dup) { ++plan.duplicateSuppressed; continue; }
        plan.send.push_back(root);
    }
    return plan;
}
// ── GP-GBRETURN-1（裁决 M1/M2/M3/M5，2026-09-27）：关闭归还事务判定（纯逻辑；生产与离线自测共用）──
// 已证缺口（裁决 §3 源码探针，冻结前像）：旧 Close 把"隐藏名单写回成功"当唯一结算依据——
// 配置成功即销账（CONFIG_ONLY_RETIRES_BORROW=1）、隐藏失败也销账（HIDE_FAILURE_ALSO_DROPS_BORROW=1），
// 且从不做设备侧刷新 ⇒ 借用期已在消费者（Steam/Game Bar）打开的物理手柄**旧连接从未失效**。
// 本事务把"归还"拆成显式事实：配置已写回（含一次预算内补试）/ 刷新已发起并结算 /
// 同源采集已恢复 / 中性门已释放（释放与结算分开，且受 2s 绝对预算约束——不得永久压帧）。
enum class PhysicalCloseDutyVerdict : int { Retired = 0, InFlight = 1, TerminalUnresolved = 2 };
static PhysicalCloseDutyVerdict physicalReleaseWindowCloseDutyVerdict(
        bool configRestored, int refreshState, bool refreshOk,
        bool sourceReacquired, bool late) {
    if (!configRestored) return PhysicalCloseDutyVerdict::TerminalUnresolved;   // 隐藏/读回未恢复：不假成功
    if (refreshState == 0) return PhysicalCloseDutyVerdict::TerminalUnresolved; // 刷新未发起（无根/忙/无预算）
    if (refreshState == 1)                 // 在途：未到观察上限 ⇒ 继续等；到点 ⇒ 明确终态（不重发）
        return late ? PhysicalCloseDutyVerdict::TerminalUnresolved
                    : PhysicalCloseDutyVerdict::InFlight;
    if (!refreshOk) return PhysicalCloseDutyVerdict::TerminalUnresolved;        // 刷新动作明确失败
    if (!sourceReacquired)                 // 刷新已结算但仍等同源采集回归
        return late ? PhysicalCloseDutyVerdict::TerminalUnresolved
                    : PhysicalCloseDutyVerdict::InFlight;
    return PhysicalCloseDutyVerdict::Retired;                                   // 四事实齐备 = 真收回
}
// 中性门释放：与清理结算**分开**——刷新未结算也只在本次 2s 绝对预算到点时释放（不永久压帧）。
static bool physicalReleaseWindowNeutralReleaseDue(bool refreshSettled, ULONGLONG now,
                                                   ULONGLONG budgetDeadline) {
    if (refreshSettled) return true;
    return budgetDeadline != 0 && now >= budgetDeadline;
}
// 是否发起本次关闭刷新（每 token 至多一次；无自有根/配置未恢复/预算已尽/cycle 忙 全部落显式原因）。
enum class PhysicalRefreshDecision : int {
    Begin = 0, NoTarget = 1, ConfigIncomplete = 2, AlreadyAttempted = 3,
    BudgetExhausted = 4, CycleBusy = 5
};
static PhysicalRefreshDecision physicalReleaseWindowRefreshDecision(
        bool hasOwnedRoot, bool configRestored, bool attemptedAlready,
        ULONGLONG now, ULONGLONG budgetDeadline, bool cycleBusy) {
    if (!hasOwnedRoot) return PhysicalRefreshDecision::NoTarget;               // 非 USB/未解析：不重试
    if (!configRestored) return PhysicalRefreshDecision::ConfigIncomplete;     // 未写回就 cycle = 让设备以可见态重枚举
    if (attemptedAlready) return PhysicalRefreshDecision::AlreadyAttempted;    // 每 token 最多一次真实刷新
    if (budgetDeadline != 0 && now >= budgetDeadline)
        return PhysicalRefreshDecision::BudgetExhausted;                       // 共用 2s 预算，不各自重置
    if (cycleBusy) return PhysicalRefreshDecision::CycleBusy;                  // 在途动作唯一：让路并显式记录
    return PhysicalRefreshDecision::Begin;
}
static const char* physicalReleaseWindowRefreshDecisionReason(PhysicalRefreshDecision decision) {
    switch (decision) {
        case PhysicalRefreshDecision::Begin: return "begin";
        case PhysicalRefreshDecision::NoTarget: return "no-owned-root";
        case PhysicalRefreshDecision::ConfigIncomplete: return "config-not-restored";
        case PhysicalRefreshDecision::AlreadyAttempted: return "already-attempted";
        case PhysicalRefreshDecision::BudgetExhausted: return "budget-exhausted";
        case PhysicalRefreshDecision::CycleBusy: return "cycle-busy";
    }
    return "unknown";
}
// R17-1 新鲜度门：观察过期或异常降级 ⇒ Unknown(-1)。
static int gamebarTraceTriFresh(bool available, int visible, int redirected,
                                ULONGLONG observedTick, ULONGLONG now) {
    if (!available) return -1;                             // 读不到 = Unknown
    if (observedTick == 0 || now - observedTick > kGamebarTraceObsFreshMs) return -1;   // 过期值不作数
    if (visible == 1 || redirected == 1) return 1;         // 可信出现（可见或已接管输入）
    if (visible == 0 && redirected == 0) return 0;         // 明确消失
    return -1;                                             // 其余 = Unknown
}

