static std::atomic<unsigned long long> g_inputHostLastSubmitElapsedUs{0};
// Power callbacks only revoke admission and queue intent. The capture thread
// is the Coordinator lane that performs the potentially blocking pipe and
// local-release work. A new Host can only be requested for the exact committed
// power generation; it can never revive a stale target on its own.
static std::atomic<bool> g_inputHostPowerReleaseRequested{false};
static std::atomic<unsigned long long> g_inputHostPowerReleaseGeneration{0};
static std::atomic<bool> g_inputHostPowerRearmRequested{false};
static std::atomic<unsigned long long> g_inputHostPowerRearmGeneration{0};
// （g_inputHostPowerAdmissionRevoked 按 GP-926R13 前置声明；见文件前部声明区。）
static std::string g_inputHostPowerReleaseReason;
static std::string g_inputHostPowerRearmReason;
static std::mutex g_inputHostPowerRequestMx;
// ── GP-926R13 B1/B2（T0优先裁决 §4）：共享恢复准入（真实电源）与 episode/滚动预算 ──────
// 生产者/消费者共用同一准入；只有真正开始恢复才计次；内部 reopen 的新 epoch 不是额度
// 刷新券；排队/去重/held/冷却等待不计；每 episode ≤2 次真恢复且间隔 ≥1s；自动重开另有
// 跨 episode 滚动上限（30s 内 ≤2 次）；连续健康 2s 或外部明确新意图/真实电源新周期才
// 开新 episode。预算字段只在持 g_inputHostMx 时改写；维护拍做无锁预览、空闲零取锁。
// （枚举/常量/原子量已按声明区前置；此处只放函数体，避免前向引用。）
static const char* inputHostRecoveryAdmissionName(InputHostRecoveryAdmission a) {
    switch (a) {
        case InputHostRecoveryAdmission::Allowed: return "allowed";
        case InputHostRecoveryAdmission::DeferredPower: return "deferred-power";
        case InputHostRecoveryAdmission::Cancelled: return "cancelled";
        case InputHostRecoveryAdmission::BudgetExhausted: return "budget-exhausted";
    }
    return "unknown";
}
static int inputHostRecoveryRollingCountLocked(ULONGLONG now) {
    int n = 0;
    for (int i = 0; i < 2; ++i) {
        const ULONGLONG t = g_inputHostRecoveryRolling[i].load(std::memory_order_acquire);
        if (t != 0 && now - t < kRecoveryRollingWindowMs) ++n;
    }
    return n;
}
// 预算耗尽（持有锁）：episode 上限 或 滚动窗上限。独立成函数以便直测（无环境耦合）。
static bool inputHostRecoveryBudgetExhaustedLocked(ULONGLONG now) {
    return g_inputHostRecoveryEpisodeAttempts.load(std::memory_order_acquire) >= kRecoveryEpisodeMax ||
        inputHostRecoveryRollingCountLocked(now) >= kRecoveryRollingMax;
}
// Exactly one shared charge after a caller's admission and, if protected, its
// central fallback reservation. Waiting/inspection never enters this function.
static int inputHostRecoveryChargeAttemptLocked(ULONGLONG now) {
    const int attempt=g_inputHostRecoveryEpisodeAttempts.fetch_add(1,std::memory_order_acq_rel)+1;
    g_inputHostRecoveryLastStartTick.store(now,std::memory_order_release);
    const auto slot=g_inputHostRecoveryRollingNext.load(std::memory_order_acquire);
    g_inputHostRecoveryRolling[slot].store(now,std::memory_order_release);
    g_inputHostRecoveryRollingNext.store(slot^1,std::memory_order_release);
    g_inputHostRecoveryHealth.clear();g_inputHostHealthySinceTick.store(0,std::memory_order_release);
    return attempt;
}
// 持锁调用。Cancelled=退出/Off/意图取消；DeferredPower=真实电源非 Ready（含撤销位）；
// BudgetExhausted=episode 或滚动额度耗尽；其余 Allowed（冷却在消费点另行装卸）。
static InputHostRecoveryAdmission inputHostRecoveryAdmissionLocked() {
    const bool publicationWanted = g_realStickTest.enabled && g_realStickTest.virtualTargetEnabled &&
        !g_externalPriorityVirtualSuspended.load(std::memory_order_acquire);
    if (!publicationWanted || inputHostConfiguredPersona() == "disabled" || inputHostExitFenceRaised())
        return InputHostRecoveryAdmission::Cancelled;
    if (g_inputHostPowerAdmissionRevoked.load(std::memory_order_acquire) ||
        g_powerLifecycle.load(std::memory_order_acquire) != PowerLifecycle::Ready)
        return InputHostRecoveryAdmission::DeferredPower;
    const ULONGLONG now = GetTickCount64();
    if (inputHostRecoveryBudgetExhaustedLocked(now))
        return InputHostRecoveryAdmission::BudgetExhausted;
    return InputHostRecoveryAdmission::Allowed;
}
// 耗尽终态（幂等，持锁）：落一次耗尽行、抬既有闩锁、把"可见物理兜底"交给生命周期 worker。
static void inputHostRecoveryTerminalLocked(const char* via) {
    if (g_inputHostRecoveryTerminalLogged.exchange(true, std::memory_order_acq_rel)) return;
    g_inputHostFaultHoldsStart.store(true, std::memory_order_release);
    appendNativeLifecycleLog("input-host-backend-fault-hold", {
        {"reason", "seq-desync-resync-exhausted-keep-writer"},
        {"via", via ? via : "unknown"},
        {"hint", "explicit-user-rearm-or-power-rearm-required"}
    });
    appendNativeLifecycleLog("input-host-recovery-exhausted", {
        {"via", via ? via : "unknown"},
        {"episodeAttempts", g_inputHostRecoveryEpisodeAttempts.load(std::memory_order_acquire)},
        {"rollingCount", inputHostRecoveryRollingCountLocked(GetTickCount64())},
        {"policy", "bounded-recovery-then-physical-fallback"}
    });
    inputHostQueueLifecycleWork("recovery-exhausted-physical-fallback");
}
// 维护拍：~100ms 一次（生命周期 worker 每次取件前调用）。空闲零取锁。
// Health adapters use only existing snapshots/locks; no source or device I/O.
// Caller owns g_inputHostMx. Producer/BUS release the snapshot mutex before
// acquiring the Host mutex, so this projection adds no reverse lock edge.
static bool inputHostRecoveryHealthTrackingLocked() {
    return g_inputHostRecoveryEpisodeAttempts.load(std::memory_order_acquire) != 0 ||
        g_inputHostRecoveryTerminalLogged.load(std::memory_order_acquire) ||
        g_inputHostRecoveryPending.load(std::memory_order_acquire) ||
        g_inputHostTupleHealPending.load(std::memory_order_acquire);
}
static ymcc::input::recoveryHealth::Context inputHostRecoveryHealthContextLocked(bool verifyPersona = true) {
    const auto power = currentPowerGeneration();
    const bool allowed = g_realStickTest.enabled && g_realStickTest.virtualTargetEnabled &&
        !g_externalPriorityVirtualSuspended.load(std::memory_order_acquire) &&
        !inputHostExitFenceRaised() && g_inputReady.load(std::memory_order_acquire) &&
        sgVirtualWriterAllowedNow() &&
        !g_inputHostPowerAdmissionRevoked.load(std::memory_order_acquire) &&
        g_powerLifecycle.load(std::memory_order_acquire) == PowerLifecycle::Ready &&
        // Retained standby Hosts keep their original protocol generation.
        // Health still requires a fresh current-power source and an owned kept/recreated wake proof.
        (g_inputHostBoundPowerGeneration == power ||
            ymcc::sleeprecovery::inputBindingAllowed(g_inputHostBoundPowerGeneration,power,
                inputHostWakeBindingProofLocked())) &&
        g_inputHostProcess && g_inputHostPrepared && g_inputHostNeutralized &&
        !g_inputHostTransportFault && !g_inputHostFaultHoldsStart.load(std::memory_order_acquire) &&
        !g_inputHostRecoveryIntentReset.load(std::memory_order_acquire) &&
        (!verifyPersona || inputHostBoundPersonaValue() == inputHostPersona()) && !physicalReleaseWindowActive();
    return {g_inputHostEpoch, power,
        g_inputHostPresentationWorkGeneration.load(std::memory_order_acquire),
        g_xinputTopologyEpoch.load(std::memory_order_acquire),
        g_xinputSlotIdentityEpoch.load(std::memory_order_acquire), allowed};
}
static ymcc::input::recoveryHealth::Source inputHostRecoveryHealthSource(
    const InputCaptureGamepadSnapshot* source, bool eligible) {
    if (!source) return {};
    const bool xinputSource = (source->inputSource == "xinput" || source->inputSource == "xinput-any-connected") && source->connectedMask != 0;
    const bool msiSource = source->inputSource == "msi-dinput" && source->readMsiSourceRevision != 0 &&
        source->readMsiSourceRevision == g_msiMainSourceRevision.load(std::memory_order_acquire) &&
        source->readMsiModeGeneration == g_msiFeedbackModeGeneration.load(std::memory_order_acquire) &&
        msiControllerRepairScope() && msiDinputMainSourceEligible();
    using Route = ymcc::input::recoveryHealth::Route;
    const auto route = xinputSource ? Route::XInput : (msiSource ? Route::MsiDinput : Route::Unspecified);
    // An old MSI read becomes ineligible at a mode edge even if its handle
    // revision is retained. The canonical nextContinuity producer then retires
    // its accepted coverage; old-mode health cannot reset a new-mode budget.
    // Evidence only: current XInput identity epoch already covers remapping;
    // the selected slot and MSI reader incarnation additionally split health.
    const auto incarnation = xinputSource ? static_cast<ymcc::input::recoveryHealth::Tick>(source->primarySlot) + 1
        : source->readMsiSourceRevision;
    return {source->readAttemptSequence, source->readStartedTick, source->readCompletedTick,
        source->readPowerGeneration, source->readTopologyGeneration, source->readIdentityGeneration,
        eligible && source->live && (xinputSource || msiSource),
        source->readContextStable, source->readContinuityGeneration, route, incarnation};
}
static ymcc::input::recoveryHealth::Source inputHostRecoveryHealthLatestSourceLocked(bool eligible = true) {
    std::lock_guard<std::mutex> sourceLock(g_inputCaptureGamepadSnapshotMx);
    return inputHostRecoveryHealthSource(&g_inputCaptureGamepadSnapshot, eligible);
}
static void inputHostRecoveryHealthObserveLocked(bool eligible = true) {
    const bool tracking = inputHostRecoveryHealthTrackingLocked();
    if (!tracking) {
        if (g_inputHostRecoveryHealthWasTracking || !eligible) g_inputHostRecoveryHealth.clear();
        g_inputHostRecoveryHealthWasTracking = false;
        if (!eligible) g_inputHostHealthySinceTick.store(0, std::memory_order_release);
        return;
    }
    if (!g_inputHostRecoveryHealthWasTracking) {
        g_inputHostRecoveryHealth.clear();
        g_inputHostHealthySinceTick.store(0, std::memory_order_release);
        g_inputHostRecoveryHealthWasTracking = true;
    }
    if (!g_inputHostHealthySinceTick.load(std::memory_order_acquire)) g_inputHostRecoveryHealth.clear();
    g_inputHostRecoveryHealth.observe(inputHostRecoveryHealthContextLocked(),
        inputHostRecoveryHealthLatestSourceLocked(eligible), GetTickCount64());
    g_inputHostHealthySinceTick.store(g_inputHostRecoveryHealth.since(), std::memory_order_release);
}
static void inputHostRecoveryHealthAcceptedLocked(
    const ymcc::input::recoveryHealth::Context& request,
    const ymcc::input::recoveryHealth::Source& source, bool eligible) {
    const bool tracking = inputHostRecoveryHealthTrackingLocked();
    if (tracking != g_inputHostRecoveryHealthWasTracking) {
        g_inputHostRecoveryHealth.clear();
        g_inputHostHealthySinceTick.store(0, std::memory_order_release);
        g_inputHostRecoveryHealthWasTracking = tracking;
    }
    if (!g_inputHostHealthySinceTick.load(std::memory_order_acquire)) g_inputHostRecoveryHealth.clear();
    // No recovery obligation: preserve the lightweight T1 timestamp using the
    // already captured canonical read. No persona copy or snapshot lock here.
    g_inputHostRecoveryHealth.accepted(request, source, inputHostRecoveryHealthContextLocked(tracking),
        tracking ? inputHostRecoveryHealthLatestSourceLocked(eligible) : source, GetTickCount64());
    g_inputHostHealthySinceTick.store(g_inputHostRecoveryHealth.since(), std::memory_order_release);
}
static void inputHostRecoveryMaintenanceTick() {
    if (!g_inputHostSwitchVerificationPending.load(std::memory_order_acquire) &&
        !g_inputHostSwitchExecutionReturnPending.load(std::memory_order_acquire) &&
        !g_inputHostSwitchRecoveryPending.load(std::memory_order_acquire) &&
        !g_inputHostRecoveryPending.load(std::memory_order_acquire) &&
        g_inputHostRecoveryEpisodeAttempts.load(std::memory_order_acquire) == 0 &&
        !g_inputHostRecoveryTerminalLogged.load(std::memory_order_acquire) &&
        !g_inputHostRecoveryIntentReset.load(std::memory_order_acquire) &&
        g_inputHostRecoveryFallbackState.load(std::memory_order_acquire) == 0)
        return;
    const ULONGLONG now = GetTickCount64();
    bool queueReopen = false;
    std::string reopenReason;
    {
        std::lock_guard<InputHostMutex> lock(g_inputHostMx);
        if (g_inputHostRecoveryIntentReset.exchange(false, std::memory_order_acq_rel)) {
            g_inputHostRecoveryHealth.clear();
            g_inputHostHealthySinceTick.store(0, std::memory_order_release);
            g_inputHostRecoveryEpisodeAttempts.store(0, std::memory_order_release);
            g_inputHostRecoveryTerminalLogged.store(false, std::memory_order_release);
            g_inputHostRecoveryPending.store(false, std::memory_order_release);
            g_inputHostRecoveryDeferredUntil.store(0, std::memory_order_release);
            g_inputHostRecoveryFallbackState.store(0, std::memory_order_release);
            appendNativeLifecycleLog("input-host-recovery-episode-new", {
                {"via", "external-intent-or-power-cycle"},
                {"policy", "fresh-recovery-budget"}
            });
        }
        inputHostSwitchExecutionReturnMaintenanceLocked();
        inputHostSwitchRecoveryMaintenanceLocked();
        inputHostSwitchVerificationMaintenanceLocked();
        inputHostRecoveryHealthObserveLocked();
        const ULONGLONG healthySince = g_inputHostRecoveryHealth.since();
        const ULONGLONG healthyThrough = g_inputHostRecoveryHealth.through();
        if (g_inputHostRecoveryHealth.complete(kRecoveryHealthyCompleteMs) &&
            !g_inputHostTupleHealPending.load(std::memory_order_acquire) &&
            !g_inputHostRecoveryPending.load(std::memory_order_acquire)) {
            if (g_inputHostRecoveryEpisodeAttempts.load(std::memory_order_acquire) != 0 ||
                g_inputHostRecoveryTerminalLogged.load(std::memory_order_acquire)) {
                g_inputHostRecoveryEpisodeAttempts.store(0, std::memory_order_release);
                g_inputHostRecoveryTerminalLogged.store(false, std::memory_order_release);
                appendNativeLifecycleLog("input-host-recovery-healthy", {
                    {"healthyMs", (unsigned long long)(healthyThrough - healthySince)},
                    {"healthyThroughReadTick", healthyThrough},
                    {"proofScope", "same-context-source-reads-with-accepted-receipts"},
                    {"sourceRoute", ymcc::input::recoveryHealth::routeName(g_inputHostRecoveryHealth.route())},
                    {"sourceIncarnation", g_inputHostRecoveryHealth.incarnation()},
                    {"sourceContinuity", g_inputHostRecoveryHealth.continuity()},
                    {"policy", "episode-complete-after-2s-healthy"}
                });
            }
            g_inputHostRecoveryDeferredUntil.store(0, std::memory_order_release);
            g_inputHostRecoveryHealth.settled();
            g_inputHostHealthySinceTick.store(g_inputHostRecoveryHealth.since(), std::memory_order_release);
        }
        queueReopen=inputHostTupleRecoveryMaintenanceLocked(reopenReason);
    }
    if (queueReopen) inputHostQueueLifecycleWork(reopenReason.c_str());
}
// ── 唤醒加固（2026-09-15 用户需求 + 实机证据闭环）──
