static std::atomic<unsigned long long> g_wakeRescanGeneration{0};
static std::atomic<ULONGLONG> g_wakeRescanArmTick{0};
static std::atomic<ULONGLONG> g_wakeHotReplaceRetryAfterTick{0};
static std::atomic<bool> g_wakeHoldPhysicalUnhide{false};
