static void inputHostSubmitFlowNote(bool admitted, bool neutral) {
    if (admitted && !neutral) {
        g_submitFlowNonNeutral.fetch_add(1, std::memory_order_relaxed);
        bool expected = false;
        if (g_submitFlowLoggedNonNeutral.compare_exchange_strong(expected, true,
                                                                std::memory_order_acq_rel)) {
            appendNativeLifecycleLog("input-host-submit-flow", {
                {"reason", "first-non-neutral-admitted"},
                {"admitted", true}, {"neutral", false},
                {"nonNeutralCount", (int)g_submitFlowNonNeutral.load(std::memory_order_relaxed)},
                {"virtualTargetEnabled", g_realStickTest.virtualTargetEnabled},
                {"hostPrepared", g_inputHostPrepared},
                {"ymccForeground", focusMainWindowIsForeground()}
            });
        }
        return;
    }
    if (neutral) {
        g_submitFlowNeutral.fetch_add(1, std::memory_order_relaxed);
        bool expected = false;
        if (g_submitFlowLoggedNeutral.compare_exchange_strong(expected, true,
                                                              std::memory_order_acq_rel)) {
            appendNativeLifecycleLog("input-host-submit-flow", {
                {"reason", "neutral-cleanup"},
                {"admitted", admitted}, {"neutral", true},
                {"neutralCount", (int)g_submitFlowNeutral.load(std::memory_order_relaxed)}
            });
        }
        return;
    }
    // admitted=false 且 neutral=false —— 修复前每帧都会落到这里（publication-skipped-source-absent 形状）。
    g_submitFlowBlocked.fetch_add(1, std::memory_order_relaxed);
    bool expected = false;
    if (g_submitFlowLoggedBlocked.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
        appendNativeLifecycleLog("input-host-submit-flow", {
            {"reason", "blocked-both-false"},
            {"admitted", false}, {"neutral", false},
            {"blockedCount", (int)g_submitFlowBlocked.load(std::memory_order_relaxed)},
            {"note", "pre-fix failure shape; must not occur after the live||submitNeutral fix"}
        });
    }
}


// Diagnostic state never changes the producer/Host report. All disk and power
// queries run on the existing lifecycle owner, NOT the 8ms timer callback.
static ymcc::idle::Accumulator g_inputIdleActivity;

static std::atomic<std::uint64_t> g_focusShortcutEvidenceFailures{0};
// Explicit shortcut call boundaries only. Never change focus/input or drain
// another recorder. The family/detail gate is maintained by the existing owner.
static void focusShortcutInputEvidence(const char* phase,unsigned long long generation,bool targetCaptured) noexcept {
    if(!g_keyboardModifierEventGate.load(std::memory_order_acquire))return;
    const DWORD saved=GetLastError();
    struct RestoreError {DWORD value;~RestoreError(){SetLastError(value);}} restoreError{saved};
    try {
        const auto modifiers=ymcc::keyboardEvidence::read();
        const auto physicalBegin=GetTickCount64();
        ymcc::idle::PhysicalSnapshot physical{};
        const bool captured=g_inputIdleActivity.peekPhysical(physical);
        const auto physicalEnd=GetTickCount64();
        json pad={{"captured",captured},{"captureBeginTick",physicalBegin},{"captureEndTick",physicalEnd},
            {"scope","Latest existing physical channel; try-lock only, no fresh device read or source identity"}};
        if(captured)pad.update({{"haveLastSample",physical.haveLastSample},{"latestPhysicalLive",physical.latestPhysicalLive},
            {"contextKnown",physical.contextKnown},{"contextTransitions",physical.contextTransitions},
            {"observationTick",physical.observationTick},{"sampleTick",physical.sampleTick},
            {"sampleAgeMs",physical.haveLastSample&&physicalEnd>=physical.sampleTick?json(physicalEnd-physical.sampleTick):json(nullptr)},
            {"sampleIsLatestLiveObservation",physical.latestPhysicalLive&&physical.haveLastSample&&physical.sampleTick==physical.observationTick},
            {"powerGeneration",physical.powerGeneration},{"virtualTargetEnabled",physical.virtualEnabled},{"connectedMask",physical.connectedMask},
            {"buttons",physical.haveLastSample?json(physical.buttons):json(nullptr)},
            {"leftShoulderInLastSample",physical.haveLastSample?json((physical.buttons&0x0100u)!=0):json(nullptr)},
            {"rightShoulderInLastSample",physical.haveLastSample?json((physical.buttons&0x0200u)!=0):json(nullptr)}});
        else pad["reason"]="disabled-or-contended";
        json row={{"schemaVersion",1},{"phase",phase},{"summonGeneration",generation},{"targetCaptured",targetCaptured},
            {"keyboardModifiers",ymcc::keyboardEvidence::toJson(modifiers)},{"physicalAtBoundary",std::move(pad)},
            {"diagnosticFailures",g_focusShortcutEvidenceFailures.load(std::memory_order_relaxed)},
            {"crossSourceAtomic",false},{"keyboardProducerIdentified",false},{"keyReleaseProven",false},
            {"scope","Shortcut summon call boundary, not atomic keyboard/physical state, successful focus, downstream key delivery or source attribution"}};
        appendDomainLog("focus","focus-shortcut-input",row);
        appendDomainLog("virtual","focus-shortcut-input",row);
    } catch(...) {g_focusShortcutEvidenceFailures.fetch_add(1,std::memory_order_relaxed);}
}


// The existing modifier drain is the only observer; no new callbacks or polling.
static ymcc::keyboardOrigin::Cache g_keyboardDeviceOriginCache;
static std::atomic<std::uint64_t> g_keyboardDeviceOriginObserveFailures{0};
static void keyboardDeviceOriginObserveAtDrain(const ymcc::keyboardEvents::Event& event,
                                               const wchar_t* name,std::size_t chars) noexcept {
    const DWORD saved=GetLastError();
    try {
        if(domainLogEnabled("virtual"))
            g_keyboardDeviceOriginCache.observe(std::wstring(name,chars),event.device,
                event.deviceGeneration,event.tick,GetTickCount64());
    }catch(...){g_keyboardDeviceOriginObserveFailures.fetch_add(1,std::memory_order_relaxed);}
    SetLastError(saved);
}

// Drain-time names are bounded metadata observations, not event-time device
// provenance. No shared HID/OEM admission cache is queried or mutated.
static json keyboardModifierRawNameAtDrain(const ymcc::keyboardEvents::Event& e,unsigned& queryBudget) {
    const DWORD saved=GetLastError();
    struct ErrorRestorer{DWORD value;~ErrorRestorer(){SetLastError(value);}} errorRestorer{saved};
    json r={{"eventDeviceGeneration",e.deviceGeneration},{"queriedAfterEvent",true},{"eventPathIdentityProven",false}};
    const auto generation=g_keyboardModifierDeviceGeneration.load(std::memory_order_acquire);
    r["drainDeviceGeneration"]=generation;
    if(!e.device){r["status"]="null-device-handle";return r;}
    if(e.deviceGeneration!=generation){r["status"]="device-generation-changed";return r;}
    if(queryBudget==0){r["status"]="query-budget-exhausted";return r;}--queryBudget;
    UINT chars=0;
    const HANDLE device=reinterpret_cast<HANDLE>(e.device);
    const UINT sizeResult=GetRawInputDeviceInfoW(device,RIDI_DEVICENAME,nullptr,&chars);
    r["sizeResult"]=sizeResult;r["requiredChars"]=chars;
    if(sizeResult==UINT(-1)||!chars||chars>1024){
        r["status"]=sizeResult==UINT(-1)?"size-query-failed":(!chars?"empty-size":"name-over-limit");
        if(sizeResult==UINT(-1))r["win32Error"]=GetLastError();SetLastError(saved);return r;
    }
    std::array<wchar_t,1024> name;name.fill(wchar_t(0xffff));UINT capacity=static_cast<UINT>(name.size());
    const UINT result=GetRawInputDeviceInfoW(device,RIDI_DEVICENAME,name.data(),&capacity);
    r["nameResult"]=result;r["returnedChars"]=capacity;
    if(result==UINT(-1)){r["status"]="name-query-failed";r["win32Error"]=GetLastError();SetLastError(saved);return r;}
    const auto end=std::find(name.begin(),name.end(),wchar_t(0));
    const auto after=g_keyboardModifierDeviceGeneration.load(std::memory_order_acquire);
    r["afterQueryDeviceGeneration"]=after;
    if(after!=generation){r["status"]="device-generation-changed-during-query";}
    else if(capacity>name.size()||end==name.end()||end==name.begin()){r["status"]="invalid-or-unterminated-name";}
    else{r["status"]="name-observed-at-drain";r["interfacePath"]=W2U(name.data(),static_cast<int>(end-name.begin()));
        keyboardDeviceOriginObserveAtDrain(e,name.data(),static_cast<std::size_t>(end-name.begin()));}
    SetLastError(saved);return r;
}
