// Ctrl-return evidence shares the Host mutex and the existing virtual-log gate.
// A diagnostic failure must never skip QUIESCE, neutral, release or mode return.
static ymcc::stopSignalEvidence::Tracker g_inputStopSignalEvidence;
static std::atomic<unsigned long long> g_inputStopSignalEvidenceFailures{0};
static bool inputStopSignalEvidenceEnabled() {
    return domainLogEnabled("virtual") &&
        (msiClawKnownBoardAuthority() || (g_machineIdentity.resolved && ymccIsRogFamily()));
}
static unsigned long long inputStopSignalBeginLocked(const char* reason,const std::string& persona,
                                                     unsigned long long hostPid) noexcept {
    const DWORD saved=GetLastError(); unsigned long long id=0;
    g_inputStopSignalEvidence.reset();
    try {
        if(inputStopSignalEvidenceEnabled())
            id=g_inputStopSignalEvidence.begin(GetTickCount64(),g_inputHostRunId,g_inputHostEpoch,
                hostPid,persona,reason?reason:"unknown",g_powerGeneration.load(std::memory_order_acquire));
    } catch(...) { g_inputStopSignalEvidenceFailures.fetch_add(1,std::memory_order_relaxed); }
    SetLastError(saved); return id;
}
static void inputStopSignalPhaseLocked(unsigned long long id,const char* phase,
                                       const char* command=nullptr,int accepted=-1,bool finished=false) noexcept {
    if(!id)return;
    const DWORD saved=GetLastError();
    try {
        const auto now=GetTickCount64();
        if(finished)g_inputStopSignalEvidence.finish(id,now);
        if(inputStopSignalEvidenceEnabled()) {
            auto row=g_inputStopSignalEvidence.context(id,now);
            if(!row.is_null()) {
                row["phase"]=phase; row["command"]=command?json(command):json(nullptr);
                row["commandAccepted"]=accepted<0?json(nullptr):json(accepted!=0);
                row["keyboardModifiers"]=ymcc::keyboardEvidence::toJson(ymcc::keyboardEvidence::read());
                row["hostActive"]=g_inputHostActive; row["hostPrepared"]=g_inputHostPrepared;
                row["hostProcessPresent"]=g_inputHostProcess!=nullptr;
                row["hostLifecycle"]=g_inputHostLifecycle;
                row["commandSequence"]=g_inputHostSequence; row["sampleSequence"]=g_inputHostSampleSequence;
                row["diagnosticFailures"]=g_inputStopSignalEvidenceFailures.load(std::memory_order_relaxed);
                row["receiptScope"]="Local lifecycle and sampled OS modifier state; not per-endpoint HID completion or Steam key-up receipt";
                appendDomainLog("virtual","input-stop-signal-evidence",row);
            }
        }
    } catch(...) { g_inputStopSignalEvidenceFailures.fetch_add(1,std::memory_order_relaxed); }
    SetLastError(saved);
}
static void inputStopSignalAppendRecentLocked(json& row,ULONGLONG now) noexcept {
    const DWORD saved=GetLastError();
    try {
        if(inputStopSignalEvidenceEnabled()) {
            const auto recent=g_inputStopSignalEvidence.recent(now,g_inputHostRunId,g_inputHostEpoch);
            if(!recent.is_null())row["recentStopSignalContext"]=recent;
            row["stopSignalDiagnosticFailures"]=g_inputStopSignalEvidenceFailures.load(std::memory_order_relaxed);
        }
    } catch(...) { g_inputStopSignalEvidenceFailures.fetch_add(1,std::memory_order_relaxed); }
    SetLastError(saved);
}

