// ── HidHide 并发串行化（HC parity：Misc\HidHide.cs 每个操作 lock(hidLock)）──
// HC 用 HidHideControlService 进程内 API，且全部 Hide/Unhide/Register/Cloak
// 操作均 lock(hidLock)（HidHide.cs:56/71/97/132/167/210/248）。YMCC 走 CLI，
// 若 28 处 hidHideRun 无锁并发（hide 线程 / watchdog / BUS / 自愈），CLI 子
// 进程互撞会触发 FilterDriverProxy 0x0005、wedged 并把正常 restore 吞掉 →
// 物理手柄保持隐藏，需拔插/卸载才能恢复（0910-21 用户实测）。此处加全局
// 互斥使所有 HidHide 调用串行，与 HC hidLock 语义一致。
#include "hidhide_cli_job_guard.h"
#include "hidhide_cli_writer_runtime.h"
static std::string inputHostNewId();
static std::mutex g_hidHideMx;

// All fields below are protected by the existing g_hidHideMx.
// A retained handle describes one exact possibly live CLI, not a Host process.
static HANDLE g_hidHidePendingChildProcess = nullptr;
static HANDLE g_hidHidePendingReadPipe = nullptr;
// An unknown CLI keeps its kernel job AND durable writer lease as well as its
// exact process/pipe. A new native must acquire the same file owner before use.
static ymcc::hidHideCli::JobGuard g_hidHidePendingJob;
static std::unique_ptr<ymcc::hidhideCliWriter::Session> g_hidHidePendingWriter;
static std::string g_hidHidePendingAttempt;
struct HidHideCliCallHandles {
    HANDLE readPipe=nullptr,writePipe=nullptr;
    PROCESS_INFORMATION pi{};
    ymcc::hidHideCli::JobGuard job;
    std::unique_ptr<ymcc::hidhideCliWriter::Session> writer;
    std::string attemptId;
    ULONGLONG deadline=0;
    bool exitProven=false,stopRequested=false,settlementAttempted=false;
    bool writerActive() const noexcept {
        return writer&&writer->record()&&writer->record()->active.has_value();
    }
    bool proveExit() const noexcept {
        return (!pi.hProcess||WaitForSingleObject(pi.hProcess,0)==WAIT_OBJECT_0)&&
            (!job.ready()||job.idle());
    }
    void requestStop() noexcept {
        if(!stopRequested) {
            stopRequested=true;
            if(pi.hProcess)TerminateProcess(pi.hProcess,1);
            if(job.ready())job.requestStop(1);
        }
        exitProven=proveExit(); // Accepted termination is not this proof.
    }
    bool settle() noexcept {
        if(!writerActive())return true;
        if(settlementAttempted||!exitProven||(deadline&&GetTickCount64()>=deadline))return false;
        settlementAttempted=true; // One commit attempt per original CLI call.
        try {return ymcc::hidHideCliWriterRuntime::settleOwned(*writer,attemptId);}
        catch(...){return false;}
    }
    ~HidHideCliCallHandles() noexcept {
        if(pi.hThread)CloseHandle(pi.hThread);
        if(writePipe)CloseHandle(writePipe);
        if(!exitProven)requestStop();
        if(exitProven)settle();
        if(!exitProven) {
            g_hidHidePendingChildProcess=std::exchange(pi.hProcess,nullptr);
            g_hidHidePendingReadPipe=std::exchange(readPipe,nullptr);
            g_hidHidePendingJob=std::move(job);
        }
        // A proved-dead process/subtree no longer needs pipe/process handles.
        // Keep only the unsettled file lease when its commit budget is spent.
        // The next existing admission settles it before any new writer starts.
        if(writerActive()) {
            g_hidHidePendingWriter=std::move(writer);
            g_hidHidePendingAttempt=std::move(attemptId);
        }
        if(readPipe)CloseHandle(readPipe);
        if(pi.hProcess)CloseHandle(pi.hProcess);
    }
};

// VC-LIFECYCLE-20261020-R3: one CLI owner, original absolute deadline.
// A termination request is not exit proof. Keep the exact unproven child/pipe
// handles; an existing later call rechecks Wait(0) before any new dispatch.
// Shared by existing CLI admission and physical-return checks under g_hidHideMx.
// Observe once; no termination/restart, additional worker or renewed deadline.
static bool hidHideCliReapPendingLocked(ULONGLONG absoluteDeadlineTick=0) {
    if(!g_hidHidePendingChildProcess&&!g_hidHidePendingJob.ready()&&!g_hidHidePendingWriter)return true;
    if(absoluteDeadlineTick&&GetTickCount64()>=absoluteDeadlineTick)return false;
    const bool exited=!g_hidHidePendingChildProcess||WaitForSingleObject(g_hidHidePendingChildProcess,0)==WAIT_OBJECT_0;
    const bool idle=!g_hidHidePendingJob.ready()||g_hidHidePendingJob.idle();
    if(!exited||!idle)return false;
    if(g_hidHidePendingWriter&&
       !ymcc::hidHideCliWriterRuntime::settleOwned(*g_hidHidePendingWriter,g_hidHidePendingAttempt))return false;
    if(g_hidHidePendingReadPipe)CloseHandle(g_hidHidePendingReadPipe);
    if(g_hidHidePendingChildProcess)CloseHandle(g_hidHidePendingChildProcess);
    g_hidHidePendingReadPipe=nullptr;g_hidHidePendingChildProcess=nullptr;
    g_hidHidePendingJob.reset();g_hidHidePendingWriter.reset();g_hidHidePendingAttempt.clear();
    return true;
}

static bool hidHideRun(const std::wstring& arguments,std::string* output=nullptr,
                       DWORD* exitCodeOut=nullptr,ULONGLONG absoluteDeadlineTick=0) {
    const auto executionDeadline=g_inputHostSwitchRecoveryStartDeadline;
    if(executionDeadline&&(!absoluteDeadlineTick||executionDeadline<absoluteDeadlineTick))absoluteDeadlineTick=executionDeadline;
    if(output)output->clear();
    if(exitCodeOut)*exitCodeOut=ERROR_GEN_FAILURE;
    std::unique_lock<std::mutex> commandOwner(g_hidHideMx,std::try_to_lock);
    if(!commandOwner.owns_lock()){if(exitCodeOut)*exitCodeOut=ERROR_BUSY;return false;}
    const ULONGLONG begin=GetTickCount64();
    const ULONGLONG fallback=begin>~ULONGLONG(0)-4000?~ULONGLONG(0):begin+4000;
    const ULONGLONG deadline=absoluteDeadlineTick&&absoluteDeadlineTick<fallback?absoluteDeadlineTick:fallback;
    const auto expired=[&]{return GetTickCount64()>=deadline;};
    const auto operationPower=currentPowerGeneration();
    const auto currentRequest=[&] {
        return currentPowerGeneration()==operationPower &&
            (!g_inputHostSwitchRecoveryStartRequestId ||
             (g_inputHostSwitchRecoveryStartPower==operationPower &&
              g_virtualStartProtection.view(GetTickCount64()).requestId==g_inputHostSwitchRecoveryStartRequestId));
    };
    if(expired()){if(exitCodeOut)*exitCodeOut=WAIT_TIMEOUT;return false;}
    try {
        if(!hidHideCliReapPendingLocked(deadline)) {
            if(exitCodeOut)*exitCodeOut=ERROR_BUSY;return false;
        }
        auto lease=ymcc::hidHideCliWriterRuntime::open();
        if(!lease||!ymcc::hidHideCliWriterRuntime::clearSettled(*lease)) {
            if(exitCodeOut)*exitCodeOut=ERROR_BUSY;return false;
        }
        if(expired()){if(exitCodeOut)*exitCodeOut=WAIT_TIMEOUT;return false;}
        if(!currentRequest()){if(exitCodeOut)*exitCodeOut=ERROR_CANCELLED;return false;}
        const auto parent=hidHideCliWriterCapture(GetCurrentProcess());
        if(!parent)return false;
        const std::wstring cli=hidHideCliPath();
        if(GetFileAttributesW(cli.c_str())==INVALID_FILE_ATTRIBUTES)return false;
        HidHideCliCallHandles scope;scope.deadline=deadline;scope.writer=std::move(lease);
        SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};
        if(!CreatePipe(&scope.readPipe,&scope.writePipe,&sa,0))return false;
        if(!SetHandleInformation(scope.readPipe,HANDLE_FLAG_INHERIT,0))return false;
        STARTUPINFOW si{};si.cb=sizeof(si);si.dwFlags=STARTF_USESTDHANDLES|STARTF_USESHOWWINDOW;
        si.hStdOutput=scope.writePipe;si.hStdError=scope.writePipe;si.wShowWindow=SW_HIDE;
        std::wstring cmd=L"\""+cli+L"\" "+arguments;
        std::vector<wchar_t> buf(cmd.begin(),cmd.end());buf.push_back(0);
        scope.attemptId=inputHostNewId();
        const std::string jobName=std::string(ymcc::hidhideCliWriter::jobPrefix)+scope.attemptId;
        if(!scope.job.prepare(si,U2W(jobName))) {
            if(exitCodeOut)*exitCodeOut=scope.job.error();
            ymcc::hidHideCliWriterRuntime::note("launch-rejected","atomic-CLI-job-unavailable");return false;
        }
        ymcc::hidhideCliWriter::Attempt reservation;
        reservation.attemptId=scope.attemptId;reservation.parent=*parent;reservation.jobName=jobName;
        if(!scope.writer->reserve(scope.writer->record()->revision,reservation)) {
            ymcc::hidHideCliWriterRuntime::note("launch-rejected",scope.writer->error().reason.c_str());return false;
        }
        if(expired()){if(exitCodeOut)*exitCodeOut=WAIT_TIMEOUT;return false;}
        if(!currentRequest()){if(exitCodeOut)*exitCodeOut=ERROR_CANCELLED;return false;}
        const BOOL created=ymcc::processEfficiency::createProcess(nullptr,buf.data(),nullptr,nullptr,TRUE,
            CREATE_NO_WINDOW|CREATE_SUSPENDED|scope.job.flags(),nullptr,nullptr,scope.job.startup(),&scope.pi);
        if(!CloseHandle(scope.writePipe))return false;
        scope.writePipe=nullptr;
        if(!created)return false;
        const auto child=hidHideCliWriterCapture(scope.pi.hProcess);
        if(!child||!scope.writer->markMayRun(scope.writer->record()->revision,scope.attemptId,*child)) {
            ymcc::hidHideCliWriterRuntime::note("launch-rejected","CLI-child-identity-not-durably-published");return false;
        }
        // Neither runtime code nor DLL initialization may execute before the
        // child's exact PID/birth and named Job are committed to the writer slot.
        if(expired()){if(exitCodeOut)*exitCodeOut=WAIT_TIMEOUT;return false;}
        if(!currentRequest()){if(exitCodeOut)*exitCodeOut=ERROR_CANCELLED;return false;}
        if(ResumeThread(scope.pi.hThread)!=1)return false;
        if(!CloseHandle(scope.pi.hThread))return false;
        scope.pi.hThread=nullptr;
        std::string text;char chunk[4096];constexpr std::size_t maxCaptureBytes=1024*1024;
        bool complete=false;DWORD failure=ERROR_READ_FAULT;
        for(;;) {
            if(expired()){failure=WAIT_TIMEOUT;break;}
            const bool exitObservedBeforePeek=scope.exitProven;
            DWORD available=0;
            const BOOL peeked=PeekNamedPipe(scope.readPipe,nullptr,0,nullptr,&available,nullptr);
            if(!peeked&&GetLastError()!=ERROR_BROKEN_PIPE)break;
            if(available) {
                if(text.size()>=maxCaptureBytes){failure=ERROR_BUFFER_OVERFLOW;break;}
                const DWORD want=static_cast<DWORD>((std::min)({std::size_t(available),sizeof(chunk),maxCaptureBytes-text.size()}));
                DWORD read=0;
                if(!ReadFile(scope.readPipe,chunk,want,&read,nullptr)||!read||read>want)break;
                text.append(chunk,read);
            }
            const DWORD state=WaitForSingleObject(scope.pi.hProcess,0);
            if(state!=WAIT_OBJECT_0&&state!=WAIT_TIMEOUT){failure=ERROR_GEN_FAILURE;break;}
            scope.exitProven=state==WAIT_OBJECT_0&&scope.job.idle();
            if(scope.exitProven&&exitObservedBeforePeek&&available==0){complete=true;break;}
            if(!available&&!scope.exitProven) {
                const ULONGLONG now=GetTickCount64();if(now>=deadline){failure=WAIT_TIMEOUT;break;}
                Sleep(static_cast<DWORD>((std::min)(ULONGLONG(10),deadline-now)));
            }
        }
        if(!complete) {
            scope.requestStop();
            if(output)*output=std::move(text);
            if(exitCodeOut)*exitCodeOut=failure;
            return false;
        }
        DWORD exitCode=ERROR_GEN_FAILURE;
        if(!GetExitCodeProcess(scope.pi.hProcess,&exitCode))return false;
        if(!scope.settle())return false;
        if(expired()){if(exitCodeOut)*exitCodeOut=WAIT_TIMEOUT;return false;}
        if(!currentRequest()){if(exitCodeOut)*exitCodeOut=ERROR_CANCELLED;return false;}
        if(output)*output=std::move(text);
        if(exitCodeOut)*exitCodeOut=exitCode;
        return exitCode==ERROR_SUCCESS;
    }catch(...) {
        if(output)output->clear();if(exitCodeOut)*exitCodeOut=ERROR_GEN_FAILURE;
        return false;
    }
}

// ── T0 (2026-09-10): HidHide 自愈 ──
// HC 只有 fail-fast 启动检查与 API→CLI fallback（Misc\HidHide.cs），没有自动
// 重装/重置/服务重启。用户将 HidHide 故障（服务停、驱动异常、配置损坏导致
// Configuration Client 崩溃、隐藏残留致手柄不可用）升级为 T0：YMCC 自愈。
//   L1  服务未 RUNNING         → sc start HidHide
//   L3  隐藏残留纠偏           → 由 RecoverPersistentTransaction + exact
//                                restore（已有路径）承担，不重复。
// 2026-09-10 收敛（0910-18 探针 + 用户裁决）：
//   原 L2（sc stop/start 重启驱动）与 L4（每 30s 静默重装）删除：
//   (1) L4 每 30s 拉起 Inno Setup，第一个实例超时后成为僵尸持有安装互斥锁，
//       后续实例必然弹 "Another instance of setup is already running"
//       （/VERYSILENT /SUPPRESSMSGBOXES 压制不了 Inno 的单实例检查）；
//   (2) L2 在虚拟手柄会话进行中执行 sc stop/start HidHide，等于每 30s 掐断
//       物理源读取通道；HC 从不做这两种运行时破坏性操作。
//   运行时保留 L1（服务未运行则拉起，无破坏性）与 L3；HidHide 驱动/配置
//   坏态（--dev-all 不可交互）只做持久诊断（hidhide.driver-degraded），由
//   部署/发布通道做干净重装或在 UI 提示用户。用户曾授权运行时自动卸载+
//   重装，因进程权限不足（非管理员，Inno 静默重装不可行）于 2026-09-10
//   撤销：本代码库不含任何自动卸载/重装逻辑，与 HC 完全一致。
static ULONGLONG g_hidHideLastHealTick = 0;

static bool hidHideRunSc(const std::wstring& arguments, std::string* output = nullptr) {
    SECURITY_ATTRIBUTES sa{ sizeof(sa), nullptr, TRUE };
    HANDLE readPipe = nullptr, writePipe = nullptr;
    if (!CreatePipe(&readPipe, &writePipe, &sa, 0)) return false;
    SetHandleInformation(readPipe, HANDLE_FLAG_INHERIT, 0);
    STARTUPINFOW si{}; si.cb = sizeof(si); si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.hStdOutput = writePipe; si.hStdError = writePipe; si.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION pi{};
    std::wstring cmd = L"sc.exe " + arguments;
    std::vector<wchar_t> buf(cmd.begin(), cmd.end()); buf.push_back(0);
    const BOOL ok = ymcc::processEfficiency::createProcess(nullptr, buf.data(), nullptr, nullptr, TRUE, CREATE_NO_WINDOW, nullptr, nullptr, &si, &pi);
    CloseHandle(writePipe);
    if (!ok) { CloseHandle(readPipe); return false; }
    std::string text; char chunk[512];
    DWORD n = 0;
    const ULONGLONG deadline = GetTickCount64() + 4000;
    for (;;) {
        DWORD avail = 0;
        if (PeekNamedPipe(readPipe, nullptr, 0, nullptr, &avail, nullptr) && avail > 0) {
            const DWORD want = avail < sizeof(chunk) ? avail : sizeof(chunk);
            if (ReadFile(readPipe, chunk, want, &n, nullptr) && n) text.append(chunk, chunk + n);
        }
        if (WaitForSingleObject(pi.hProcess, 0) == WAIT_OBJECT_0) break;
        if (GetTickCount64() >= deadline) {
            TerminateProcess(pi.hProcess, 1);
            WaitForSingleObject(pi.hProcess, 1000);
            break;
        }
        Sleep(10);
    }
    DWORD exitCode = 1;
    GetExitCodeProcess(pi.hProcess, &exitCode);
    CloseHandle(readPipe); CloseHandle(pi.hThread); CloseHandle(pi.hProcess);
    if (output) *output = text;
    return exitCode == ERROR_SUCCESS;
}

// S60（2026-09-11）：HidHide 安装/重装由部署通道完成（deploy-installed.ps1 已
// 把锁定安装器校验 hash 后放入 POWER_CONTROL_DIR\redist）。HC Misc\HidHide.cs
// 为 fail-fast 启动检查，绝无运行时自动安装；早前 boot 自动安装（Inno Setup
// 静默重装会触发设备重枚举/重启队列，破坏外接 XInput 手柄需拔插恢复）已整
// 段移除。kHidHideSetupName 保留供部署脚本引用。
static const wchar_t* kHidHideSetupName = L"HidHide_1.5.230_x64.exe";

static bool hidHideServiceRunning(bool* queriedOk = nullptr) {
    if (queriedOk) *queriedOk = false;
    std::string svc;
    if (!hidHideRunSc(L"query HidHide", &svc)) return false;
    std::string upper = svc;
    std::transform(upper.begin(), upper.end(), upper.begin(),
        [](unsigned char c) { return static_cast<char>(toupper(c)); });
    if (queriedOk) *queriedOk = true;
    return upper.find("RUNNING") != std::string::npos;
}

// 7.52 P1-T5（A4，用户裁决删除运行时自愈）：对齐 HC Misc\HidHide.cs:24-29
// （静态 ctor IsInstalled → false 即 throw）——启动态仅做服务存在性检查并
// fail-closed 记录，绝不做 sc start 运行时自愈（HC 无自愈）。服务缺失的
// 根治靠部署通道（deploy-installed.ps1 已把锁定安装器校验放 redist）；
// 此处仅在 apply/start 前输出诊断，不修改设备树。
static bool hidHideServiceHealth(const char* reason) {
    if (g_hidHideLastHealTick != 0 && GetTickCount64() - g_hidHideLastHealTick < 15000)
        return true; // 节流：健康检查 ≤ 15s（原 selfHeal 节流，保留）
    g_hidHideLastHealTick = GetTickCount64();

    // 服务健康检查（只读，无 sc start —— A4 已删自愈）。
    bool queried = false;
    const bool running = hidHideServiceRunning(&queried);
    if (queried && !running) {
        appendNativeLifecycleLog("hidhide.service-not-running", {
            {"reason", reason ? reason : "unknown"},
            {"note", "deploy-channel-reinstall-required; no-runtime-selfheal-hc-parity"}
        });
    }

    // 坏态诊断（只记日志，不做任何运行时破坏/重装——对齐 HC 无运行时自愈，
    // 用户裁决撤销自动卸载+重装后与 HC 完全一致）：
    // --dev-all 不可交互说明驱动/配置坏态，本机 0910-18 实证这种状态下 hide
    // 注册仍可写盘但物理源（XInput）永不复现；根治靠部署通道干净重装/UI 指引。
    std::string listed;
    if (!(hidHideRun(L"--dev-all", &listed) && !listed.empty())) {
        appendNativeLifecycleLog("hidhide.driver-degraded", {
            {"reason", reason ? reason : "unknown"},
            {"note", "cli-uninteractive; deploy-channel-clean-reinstall-or-manual-repair"}
        });
    }
    return true;
}

// HC parity runner: pnputil.exe /restart-device restarts the device instance
// ITSELF (devcon/pnputil semantics), preserving HidHide cloaking state so the
// device re-enumerates hidden-but-present and its XInput slot returns.  This is
// the HC CyclePort equivalent for USB/HID enumerators (IController.cs:585-588).
// HC CyclePort 语义（PnPDetails.CyclePort -> Nefarius UsbPnPDevice.CyclePort）：
// 已迁移到 InputHost HIDHIDE_CYCLE 命令（7.52，InputHost 持有 Nefarius
// PnPDevice 实例，见 hidHideCycleInstance）。native 原手写 hub-cycle
// （hidHideCyclePortHub + IOCTL 0x220444）属原创传输层，按「已调用 HC DLL
// 零原创」原则移除——实证细节见 40 号 ledger，不再保留实现。
// HC IController.CyclePort 语义对齐（IController.cs:561-600 + PnPDetails.cs:126-151
// + Nefarius UsbPnPDevice.CyclePort）：顺序 = StopRumble → IsBusy(防重入) →
// enumerator switch（USB/HID → hub port cycle；BTHENUM/BTHLEDEVICE → 卸载+refresh，
// YMCC 无蓝牙物理源，登记差异不实现；其他 enumerator → 不操作）→ 失败复位。
// 前向声明先于此处的定义使用（7.52 CyclePort 迁移后 hidHideCycleInstance
// 需经 inputHostRequestLocked 调用 InputHost HIDHIDE_CYCLE，早于 8297 声明区）。
static bool inputHostRequestLocked(const char* command, const json& payload,
                                   const char* expectedStatus, DWORD timeoutMs,
                                   json* responseOut = nullptr, bool advanceSequence = true,
                                   inputHostSelfTestRules::ReceiptObservation* receiptObservationOut = nullptr);
static std::atomic<bool> g_hidHideCycleInFlight{false};
// F3（2026-09-11 十二批次）：HC IsBusy 语义对齐——IController.cs:573 cycle 前
// 挂 busy、:596 仅失败复位；ControllerManager.cs:501/691/897 控制器重新出现
// 时复位。native 用 inFlight 兼作 busy：成功 cycle 后保持 busy 直到
// controller-wake 才复位（防重枚举掉线被 P1-T10 误判为拔线解隐）。
// 15s 超时兜底防 wake 丢失（**兜底为 YMCC delta**，HC 无超时——wake 事件
// 若因系统态丢事件，超时后允许 unhide 照常。代码标注以区分）。
static ULONGLONG g_hidHideCycleBusySinceTick = 0;
static constexpr ULONGLONG kHidHideCycleBusyTimeoutMs = 15000;

// ── 取证（2026-09-18 用户授权）：cycle/busy 状态机观测 ──
// 边界纪律（用户裁决）：**只允许投放到"开关打开才存在的高频区"**，即受门控的
// 域日志 virtual-gamepad.log（门 = domainLogs.virtual）；**绝不加入常驻低频事件
// 区**（native-lifecycle.log 不新增任何行）。门关时零构造、零写入。
// 调用点仅 hide/restore 事务级（非每 tick），门关时的入参构造成本可忽略。
static void hidHideCycleTrace(const char* event, const json& detail) {
    if (!domainLogEnabled("virtual")) return;
    appendDomainLog("virtual", event, detail);
}
// busy 状态机显式终态（评审要求：skip/失败/超时/退出都要可判别）。
static void hidHideCycleTraceBusy(const char* state, const char* via,
                                  unsigned long long heldMs, const std::wstring& instance) {
    if (!domainLogEnabled("virtual")) return;
    appendDomainLog("virtual", "hidhide.cycle-busy", {
        {"state", state ? state : ""}, {"via", via ? via : ""},
        {"heldMs", heldMs}, {"instance", W2U(instance)}, {"tick", GetTickCount64()}
    });
}

// HC ControllerManager.XUsbDeviceArrived 复位 busy（:897 同义）。由
// controller-wake 调用；亦在超时兜底路径调用。失败 cycle 不经过此（即时复位）。
static void hidHideCycleClearBusy(const char* via = "unspecified") {
    if (g_hidHideCycleInFlight.load(std::memory_order_acquire)) {
        const ULONGLONG since = g_hidHideCycleBusySinceTick;
        hidHideCycleTraceBusy("idle", via, since ? (GetTickCount64() - since) : 0,
                              std::wstring());
    }
    g_hidHideCycleInFlight.store(false, std::memory_order_release);
    g_hidHideCycleBusySinceTick = 0;
}
// P1-T10/F3：cycle 后 busy 窗口内（成功保持 / 超时兜底已过期）视为
// "重枚举在途"，拔线 unhide 须排除此窗口（HC if (!IsPowerCycling) 同义）。
static bool hidHideCycleBusyActive() {
    if (!g_hidHideCycleInFlight.load(std::memory_order_acquire)) return false;
    const ULONGLONG since = g_hidHideCycleBusySinceTick;
    if (since == 0) return false;
    if (GetTickCount64() - since < kHidHideCycleBusyTimeoutMs) return true;
    // 超时兜底（YMCC delta）：wake 事件丢失时允许 busy 过期，unhide 照常。
    hidHideCycleClearBusy("timeout");
    return false;
}
// 批105 / F-a 族前置（自纠）：busy 兼作**跨线程重入保护**（cycle 调用点分居生命周期线程与
// gamepadSerial worker）。无条件释放会在极窄交错下允许两个端口 cycle 并发（可能顶死 hub）。
// 判据不用猜测：HIDHIDE_CYCLE 的 pipe 超时是 5000 ms（本文件 L13885 调用点），故**任何在途
// 调用必 <5 s**；挂起超过 5500 ms 的 busy 不可能是在途调用，只可能是需要解锁的陈旧挂起
//（丢 wake 的那次成功 cycle）。只在此时释放。
static constexpr ULONGLONG kHidHideCycleStaleClearMs = 5500;
static bool hidHideCycleClearBusyIfStale(const char* via) {
    if (!g_hidHideCycleInFlight.load(std::memory_order_acquire)) return false;
    const ULONGLONG since = g_hidHideCycleBusySinceTick;
    if (since == 0) return false;
    if (GetTickCount64() - since < kHidHideCycleStaleClearMs) return false;
    hidHideCycleClearBusy(via);
    return true;
}
// GP-926R17 R17-4：RPC 超时可传入（默认 5000 保持其它调用点逐字等价）；T1 侧传剩余预算。
static bool hidHideCycleInstance(const std::wstring& instanceId,
                                 const char* phase = "unspecified",
                                 DWORD cycleTimeoutMs = 5000) {
    if (instanceId.empty()) return false;
    // 取证：cycle 尝试（补齐"成功 cycle 未记实例"的空白；供与外部设备到达
    // 监视器 Kernel-PnP/WMI 按时间戳对齐）。
    const ULONGLONG cycleStartTick = GetTickCount64();
    const DWORD cycleMaskBefore = g_xinputConnectedMask;
    hidHideCycleTrace("hidhide.cycle-attempt", {
        {"phase", phase ? phase : ""}, {"instance", W2U(instanceId)},
        {"busyBefore", g_hidHideCycleInFlight.load(std::memory_order_acquire)},
        {"xinputMask", cycleMaskBefore}, {"tick", cycleStartTick}
    });
    // HC StopRumble()：cycle 前停止物理手柄震动（XInputSetState 清零），避免
    // 断电/重枚举期间驱动 I/O 干扰（XInputController.StopRumble 等价）。
    if (g_xinputPrimarySlot < 4) {
        XINPUT_VIBRATION zero{ 0, 0 };
        (void)ymccXInputSetState14(g_xinputPrimarySlot, &zero);
    }
    // GP-MSIG3E-3-R2（E4）：同一 StopRumble 语义覆盖 MSI DInput 实体后端（仅受管时写实机）。
    msiDinputFeedbackStop("hidhide-cycle");
    // GP-MSIG3E-3-R2（r2-6）：power cycle 会重枚举物理手柄 ⇒ 登记为"最近受管事务"，
    // 供随后的 InputLost 归因（区分"隐藏副作用"与"采集自身缺陷"）。
    msiNoteDisruptiveTx("hidhide-cycle");
    // HC IsBusy / ControllerManager.PowerCyclers 防重入（IController.cs:572-573）。
    if (g_hidHideCycleInFlight.exchange(true)) {
        // 取证：cycle-in-flight 可能是刚发起的真实在途调用，也可能是已丢失
        // wake 后留下的陈旧 busy。只记状态，不在这里擅自清锁或重试。
        const ULONGLONG skipTick = GetTickCount64();
        const ULONGLONG busySince = g_hidHideCycleBusySinceTick;
        const ULONGLONG busyAgeMs = busySince != 0 && skipTick >= busySince
            ? skipTick - busySince : 0;
        appendNativeLifecycleLog("hidhide.cycle-skip", {
            {"reason", "cycle-in-flight"}, {"instance", W2U(instanceId)},
            {"busySinceTick", busySince}, {"busyAgeMs", busyAgeMs},
            {"busyTimeoutMs", kHidHideCycleBusyTimeoutMs},
            {"staleClearThresholdMs", kHidHideCycleStaleClearMs}
        });
        hidHideCycleTrace("hidhide.cycle-result", {
            {"phase", phase ? phase : ""}, {"instance", W2U(instanceId)},
            {"skipped", true}, {"success", false},
            {"busySinceTick", busySince}, {"busyAgeMs", busyAgeMs},
            {"busyTimeoutMs", kHidHideCycleBusyTimeoutMs},
            {"staleClearThresholdMs", kHidHideCycleStaleClearMs},
            {"elapsedMs", skipTick - cycleStartTick},
            {"xinputMaskAtReturn", g_xinputConnectedMask}, {"tick", skipTick}
        });
        return false;
    }
    g_hidHideCycleBusySinceTick = GetTickCount64();
    hidHideCycleTraceBusy("busy", "cycle-attempt", 0, instanceId);

    // HC GetEnumerator() switch（IController.cs:575-590）：只对已知 enumerator
    // 做传输操作；未知 enumerator 一律返回 false，不尝试任何 pnputil/disable。
    std::wstring enumerator;
    {
        DEVINST dnTmp = 0;
        if (CM_Locate_DevNodeW(&dnTmp, const_cast<wchar_t*>(instanceId.c_str()), CM_LOCATE_DEVNODE_NORMAL) == CR_SUCCESS) {
            WCHAR buf[64]{};
            ULONG len = sizeof(buf);
            if (CM_Get_DevNode_Registry_PropertyW(dnTmp, CM_DRP_ENUMERATOR_NAME,
                nullptr, buf, &len, 0) == CR_SUCCESS && len > 2)
                enumerator.assign(buf, (len / sizeof(wchar_t)) - 1);
        }
    }
    std::string enumUpper;
    enumUpper.resize(enumerator.size());
    std::transform(enumerator.begin(), enumerator.end(), enumUpper.begin(),
        [](wchar_t c) { return static_cast<char>(toupper((unsigned char)c)); });
    const bool isUsbLike = enumUpper == "USB" || enumUpper == "HID";
    const bool isBtLike = enumUpper == "BTHENUM" || enumUpper == "BTHLEDEVICE";
    if (!isUsbLike && !isBtLike && !enumerator.empty()) {
        appendNativeLifecycleLog("hidhide.cycle-skip", {
            {"reason", "unsupported-enumerator"}, {"enumerator", enumUpper},
            {"instance", W2U(instanceId)}
        });
        // F3：非成功路径即时复位 busy（HC IController.cs:596 仅失败复位）。
        hidHideCycleClearBusy("unsupported-enumerator");
        hidHideCycleTrace("hidhide.cycle-result", {
            {"phase", phase ? phase : ""}, {"instance", W2U(instanceId)},
            {"skipped", true}, {"reason", "unsupported-enumerator"},
            {"enumerator", enumUpper}, {"success", false},
            {"elapsedMs", GetTickCount64() - cycleStartTick},
            {"xinputMaskAtReturn", g_xinputConnectedMask}, {"tick", GetTickCount64()}
        });
        return false;
    }

    // 7.52（CyclePort 迁移到 HC 捆绑 Nefarius DLL）：HC PnPDetails.CyclePort =
    // GetUsbPnPDevice().CyclePort()（Nefarius.Utilities.DeviceManagement，
    // PnPDetails.cs:126-151 + IController.cs:561-600）。native 原手写 hub-cycle
    // IOCTL（0x220444）属原创传输层——按「已调用 HC DLL 零原创」原则移除，
    // 改经 InputHost HIDHIDE_CYCLE 命令调用 Nefarius CyclePort（InputHost 持有
    // PnPDevice 实例；Nefarius CyclePort 返回 void，不抛 = 成功，与 HC
    // PnPDetails.cs:141-146 try/catch 语义一致）。
    // enumerator 门控保留（HC GetEnumerator switch：USB/HID→cycle，无线/未知→false）。
    const bool hcUsbLike = isUsbLike;
    bool success = false;
    if (hcUsbLike) {
        // 仅 USB/HID 走 CyclePort（HC 同）；BTH/未知返回 false 由上方跳过。
        json cycleResponse;
        // 2026-09-11：载荷键名与 HIDE/UNHIDE/APP_REG 统一为 "path"
        // （InputHost HidHidePath 解析 properties["path"]，7.52 误用
        // "hidHidePath" 导致空 path → cycle 恒 false-empty-path）。
        const bool pipeOk = inputHostRequestLocked("HIDHIDE_CYCLE",
            {{"path", W2U(instanceId)}},
            "hidhide-cycle", cycleTimeoutMs, &cycleResponse);
        // HIDHIDE_CYCLE 是 Ack 命令（status=hidhide-cycle），inputHostRequestLocked
        // 的 expectedStatus 需匹配 InputHost; 直接取响应体解码。结果在 detail
        // 字段（InputHost SerializeResponse 未定义 payload 字段，7.52 首轮曾
        // 误读 payload 导致 CyclePort 成功也被判失败——2026-09-11 实机审查修复）。
        if (pipeOk && cycleResponse.contains("detail")) {
            const std::string detail = cycleResponse.value("detail", "");
            success = detail == "true" || detail.rfind("true", 0) == 0;
        }
        if (!pipeOk)
            appendNativeLifecycleLog("hidhide.cycle-pipe-failed", {
                {"instance", W2U(instanceId)}, {"reason", "input-host-unreachable"},
                {"hostProcessPresent", g_inputHostProcess != nullptr},
                {"transportFault", g_inputHostTransportFault},
                {"pipeRetired", g_inputHostPipeRetired},
                {"hello", g_inputHostHello},
                {"pipeConnected", g_inputHostPipeConnected},
                {"pipeNamePresent", !g_inputHostPipeName.empty()},
                {"runIdPresent", !g_inputHostRunId.empty()},
                {"startupNoncePresent", !g_inputHostStartupNonce.empty()},
                {"unavailabilityReason", ymcc::input::transport::unavailabilityReason(ymcc::input::transport::Facts{g_inputHostProcess != nullptr, g_inputHostTransportFault,
                    g_inputHostPipeRetired, g_inputHostHello, g_inputHostPipeConnected,
                    !g_inputHostPipeName.empty(), !g_inputHostRunId.empty(),
                    !g_inputHostStartupNonce.empty()})},
                {"note", "HC Nefarius CyclePort 需 Host 进程内 PnPDevice"}
            });
    }
    // F3：成功 cycle 保持 busy 直到 controller-wake 才复位（HC IController.cs:
    // 573 挂 busy、仅失败 :596 复位；ControllerManager :897 控制器重现复位）。
    // 失败即时复位（HC 同）——失败后无重枚举在途，busy 无意义。
    if (!success)
        hidHideCycleClearBusy("cycle-failed");
    // 取证：cycle 结果（含成功路径——此前成功 cycle 不留实例/耗时记录）。
    // 注意 xinputMaskAtReturn 是"返回时刻"的掩码快照；重枚举引起的掉槽通常
    // 稍晚发生，须与 xinput-slot-devices / 外部到达监视器按时间戳对齐判读。
    hidHideCycleTrace("hidhide.cycle-result", {
        {"phase", phase ? phase : ""}, {"instance", W2U(instanceId)},
        {"skipped", false}, {"reason", hcUsbLike ? "usb-like-cycle" : "non-usb-enumerator"},
        {"success", success}, {"elapsedMs", GetTickCount64() - cycleStartTick},
        {"xinputMaskAtReturn", g_xinputConnectedMask},
        {"busyHeld", g_hidHideCycleInFlight.load(std::memory_order_acquire)},
        {"tick", GetTickCount64()}
    });
    return success;
}
// A5 已删除（2026-09-11，执行项 1）：四死函数 hidHideLegacyUnadmittedGamingScan /
// hidHideRestorePhysical / hidHideShouldHidePhysical / hidHideCollectLegacyGamingCandidates
// 及其独占辅助（hidHideLooksLikeVirtualDs4Legacy / hidHideSanitize / hidHideParseList /
// hcIsGamingHid / g_hidHideHidden / g_hidHideCloakEnabledByUs）均为生产不可达
// 遗留扫描路径，无任何调用点（HC_REFERENCE_FRAGMENT 注明"非 HC target 选择"）。
// 删除缘由与证据见 43 号 E2-A5，符合「已调用 HC DLL 零原创」原则。
// 10 号之后建立的 HC-parity 事务（hidHideApplyPhysicalTransaction /
// hidHideRestorePhysicalTransaction）是唯一隐藏/恢复路径。

// HC-parity physical identity and visibility transaction.  This path is
// HC's selected-controller lifecycle (no legacy broad gaming scan): HC hides
// the already-selected controller's instance/container pair, never a broad
// "all gaming HID" scan.  The transaction below is admitted only after a
// concrete Raw Input -> PnP identity (or one unambiguous physical controller
// group) has been resolved, and it keeps an exact pre-mutation journal for
// rollback.  P-HID success is still not P-XINPUT or game-consumer proof.
struct HidHidePhysicalIdentity {
    bool resolved = false;
    std::string sourcePath;
    std::string deviceInstanceId;
    std::string baseContainerDeviceInstanceId;
    // S2 墙 B（虚拟手柄常驻任务书 2026-09-15）：XUSB 接口路径
    // （\\?\usb#vid..pid..#..#{ec87f1e3-...}）。OpenXInput 代理只认该形态；
    // 实例 ID 形态实测 1167 拒绝。由 hidHideResolveXusbInterfacePath 填充，
    // 空 = 解析失败 → slot-guard 回退跳过（零行为差）。
    std::string baseContainerDevicePath;
    USHORT vendorId = 0;
    USHORT productId = 0;
    USAGE usagePage = 0;
    USAGE usage = 0;
    std::string physicalIdentity;
};

static bool legionMotionHardwareAdmitted(USHORT vendorId,USHORT productId) {
    return legionMotionModelBinding().hardwareAdmitted(vendorId,productId,legionBackIsPid,legionSBackIsPid);
}
static bool legionMotionCollectionAdmitted(USHORT vendorId,USHORT productId,USAGE usagePage,USAGE usage) {
    return usagePage==0xFFA0 && usage==0x0001 && legionMotionHardwareAdmitted(vendorId,productId);
}
static bool legionMotionIdentityAdmitted(const HidHidePhysicalIdentity& identity) {
    return identity.resolved && !identity.baseContainerDeviceInstanceId.empty() &&
        legionMotionHardwareAdmitted(identity.vendorId,identity.productId);
}
static std::string legionMotionStableIdentity(const HidHidePhysicalIdentity& identity) {
    if (!legionMotionIdentityAdmitted(identity)) return {};
    return "controller/lenovo/" + std::to_string(identity.vendorId) + "/" +
        std::to_string(identity.productId) + "/" + ascii_lower(identity.baseContainerDeviceInstanceId);
}
static std::optional<ymcc::legion_input::MotionAxes> legionMotionDecodeReport(
    const HidHidePhysicalIdentity& identity,const BYTE* rawReport,size_t capacity,
    size_t actualBytes,unsigned sensorIndex) {
    if (!legionMotionIdentityAdmitted(identity) || identity.usagePage!=0xFFA0 || identity.usage!=0x0001 ||
        actualBytes>capacity) return std::nullopt;
    const BYTE* logical=rawReport;
    size_t logicalBytes=actualBytes;
    if (!legionHcInputReportView(logical,logicalBytes)) return std::nullopt;
    return legionMotionModelBinding().decode(ymcc::legion_input::Protocol::Tablet,
        ymcc::legion_input::Protocol::GoS,ymcc::legion_input::decodeLogical,
        logical,logicalBytes,logicalBytes,sensorIndex);
}
// Caller holds physicalIdentityMx. Retire the source before publishing a new
// selected container, including A -> B -> A with unchanged RawInput generation.
static void legionMotionSelectedIdentityChanging(const HidHidePhysicalIdentity& previous,
                                                 const HidHidePhysicalIdentity& next) {
    if (g_machineIdentity.family == YmccFamily::LenovoLegionGo &&
        legionMotionStableIdentity(previous) != legionMotionStableIdentity(next)) legionMotionRevoke();
}

struct HidHideVisibilitySnapshot {
    bool valid = false;
    bool cloaking = false;
    std::vector<std::wstring> hidden;
    std::vector<std::wstring> applications;
    std::string cloakRaw;
    std::string hiddenRaw;
    std::string applicationsRaw;
    // GP-MSIG3E-3 §3.A / GP-MSIG3E-6-LC-R2 §四 R4：inverse application list 只读三态原始串。
    // CLI 兜底路径（`--inv-state` → `--inv-on`/`--inv-off`）与 pipe full-query（Host `inverse`
    // 只读枚举 `on`/`off`）均可填；任一读取失败 / 字段缺失 / 非 string / 未知值 ⇒ 留空 =
    // unknown（**不得当成 off**）。语义：off = 正常 allowlist 语义（被 hide 的目标对未登记
    // 应用不可见），on = 反选（只有清单内应用可见）——虚拟模式要求 off。
    std::string inverseRaw;
};

struct HidHideVisibilityJournal {
    bool active = false;
    bool applicationAdded = false;
    std::vector<std::wstring> ownedApplications; // MSI: exact attempted additions, independent of later file existence
    bool ownedApplicationResponsibilityUnknown = false; // unknown responsibility survives union with known paths
    bool cloakChanged = false;
    std::string transactionId;
    // HC's selected IController owns one source identity and one HideHID
    // transaction.  The public side remains one virtual target and one writer;
    // this journal must not grow into a multi-controller hide list.
    std::vector<HidHidePhysicalIdentity> physicalSources;
    std::vector<std::wstring> cycledBaseContainers;
    HidHidePhysicalIdentity physical;
    HidHideVisibilitySnapshot before;
    std::vector<std::wstring> hiddenByUs;
    ULONGLONG admittedTick = 0;
    // D2（2026-09-17）：恢复侧重枚举改在 Host 存活窗口（pre-release 段）完成，
    // 结果登记于此；post-release 的 restore 只消费结果、不再重复尝试（彼时 Host
    // 已死，任何 cycle 必失败且 cycle 本身仅诊断）。hide 事务开簿处整结构重置
    // ⇒ 本字段随事务自动归零，无需额外清零。
    bool preReleaseCycleAttempted = false;
    bool preReleaseCycleOk = false;
};

