static std::string hidHideUpper(std::string value) {
    for (char& c : value) c = static_cast<char>(toupper(static_cast<unsigned char>(c)));
    return value;
}

// GP-MSIG3E-3-R2（E1）：MSI 受管 DInput 主源的**单一记录**。
// 背景：隐藏选择与重确认门过去读 g_hidHidePhysicalIdentity（来自 Raw Input，通常是
// 1901/IG_01 XInput 接口），而 MSI 主源是 1902/MI_00&COL01 DInput 接口；切换模式时
// 前者消失、后者出现，两处比对全部失败 ⇒ N9（隐藏挂不上）+ InputLost 后重确认被拒。
// 本记录由采集侧（msiDinputOpen，通过 1902+MI_00&COL01 双门后）发布，释放/禁用/停止时撤销；
// 隐藏选择、重确认门、late-hide/refresh 都读它，跨代际一致（generation = 绑定代次）。
struct HidHideMsiMainSourceRecord {
    bool valid = false;
    unsigned generation = 0;
    std::string interfacePath;                 // DirectInput DIPROP_GUIDANDPATH 接口路径
    std::string usbInstance;                   // 上溯到的 USB 顶层设备实例（父节点树级身份）
    std::string containerGuid;                 // 接口容器 GUID（未解析时 "unresolved"/"unknown"）
    unsigned vendorId = 0;
    unsigned productId = 0;
    ULONGLONG publishedAt = 0;
};
static std::mutex g_msiMainSourceMx;
static std::atomic<unsigned long long> g_msiFeedbackSourceGeneration{0};
static HidHideMsiMainSourceRecord g_msiMainSource;

static std::shared_ptr<const HidHideMsiMainSourceRecord> g_msiFeedbackSourceRecord;
static std::atomic<unsigned long long> g_msiFeedbackIdentityBuilds{0};

// Diagnostic metadata only: the Native process never opens a USB hub for this probe.
#if defined(YMCC_MSI_USB_NAME_ORIGIN_DIAGNOSTIC) && defined(YMCC_MSI_VISIBILITY_DIAGNOSTIC) && !defined(YMCC_FAULT_INJECT) && !defined(YMCC_MSI_FOREGROUND_ISOLATION_TEST)
static ymcc::msi::usbName::ContextPublisher g_msiUsbNameContext;
static uint64_t g_msiUsbNameSourcePowerGeneration=0; // protected by g_msiMainSourceMx
static void msiUsbNameContextPublishLocked(const char* phase,bool freshBinding=false) noexcept {
    try{using namespace ymcc::msi::usbName;const bool board=msiClawKnownBoardAuthority(),detail=msiControllerTraceEnabled();
        if((!board||!detail)&&!g_msiUsbNameContext.opened())return;
        const auto powerSnapshot=currentPowerGeneration();
        if(freshBinding)g_msiUsbNameSourcePowerGeneration=powerSnapshot;
        Context c;c.boardAuthorized=board?1:0;c.sourceValid=board&&detail&&!g_exitRequested.load(std::memory_order_acquire)&&g_powerLifecycle.load(std::memory_order_acquire)==PowerLifecycle::Ready&&g_msiUsbNameSourcePowerGeneration==powerSnapshot&&g_msiMainSource.valid&&g_msiMainSource.vendorId==0x0db0&&g_msiMainSource.productId==0x1902?1:0;
        c.sourceGeneration=g_msiMainSource.generation;bindPower(c,g_msiUsbNameSourcePowerGeneration,powerSnapshot);c.hostEpoch=inputHostEpochToken();c.observedTick=GetTickCount64();
        const bool fit=text(c.board,g_machineIdentity.product)&&text(c.usbRoot,g_msiMainSource.usbInstance)&&text(c.interfacePath,g_msiMainSource.interfacePath)&&text(c.phase,phase?phase:"unknown");
        if(!fit||g_powerLifecycle.load(std::memory_order_acquire)!=PowerLifecycle::Ready||g_exitRequested.load(std::memory_order_acquire))c.sourceValid=0;
        bindPower(c,g_msiUsbNameSourcePowerGeneration,currentPowerGeneration());(void)g_msiUsbNameContext.publish(c);
    }catch(...){/* Metadata failure never changes source, target or exit. */}
}
static void msiUsbNameContextRefresh() noexcept {try{if(!msiClawKnownBoardAuthority())return;std::lock_guard<std::mutex> lock(g_msiMainSourceMx);msiUsbNameContextPublishLocked("current-source");}catch(...){}}
static std::wstring msiUsbNameContextCommandSuffix() noexcept {
    try{if(!msiClawKnownBoardAuthority()||!msiControllerTraceEnabled())return{};msiUsbNameContextRefresh();const auto name=g_msiUsbNameContext.name();return name.empty()?std::wstring{}:L" --msi-name-context "+name;}catch(...){return{};}
}
#else
static void msiUsbNameContextPublishLocked(const char*,bool=false) noexcept {}
static void msiUsbNameContextRefresh() noexcept {}
static std::wstring msiUsbNameContextCommandSuffix() noexcept {return{};}
#endif

static void msiDinputPublishMainSourceIdentity(const std::string& interfacePath,
                                               const std::string& containerGuid,
                                               unsigned vendorId, unsigned productId,
                                               unsigned generation) {
    HidHideMsiMainSourceRecord record;
    record.valid = true;
    record.generation = generation;
    record.interfacePath = interfacePath;
    record.containerGuid = containerGuid;
    record.vendorId = vendorId;
    record.productId = productId;
    record.publishedAt = GetTickCount64();
    // 上溯 USB 顶层实例（父节点树级身份）：取不到留空，消费侧按 fail-closed 处理（不猜）。
    if (!interfacePath.empty()) {
        std::wstring usbInstance;
        if (deviceInterfaceUsbInstance(U2W(interfacePath).c_str(), usbInstance))
            record.usbInstance = W2U(usbInstance);
    }
    bool ownedReturnAvailabilityEdge=false;
    {
        std::lock_guard<std::mutex> lock(g_msiMainSourceMx);
        const bool changed=!g_msiMainSource.valid || g_msiMainSource.generation!=record.generation ||
            g_msiMainSource.interfacePath!=record.interfacePath || g_msiMainSource.usbInstance!=record.usbInstance;
        ownedReturnAvailabilityEdge=changed && msiClawKnownBoardAuthority() &&
            g_msiOwnedReturnPending.load(std::memory_order_acquire) && !g_realStickTest.virtualTargetEnabled &&
            record.generation!=0 && record.vendorId==0x0db0 && record.productId==0x1902 &&
            !record.interfacePath.empty() && hidHideUpper(record.usbInstance).find("USB\\VID_0DB0&PID_1902\\")==0;
        g_oemShortcutEdgeEpoch.fetch_add(1, std::memory_order_acq_rel);
        g_msiMainSourceRevision.fetch_add(1,std::memory_order_acq_rel);
        g_msiMainSource = record;
        msiUsbNameContextPublishLocked("source-published",true);
        g_msiFeedbackSourceRecord=std::make_shared<const HidHideMsiMainSourceRecord>(record);
        g_msiFeedbackIdentityBuilds.fetch_add(1,std::memory_order_relaxed);
        g_msiFeedbackSourceGeneration.store(msiClawKnownBoardAuthority()?generation:0,std::memory_order_release);
        // Availability notification only: the return observer revalidates exact
        // ownership/root and keeps its original retry budget. No Windows event
        // or XInput slot arrival is required for a late DInput source rebind.
        if(ownedReturnAvailabilityEdge)g_msiOwnedReturnSourceEvent.fetch_add(1,std::memory_order_release);
    }
    if(msiControllerTraceEnabled())msiControllerTraceLog("source-published",{{"generation",generation},{"interfacePath",interfacePath},{"productId",productId}},false);
    msiForegroundIsolationRememberMain(record.usbInstance);
    (void)msiDinputFeedbackWakePendingStop();
    // GP-MSIG3E-4B §4（Q2）：本行已登记进 kBaseEvents——默认详细门关也必须可读，因为
// late-hide 旁路的判读需要"记录何时发布/撤销、代次多少、板号是否已授权"这条时间线
//（只有 decision 行的结论字段无法区分"未重绑/快照未知/代次不符"）。事件级：每次绑定 1 行。
    appendNativeLifecycleLog("msi-main-source-record", {
        {"phase", "published"},
        {"generation", static_cast<unsigned long long>(generation)},
        {"interfacePath", interfacePath},
        {"usbInstance", record.usbInstance},
        {"containerGuid", containerGuid},
        {"ownedReturnAvailabilityEdge",ownedReturnAvailabilityEdge},
        {"ownedReturnSourceEvent",g_msiOwnedReturnSourceEvent.load(std::memory_order_acquire)},
        {"vendorId", static_cast<int>(vendorId)},
        {"productId", static_cast<int>(productId)},
        {"family", ymccFamilyName(g_machineIdentity.family)},
        {"board", g_machineIdentity.product},
        {"boardAuthorized", msiClawKnownBoardAuthority()},
        // R10-R2 M0：source publish 事务身份（owner token = Host runId）。
        {"hostEpoch", inputHostEpochToken()}, {"ownerToken", inputHostOwnerToken()}
    });
}

static void msiDinputRevokeMainSourceIdentity(const char* reason) {
    HidHideMsiMainSourceRecord previous;
    {
        std::lock_guard<std::mutex> lock(g_msiMainSourceMx);
        previous = g_msiMainSource;
        if (previous.valid) g_oemShortcutEdgeEpoch.fetch_add(1, std::memory_order_acq_rel);
        g_msiMainSourceRevision.fetch_add(1,std::memory_order_acq_rel);
        g_msiMainSource = HidHideMsiMainSourceRecord{};
        msiUsbNameContextPublishLocked("source-revoked");
        g_msiFeedbackSourceRecord.reset();
        g_msiFeedbackSourceGeneration.store(0,std::memory_order_release);
    }
    msiDinputInvalidateFeedbackLease();
    if (!previous.valid) return;
    (void)msiDinputFeedbackWakePendingStop();
    if(msiControllerTraceEnabled())msiControllerTraceLog("source-revoked",{{"reason",reason?reason:"unspecified"},{"previousGeneration",previous.generation},{"previousInterfacePath",previous.interfacePath}},false);
    // GP-MSIG3E-4B §4（Q2）：撤销行同样常开可读（同一事件的另一半）——带被撤记录的身份字段，
    // 现场可据此判断"重确认时刻记录是否仍为同一个代次"。事件级：每次撤销 1 行。
    appendNativeLifecycleLog("msi-main-source-record", {
        {"phase", "revoked"},
        {"reason", reason ? reason : ""},
        {"generation", static_cast<unsigned long long>(previous.generation)},
        {"interfacePath", previous.interfacePath},
        {"vendorId", static_cast<int>(previous.vendorId)},
        {"productId", static_cast<int>(previous.productId)},
        {"family", ymccFamilyName(g_machineIdentity.family)},
        {"board", g_machineIdentity.product},
        {"boardAuthorized", msiClawKnownBoardAuthority()},
        // R10-R2 M0：source revoke 事务身份（owner token = Host runId）。
        {"hostEpoch", inputHostEpochToken()}, {"ownerToken", inputHostOwnerToken()}
    });
}

static bool msiDinputMainSourceRecordSnapshot(HidHideMsiMainSourceRecord& out) {
    std::lock_guard<std::mutex> lock(g_msiMainSourceMx);
    out = g_msiMainSource;
    return out.valid;
}

// 受管主源是否**当前有效**：记录有效 + 板号权威（R4）。两者齐备才允许把 1901→1902
// 当作同一物理源（受管模式操作 + 可靠绑定证明），不做"任意发现的 MSI 控制器都同源"。
static bool msiDinputManagedMainSourceActive(HidHideMsiMainSourceRecord& out) {
    if (!msiDinputMainSourceRecordSnapshot(out)) return false;
    return msiClawKnownBoardAuthority();
}

// Feedback snapshots keep immutable source identity alive without copying three
// strings on every start/stop. The mutex still signs current generation/path.
static std::shared_ptr<const HidHideMsiMainSourceRecord> msiDinputFeedbackSourceSnapshot() {
    std::lock_guard<std::mutex> lock(g_msiMainSourceMx);
    if(!g_msiMainSource.valid||!msiClawKnownBoardAuthority())return {};
    // Legacy early-return fixtures assign the public source record directly.
    // Synchronize that record once too; normal publication already built it.
    if(!g_msiFeedbackSourceRecord||g_msiFeedbackSourceRecord->generation!=g_msiMainSource.generation||
        g_msiFeedbackSourceRecord->interfacePath!=g_msiMainSource.interfacePath){
        g_msiFeedbackSourceRecord=std::make_shared<const HidHideMsiMainSourceRecord>(g_msiMainSource);
        g_msiFeedbackIdentityBuilds.fetch_add(1,std::memory_order_relaxed);
    }
    return g_msiFeedbackSourceRecord;
}
static bool msiDinputFeedbackSourceCurrent(const std::shared_ptr<const HidHideMsiMainSourceRecord>& record) {
    std::lock_guard<std::mutex> lock(g_msiMainSourceMx);
    return record&&g_msiMainSource.valid&&msiClawKnownBoardAuthority()&&record==g_msiFeedbackSourceRecord&&
        record->generation==g_msiMainSource.generation&&record->interfacePath==g_msiMainSource.interfacePath;
}
// Existing source edges may wake one retained stop; no polling or new timer loop.
static bool msiDinputFeedbackWakePendingStop() noexcept {
    try {
        const auto pending=g_xinputDeferredFeedbackStop.pendingFor(4);
        return !pending||gamepadSerialScheduleFeedbackStop(pending,0);
    } catch (...) { return false; } // Keep the outstanding owner when scheduling is unavailable.
}

