static void msiTargetIntentObserveInput(const json& saved,const json& effective,bool shortcut,bool overrideActive) noexcept {
    if(!msiTargetIntentEvidenceEnabled())return;
    try{auto row=g_msiTargetIntentObservation.take(true,ymcc::msi::intentEvidence::observation(saved,effective,shortcut,overrideActive),true);
        if(row.is_null())return;row["observedTick"]=GetTickCount64();row["nativePid"]=GetCurrentProcessId();
        row["hostEpochAtReceipt"]=inputHostEpochToken();row["powerGenerationAtReceipt"]=currentPowerGeneration();
        row["family"]=ymccFamilyName(g_machineIdentity.family);row["board"]=g_machineIdentity.product;
        row["coverageScope"]="all-families;diagnostic-only";
        appendNativeLifecycleLog(msiClawKnownBoardAuthority()?"msi-target-intent-evidence":"input-target-intent-evidence",std::move(row));
    }catch(...){g_msiTargetIntentEvidenceFailures.fetch_add(1);/* Diagnostic failure never changes effective input or admission. */}
}
static void msiTargetIntentDocumentWrite(const json& args,const json& committed,bool ok,bool conflict,long long stale,long long expected) noexcept {
    if(!msiTargetIntentEvidenceEnabled())return;
    try{json requested=json::parse(args.value("content",std::string{}),nullptr,false);
        const json baseline=args.contains("baseline")&&args["baseline"].is_object()?args["baseline"]:json::object();
        const auto input=[](const json& doc){return doc.is_object()&&doc.contains("input")?doc["input"]:json(nullptr);};
        const json r=input(requested),b=input(baseline),c=input(committed);
        // An unrelated unified document write is not an input intent receipt.
        if(ymcc::msi::intentEvidence::target(r)==ymcc::msi::intentEvidence::target(b)&&
           ymcc::msi::intentEvidence::target(b)==ymcc::msi::intentEvidence::target(c))return;
        auto row=g_msiTargetIntentWrites.take(true,ymcc::msi::intentEvidence::documentWrite(r,b,c,ok,conflict,stale,expected),false);
        if(row.is_null())return;row["completedTick"]=GetTickCount64();row["nativePid"]=GetCurrentProcessId();
        row["hostEpochAtReceipt"]=inputHostEpochToken();row["powerGenerationAtReceipt"]=currentPowerGeneration();
        row["family"]=ymccFamilyName(g_machineIdentity.family);row["board"]=g_machineIdentity.product;
        row["coverageScope"]="all-families;diagnostic-only";
        appendNativeLifecycleLog(msiClawKnownBoardAuthority()?"msi-target-intent-evidence":"input-target-intent-evidence",std::move(row));
    }catch(...){g_msiTargetIntentEvidenceFailures.fetch_add(1);/* No retry, settings/control write, or reinterpretation of the commit. */}
}
static bool msiControllerTraceEnabled(){return ymcc::msi::trace::enabled(msiClawKnownBoardAuthority(),domainLogEnabled("virtual"));}
static void msiControllerTraceLog(const char* stage,json facts,bool inventory){
    if(!msiControllerTraceEnabled())return;
    try{
        ymcc::msi::trace::Context c;c.sequence=g_msiControllerTraceSequence.fetch_add(1,std::memory_order_relaxed)+1;c.tick=GetTickCount64();
        c.hostEpoch=inputHostEpochToken();c.ownerToken=inputHostOwnerToken();c.powerGeneration=currentPowerGeneration();
        c.routeArmed=g_msiDinputRouteDinputArmed.load(std::memory_order_acquire);c.routeConfirmed=g_msiDinputRouteConfirmed.load(std::memory_order_acquire);
        c.sourceValid=g_msiDinputSourceValid.load(std::memory_order_acquire);c.returnOwed=g_msiDinputReturnOwed.load(std::memory_order_acquire);
        HidHideMsiMainSourceRecord record;c.recordValid=msiDinputMainSourceRecordSnapshot(record);c.sourceGeneration=record.generation;c.sourcePid=record.productId;c.sourcePath=record.interfacePath;
        auto row=ymcc::msi::trace::row(stage,c,std::move(facts));row["inventoryRequested"]=inventory;
        if(inventory){
#ifdef YMCC_FAULT_INJECT
            row["physicalNamespace"]=g_msiControllerTraceInventoryForTest?g_msiControllerTraceInventoryForTest():ymcc::msi::trace::physicalNamespace();
            row["officialStack"]=g_msiControllerOfficialStackForTest?g_msiControllerOfficialStackForTest():ymcc::msi::cause::officialStack();
#else
            row["physicalNamespace"]=ymcc::msi::trace::physicalNamespace();
            row["officialStack"]=ymcc::msi::cause::officialStack();
#endif
            HidHideMsiMainSourceRecord after;const bool afterValid=msiDinputMainSourceRecordSnapshot(after);
            row["contextStableAcrossInventory"]=inputHostEpochToken()==c.hostEpoch&&currentPowerGeneration()==c.powerGeneration&&
                afterValid==c.recordValid&&after.generation==c.sourceGeneration&&after.interfacePath==c.sourcePath&&
                g_msiDinputRouteDinputArmed.load(std::memory_order_acquire)==c.routeArmed&&g_msiDinputRouteConfirmed.load(std::memory_order_acquire)==c.routeConfirmed&&
                g_msiDinputSourceValid.load(std::memory_order_acquire)==c.sourceValid&&g_msiDinputReturnOwed.load(std::memory_order_acquire)==c.returnOwed;
        }
#ifdef YMCC_FAULT_INJECT
        if(g_msiControllerTraceEmitForTest){g_msiControllerTraceEmitForTest(row);return;}
#endif
        appendNativeLifecycleLog("msi-controller-transition",std::move(row));
    }catch(...){/* diagnosis must not change a mode/write/admission result */}
}

#include "msi_visibility_wake_runtime.h"
// Opt-in MSI diagnostics only. Start once from lifecycle entry, never from BUS.
// Observer failure is a receipt, not a reason to hide/cycle/restart or reject input.
static void msiControllerVisibilityObserverStart() noexcept {
#if defined(YMCC_MSI_VISIBILITY_DIAGNOSTIC) && defined(YMCC_MSI_VISIBILITY_WAKE_DIAGNOSTIC)
    msiVisibilityObserverStartupDiagnostic();
#elif defined(YMCC_MSI_VISIBILITY_DIAGNOSTIC) && !defined(YMCC_FAULT_INJECT) && !defined(YMCC_MSI_FOREGROUND_ISOLATION_TEST)
    if(inputHostExitFenceRaised() || g_exitRequested.load(std::memory_order_acquire))return;
    if(!ymcc::msi::visibility::observerEligible(true,msiClawKnownBoardAuthority(),domainLogEnabled("virtual")))return;
    static std::atomic<bool> attempted{false};if(attempted.exchange(true))return;
    try {
        const std::wstring executable=exe_dir()+L"\\YeManControllerVisibilityProbe.exe";
        const std::wstring log=app_data_dir()+L"\\msi-controller-visibility.log";
        FILETIME created{},exited{},kernel{},user{};ULARGE_INTEGER stamp{};
        const bool timeOk=GetProcessTimes(GetCurrentProcess(),&created,&exited,&kernel,&user)!=FALSE;
        stamp.LowPart=created.dwLowDateTime;stamp.HighPart=created.dwHighDateTime;
        if(!timeOk){msiControllerTraceLog("independent-observer-start",{{"started",false},{"error",GetLastError()},{"reason","parent-identity-unavailable"}},false);return;}
        std::wstring command=L"\""+executable+L"\" \""+log+L"\" msi-evidence 300 "+std::to_wstring(GetCurrentProcessId())+L" "+std::to_wstring(stamp.QuadPart);
        command+=ymcc::msi::visibility::observerRawReceiptSuffix();
        command+=msiUsbNameContextCommandSuffix();
        std::vector<wchar_t> buffer(command.begin(),command.end());buffer.push_back(0);
        STARTUPINFOW si{};si.cb=sizeof(si);si.dwFlags=STARTF_USESHOWWINDOW;si.wShowWindow=SW_HIDE;PROCESS_INFORMATION pi{};
        const bool started=ymcc::processEfficiency::createProcess(executable.c_str(),buffer.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,exe_dir().c_str(),&si,&pi)!=FALSE;
        const DWORD error=started?0:GetLastError();const DWORD observerPid=started?pi.dwProcessId:0;
        if(started){CloseHandle(pi.hThread);CloseHandle(pi.hProcess);}
        msiControllerTraceLog("independent-observer-start",{{"started",started},{"observerPid",observerPid},{"error",error},{"executable",W2U(executable)},{"log",W2U(log)},{"durationSec",300},{"autoRestart",false},{"writesHardware",false},{"addsApplicationExemption",false},{"parentIdentityBound",true}},false);
    }catch(...){/* diagnostics never change the lifecycle result */}
#endif
}
static json msiControllerVisibilityApplications(const HidHideVisibilitySnapshot& snap,bool readback) noexcept {
    try {
        std::vector<std::string> paths;if(readback)for(const auto& value:snap.applications)paths.push_back(W2U(value));
        return ymcc::msi::visibility::applications(readback,paths,snap.inverseRaw);
    }catch(...){return nullptr;} // logging failure must not alter visibility admission
}

// 解析 HidHide physicalIdentity 的**权威尾段** `|VID_<十进制>|PID_<十进制>`
// （见 hidHideResolveInterfaceIdentity: instance + "|" + base + "|VID_" + dec + "|PID_" + dec）。
// 注意：设备实例段里也含 `VID_0DB0`/`PID_1902` 这类**十六进制**串，若取首次出现，VID 会
// 在 'D' 处截断成 0（⇒ 同源兄弟判定恒假），故只认带 `|` 前缀的尾段，且要求 VID 段在 PID 段
// 之前、VID 段后紧跟 `|`。任何形态不符一律 false（fail-closed，不猜）。
static bool hidHidePhysicalIdentityVidPid(const std::string& identity, unsigned& vid, unsigned& pid) {
    vid = 0;
    pid = 0;
    const std::string upper = hidHideUpper(identity);
    const size_t vpos = upper.rfind("|VID_");
    const size_t ppos = upper.rfind("|PID_");
    if (vpos == std::string::npos || ppos == std::string::npos || ppos < vpos) return false;
    auto parse = [&upper](size_t pos, unsigned& value, bool& terminated) -> bool {
        size_t i = pos + 5;   // 跳过 "|VID_" / "|PID_"
        unsigned acc = 0;
        bool any = false;
        while (i < upper.size() && upper[i] >= '0' && upper[i] <= '9') {
            acc = acc * 10u + static_cast<unsigned>(upper[i] - '0');
            any = true;
            ++i;
        }
        value = acc;
        terminated = i >= upper.size() || upper[i] == '|';
        return any;
    };
    bool vTerm = false, pTerm = false;
    if (!parse(vpos, vid, vTerm) || !parse(ppos, pid, pTerm)) return false;
    if (!vTerm || !pTerm) return false;
    return true;
}

// GP-MSIG3E-3-R2（E1）：1901(XInput/IG_*) 与 1902(DInput 主接口) 是同一 MSI 手柄的两个
// 传输面（本程序受管模式切换导致前者消失、后者出现）。仅当两侧同 VID、PID 均属 {0x1901,0x1902}
// 且至少一侧为受管主源 PID 时，才按同源兄弟衔接。**不修改**通用 sameHardware 的 PID 条件，
// 也不把任意 MSI 控制器当同一源。
static bool hidHideMsiFamilyPeerIdentity(const std::string& a, const std::string& b,
                                         unsigned managedVendorId, unsigned managedProductId) {
    if (a.empty() || b.empty()) return false;
    unsigned va = 0, pa = 0, vb = 0, pb = 0;
    if (!hidHidePhysicalIdentityVidPid(a, va, pa)) return false;
    if (!hidHidePhysicalIdentityVidPid(b, vb, pb)) return false;
    if (va == 0 || va != vb) return false;
    if (managedVendorId != 0 && va != managedVendorId) return false;
    const unsigned kPidXInput = 0x1901;
    const unsigned kPidDInput = 0x1902;
    if (!((pa == kPidXInput) || (pa == kPidDInput))) return false;
    if (!((pb == kPidXInput) || (pb == kPidDInput))) return false;
    return managedProductId != 0 ? (pa == managedProductId || pb == managedProductId)
                                 : (pa == kPidDInput || pb == kPidDInput);
}

// GP-MSIG3E-3-S1：MSI 主源隐藏目标的"唯一同源兄弟"判据。要求同一主游戏接口 token
// （MI_00&COL01）+ 同一 VID/PID +（同容器 GUID 或同 USB 顶层实例）。任一身份字段缺失时
// sameContainerGuid/sameUsbInstance 恒假 ⇒ 不会凭"同型不同容器"误纳管（fail-closed，不猜）。
static bool hidHideMsiSiblingSourceAdmitted(bool mainInterfaceToken, bool sameVidPid,
                                            bool sameContainerGuid, bool sameUsbInstance) {
    return mainInterfaceToken && sameVidPid && (sameContainerGuid || sameUsbInstance);
}

static bool hidHidePathEquals(const std::wstring& left, const std::wstring& right) {
    return ascii_lower(W2U(left)) == ascii_lower(W2U(right));
}

static bool hidHideContainsPath(const std::vector<std::wstring>& paths, const std::string& value) {
    const std::string wanted = ascii_lower(trim_ascii(value));
    for (const auto& path : paths) {
        if (ascii_lower(W2U(path)) == wanted) return true;
    }
    return false;
}

static std::vector<std::wstring> hidHideParseCommandPaths(const std::string& raw, const char* command) {
    std::vector<std::wstring> result;
    std::istringstream stream(raw);
    std::string line;
    const std::string prefix = std::string(command) + " \"";
    while (std::getline(stream, line)) {
        line = trim_ascii(line);
        if (line.rfind(prefix, 0) != 0 || line.size() < prefix.size() + 1) continue;
        if (line.back() != '"') continue;
        line.resize(line.size() - 1);
        line.erase(0, prefix.size());
        if (!line.empty()) result.emplace_back(U2W(line));
    }
    return result;
}

