// Existing export boundary only. Reads never enter the mouse-setting/editor,
// session preparation, native input or live Steam command paths.
struct SteamDesktopBindingCaptureOps {
    struct ReadResult {
        std::string bytes;bool available=false,truncated=false;
        std::uint64_t originalBytes=0;std::string reason;
    };
    auto session() {return SleepSteamRecovery::session();}
    bool validSession(const SleepSteamRecovery::Session& client) {return SleepSteamRecovery::validSession(client);}
    bool sameSession(const SleepSteamRecovery::Session& client) {return SleepSteamRecovery::sameSession(client);}
    json clientIdentity(const SleepSteamRecovery::Session& client) {return SleepSteamRecovery::clientIdentity(client);}
    ReadResult read(const std::wstring& path,DWORD cap) {
        auto tail=SleepRecoveryApi::readTail(path,cap);ReadResult result;
        result.bytes=std::move(tail.bytes);result.available=tail.meta.value("available",false);
        result.truncated=tail.meta.value("truncated",false);
        result.originalBytes=tail.meta.value("originalBytes",std::uint64_t(0));
        result.reason=tail.meta.value("reason",std::string());return result;
    }
    std::wstring widen(const std::string& value) {return U2W(value);}
    std::string hash(const std::string& bytes) {return inputHostSha256(bytes);}
    std::uint64_t now() {return GetTickCount64();}
};
static std::wstring exportSteamDesktopBindingEvidence() noexcept {
    const DWORD saved=GetLastError();
    struct RestoreError {DWORD value;~RestoreError(){SetLastError(value);}} restoreError{saved};
    try {
        SteamDesktopBindingCaptureOps ops;
        auto snapshot=ymcc::steamDesktopCapture::collect(domainLogEnabled("virtual"),ops);
        snapshot["nativeEvidenceVersion"]=1;snapshot["exportEntry"]="logs.exportAll";
        const auto path=SG_DIR+L"\\steam-input-log-tails\\steam-desktop-bindings.json";
        if(sgWriteFileAtomic(path,snapshot.dump(2,' ',false,json::error_handler_t::replace)))return path;
    }catch(...){/* Missing evidence is reported by export availability, never input repair. */}
    return {};
}


// Explicit export only: fixed-profile read-only Steam consumer globals.
// No report/input path, recurring observer or game/recovery admission uses this result.
static std::wstring exportSteamTouchpadConsumerEvidence() noexcept {
    const DWORD saved=GetLastError();
    struct RestoreError {DWORD value;~RestoreError(){SetLastError(value);}} restoreError{saved};
    try {
        const bool detailed=domainLogEnabled("virtual");
        json snapshot;
        if(detailed) {
            const auto client=SleepSteamRecovery::session();
            ymcc::steamtouchpadconsumer::Context context;
            context.pid=client.pid;context.birth=client.created;context.steamRoot=client.root;
            context.sessionBound=SleepSteamRecovery::validSession(client);
            DWORD currentSession=0;
            if(ProcessIdToSessionId(GetCurrentProcessId(),&currentSession))context.windowsSession=currentSession;
            else context.sessionBound=false;
            snapshot=ymcc::steamtouchpadconsumer::capture(true,context,
                [](const std::wstring& path){return sha256File(path);},
                [client]{return SleepSteamRecovery::sameSession(client);});
        } else {
            snapshot=ymcc::steamtouchpadconsumer::capture(false,{}, {}, {});
        }
        snapshot["exportEntry"]="logs.exportAll";snapshot["observedAt"]=nativeLifecycleTimestamp();
        const auto path=SG_DIR+L"\\steam-input-log-tails\\steam-touchpad-consumer.json";
        if(sgWriteFileAtomic(path,snapshot.dump(2,' ',false,json::error_handler_t::replace)))return path;
    }catch(...){/* Export availability reports missing evidence; never repairs input. */}
    return {};
}

