// Export-time MSI-owned evidence only; no mode queries or OEM control.
struct MsiOfficialModeLogEvidenceOps {
    static std::wstring knownFolder(REFKNOWNFOLDERID id) {
        PWSTR path=nullptr;
        struct FreePath { PWSTR& value;~FreePath(){if(value)CoTaskMemFree(value);} } freePath{path};
        const auto result=SHGetKnownFolderPath(id,KF_FLAG_DONT_VERIFY,nullptr,&path);
        return SUCCEEDED(result)&&path?std::wstring(path):std::wstring();
    }
    std::vector<ymcc::msi::officialLogEvidence::Root> roots() {
        return {{"program-data",knownFolder(FOLDERID_ProgramData)},
                {"program-files-x86",knownFolder(FOLDERID_ProgramFilesX86)},
                {"local-app-data",knownFolder(FOLDERID_LocalAppData)}};
    }
    std::vector<std::string> dates() {
        SYSTEMTIME local{};GetLocalTime(&local);
        auto format=[](const SYSTEMTIME& day) {
            char value[32]{};
            sprintf_s(value,sizeof(value),"%04u-%02u-%02u",static_cast<unsigned>(day.wYear),
                static_cast<unsigned>(day.wMonth),static_cast<unsigned>(day.wDay));
            return std::string(value);
        };
        std::vector<std::string> result{format(local)};
        // Treat local civil midnight as a calendar value; no timezone conversion.
        local.wHour=local.wMinute=local.wSecond=local.wMilliseconds=0;
        FILETIME stamp{};
        if(SystemTimeToFileTime(&local,&stamp)) {
            ULARGE_INTEGER day{};day.LowPart=stamp.dwLowDateTime;day.HighPart=stamp.dwHighDateTime;
            constexpr ULONGLONG civilDay=864000000000ULL;
            if(day.QuadPart>=civilDay) {
                day.QuadPart-=civilDay;stamp.dwLowDateTime=day.LowPart;stamp.dwHighDateTime=day.HighPart;
                SYSTEMTIME previous{};
                if(FileTimeToSystemTime(&stamp,&previous))result.push_back(format(previous));
            }
        }
        return result;
    }
    ymcc::msi::officialLogEvidence::ReadResult read(const std::wstring& path,std::uint32_t cap) {
        auto tail=SleepRecoveryApi::readTail(path,cap);
        ymcc::msi::officialLogEvidence::ReadResult result;
        result.bytes=std::move(tail.bytes);result.available=tail.meta.value("available",false);
        result.truncated=tail.meta.value("truncated",false);
        result.originalBytes=tail.meta.value("originalBytes",std::uint64_t(0));
        result.reason=tail.meta.value("reason",std::string());return result;
    }
    std::string hash(const std::string& bytes) {return inputHostSha256(bytes);}
    std::uint64_t now() {return GetTickCount64();}
};
static std::wstring exportMsiOfficialModeLogEvidence() noexcept {
    const DWORD saved=GetLastError();
    struct RestoreError {DWORD value;~RestoreError(){SetLastError(value);}} restoreError{saved};
    try {
        const bool detailed=domainLogEnabled("virtual"),knownMsi=msiClawKnownBoardAuthority();
        MsiOfficialModeLogEvidenceOps ops;
        auto snapshot=ymcc::msi::officialLogEvidence::collect(detailed&&knownMsi,ops);
        snapshot["nativeEvidenceVersion"]=1;snapshot["exportEntry"]="logs.exportAll";
        snapshot["knownMsiBoard"]=knownMsi;snapshot["detailEnabled"]=detailed;
        snapshot["gateReason"]=!detailed?"virtual-detail-disabled":!knownMsi?"unsupported-machine":"enabled";
        const auto path=SG_DIR+L"\\steam-input-log-tails\\msi-official-mode-evidence.json";
        if(sgWriteFileAtomic(path,snapshot.dump(2,' ',false,json::error_handler_t::replace)))return path;
    }catch(...){/* Evidence failures do not authorize mode writes or repairs. */}
    return {};
}

// Read only current PnP properties for paths already named by the modifier drain.
// Limits count actual Configuration Manager calls, including both resolve calls.
struct KeyboardDeviceOriginEvidenceOps {
    unsigned cmCalls=0;bool cmBudgetExhausted=false;
    bool takeCmCall() noexcept {
        if(cmCalls>=160){cmBudgetExhausted=true;return false;}++cmCalls;return true;
    }
    auto snapshot() {return g_keyboardDeviceOriginCache.snapshot();}
    std::uint64_t now() {return GetTickCount64();}
    std::string utf8(const std::wstring& text) {return W2U(text);}
    static bool validStringBuffer(const std::array<wchar_t,1024>& buffer,ULONG bytes,std::wstring& text) {
        if(bytes<sizeof(wchar_t)||bytes>sizeof(buffer)||bytes%sizeof(wchar_t))return false;
        const auto limit=buffer.begin()+bytes/sizeof(wchar_t);
        const auto end=std::find(buffer.begin(),limit,wchar_t(0));
        if(end==limit)return false;text.assign(buffer.begin(),end);return true;
    }
    ymcc::keyboardOrigin::ResolveResult resolve(const std::wstring& path) {
        using Result=ymcc::keyboardOrigin::ResolveResult;
        if(!takeCmCall())return Result{false,0,0xffffffffu};
        std::array<wchar_t,1024> buffer{};buffer.fill(wchar_t(0xffff));
        ULONG bytes=static_cast<ULONG>(sizeof(buffer));DEVPROPTYPE type=0;
        const auto cr=CM_Get_Device_Interface_PropertyW(path.c_str(),&DEVPKEY_Device_InstanceId,&type,
            reinterpret_cast<PBYTE>(buffer.data()),&bytes,0);
        if(cr!=CR_SUCCESS)return Result{false,0,static_cast<std::uint32_t>(cr)};
        std::wstring id;
        if(type!=DEVPROP_TYPE_STRING||!validStringBuffer(buffer,bytes,id)||id.empty())return Result{false,0,0xfffffffeu};
        if(!takeCmCall())return Result{false,0,0xffffffffu};
        DEVINST node=0;const auto locate=CM_Locate_DevNodeW(&node,id.data(),CM_LOCATE_DEVNODE_NORMAL);
        return Result{locate==CR_SUCCESS,static_cast<std::uint32_t>(node),static_cast<std::uint32_t>(locate)};
    }
    ymcc::keyboardOrigin::StringResult instance(std::uint32_t node) {
        using Result=ymcc::keyboardOrigin::StringResult;
        if(!takeCmCall())return Result{false,0xffffffffu,{}};
        std::array<wchar_t,1024> buffer{};buffer.fill(wchar_t(0xffff));
        const auto cr=CM_Get_Device_IDW(static_cast<DEVINST>(node),buffer.data(),static_cast<ULONG>(buffer.size()),0);
        if(cr!=CR_SUCCESS)return Result{false,static_cast<std::uint32_t>(cr),{}};
        std::wstring text;
        if(!validStringBuffer(buffer,static_cast<ULONG>(sizeof(buffer)),text)||text.empty())return Result{false,0xfffffffeu,{}};
        return Result{true,0,W2U(text)};
    }
    ymcc::keyboardOrigin::StringResult property(std::uint32_t node,const char* name) {
        using Result=ymcc::keyboardOrigin::StringResult;
        const DEVPROPKEY* key=nullptr;
        if(std::strcmp(name,"service")==0)key=&DEVPKEY_Device_Service;
        else if(std::strcmp(name,"driverInf")==0)key=&DEVPKEY_Device_DriverInfPath;
        else if(std::strcmp(name,"driverProvider")==0)key=&DEVPKEY_Device_DriverProvider;
        else if(std::strcmp(name,"manufacturer")==0)key=&DEVPKEY_Device_Manufacturer;
        else if(std::strcmp(name,"description")==0)key=&DEVPKEY_Device_DeviceDesc;
        else if(std::strcmp(name,"enumerator")==0)key=&DEVPKEY_Device_EnumeratorName;
        if(!key)return Result{false,0xfffffffdu,{}};
        if(!takeCmCall())return Result{false,0xffffffffu,{}};
        std::array<wchar_t,1024> buffer{};buffer.fill(wchar_t(0xffff));
        ULONG bytes=static_cast<ULONG>(sizeof(buffer));DEVPROPTYPE type=0;
        const auto cr=CM_Get_DevNode_PropertyW(static_cast<DEVINST>(node),key,&type,
            reinterpret_cast<PBYTE>(buffer.data()),&bytes,0);
        if(cr!=CR_SUCCESS)return Result{false,static_cast<std::uint32_t>(cr),{}};
        std::wstring text;
        if(type!=DEVPROP_TYPE_STRING||!validStringBuffer(buffer,bytes,text))return Result{false,0xfffffffeu,{}};
        return Result{true,0,W2U(text)};
    }
    ymcc::keyboardOrigin::ParentResult parent(std::uint32_t node) {
        using Result=ymcc::keyboardOrigin::ParentResult;
        if(!takeCmCall())return Result{false,false,0,0xffffffffu};
        DEVINST up=0;const auto cr=CM_Get_Parent(&up,static_cast<DEVINST>(node),0);
        // A no-such-node result cannot distinguish a root from a disappeared device.
        return Result{cr==CR_SUCCESS,false,cr==CR_SUCCESS?static_cast<std::uint32_t>(up):0u,static_cast<std::uint32_t>(cr)};
    }
};
static std::wstring exportKeyboardDeviceOriginEvidence() noexcept {
    const DWORD saved=GetLastError();
    struct RestoreError {DWORD value;~RestoreError(){SetLastError(value);}} restoreError{saved};
    try {
        KeyboardDeviceOriginEvidenceOps ops;
        auto evidence=ymcc::keyboardOrigin::collect(domainLogEnabled("virtual"),ops);
        evidence["nativeEvidenceVersion"]=1;evidence["exportEntry"]="logs.exportAll";
        evidence["nativeCmCalls"]=ops.cmCalls;evidence["nativeCmCallLimit"]=160;
        evidence["nativeCmBudgetExhausted"]=ops.cmBudgetExhausted;
        evidence["observeFailures"]=g_keyboardDeviceOriginObserveFailures.load(std::memory_order_relaxed);
        evidence["nativeErrorMeaning"]={{"4294967295","native-cm-call-budget"},{"4294967294","invalid-string-type-or-termination"},{"4294967293","unsupported-property"}};
        const auto path=SG_DIR+L"\\steam-input-log-tails\\keyboard-device-origins.json";
        if(sgWriteFileAtomic(path,evidence.dump(2,' ',false,json::error_handler_t::replace)))return path;
    }catch(...){/* Missing origin evidence never changes input ownership or releases keys. */}
    return {};
}

#include "remote_input_environment_evidence.h"
#include "remote_input_log_snapshot.h"
static std::wstring exportRemoteInputEnvironmentEvidence(std::vector<std::wstring>& copiedLogs,const InputEdgeDrainReceipt& edgeDrain) noexcept {
    const DWORD saved=GetLastError();
    struct RestoreError {DWORD value;~RestoreError(){SetLastError(value);}} restoreError{saved};
    try {
        auto evidence=collectRemoteInputEnvironmentEvidence();
        try {exportRemoteInputLogSnapshots(evidence,copiedLogs);}
        catch(...) {evidence["logSnapshots"]={{"exception",true},{"complete",false},{"reason","log-snapshot-exception"}};}
        evidence["exportEntry"]="logs.exportAll";
        evidence["passiveKeyboardHookInstalledCached"]=g_inputEdgeKeyboardInstalled.load();
        evidence["passiveMouseHookInstalledCached"]=g_inputEdgeMouseInstalled.load();
        evidence["lastPassiveKeyboardTick"]=g_inputEdgeLastKeyboardTick.load();
        evidence["lastPassiveMouseTick"]=g_inputEdgeLastMouseTick.load();
        evidence["edgeEvidenceFile"]="focus-trace.log event=input-edge-window";
        evidence["nativeControlPendingAtExport"]=nativeControlWindowSnapshot(false);
        evidence["edgeDrainAtExport"]=inputEdgeDrainReceiptJson(edgeDrain);
        const auto path=SG_DIR+L"\\steam-input-log-tails\\remote-input-environment.json";
        if(sgWriteFileAtomic(path,evidence.dump(2,' ',false,json::error_handler_t::replace)))return path;
    }catch(...){/* Export evidence must not change input or session ownership. */}
    return {};
}

