static std::wstring g_appDataDir;
static std::wstring g_yemanccDataDir;

// Product-stable per-user data root. Diagnostic paths must not follow the
// configurable window title, otherwise older builds can split fan logs across
// multiple LocalAppData directories.
static std::wstring yemancc_data_dir() {
    if (!g_yemanccDataDir.empty()) return g_yemanccDataDir;
    PWSTR p = nullptr;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_LocalAppData, 0, nullptr, &p))) {
        g_yemanccDataDir = std::wstring(p) + L"\\YeManCC";
        CoTaskMemFree(p);
    } else {
        g_yemanccDataDir = exe_dir() + L"\\data\\YeManCC";
    }
    fspath::create_directories(g_yemanccDataDir);
    return g_yemanccDataDir;
}

static std::wstring app_data_dir() {
    if (!g_appDataDir.empty()) return g_appDataDir;
    PWSTR p = nullptr;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_LocalAppData, 0, nullptr, &p))) {
        auto title = g_cfg.value("/window/title"_json_pointer, std::string{"QQ"});
        g_appDataDir = std::wstring(p) + L"\\" + safe_path_component(U2W(title), L"QQ");
        CoTaskMemFree(p);
    } else {
        g_appDataDir = exe_dir() + L"\\data";
    }
    fspath::create_directories(g_appDataDir);
    return g_appDataDir;
}

// Fan Host recovery also runs from native sleep/exit callbacks, when the
// renderer may already be gone.  Keep its mutable session capability in a
// stable product path rather than app_data_dir(), whose parent name follows a
// user-configurable window title.  Renderer, native cleanup and the emergency
// script must resolve the same directory across title/configuration changes.
static std::wstring g_fanHostStateDir;
static std::wstring fan_host_state_dir() {
    if (!g_fanHostStateDir.empty()) return g_fanHostStateDir;
    // Both native and renderer use this title-independent root through
    // app.fanStateDir, so the session path remains shared across title changes.
    g_fanHostStateDir = g_aiFanMockSession.enabled
        ? yemancc_data_dir() + L"\\ai-fan-sessions\\" + g_aiFanMockSession.id + L"\\fan-host"
        : yemancc_data_dir() + L"\\fan-host";
    std::error_code ec;
    fspath::create_directories(g_fanHostStateDir, ec);
    return g_fanHostStateDir;
}

// T0 sleep-hang repair: this log is intentionally independent of the optional
// debug trace and of the WebView renderer. It is only an audit trail; failures
// here must never affect startup, sleep, resume, or shutdown behavior.
static std::mutex g_nativeLifecycleLogMx;
static std::ofstream g_nativeLifecycleLog;
static uint32_t g_nativeLifecycleFrameWrites = 0;
// Detailed traffic has a separate stream: enabling diagnostics must never turn
// the always-on lifecycle ledger into a periodic/sample log.
static std::ofstream g_nativeDetailLog;
static uint32_t g_nativeDetailWrites = 0;
static ULONGLONG g_nativeDetailLastFlushTick = 0;
static std::string nativeLifecycleTimestamp() {
    SYSTEMTIME st{};
    GetLocalTime(&st);
    char value[40]{};
    snprintf(value, sizeof(value), "%04u-%02u-%02uT%02u:%02u:%02u.%03u",
        st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
    return value;
}
