        std::lock_guard<std::mutex> lock(g_domainLogMx);
        g_domainLogStreams[domainLogStreamIndex(domain.c_str())].flush();
        std::error_code ec;
        const auto size = fspath::file_size(path, ec);
        if (ec || size == 0) return {{"ok", false}, {"reason", "empty-or-missing"}};
        PWSTR desk = nullptr;
        if (FAILED(SHGetKnownFolderPath(FOLDERID_Desktop, 0, nullptr, &desk)) || !desk) {
            return {{"ok", false}, {"reason", "no-desktop"}};
        }
        const std::wstring stamp = std::to_wstring(GetTickCount64());
        const std::wstring fileName = path.substr(path.find_last_of(L"\\") + 1);
        const std::wstring dst = std::wstring(desk) + L"\\YeManCC-" + fileName + L"." + stamp + L".log";
        CoTaskMemFree(desk);
        if (!CopyFileW(path.c_str(), dst.c_str(), FALSE))
            return {{"ok", false}, {"reason", "copy-failed"}};
        return {{"ok", true}, {"path", W2U(dst)}};
