        observeTdpRuntimeIdentity(); // export-time file identity refresh, not a controller operation
        { std::lock_guard<std::mutex> lock(g_tdpObservationMx); for(auto& stream:g_tdpObservationStreams)stream.flush(); }
        const auto steamLogs = ymcc::logexport::collectSteamLogs(g_steamSettingsObserver.sessionSnapshot().pid);
        std::vector<std::wstring> files;
        json availability={{"schemaVersion",1},{"evidenceScope","discovery-before-snapshot-not-packed-byte-proof"},
            {"detailEnabled",domainLogEnabled("virtual")},{"gyroDetailEnabled",domainLogEnabled("gyro")},
            {"fanDiagnosticEnabled",g_fanLogEnabled.load()},{"frontendLogFailureCount",g_frontendDiagnosticsFailures.load()},
            {"frontendTraceDetailSuppressed",g_frontendTraceDetailSuppressed.load()},
            {"frontendControllerPreviewTraceSuppressed",g_frontendPreviewTraceSuppressed.load()},
            {"rendererDiagnosticDeliveryFailures",exportArgs.value("frontendDiagnosticDeliveryFailures",0ULL)},
            {"files",json::array()}};
        availability["monitorDetail"]=monitorDetailState().stats();
        auto addFile = [&](const std::wstring& path) {
            std::error_code ec;const bool present=fspath::is_regular_file(path, ec);
            json row={{"name",W2U(fspath::path(path).filename().wstring())},{"present",present}};
            if(present)files.push_back(path);
            else {row["missingReason"]=ymcc::logexport::missingFileReason(ec);if(ec)row["statusErrorCode"]=ec.value();}
            availability["files"].push_back(std::move(row));
        };
        auto addRotated = [&](const std::wstring& base) {
            addFile(base);
            addFile(base + L".1");
            addFile(base + L".prev");
            addFile(base + L".previous");
        };
        const std::wstring dataDir = yemancc_data_dir();
        const std::wstring appDir = app_data_dir();
        // Export observes the already-used media root. No download/startup or root probes.
        const auto mediaExport=ymcc::media::diagnostics::exportMetadata(fspath::path(dataDir));
        availability["sharedGameMedia"]=mediaExport.receipt;
        for(const auto& path:mediaExport.files)addFile(path.wstring());
        // One export-time snapshot of the existing state/visibility cache. No refresh,
        // input injection, target start, show/hide, hardware read or timer is permitted.
        const auto screenSnapshotPath=fspath::path(dataDir)/L"screen-touchpads-export-state.json";
        bool screenSnapshotSaved=false;
        try{json snapshot={{"schemaVersion",1},{"observedAt",nativeLifecycleTimestamp()},
            {"evidenceScope","in-memory-state-and-existing-HWND-visibility-at-export-only"},
            {"hardwareProbes",false},{"state",ymcc::screenpads::state()}};
            snapshot["cursorEventThreadOwnersAtExport"]=ymcc::screenpads::cursorvisibility::eventThreadOwnersAtExport(
                snapshot["state"]["cursorVisibilityObserver"]["eventTrace"]);
            std::ofstream out(screenSnapshotPath,std::ios::binary|std::ios::trunc);out<<snapshot.dump(2)<<'\n';out.close();screenSnapshotSaved=bool(out);
        }catch(...){/* never change screen controls or export an earlier snapshot as current */}
        if(screenSnapshotSaved)addFile(screenSnapshotPath.wstring());
        else availability["files"].push_back({{"name","screen-touchpads-export-state.json"},{"present",false},{"missingReason","current-export-snapshot-not-saved"}});
        // Export the sole publisher's bounded metadata. Raw periodic snapshots
        // belong only to the detailed file; export never enables collection.
        const auto monitorSnapshotPath=fspath::path(dataDir)/L"monitor-export-state.json";
        bool monitorSnapshotSaved=false;
        try {
            const auto cached=monitorSnapshotServeFn();
            const auto rawSettings=ymSettingsReadRaw(YM_SETTINGS_FILE);
            const auto settings=json::parse(rawSettings,nullptr,false);
            const json machine={{"manufacturer",g_machineIdentity.manufacturer},{"board",g_machineIdentity.product},
                {"systemProduct",g_machineIdentity.systemProduct},{"processor",g_machineIdentity.processor},
                {"deviceClass",g_machineIdentity.deviceClass},{"resolved",g_machineIdentity.resolved}};
            const auto state=ymcc::monitorexport::snapshot(cached,machine,settings,
                static_cast<long long>(sgNowEpoch()*1000.0),rawSettings.empty()?"missing-or-unreadable":settings.is_object()?"parsed":"invalid");
            std::ofstream out(monitorSnapshotPath,std::ios::binary|std::ios::trunc);
            out<<ymcc::monitorexport::encode(state)<<'\n';out.close();monitorSnapshotSaved=bool(out);
        } catch(...) { /* Failed export must not reuse an earlier snapshot. */ }
        if(monitorSnapshotSaved)addFile(monitorSnapshotPath.wstring());
        else availability["files"].push_back({{"name","monitor-export-state.json"},{"present",false},{"missingReason","current-export-snapshot-not-saved"}});
        // Static export-time summaries; no controller/helper is started.
        const auto tdpCoverage=tdpExportCoverage(dataDir);
        const auto tdpCoveragePath=fspath::path(dataDir)/L"tdp-export-coverage.json";
        try{std::ofstream out(tdpCoveragePath,std::ios::binary|std::ios::trunc);out<<tdpCoverage.dump(2);if(!out)++g_tdpObservationFailures;}catch(...){++g_tdpObservationFailures;}
        addFile(tdpCoveragePath.wstring());
        // native 主体（app_data_dir）
        addRotated(appDir + L"\\app.log");
        addRotated(appDir + L"\\native-lifecycle.log");
        addRotated(appDir + L"\\native-detail.log");
        addRotated(appDir + L"\\monitor-detail.log");
        addRotated(appDir + L"\\input-capture.jsonl");
        // MSI independent diagnostic process; absent on ordinary builds.
        addFile(appDir + L"\\msi-controller-return.json"); // exact owned crash-return responsibility
        addFile(appDir + L"\\external-controller-priority-return-v1.json");
        addRotated(appDir + L"\\msi-controller-visibility.log");
        addRotated(appDir + L"\\msi-controller-visibility-wake-1.log");
        addRotated(appDir + L"\\msi-controller-visibility-wake-2.log");
        // Exact historical return files; export observes existing bytes only.
        // Owner-lock sentinels and temp candidates are not collected or repaired.
        addFile(dataDir + L"\\controller-return\\target-return.json");
        addFile(dataDir + L"\\controller-return\\hidhide-cli-writer.json");
        // 域/协调/输入宿主（yemancc_data_dir）
        addRotated(dataDir + L"\\tdp.log");
        addRotated(dataDir + L"\\tdp-detail.log");
        addFile(dataDir + L"\\tdp-runtime-identity.json");
        addRotated(dataDir + L"\\decky-sidebar.log");
        addRotated(dataDir + L"\\steam-launch.log"); // Existing VBS failure receipt; export-time read only.
        addRotated(dataDir + L"\\fan-api.log");
        addRotated(dataDir + L"\\fan-lifecycle.log");
        addRotated(dataDir + L"\\gyro-motion.log");
        addRotated(dataDir + L"\\virtual-gamepad.log");
        // GP-926R5：对焦变化页（前台窗口 + GameBar 开关/输入接管）。
        addRotated(dataDir + L"\\focus-trace.log");
        addRotated(dataDir + L"\\hardware-coordinator.log");
        addRotated(dataDir + L"\\input-host-fatal.log");
        addRotated(dataDir + L"\\input-host-rejects.log");
        addRotated(dataDir + L"\\input-host-cost.log");
        // Exact owned compressed volumes and an immutable pending source, copied
        // before tar reads them. Never collect an in-progress .tmp archive.
        addFile(dataDir + L"\\input-host-cost.log.pending");
        addFile(dataDir + L"\\input-host-cost-retention.json");
        {
            std::error_code archiveEc;
            unsigned long long archivesFound=0;
            fspath::directory_iterator it(dataDir,archiveEc),end;
            while(!archiveEc && it!=end) {
                std::error_code entryEc;
                if(it->is_regular_file(entryEc) && ymcc::logexport::hostCostArchiveEvidenceName(W2U(it->path().filename().wstring()))) {
                    addFile(it->path().wstring());++archivesFound;
                }
                if(entryEc){archiveEc=entryEc;break;}
                it.increment(archiveEc);
            }
            availability["costArchiveDiscovery"]={{"status",archiveEc?"directory-enumeration-error":"complete-at-discovery"},
                {"archivesFound",archivesFound},{"errorCode",archiveEc.value()},{"atomicWithSnapshot",false}};
        }

        addRotated(dataDir + L"\\input-host-signal.log"); // Ordinary virtual-detail SDK-call evidence, bounded.
        addRotated(dataDir + L"\\input-host-report-chain.log"); // Opt-in MSI SDK-call evidence; export does not arm diagnostics.
        addRotated(dataDir + L"\\gamepad-driver-setup.json");
        addFile(dataDir + L"\\gamepad-driver-setup.json.drivers.xml"); // Preserve the outer inventory even when its schema is unknown.
        addRotated(dataDir + L"\\gamepad-driver-setup.json.hidmaestro.json");
        addFile(dataDir + L"\\gamepad-driver-setup.json.hidhide.log");
        addFile(dataDir + L"\\gamepad-driver-setup.json.hidmaestro.json.drivers.xml");
        addFile(dataDir + L"\\gamepad-driver-setup.json.hidmaestro.json.after-drivers.xml");
        addRotated(dataDir + L"\\input-host-xbox-sdk.log"); // GP-XBOX-7: bounded stock SDK evidence
