        addRotated(dataDir + L"\\recovery-service.log");
        // FanHost runtime 目录全量（含日期滚动 yeman-fan-host<date>.log；
        // flag 门控在 Host 侧生效——目录为空时自然无条目）
        {
            std::error_code hostLogEc;
            const std::wstring hostLogDir = fan_host_state_dir() + L"\\logs";
            if (fspath::is_directory(hostLogDir, hostLogEc)) {
                for (const auto& entry : fspath::directory_iterator(hostLogDir, hostLogEc)) {
                    std::error_code entryEc;
                    if (!entry.is_regular_file(entryEc)) continue;
                    if (entry.path().extension() == L".log") addFile(entry.path().wstring());
                }
            }
        }
        // 睡眠事实
        addRotated(SG_FACT_LOG);
        addFile(SG_DIR + L"\\wake-recovery-last.json"); // most recently completed generation only
        addFile(SleepRecoveryAuto::exportCurrentSnapshot()); // copied current/pending state; NEVER triggers recovery
        const auto steamLinkSnapshot=steamGameLinkExportSnapshot();
        if(!steamLinkSnapshot.empty())addFile(steamLinkSnapshot);
        else availability["files"].push_back({{"name","steam-game-link-current.json"},{"present",false},{"missingReason","current-link-snapshot-not-saved"}});
        // Read-only evidence: exporting must never enter the recovery engine.
        const auto originalRecoverySnapshot=steamOriginalRecoveryExportSnapshot();
        if(!originalRecoverySnapshot.empty())addFile(originalRecoverySnapshot);
        const auto originalRecoveryRoot=dataDir+L"\\SteamOriginalRecovery";
        addFile(originalRecoveryRoot+L"\\last-event.json");
        addFile(originalRecoveryRoot+L"\\last-recovery-summary.json");
        addFile(originalRecoveryRoot+L"\\status.json");
        addRotated(dataDir+L"\\steam-original-recovery.jsonl");
        // Steam-only bounded tails share the existing export entry; no long form.
        for (const auto& path : SleepSteamRecovery::exportLogTails()) addFile(path);
        const auto desktopBindings=exportSteamDesktopBindingEvidence();
        if(!desktopBindings.empty())addFile(desktopBindings);
        else availability["files"].push_back({{"name","steam-desktop-bindings.json"},{"present",false},{"missingReason","current-export-snapshot-not-saved"}});
        const auto touchpadConsumer=exportSteamTouchpadConsumerEvidence();
        if(!touchpadConsumer.empty())addFile(touchpadConsumer);
        else availability["files"].push_back({{"name","steam-touchpad-consumer.json"},{"present",false},{"missingReason","current-export-snapshot-not-saved"}});
        // WebView 目录
        // Trainer evidence is collected read-only at export time, including failed preparation.
