        addRotated((fspath::path(webview_data_dir()) / L"frontend-trace.log").wstring());
        addRotated((fspath::path(webview_data_dir()) / L"frontend-trace-detail.log").wstring());
        addRotated((fspath::path(webview_data_dir()) / L"webview-failures.log").wstring());
        const auto controllerSensorBankEvidence=exportControllerSensorBankEvidence();
        if(!controllerSensorBankEvidence.empty())addFile(controllerSensorBankEvidence);
