static void reg_hotkey() {
    ipc_on("hotkey.register", [](const json& a) -> json {
        int id  = a.value("id", 0);
        int mod = a.value("modifiers", 0); // MOD_ALT=1, MOD_CONTROL=2, MOD_SHIFT=4, MOD_WIN=8
        int key = a.value("key", 0);       // Virtual key code
        bool ok = RegisterHotKey(g_hwnd, id, mod | MOD_NOREPEAT, key);
        return ok;
    });
    ipc_on("hotkey.unregister", [](const json& a) -> json {
        return (bool)UnregisterHotKey(g_hwnd, a.value("id", 0));
    });
    ipc_on("hotkey.unregisterAll", [](const json&) -> json {
        // Unregister IDs 1..100
        for (int i = 1; i <= 100; i++) UnregisterHotKey(g_hwnd, i);
        return true;
    });
}

// ================================================================
//  Commands: Notifications
// ================================================================

static void reg_notification() {
    ipc_on("notification.show", [](const json& a) -> json {
        auto title = U2W(a.value("title", std::string{"通知"}));
        auto body  = U2W(a.value("body", std::string{}));
        // Use tray balloon if tray is active
        if (g_trayActive) {
            g_nid.uFlags |= NIF_INFO;
            wcsncpy_s(g_nid.szInfoTitle, title.c_str(), _TRUNCATE);
            wcsncpy_s(g_nid.szInfo, body.c_str(), _TRUNCATE);
            g_nid.dwInfoFlags = NIIF_INFO;
            Shell_NotifyIconW(NIM_MODIFY, &g_nid);
            return true;
        }
        // Create temporary tray icon for notification
        NOTIFYICONDATAW nid{sizeof(nid)};
        nid.hWnd  = g_hwnd;
        nid.uID   = 99;
        nid.uFlags = NIF_ICON | NIF_INFO;
        nid.hIcon  = g_appIconSmall ? g_appIconSmall : LoadIconW(nullptr, IDI_APPLICATION);
        wcsncpy_s(nid.szInfoTitle, title.c_str(), _TRUNCATE);
        wcsncpy_s(nid.szInfo, body.c_str(), _TRUNCATE);
        nid.dwInfoFlags = NIIF_INFO;
        Shell_NotifyIconW(NIM_ADD, &nid);
        // Remove after a delay (fire-and-forget via timer)
        SetTimer(g_hwnd, 99, 5000, [](HWND h, UINT, UINT_PTR id, DWORD) {
            NOTIFYICONDATAW nid{sizeof(nid)};
            nid.hWnd = h; nid.uID = 99;
            Shell_NotifyIconW(NIM_DELETE, &nid);
            KillTimer(h, id);
        });
        return true;
    });
}

// ================================================================
//  Commands: Context menu
// ================================================================

static void reg_menu() {
    ipc_on("menu.popup", [](const json& a) -> json {
        if (!a.contains("items") || !a["items"].is_array()) return nullptr;
        HMENU hMenu = CreatePopupMenu();
        int idx = 1;
        for (auto& item : a["items"]) {
            if (item.is_string() && item.get<std::string>() == "-") {
                AppendMenuW(hMenu, MF_SEPARATOR, 0, nullptr);
            } else if (item.is_object()) {
                auto label = U2W(item.value("label", std::string{""}));
                UINT flags = MF_STRING;
                if (item.value("disabled", false)) flags |= MF_GRAYED;
                if (item.value("checked", false))  flags |= MF_CHECKED;
                AppendMenuW(hMenu, flags, idx, label.c_str());
            }
            idx++;
        }
        POINT pt;
        GetCursorPos(&pt);
        SetForegroundWindow(g_hwnd);
        int cmd = TrackPopupMenuEx(hMenu, TPM_RETURNCMD | TPM_NONOTIFY,
                                    pt.x, pt.y, g_hwnd, nullptr);
        DestroyMenu(hMenu);
        if (cmd == 0) return nullptr; // cancelled
        return cmd - 1; // 0-based index
    });
}

// ================================================================
//  Commands: HTTP client
// ================================================================

static bool crackHttpUrl(const std::string& url, URL_COMPONENTS& uc,
                         wchar_t (&host)[256], wchar_t (&path)[2048],
                         wchar_t (&extra)[2048], std::wstring& objectPath) {
    auto wUrl = U2W(url);
    ZeroMemory(&uc, sizeof(uc));
    uc.dwStructSize = sizeof(uc);
    uc.lpszHostName = host;  uc.dwHostNameLength = 256;
    uc.lpszUrlPath = path;   uc.dwUrlPathLength = 2048;
    uc.lpszExtraInfo = extra; uc.dwExtraInfoLength = 2048;
    if (!WinHttpCrackUrl(wUrl.c_str(), 0, 0, &uc))
        return false;

    objectPath.assign(path, uc.dwUrlPathLength);
    objectPath.append(extra, uc.dwExtraInfoLength);
    auto fragment = objectPath.find(L'#');
    if (fragment != std::wstring::npos)
        objectPath.resize(fragment);
    if (objectPath.empty())
        objectPath = L"/";
    return true;
}

static void reg_http() {
    ipc_on("http.request", [](const json& a) -> json {
        auto url    = a.value("url", std::string{});
        auto method = a.value("method", std::string{"GET"});
        auto body   = a.value("body", std::string{});
        auto hdrs   = a.value("headers", json::object());
        const DWORD requestTimeoutMs = ymcc::http::timeoutBudget(a.value("timeoutMs", 30000LL));
        const auto deadline = a.value("_nativeHttpDeadlineTick", GetTickCount64() + requestTimeoutMs);
        ymcc::http::requireDeadline(deadline, "queue");
        if (url.empty()) throw std::runtime_error("url is required");

        // Parse URL
        URL_COMPONENTS uc;
        wchar_t host[256]{}, path[2048]{}, extra[2048]{};
        std::wstring objectPath;
        if (!crackHttpUrl(url, uc, host, path, extra, objectPath))
            throw std::runtime_error("Invalid URL");

        if (uc.nScheme != INTERNET_SCHEME_HTTP && uc.nScheme != INTERNET_SCHEME_HTTPS)
            throw std::runtime_error("Only http and https URLs are supported");
        if (!is_http_token(method))
            throw std::runtime_error("Invalid HTTP method");

        bool https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
        bool steamHostHeader = false;
        if (hdrs.is_object()) {
            const auto it = hdrs.find("Host");
            if (it != hdrs.end() && it->is_string()) {
                const auto hostHeader = U2W(it->get<std::string>());
                steamHostHeader = isSteamHostName(hostHeader.c_str());
            }
        }
        const bool steamHost = isSteamHostName(host) || steamHostHeader;
        const bool loopbackHost = isLoopbackHost(host);
        const bool monitorFanRequest = loopbackHost && uc.nPort == 8765;
        const auto monitorFanPath = monitorFanRequest ? fanApiPathFromObject(objectPath) : std::string{};
        const auto monitorFanEpoch = monitorFanRequest && method != "GET" && method != "HEAD" && ymcc::monitorfan::isMutation(monitorFanPath)
            ? g_monitorFanDisplay.invalidate() : g_monitorFanDisplay.epoch();
        if (g_aiFanMockSession.enabled && loopbackHost && uc.nPort == 8765 && method != "GET" && method != "HEAD") {
            const DWORD ownedPid = g_aiFanMockHost.livePid();
            if (!ownedPid || !fanHostOwnsLoopbackPort(ownedPid, 8765)) throw std::runtime_error("AI_FAN_OWNED_MOCK_REQUIRED");
        }
        HINTERNET hSession = WinHttpOpen(L"QQ/1.0",
                                          (steamHost || loopbackHost) ? WINHTTP_ACCESS_TYPE_NO_PROXY
                                                    : WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                          WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, WINHTTP_FLAG_ASYNC);
        if (!hSession) throw std::runtime_error("WinHttpOpen failed");
        setHttpTimeouts(hSession, requestTimeoutMs);
        DWORD redirectPolicy = WINHTTP_OPTION_REDIRECT_POLICY_ALWAYS;
        WinHttpSetOption(hSession, WINHTTP_OPTION_REDIRECT_POLICY, &redirectPolicy, sizeof(redirectPolicy));

        HINTERNET hConnect = WinHttpConnect(hSession, host, uc.nPort, 0);
        if (!hConnect) { WinHttpCloseHandle(hSession); throw std::runtime_error("WinHttpConnect failed"); }

        auto wMethod = U2W(method);
        HINTERNET hRequest = WinHttpOpenRequest(hConnect, wMethod.c_str(), objectPath.c_str(),
                                                 nullptr, WINHTTP_NO_REFERER,
                                                 WINHTTP_DEFAULT_ACCEPT_TYPES,
                                                 https ? WINHTTP_FLAG_SECURE : 0);
        if (!hRequest) {
            WinHttpCloseHandle(hConnect);
            WinHttpCloseHandle(hSession);
            throw std::runtime_error("WinHttpOpenRequest failed");
        }
        ymcc::http::AsyncRequest request(hSession, hConnect, hRequest, deadline,
            [] { return g_poolCancel.load(std::memory_order_acquire); });
        if (steamHost && https) {
            DWORD securityFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA |
                                  SECURITY_FLAG_IGNORE_CERT_DATE_INVALID |
                                  SECURITY_FLAG_IGNORE_CERT_CN_INVALID;
            WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &securityFlags, sizeof(securityFlags));
        }

        // Add custom headers
        std::wstring allHeaders;
        for (auto& [k, v] : hdrs.items()) {
            if (!v.is_string() || !is_http_token(k) || has_header_injection_chars(v.get<std::string>()))
                throw std::runtime_error("Invalid HTTP header");
            allHeaders += U2W(k) + L": " + U2W(v.get<std::string>()) + L"\r\n";
        }
        if (!allHeaders.empty())
            WinHttpAddRequestHeaders(hRequest, allHeaders.c_str(), (DWORD)-1, WINHTTP_ADDREQ_FLAG_ADD);

        // Fan-only mode metadata rides this existing request; no new heartbeat.
        if (monitorFanRequest && monitorFanPath == "/api/heartbeat" &&
            (method == "POST" || ascii_lower(method) == "post"))
            fanLeaseKeepaliveAddRendererMode(body, hdrs, monitorFanEpoch);

        request.send(body);
        request.headers();

        // Status code
        DWORD statusCode = 0, sz = sizeof(statusCode);
        WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                            WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &sz, WINHTTP_NO_HEADER_INDEX);

        // Response headers
        DWORD hdrSize = 0;
        WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF,
                            WINHTTP_HEADER_NAME_BY_INDEX, nullptr, &hdrSize, WINHTTP_NO_HEADER_INDEX);
        std::wstring respHdrs(hdrSize / sizeof(wchar_t), 0);
        const bool responseHeadersAvailable = WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF,
                            WINHTTP_HEADER_NAME_BY_INDEX, respHdrs.data(), &hdrSize, WINHTTP_NO_HEADER_INDEX) != FALSE;
        const auto rawResponseHeaders = W2U(respHdrs);

        // Body shares the original deadline. Fan read failure is an unconfirmed
        // receipt, never permission to promote a parseable prefix or retry a POST.
        std::string respBody;
        bool fanBodyComplete = true;
        try { respBody = request.readAll(8u << 20); }
        catch (...) {
            if (!monitorFanRequest) throw;
            fanBodyComplete = false;
            respBody.clear();
        }
        if (monitorFanRequest && fanBodyComplete) fanBodyComplete = responseHeadersAvailable
            && ymcc::fan_http::responseBodyComplete(method, statusCode, rawResponseHeaders, respBody.size());
        // Fan-only receipt preparation uses the same target as its observer.
        if (monitorFanRequest) {
            const std::string emptyFanResponse;
            const auto& observerResponse = fanBodyComplete ? respBody : emptyFanResponse;

            // 批138（F06）：渲染器是经本入口发 Fan 请求的（会话头由渲染器给出）⇒ 记录
            // "本次是否带凭据 + 凭据版本指纹"，并取 Host 的请求 ID（跨端对账到同一次请求）。
            bool fanSessionHeaderPresent = false;
            std::string fanSessionHeaderValue;
            if (hdrs.is_object()) {
                for (auto& [key, value] : hdrs.items()) {
                    if (ascii_lower(key) != "x-yeman-fan-session") continue;
                    fanSessionHeaderPresent = value.is_string();
                    // Credential text is used only by the 401/403 evidence path below.
                    if (fanSessionHeaderPresent && (statusCode == 401 || statusCode == 403))
                        fanSessionHeaderValue = value.get<std::string>();
                    break;
                }
            }
            // Passive receipt admission only; no fan query is added to monitor.snapshot.
            // Fan observers share this request-local parse; no receipt is cached across requests.
            json parsedFanResponse;
            // An explicit non-receipt avoids reparsing an incomplete body downstream.
            const json* parsedFanResponsePtr = monitorFanRequest && !fanBodyComplete ? &parsedFanResponse : nullptr;
            if (monitorFanRequest && fanBodyComplete && fanSessionHeaderPresent && respBody.size() <= 64u * 1024u) {
                parsedFanResponse = json::parse(respBody, nullptr, false);
                parsedFanResponsePtr = &parsedFanResponse;
            }
            fanLeaseKeepaliveObserveHttp(method, host, uc.nPort, objectPath, body,
                                         statusCode, observerResponse, fanSessionHeaderPresent,
                                         fanSessionHeaderValue,
                                         fanHeaderRequestIdFromRawHeaders(rawResponseHeaders), parsedFanResponsePtr, monitorFanEpoch);
            if (fanBodyComplete && parsedFanResponsePtr)
                g_monitorFanDisplay.observe(monitorFanEpoch, statusCode, *parsedFanResponsePtr, static_cast<long long>(sgNowEpoch() * 1000.0));
        }
        json response{{"status", statusCode}, {"headers", rawResponseHeaders}, {"body", respBody}};
        if (monitorFanRequest) response["bodyComplete"] = fanBodyComplete;
        return response;
    });
}

/**
 * Bounded Host cleanup operation.  This function is deliberately called only
 * by the detached fallback worker below.  It must never be called from a
 * WM_POWERBROADCAST or Kernel-Power callback: WinHTTP and its retry delays are
 * allowed to take hundreds of milliseconds and therefore cannot be part of a
 * sleep/veto path.
 */
// ①′（2026-09-17 M2″-v3）：Host 使用 HttpListener ⇒ 实际 LISTENING socket 归
// HTTP.sys（System, pid 4），不是 Host 进程本身。旧判据要求 owner==Host pid
// ⇒ 恒为 false ⇒ native 续租静默全灭（长期 0 success 的根因）。身份判据改为
// "精确 Host pid 或 HTTP.sys owner"两者之一；exact-image 校验（进程名 + 映像
// 最终路径）仍在上游执行，会话令牌因此仍只发给已验证的 YeManFanHost.exe 映像。
static constexpr DWORD kHttpSysListenerOwnerPid = 4; // System / HTTP.sys
static bool fanHostOwnsLoopbackPort(DWORD pid, unsigned short port = 8765) {
    ULONG bytes = 0;
    constexpr ULONG kIpv4Family = 2; // AF_INET; keep native shell free of Winsock ABI headers
    if (GetExtendedTcpTable(nullptr, &bytes, FALSE, kIpv4Family,
                            TCP_TABLE_OWNER_PID_LISTENER, 0) != ERROR_INSUFFICIENT_BUFFER ||
        bytes == 0) return false;
    std::vector<unsigned char> buffer(bytes);
    auto* table = reinterpret_cast<PMIB_TCPTABLE_OWNER_PID>(buffer.data());
    if (GetExtendedTcpTable(table, &bytes, FALSE, kIpv4Family,
                            TCP_TABLE_OWNER_PID_LISTENER, 0) != NO_ERROR) return false;
    const auto decodeNetworkU16 = [](DWORD value) -> unsigned short {
        return static_cast<unsigned short>(((value & 0xffu) << 8) | ((value >> 8) & 0xffu));
    };
    for (DWORD i = 0; i < table->dwNumEntries; ++i) {
        const auto& row = table->table[i];
        if (row.dwLocalAddr == 0x0100007Fu &&
            decodeNetworkU16(row.dwLocalPort) == port &&
            (row.dwOwningPid == pid || row.dwOwningPid == kHttpSysListenerOwnerPid))
            return true;
    }
    return false;
}

// ── 第二十五轮返修（2026-09-18，P1「YMCC 按钮关闭未交回 OEM」裁决书）──
// 旧退出路径在身份门失败时静默 return true ⇒"未找到可验证 Host"被外层写成
// 旧的两态"清理已确认"串（语义错误，本轮已移除）。本组结构把门的三条件（进程名 / 最终镜像
// 路径 / 127.0.0.1:8765 LISTEN 归属）逐项暴露为**事件级证据**（只在退出与自测时
// 采样一次，无周期成本），并把退出结果改为三态。
struct FanHostIdentityProbe {
    bool processFound = false;   // 存在名为 YeManFanHost.exe 的进程
    bool imageMatched = false;   // 其最终镜像路径 == POWER_CONTROL_DIR\fan-host\YeManFanHost.exe
    bool portFound = false;      // 127.0.0.1:8765 有 LISTEN 且 owner ∈ {该进程, HTTP.sys(4)}
    DWORD matchedPid = 0;        // 三条件同时命中的 pid（0 = 未命中）
};

#ifdef YMCC_FAULT_INJECT
// ── 仅注入构建：退出交接六例自测（生产 exe 编译期完全剔除；见
// native/build_faultinject.bat 与 review-14 §7 的隔离边界要求）──
// 故障文件：%LOCALAPPDATA%\YeManCC\test-exit-handoff-fault.txt
//   gate=real|ok|no-process|image-mismatch|port-late
//   parent-exit=real|ok|ok-unbound|401|404|timeout
//   close=real|ok|fail
static int g_fiExitHandoffActive = 0;
static std::string g_fiExitGate = "real";
static std::string g_fiExitParentExit = "real";
static std::string g_fiExitClose = "real";
static int g_fiExitPortLateSteps = 3;

static void fiExitHandoffLoadConfig() {
    g_fiExitGate = "real";
    g_fiExitParentExit = "real";
    g_fiExitClose = "real";
    g_fiExitPortLateSteps = 3;
    std::ifstream in(fspath::path(yemancc_data_dir()) / L"test-exit-handoff-fault.txt");
    std::string line;
    while (std::getline(in, line)) {
        const auto eq = line.find('=');
        if (eq == std::string::npos) continue;
        const auto key = line.substr(0, eq);
        auto value = line.substr(eq + 1);
        while (!value.empty() && (value.back() == '\r' || value.back() == ' ')) value.pop_back();
        if (key == "gate") g_fiExitGate = value;
        else if (key == "parent-exit") g_fiExitParentExit = value;
        else if (key == "close") g_fiExitClose = value;
        else if (key == "port-late-steps") {
            try { g_fiExitPortLateSteps = std::stoi(value); } catch (...) { g_fiExitPortLateSteps = 3; }
        }
    }
    g_fiExitHandoffActive = 1;
}

// 门改写：注入不修改最终分类，只改写**输入**，让生产判据自行裁决。
static void fiExitHandoffApplyGateOverride(FanHostIdentityProbe* probe) {
    if (!g_fiExitHandoffActive) return;
    if (g_fiExitGate == "ok") {
        probe->processFound = probe->imageMatched = probe->portFound = true;
        probe->matchedPid = 4242;
    } else if (g_fiExitGate == "no-process") {
        probe->processFound = probe->imageMatched = probe->portFound = false;
        probe->matchedPid = 0;
    } else if (g_fiExitGate == "image-mismatch") {
        probe->processFound = true;
        probe->imageMatched = false;
        probe->portFound = false;
        probe->matchedPid = 0;
    } else if (g_fiExitGate == "port-late") {
        probe->processFound = true;
        probe->imageMatched = true;
        probe->portFound = g_fiExitPortLateSteps <= 0;
        probe->matchedPid = probe->portFound ? 4242 : 0;
        if (g_fiExitPortLateSteps > 0) --g_fiExitPortLateSteps;
    }
}

// POST 改写：false = 不干预；true = 以给定**状态码 + 响应体**作为输入（0 = 传输失败/超时）。
// 注入只提供"宿主会怎么答"，接受与绑定仍由生产纯函数自行裁决（FAN925B §5.1 / CP-03）：
//   parent-exit=ok        ⇒ 新宿主契约（带 acceptingHostInstanceId + acceptedRecoveryCycleId）
//   parent-exit=ok-unbound⇒ 旧宿主形态（2xx + recoveryAccepted，但无实例/周期绑定）
//   parent-exit=401       ⇒ 认证未获接受（不得据此回退无认证 close）
static bool fiExitHandoffForcedPost(const wchar_t* endpoint, DWORD* statusOut, std::string* bodyOut) {
    if (!g_fiExitHandoffActive) return false;
    auto boundReceipt = []() -> std::string {
        return std::string("{\"ok\":true,\"recoveryAccepted\":true,\"queuedNow\":true,")
            + "\"hostWillRemainResident\":true,"
            + "\"acceptingHostInstanceId\":\"0123456789abcdef0123456789abcdef\","
            + "\"acceptedRecoveryCycleId\":\"0123456789abcdef0123456789abcdef:1\","
            + "\"acceptanceScope\":\"accepted-by-this-host-instance-for-this-recovery-cycle\"}";
    };
    auto unboundReceipt = []() -> std::string {
        return std::string("{\"ok\":true,\"recoveryAccepted\":true,\"queuedNow\":false,")
            + "\"hostWillRemainResident\":true}";
    };
    if (wcscmp(endpoint, L"/api/parent-exit") == 0) {
        if (g_fiExitParentExit == "ok") {
            if (statusOut) *statusOut = 200;
            if (bodyOut) *bodyOut = boundReceipt();
            return true;
        }
        if (g_fiExitParentExit == "ok-unbound") {
            if (statusOut) *statusOut = 200;
            if (bodyOut) *bodyOut = unboundReceipt();
            return true;
        }
        if (g_fiExitParentExit == "401") {
            if (statusOut) *statusOut = 401;
            if (bodyOut) *bodyOut = "{\"ok\":false,\"error\":{\"code\":\"API_SESSION_REQUIRED\"}}";
            return true;
        }
        if (g_fiExitParentExit == "404") {
            if (statusOut) *statusOut = 404;
            return true;
        }
        if (g_fiExitParentExit == "timeout") {
            if (statusOut) *statusOut = 0;
            return true;
        }
    } else if (wcscmp(endpoint, L"/api/close") == 0) {
        if (g_fiExitClose == "ok") {
            if (statusOut) *statusOut = 200;
            return true;
        }
        if (g_fiExitClose == "fail") {
            if (statusOut) *statusOut = 503;
            return true;
        }
    }
    return false;
}

// ── 仅注入构建（2026-09-23 裁决 B / P-2；Q1 扩展 2026-09-23 补充裁决）──
// resume 恢复夹具。故障文件：%LOCALAPPDATA%\YeManCC\test-resume-recovery-fault.txt
//   resume=real|nohost|timeout|409|noop|ready|supersede-before-consume|faultlocked
//          |accepted|accepted-await-user|accept409|superseded409|ready-legacy
//   state =real|unreachable|resuming-forever|resuming-then-ready|slow-ready|await-user|faultlocked|superseded
// 只改写 /api/resume（POST）与 /api/state（GET 观察）的**输入**（状态码/响应体），
// 生产判据自行裁决；生产 exe 编译期剔除。
static std::string g_fiResumeMode = "real";
static std::string g_fiResumeStateMode = "real";
static std::atomic<int> g_fiResumeStateProbeCounter{0};
static std::atomic<unsigned long long> g_fiResumeStateProbeStartTick{0};

static void fiResumeLoadConfig() {
    g_fiResumeMode = "real";
    g_fiResumeStateMode = "real";
    g_fiResumeStateProbeCounter.store(0, std::memory_order_release);
    g_fiResumeStateProbeStartTick.store(0, std::memory_order_release);
    std::ifstream in(fspath::path(yemancc_data_dir()) / L"test-resume-recovery-fault.txt");
    std::string line;
    while (std::getline(in, line)) {
        const auto eq = line.find('=');
        if (eq == std::string::npos) continue;
        const auto key = line.substr(0, eq);
        auto value = line.substr(eq + 1);
        while (!value.empty() && (value.back() == '\r' || value.back() == ' ')) value.pop_back();
        if (key == "resume") g_fiResumeMode = value;
        else if (key == "state") g_fiResumeStateMode = value;
    }
}

static const char* const kFiResumeStateResuming =
    "{\"ok\":true,\"state\":{\"state\":\"Resuming\",\"powerState\":\"On\",\"unknownState\":false,"
    "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"executing\"}}";
static const char* const kFiResumeStateReady =
    "{\"ok\":true,\"state\":{\"state\":\"Ready\",\"powerState\":\"On\",\"unknownState\":false,"
    "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"completed\",\"powerOperationOutcome\":\"restored\"}}";

// true = 本次 GET /api/state 完全由夹具决定（Q1 观察阶段）。
static bool fiResumeForcedStateProbe(DWORD* status, std::string* bodyOut) {
    auto emit = [&](DWORD code, const std::string& body) {
        if (status) *status = code;
        if (bodyOut) *bodyOut = body;
        return true;
    };
    if (g_fiResumeStateMode == "real") return false;
    const int probe = g_fiResumeStateProbeCounter.fetch_add(1, std::memory_order_acq_rel) + 1;
    if (g_fiResumeStateMode == "unreachable") return emit(0, {});
    if (g_fiResumeStateMode == "resuming-forever") return emit(200, kFiResumeStateResuming);
    if (g_fiResumeStateMode == "resuming-then-ready")
        return emit(200, probe <= 2 ? kFiResumeStateResuming : kFiResumeStateReady);
    if (g_fiResumeStateMode == "slow-ready") {
        unsigned long long start = g_fiResumeStateProbeStartTick.load(std::memory_order_acquire);
        if (start == 0) {
            start = GetTickCount64();
            g_fiResumeStateProbeStartTick.store(start, std::memory_order_release);
        }
        return emit(200, (GetTickCount64() - start) < 10200 ? kFiResumeStateResuming : kFiResumeStateReady);
    }
    if (g_fiResumeStateMode == "await-user")
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"AwaitingControl\",\"powerState\":\"On\",\"unknownState\":false,"
                         "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"completed\",\"powerOperationOutcome\":\"await-user\"}}");
    if (g_fiResumeStateMode == "faultlocked")
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"FaultLocked\",\"unknownState\":true,"
                         "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"failed\"}}");
    if (g_fiResumeStateMode == "superseded")
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"Suspended\",\"powerState\":\"Suspended\",\"unknownState\":false,"
                         "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"superseded\"}}");
    return false;
}

// true = 本次 POST 完全由夹具决定（端点必须是 /api/resume）。
static bool fiResumeForcedPost(const wchar_t* endpoint, DWORD* status, std::string* bodyOut) {
    if (wcscmp(endpoint, L"/api/resume") != 0) return false;
    auto emit = [&](DWORD code, const std::string& body) {
        if (status) *status = code;
        if (bodyOut) *bodyOut = body;
        return true;
    };
    if (g_fiResumeMode == "real") return false;
    if (g_fiResumeMode == "nohost") return emit(0, {});
    if (g_fiResumeMode == "timeout") return emit(0, {});
    if (g_fiResumeMode == "409") return emit(409, "{\"error\":\"HC_RESUME_REBUILD_FAILED\"}");
    // Q1 接受形状（新宿主）：只表示"已接纳"，完成由 GET /api/state 观察判定。
    if (g_fiResumeMode == "accepted")
        return emit(200, "{\"ok\":true,\"resumeAccepted\":true,\"resumePhase\":\"Resuming\",\"generation\":2,\"attempt\":7,"
                         "\"retryAfterMs\":250,\"state\":{\"state\":\"Resuming\",\"powerState\":\"On\",\"unknownState\":false,"
                         "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"executing\"}}");
    if (g_fiResumeMode == "accepted-await-user")
        return emit(200, "{\"ok\":true,\"resumeAccepted\":true,\"resumePhase\":\"AwaitingControl\",\"generation\":2,\"attempt\":8,"
                         "\"retryAfterMs\":250,\"state\":{\"state\":\"AwaitingControl\",\"powerState\":\"On\",\"unknownState\":false,"
                         "\"hcCloseCleanupPending\":false,\"powerOperationStatus\":\"completed\",\"powerOperationOutcome\":\"await-user\"}}");
    if (g_fiResumeMode == "accept409")
        return emit(409, "{\"error\":{\"code\":\"POWER_RESUMING\",\"message\":\"transitional\"}}");
    if (g_fiResumeMode == "superseded409")
        return emit(409, "{\"error\":{\"code\":\"HC_RESUME_SUPERSEDED\",\"message\":\"superseded by a new sleep\"}}");
    if (g_fiResumeMode == "ready-legacy")
        // 旧宿主（同步等待实现）的终态形状：一次调用即 Ready。
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"Ready\",\"unknownState\":false,\"hcCloseCleanupPending\":false}}");
    if (g_fiResumeMode == "faultlocked")
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"FaultLocked\",\"unknownState\":false,\"hcCloseCleanupPending\":false}}");
    if (g_fiResumeMode == "noop")
        return emit(200, "{\"ok\":true,\"resumeNoop\":true,\"reason\":\"not-suspended\",\"state\":{\"state\":\"AwaitingControl\",\"unknownState\":false,\"hcCloseCleanupPending\":false}}");
    if (g_fiResumeMode == "ready")
        // 注意：注入自测不经过应用启动初始化，lease 重武装（fanLeaseKeepaliveArm）
        // 在自测环境不可安全调用（实测 0xC0000409 fail-fast）⇒ 该夹具不带 lease，
        // 只验证"真相恢复判据"；lease 重武装由既有 identity/等待者夹具与真机取证覆盖。
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"Ready\",\"unknownState\":false,\"hcCloseCleanupPending\":false}}");
    if (g_fiResumeMode == "supersede-before-consume") {
        // 抢在消费之前制造"新 session 已接管"（generation 前进）后仍给出 Ready 响应：
        // 该响应属旧代，恢复序列必须判 superseded，不得记成 recovered。
        g_fanResumeRecoveryGeneration.fetch_add(1, std::memory_order_acq_rel);
        return emit(200, "{\"ok\":true,\"state\":{\"state\":\"Ready\",\"unknownState\":false,\"hcCloseCleanupPending\":false}}");
    }
    return false;
}
#endif

// 8765 的 LISTEN 行明细（同一张表，退出/自测专用；供证据留存）。
static json fanHostLoopbackListenerRows() {
    json rows = json::array();
    ULONG bytes = 0;
    constexpr ULONG kIpv4Family = 2;
    if (GetExtendedTcpTable(nullptr, &bytes, FALSE, kIpv4Family,
                            TCP_TABLE_OWNER_PID_LISTENER, 0) != ERROR_INSUFFICIENT_BUFFER ||
        bytes == 0) return rows;
    std::vector<unsigned char> buffer(bytes);
    auto* table = reinterpret_cast<PMIB_TCPTABLE_OWNER_PID>(buffer.data());
    if (GetExtendedTcpTable(table, &bytes, FALSE, kIpv4Family,
                            TCP_TABLE_OWNER_PID_LISTENER, 0) != NO_ERROR) return rows;
    for (DWORD i = 0; i < table->dwNumEntries; ++i) {
        const auto& row = table->table[i];
        const auto port = static_cast<unsigned short>(((row.dwLocalPort & 0xffu) << 8) |
                                                      ((row.dwLocalPort >> 8) & 0xffu));
        if (port != 8765) continue;
        char addr[32] = {};
        snprintf(addr, sizeof(addr), "%u.%u.%u.%u",
                 row.dwLocalAddr & 0xffu, (row.dwLocalAddr >> 8) & 0xffu,
                 (row.dwLocalAddr >> 16) & 0xffu, (row.dwLocalAddr >> 24) & 0xffu);
        rows.push_back(json{{"address", addr}, {"port", port},
                            {"ownerPid", static_cast<unsigned long>(row.dwOwningPid)}});
    }
    return rows;
}

static FanHostIdentityProbe fanHostIdentityProbe() {
    FanHostIdentityProbe probe;
    HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snapshot != INVALID_HANDLE_VALUE) {
        const auto expected = POWER_CONTROL_DIR + L"\\fan-host-v2\\YeManFanHost.exe";
        PROCESSENTRY32W entry{};
        entry.dwSize = sizeof(entry);
        if (Process32FirstW(snapshot, &entry)) {
            do {
                if (_wcsicmp(entry.szExeFile, L"YeManFanHost.exe") != 0) continue;
                if (g_aiFanMockSession.enabled && !g_aiFanMockHost.owns(entry.th32ProcessID)) continue;
                probe.processFound = true;
                const auto image = processImagePath(entry.th32ProcessID);
                if (image.empty() || !sameFinalPath(image, expected)) continue;
                probe.imageMatched = true;
                if (fanHostOwnsLoopbackPort(entry.th32ProcessID)) {
                    probe.portFound = true;
                    probe.matchedPid = entry.th32ProcessID;
                    break;
                }
            } while (Process32NextW(snapshot, &entry));
        }
        CloseHandle(snapshot);
    }
#ifdef YMCC_FAULT_INJECT
    fiExitHandoffApplyGateOverride(&probe);   // 仅注入构建（自测期生效；生产无此路径）
#endif
    return probe;
}

// 门明细（含所有同名进程的镜像路径与 8765 全部 LISTEN 行）——退出时一次性落盘。
static json fanHostIdentityDetail(const FanHostIdentityProbe& probe, bool waited, unsigned long long waitedMs) {
    json candidates = json::array();
    HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snapshot != INVALID_HANDLE_VALUE) {
        const auto expected = POWER_CONTROL_DIR + L"\\fan-host-v2\\YeManFanHost.exe";
        PROCESSENTRY32W entry{};
        entry.dwSize = sizeof(entry);
        if (Process32FirstW(snapshot, &entry)) {
            do {
                if (_wcsicmp(entry.szExeFile, L"YeManFanHost.exe") != 0) continue;
                const auto image = processImagePath(entry.th32ProcessID);
                candidates.push_back(json{
                    {"pid", static_cast<unsigned long>(entry.th32ProcessID)},
                    {"imagePath", W2U(image)},
                    {"imageMatches", !image.empty() && sameFinalPath(image, expected)},
                    {"ownsLoopback8765", fanHostOwnsLoopbackPort(entry.th32ProcessID)}});
            } while (Process32NextW(snapshot, &entry));
        }
        CloseHandle(snapshot);
    }
    const bool verified = probe.processFound && probe.imageMatched && probe.portFound;
    return json{
        {"expectedPath", W2U(POWER_CONTROL_DIR + L"\\fan-host-v2\\YeManFanHost.exe")},
        {"candidates", candidates},
        {"listeners", fanHostLoopbackListenerRows()},
        {"gates", json{{"process", probe.processFound},
                       {"image", probe.imageMatched},
                       {"port", probe.portFound}}},
        {"verified", verified},
        {"matchedPid", static_cast<unsigned long>(probe.matchedPid)},
        {"waited", waited},
        {"waitedMs", waitedMs}};
}

// ── 批138（FAN925B §5.1 / §2(5)(6)(7) / F06 / GP G9）：Fan HTTP 认证与实例证据 ──
// 口径（照抄裁决，禁止下游加码）：
//   · 401 只表示"**这次**请求的凭据未获接受"；不据此宣布对方是"旧代"，更不是强杀 /
//     绕过认证 / 重写 sidecar / 新起第二 owner 的许可；
//   · 进程（pid + 创建时间）、凭据版本（非秘密指纹）、HC 会话**必须分列**，不得互相代替；
//   · **绝不**记录凭据值、前缀或密钥材料；不记录命令行原文（可能含 --confirm 等令牌）。
//   · 低频：实例/凭据加载按进程一次；认证拒绝按 (source|method|path|status) 限频 60 s 并
//     累计被抑制条数 —— 关闭详细日志也不会让认证责任链失踪。
static constexpr ULONGLONG kFanAuthRejectThrottleMs = 60000;

static std::string fanHostReadSessionToken();   // 定义见本区下部；实例/凭据行需要它

static unsigned long long fanHostProcessStartMs(DWORD pid) {
    if (!pid) return 0;
    HANDLE process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (!process) return 0;
    FILETIME create{}, exitTime{}, kernel{}, user{};
    unsigned long long startMs = 0;
    if (GetProcessTimes(process, &create, &exitTime, &kernel, &user)) {
        constexpr unsigned long long kEpochDeltaTicks = 116444736000000000ULL;   // 1601 → 1970
        const ULONGLONG ticks = focusFileTimeTicks(create);
        if (ticks > kEpochDeltaTicks) startMs = (ticks - kEpochDeltaTicks) / 10000ULL;
    }
    CloseHandle(process);
    return startMs;
}

// 凭据的**非秘密版本标识** = SHA-256 前 8 位小写十六进制：与 Host 侧
// HostDiagnosticLog.CredentialVersionId 同算法同格式（可跨端对账），不可反推凭据。
static std::string fanCredentialVersionId(const std::string& credential) {
    if (credential.empty()) return "absent";
    const std::string digest = inputHostSha256(credential);
    return digest.size() >= 8 ? digest.substr(0, 8) : std::string("unavailable");
}

static json fanCredentialVersionDetail(const std::string& credentialUsed) {
    const auto path = fan_host_state_dir() + L"\\YeManFanHost.session";
    const bool formatOk = credentialUsed.size() == 64 &&
        std::all_of(credentialUsed.begin(), credentialUsed.end(),
                    [](unsigned char value) { return std::isxdigit(value) != 0; });
    return json{
        {"credentialPresent", !credentialUsed.empty()},
        {"credentialFilePresent", GetFileAttributesW(path.c_str()) != INVALID_FILE_ATTRIBUTES},
        {"credentialFormatOk", formatOk},
        {"credentialVersionId", fanCredentialVersionId(credentialUsed)},
        {"credentialBytes", static_cast<unsigned long long>(credentialUsed.size())}};
}

// 请求关联 ID（**非凭据、不授权**）：把 native 侧"这一次请求"的多行串起来。
// 与 Host 响应头 `X-YeMan-Fan-Request-Id` 不同源（那是 Host 自己的 ID）；跨端对齐用
// hostRequestId 字段，本 ID 只解决 native 内部的行间关联。
static std::string fanRequestId(const char* scope) {
    static std::atomic<unsigned long long> seq{0};
    const unsigned long long n = seq.fetch_add(1, std::memory_order_relaxed) + 1;
    char buf[96] = {};
    snprintf(buf, sizeof(buf), "%s-%lu-%llu-%llu",
             scope && *scope ? scope : "fan",
             static_cast<unsigned long>(GetCurrentProcessId()),
             static_cast<unsigned long long>(GetTickCount64()), n);
    return std::string(buf);
}

// 认证类别（纯函数，可逐条断言）：401/403 **只**表示"这一次请求未获接受"，不判代、
// 不是绕过认证的许可；status==0 ⇒"连响应都没有"（加头/发送/收包失败，与拒绝分开读）。
static const char* fanAuthCategory(DWORD status) {
    if (status == 0) return "transport-unknown";
    if (status >= 200 && status < 300) return "accepted";
    if (status == 401) return "rejected-401";
    if (status == 403) return "rejected-403";
    return "other-status";
}

// 响应体里的**非秘密**标识字段（新宿主才有；旧宿主 ⇒ absent）。只接受**固定长度十六进制**，
// 于是任何原值（凭据 / 凭据前缀 / 命令行）都不可能经此进入日志。
static std::string fanHostHexFieldFromBody(const std::string& body, const char* key,
                                           size_t expectedLength) {
    if (body.empty() || !key || !*key) return {};
    const auto parsed = json::parse(body, nullptr, false);
    if (parsed.is_discarded() || !parsed.is_object()) return {};
    const auto it = parsed.find(key);
    if (it == parsed.end() || !it->is_string()) return {};
    const std::string value = ascii_lower(it->get<std::string>());
    if (value.size() != expectedLength) return {};
    if (!std::all_of(value.begin(), value.end(),
                     [](unsigned char c) { return std::isxdigit(c) != 0; })) return {};
    return value;
}

// 三要素分列：进程 / 凭据版本 / HC 会话。native 只持有前两项 + 自己**观察到**的事实；
// HC 会话不在 native 手里（不得用凭据版本或 pid 冒充会话 / 实例）。
static json fanHostInstanceSplit(DWORD pid, const std::string& credentialForThisRequest) {
    json detail = fanCredentialVersionDetail(credentialForThisRequest);
    detail["hostProcessPid"] = static_cast<unsigned long>(pid);
    detail["hostProcessStartMs"] = pid ? fanHostProcessStartMs(pid) : 0ULL;
    detail["hostInstanceSource"] = "native-observed-pid+creation-time";
    detail["hcSession"] = "unknown";
    detail["hcSessionSource"] = "native-does-not-track-hc-session";
    return detail;
}

// 限频判定（纯函数：与真实表共用同一窗口定义，逐字可测）。
static bool fanAuthRejectWithinWindow(ULONGLONG lastTick, ULONGLONG now) {
    return lastTick != 0 && now - lastTick < kFanAuthRejectThrottleMs;
}

static std::string fanErrorCodeFromBody(const std::string& body) {
    if (body.empty()) return {};
    const auto parsed = json::parse(body, nullptr, false);
    if (parsed.is_discarded() || !parsed.is_object()) return {};
    const auto error = parsed.find("error");
    if (error == parsed.end()) return {};
    if (error->is_string()) return error->get<std::string>();
    if (error->is_object()) {
        const auto code = error->find("code");
        if (code != error->end() && code->is_string()) return code->get<std::string>();
    }
    return {};
}

// Host 在**每个**响应上带 `X-YeMan-Fan-Request-Id`（FanLab/real-host §5.1）⇒ 用它把 native
// 行与 Host 自己的 auth.rejected / parent-exit-handoff 行对齐到**同一次请求**。只接受 32 位
// 十六进制；旧宿主不带 ⇒ 空（调用方如实写 absent-in-response）。
static std::string fanHostResponseRequestId(HINTERNET request) {
    if (!request) return {};
    wchar_t buffer[128]{};
    DWORD size = sizeof(buffer);
    if (!WinHttpQueryHeaders(request, WINHTTP_QUERY_CUSTOM, L"X-YeMan-Fan-Request-Id",
                             buffer, &size, WINHTTP_NO_HEADER_INDEX)) return {};
    std::wstring value(buffer, size / sizeof(wchar_t));
    const auto colon = value.find(L':');
    if (colon != std::wstring::npos) value.erase(0, colon + 1);
    while (!value.empty() && (value.back() == L'\0' || value.back() == L'\r' ||
                              value.back() == L'\n' || value.back() == L' ')) value.pop_back();
    size_t begin = 0;
    while (begin < value.size() && value[begin] == L' ') ++begin;
    value.erase(0, begin);
    if (value.size() != 32) return {};
    const std::string text = W2U(value);
    if (!std::all_of(text.begin(), text.end(),
                     [](unsigned char c) { return std::isxdigit(c) != 0; })) return {};
    return ascii_lower(text);
}

// 同类入口（渲染器经 native `ipc http.request`）：原始响应头里取同一字段。
static std::string fanHeaderRequestIdFromRawHeaders(const std::string& rawHeaders) {
    constexpr char kName[] = "x-yeman-fan-request-id:";
    constexpr auto nameLength = sizeof(kName) - 1;
    size_t lineStart = 0;
    while (lineStart < rawHeaders.size()) {
        const auto newline = rawHeaders.find('\n', lineStart);
        const auto lineEnd = newline == std::string::npos ? rawHeaders.size() : newline;
        auto valueEnd = lineEnd;
        if (valueEnd > lineStart && rawHeaders[valueEnd - 1] == '\r') --valueEnd;
        // A blank line ends the headers; diagnostic text after it is not a field.
        if (valueEnd == lineStart) return {};
        bool matches = valueEnd - lineStart >= nameLength;
        for (size_t i = 0; matches && i < nameLength; ++i) {
            auto c = static_cast<unsigned char>(rawHeaders[lineStart + i]);
            if (c >= 'A' && c <= 'Z') c = static_cast<unsigned char>(c + ('a' - 'A'));
            if (c != static_cast<unsigned char>(kName[i])) matches = false;
        }
        if (matches) {
            auto begin = lineStart + nameLength;
            while (begin < valueEnd && (rawHeaders[begin] == ' ' || rawHeaders[begin] == '\t')) ++begin;
            while (valueEnd > begin && (rawHeaders[valueEnd - 1] == ' ' || rawHeaders[valueEnd - 1] == '\t')) --valueEnd;
            if (valueEnd - begin != 32) return {};
            std::string value;
            value.reserve(32);
            for (; begin < valueEnd; ++begin) {
                auto c = static_cast<unsigned char>(rawHeaders[begin]);
                if (c >= 'A' && c <= 'F') c = static_cast<unsigned char>(c + ('a' - 'A'));
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return {};
                value.push_back(static_cast<char>(c));
            }
            return value;
        }
        if (newline == std::string::npos) break;
        lineStart = newline + 1;
    }
    return {};
}

// 限频槽（表上限 8：异常客户端刷 401 不会撑爆日志，但责任链始终留有一条入口行）。
struct FanAuthRejectSlot {
    std::string key;
    ULONGLONG lastTick = 0;
    unsigned long long suppressed = 0;
};

// 限频真值表（**纯表操作**，与生产共用同一实现，可离线逐条断言）：
//   新键 → 立即放行；同键窗口内 → 抑制并累计；同键窗口外 → 放行并带出被抑制条数。
static bool fanAuthRejectSlotShouldLog(std::vector<FanAuthRejectSlot>& slots,
                                       const std::string& key, ULONGLONG now,
                                       unsigned long long* suppressedOut) {
    if (suppressedOut) *suppressedOut = 0;
    auto it = std::find_if(slots.begin(), slots.end(),
                           [&](const FanAuthRejectSlot& slot) { return slot.key == key; });
    if (it == slots.end()) {
        if (slots.size() >= 8) slots.erase(slots.begin());
        FanAuthRejectSlot slot;
        slot.key = key;
        slot.lastTick = now;
        slots.push_back(slot);
        return true;
    }
    if (fanAuthRejectWithinWindow(it->lastTick, now)) {
        ++it->suppressed;
        return false;
    }
    if (suppressedOut) *suppressedOut = it->suppressed;
    it->suppressed = 0;
    it->lastTick = now;
    return true;
}

// 凭据桶（限频键的一部分）：**"没带会话头"与"带了但是空值"必须分列** ——
// b138 实测：渲染器在 401 之后做过一次**不带会话头**的 /health 试探，因当时限频键
// 不含凭据维度而被同键折叠 ⇒ 证据不可见。FAN925B §2(5) 的要求正相反。
static const char* fanCredentialBucket(bool headerPresent, const std::string& credentialUsed) {
    if (!headerPresent) return "no-header";
    return credentialUsed.empty() ? "empty" : "present";
}

// 证据行构造（纯函数；脱敏口径集中在此，便于逐字段断言"不含凭据值/前缀"）。
static json fanAuthRejectEvidenceJson(const char* source, const std::string& method,
                                      const std::string& path, DWORD status,
                                      const std::string& credentialUsed,
                                      bool credentialHeaderPresent,
                                      const std::string& credentialOrigin,
                                      const std::string& hostRequestId,
                                      const std::string& responseErrorCode,
                                      const std::string& nativeRequestId,
                                      const std::string& responseBody,
                                      bool headerAdded,
                                      DWORD matchedPid, unsigned long long suppressed) {
    json detail = fanHostInstanceSplit(matchedPid, credentialUsed);
    detail["credentialHeaderPresent"] = credentialHeaderPresent;
    detail["credentialBucket"] = fanCredentialBucket(credentialHeaderPresent, credentialUsed);
    detail["source"] = source ? source : "unknown";
    detail["method"] = method;
    detail["path"] = path;
    detail["status"] = static_cast<unsigned long>(status);
    detail["authCategory"] = fanAuthCategory(status);
    detail["nativeRequestId"] = nativeRequestId.empty() ? std::string("unavailable")
                                                       : nativeRequestId;
    // 加头与发送/收包分列：401 只有在"凭据头确实加上"时才算一次凭据裁决（FAN925B §1 段 5）。
    detail["headerAdded"] = headerAdded;
    // 响应体里的非秘密身份/版本字段（新宿主才有；旧宿主 ⇒ absent-in-response）。
    const std::string hostInstance = fanHostHexFieldFromBody(responseBody, "hostInstanceId", 32);
    const std::string hostFingerprint =
        fanHostHexFieldFromBody(responseBody, "sessionTokenFingerprint", 8);
    detail["hostLoadedInstanceId"] =
        hostInstance.empty() ? std::string("absent-in-response") : hostInstance;
    detail["hostLoadedTokenFingerprint"] =
        hostFingerprint.empty() ? std::string("absent-in-response") : hostFingerprint;
    detail["hostLoadedFieldPolicy"] = "fixed-length-hex-only;instance-and-credential-version-are-not-credentials";
    detail["port"] = 8765;
    detail["listeners"] = fanHostLoopbackListenerRows();
    detail["credentialOrigin"] = credentialOrigin;
    detail["hostRequestId"] = hostRequestId.empty() ? std::string("absent-in-response")
                                                    : hostRequestId;
    detail["responseErrorCode"] = responseErrorCode.empty() ? std::string("unknown")
                                                            : responseErrorCode;
    detail["matchedTargetInstance"] = matchedPid != 0;
    detail["attribution"] = "unknown";   // FAN925B §2(5)：单个 401 不能判代
    detail["scope"] = "this-request-not-accepted";
    detail["policy"] = "no-unauthenticated-close;no-sidecar-rewrite;no-second-owner;no-kill-on-401";
    detail["throttleMs"] = static_cast<unsigned long long>(kFanAuthRejectThrottleMs);
    detail["suppressedSinceLast"] = suppressed;
    return detail;
}

// 认证拒绝落账（常开、低频、脱敏、可对账）。禁止在此写凭据值/前缀。
// 限频键（纯函数，可逐条断言）：含凭据桶（no-header / empty / present）——同一路径的
// "带凭据被拒"与"无凭据试探"是两类不同事实，不得互相吞掉。
static std::string fanAuthRejectKey(const char* source, const std::string& method,
                                    const std::string& path, DWORD status,
                                    bool credentialHeaderPresent,
                                    const std::string& credentialUsed) {
    return std::string(source ? source : "unknown") + "|" + method + "|" + path + "|" +
        std::to_string(static_cast<unsigned long>(status)) + "|cred=" +
        fanCredentialBucket(credentialHeaderPresent, credentialUsed);
}

// 事件名（纯函数）：拒绝与"连响应都没有"必须能分开读 —— 把传输失败记成 auth-rejected
// 会把 C5（端口 owner 变化 / 不可达）误读成凭据问题。
static const char* fanAuthRejectEventName(DWORD status) {
    return status == 0 ? "fan-host-request-transport-unknown" : "fan-host-auth-rejected";
}

static void fanHostNoteAuthRejected(const char* source, const std::string& method,
                                    const std::string& path, DWORD status,
                                    const std::string& credentialUsed,
                                    bool credentialHeaderPresent,
                                    const std::string& credentialOrigin,
                                    const std::string& hostRequestId,
                                    const std::string& responseErrorCode,
                                    const std::string& nativeRequestId,
                                    const std::string& responseBody,
                                    bool headerAdded) {
    const std::string key = fanAuthRejectKey(source, method, path, status,
                                             credentialHeaderPresent, credentialUsed);
    const ULONGLONG now = GetTickCount64();
    unsigned long long suppressed = 0;
    {
        static std::mutex slotsMx;
        static std::vector<FanAuthRejectSlot> slots;
        std::lock_guard<std::mutex> lock(slotsMx);
        if (!fanAuthRejectSlotShouldLog(slots, key, now, &suppressed)) return;
    }
    const auto probe = fanHostIdentityProbe();
    appendFanLifecycleLog(fanAuthRejectEventName(status),
                          fanAuthRejectEvidenceJson(source, method, path, status, credentialUsed,
                                                    credentialHeaderPresent, credentialOrigin,
                                                    hostRequestId, responseErrorCode,
                                                    nativeRequestId, responseBody, headerAdded,
                                                    probe.matchedPid, suppressed));
}

// 凭据加载失败（缺失/格式错）——fail-closed：不发无认证请求，也不轮换 sidecar。
static void fanHostNoteCredentialUnavailable(const char* source) {
    static std::atomic<ULONGLONG> lastTick{0};
    const ULONGLONG now = GetTickCount64();
    ULONGLONG last = lastTick.load(std::memory_order_acquire);
    if (last != 0 && now - last < kFanAuthRejectThrottleMs) return;
    if (!lastTick.compare_exchange_strong(last, now, std::memory_order_acq_rel)) return;
    json detail = fanCredentialVersionDetail(std::string());
    detail["source"] = source ? source : "unknown";
    detail["reason"] = "missing-or-malformed-sidecar";
    detail["path"] = W2U(fan_host_state_dir() + L"\\YeManFanHost.session");
    detail["policy"] = "fail-closed;no-unauthenticated-request;no-rotation";
    appendFanLifecycleLog("fan-host-credential-unavailable", detail);
}

// 凭据头**没加上**（结构性缺陷，不是凭据裁决）——低频、脱敏、fail-closed：
// 调用方不得据此改走任何无认证路径（FAN925B §1 段 5 的证据缺口）。
static void fanHostNoteRequestHeaderFailed(const char* source, const std::string& method,
                                           const std::string& path,
                                           const std::string& credentialUsed) {
    const std::string key = std::string("header-failed|") + (source ? source : "unknown") +
        "|" + method + "|" + path;
    const ULONGLONG now = GetTickCount64();
    unsigned long long suppressed = 0;
    {
        static std::mutex slotsMx;
        static std::vector<FanAuthRejectSlot> slots;
        std::lock_guard<std::mutex> lock(slotsMx);
        if (!fanAuthRejectSlotShouldLog(slots, key, now, &suppressed)) return;
    }
    json detail = fanHostInstanceSplit(0, credentialUsed);
    detail["source"] = source ? source : "unknown";
    detail["method"] = method;
    detail["path"] = path;
    detail["status"] = 0;
    detail["authCategory"] = fanAuthCategory(0);
    detail["headerAdded"] = false;
    detail["nativeRequestId"] = fanRequestId("fan-header");
    detail["scope"] = "credential-header-not-attached";
    detail["policy"] = "fail-closed;no-unauthenticated-request;no-rotation;no-second-owner";
    detail["throttleMs"] = static_cast<unsigned long long>(kFanAuthRejectThrottleMs);
    detail["suppressedSinceLast"] = suppressed;
    appendFanLifecycleLog("fan-host-request-header-failed", detail);
}

// 实例启动证据（事件级：只在 pid / 创建时间变化时写一次，零周期开销）。
static void fanHostNoteInstanceObserved(const FanHostIdentityProbe& probe) {
    if (!probe.matchedPid) return;
    static std::mutex instanceMx;
    static DWORD lastPid = 0;
    static unsigned long long lastStartMs = 0;
    const unsigned long long startMs = fanHostProcessStartMs(probe.matchedPid);
    {
        std::lock_guard<std::mutex> lock(instanceMx);
        if (lastPid == probe.matchedPid && lastStartMs == startMs) return;
        lastPid = probe.matchedPid;
        lastStartMs = startMs;
    }
    // 实例身份只在变化时写一次；凭据版本单列，绝不与实例身份互相代替。
    json detail = fanHostInstanceSplit(probe.matchedPid, fanHostReadSessionToken());
    detail["source"] = "fanHostExactProcessRunning";
    detail["gates"] = json{{"process", probe.processFound},
                           {"image", probe.imageMatched},
                           {"port", probe.portFound}};
    appendFanLifecycleLog("fan-host-instance-observed", detail);
}

static bool fanHostExactProcessRunning() {
    const auto probe = fanHostIdentityProbe();
    const bool running = probe.processFound && probe.imageMatched && probe.portFound;
    if (running) fanHostNoteInstanceObserved(probe);
    return running;
}

static ymcc::fan_process::KeepaliveSelection<>& fanKeepaliveProcessSelection() {
    // Only the existing keepalive worker uses the production selection.
    // Thread-local destruction also releases the handle on worker exit.
    static thread_local ymcc::fan_process::KeepaliveSelection<> selection;
    return selection;
}

static bool fanHostExactProcessRunningForKeepalive() {
#ifdef YMCC_FAULT_INJECT
    // Preserve fault-injected complete identity probes for existing exit gates.
    return fanHostExactProcessRunning();
#else
    auto& selection = fanKeepaliveProcessSelection();
    const auto expected = POWER_CONTROL_DIR + L"\\fan-host-v2\\YeManFanHost.exe";
    DWORD matchedPid = 0;
    if (selection.matches([&](DWORD pid, HANDLE process) {
        if (g_aiFanMockSession.enabled && !g_aiFanMockHost.owns(pid)) return false;
        wchar_t image[32768];
        DWORD length = 32768;
        if (!QueryFullProcessImageNameW(process, 0, image, &length) || !length || length > 32768) return false;
        if (!sameFinalPath(std::wstring(image, length), expected) || !fanHostOwnsLoopbackPort(pid)) return false;
        matchedPid = pid;
        return true;
    })) {
        FanHostIdentityProbe probe;
        probe.processFound = probe.imageMatched = probe.portFound = true;
        probe.matchedPid = matchedPid;
        fanHostNoteInstanceObserved(probe);
        return true;
    }
    const auto probe = fanHostIdentityProbe();
    const bool running = probe.processFound && probe.imageMatched && probe.portFound;
    if (running) {
        // Failure to retain a query/synchronize handle never changes the legacy
        // full-probe result; the next request simply inventories again.
        selection.remember(probe.matchedPid);
        fanHostNoteInstanceObserved(probe);
    }
    return running;
#endif
}
// ①′ 留痕（限频 30s，禁止静默）：身份门失败曾长期以 `return false` 静默，
// 造成"native 续租 0 success 且无任何告警"。
static void fanHostIdentityNoteUnverified(const char* source) {
    static std::atomic<ULONGLONG> lastTick{0};
    const ULONGLONG now = GetTickCount64();
    ULONGLONG last = lastTick.load(std::memory_order_acquire);
    if (last != 0 && now - last < 30000ULL) return;
    if (!lastTick.compare_exchange_strong(last, now, std::memory_order_acq_rel)) return;
    json detail = {
        {"reason", "exact-process-or-port-mismatch"},
        {"source", source ? source : "unknown"}
    };
    // 去重（2026-09-17 日志重铸第一批）：fan 域事件统一只写 fan-lifecycle.log
    // （fan 时间线完整、可独立取证）；native-lifecycle.log 不再重复同一事实。
    // 跨域分析按 time 字段拼接两文件即可（两流时间戳同源）。
    appendFanLifecycleLog("fan-host-identity-unverified", detail);
}

// ②：渲染器重建证据的 epoch 推进（bump 不重置宽限 deadline）。
static void fanLeaseKeepaliveNoteRendererRebuild(const char* source) {
    const unsigned long long epoch =
        g_fanKeepaliveRendererEpoch.fetch_add(1, std::memory_order_acq_rel) + 1;
    json detail = {{"epoch", epoch}, {"source", source ? source : "unknown"}};
    // 去重：仅 fan-lifecycle.log（说明见 fan-host-identity-unverified 处）。
    appendFanLifecycleLog("native-lease-keepalive-renderer-epoch", detail);
}

static std::string fanHostReadSessionToken() {
    // The Host executable is an immutable release payload. The loopback
    // capability belongs in per-user app data so an update cannot replace it
    // while the native sleep/exit fallback still needs to close the Host.
    const auto path = fan_host_state_dir() + L"\\YeManFanHost.session";
    std::ifstream input(path, std::ios::binary);
    if (!input) return {};
    std::string token((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
    token = trim_ascii(std::move(token));
    // The application creates a 32-byte hexadecimal token. Reject malformed
    // sidecars rather than sending arbitrary local-file content as a header.
    if (token.size() != 64 || !std::all_of(token.begin(), token.end(), [](unsigned char value) {
        return std::isxdigit(value) != 0;
    })) return {};
    // 批138（FAN925B §5.1）：**凭据加载结果**（常开、低频：本进程一次；脱敏 —— 只有
    // 非秘密版本标识与格式结果，没有凭据值/前缀）。
    static std::atomic<bool> loadedLogged{false};
    if (!loadedLogged.exchange(true, std::memory_order_acq_rel)) {
        json detail = fanCredentialVersionDetail(token);
        detail["credentialOrigin"] = "native-sidecar";
        detail["path"] = W2U(path);
        detail["result"] = "loaded";
        detail["isNotInstanceIdentity"] = true;
        appendFanLifecycleLog("fan-host-credential-loaded", detail);
    }
    return token;
}

// Native Ready-only lease clock. Renderer setInterval is throttled when the
// window is minimized; Host TTL is still 15s. This worker only renews an
// already-acquired lease. Failure disarms and waits for the existing
// frontend/F5 owner. It must not become a second recover/enable writer.
static bool isFanLeaseIdValid(const std::string& id) {
    return ymcc::fan_response::leaseIdValid(id);
}

static std::string fanLeaseIdFromJsonValue(const json& value) {
    if (value.is_string()) return value.get<std::string>();
    if (value.is_object()) {
        auto id = value.value("leaseId", std::string{});
        if (id.empty()) id = value.value("LeaseId", std::string{});
        return id;
    }
    return {};
}

static std::string extractFanLeaseIdFromJson(const json& root) {
    if (!root.is_object()) return {};
    if (root.contains("lease")) {
        const auto id = fanLeaseIdFromJsonValue(root["lease"]);
        if (isFanLeaseIdValid(id)) return id;
    }
    if (root.contains("leaseId") || root.contains("LeaseId")) {
        const auto id = fanLeaseIdFromJsonValue(root.contains("leaseId") ? root["leaseId"] : root["LeaseId"]);
        if (isFanLeaseIdValid(id)) return id;
    }
    if (root.contains("state") && root["state"].is_object()) {
        const auto nested = extractFanLeaseIdFromJson(root["state"]);
        if (isFanLeaseIdValid(nested)) return nested;
    }
    return {};
}

static std::string parseFanLeaseIdText(const std::string& text) {
    if (text.empty()) return {};
    try {
        // Official heartbeat bodies are bounded ASCII tokens, optionally followed
        // by the exact unsigned revision emitted by the native metadata builder.
        // All other shapes keep the original decoder and its rejection semantics.
        constexpr char prefix[] = "{\"leaseId\":\"";
        constexpr char modeField[] = ",\"msiFirmwareModeRevision\":";
        constexpr auto prefixLength = sizeof(prefix) - 1;
        constexpr auto modeLength = sizeof(modeField) - 1;
        if (text.size() >= prefixLength + 8 + 2 && text.size() <= prefixLength + 80 + 2 + modeLength + 20
            && text.compare(0, prefixLength, prefix) == 0 && text.back() == '}') {
            const auto quote = text.find('"', prefixLength);
            if (quote != std::string::npos && quote - prefixLength >= 8 && quote - prefixLength <= 80) {
                const auto suffix = quote + 1;
                bool canonical = suffix + 1 == text.size();
                if (!canonical && text.compare(suffix, modeLength, modeField) == 0) {
                    const auto first = suffix + modeLength;
                    const auto digits = text.size() - first - 1;
                    canonical = digits >= 1 && digits <= 20 && !(digits > 1 && text[first] == '0')
                        && (digits < 20 || text.compare(first, 20, "18446744073709551615") <= 0);
                    for (auto i = first; canonical && i + 1 < text.size(); ++i)
                        if (text[i] < '0' || text[i] > '9') canonical = false;
                }
                if (canonical) {
                    auto id = text.substr(prefixLength, quote - prefixLength);
                    if (isFanLeaseIdValid(id)) return id;
                }
            }
        }
        return extractFanLeaseIdFromJson(json::parse(text));
    } catch (...) {
        return {};
    }
}

static std::string fanApiPathFromObject(const std::wstring& objectPath) {
    std::string path = W2U(objectPath);
    const auto query = path.find('?');
    if (query != std::string::npos) path.resize(query);
    return path;
}

static bool fanLeaseKeepaliveMayRun() {
    return !g_exitRequested.load(std::memory_order_acquire) &&
        !g_fanLeaseKeepaliveStop.load(std::memory_order_acquire) &&
        !g_fanSleepCleanupInFlight.load(std::memory_order_acquire) &&
        fanHostPowerMayWrite();
}

static void fanLeaseKeepaliveDisarm(const char* reason, const std::string* expectedLease) {
    bool hadLease = false;
    {
        std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
        // A rejected old heartbeat cannot retire a newer renderer lease.
        if (expectedLease && g_fanLeaseId != *expectedLease) return;
        g_monitorFanDisplay.invalidate(); // Atomic/nonblocking; after the identity fence.
        hadLease = !g_fanLeaseId.empty() ||
            g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire);
        g_fanLeaseId.clear();
        g_fanLeaseKeepaliveArmed.store(false, std::memory_order_release);
        // 睡眠/disarm 边界同步清零宽限，并让快照对齐当前 epoch（避免残留状态）。
        g_fanKeepaliveRendererGraceUntil = 0;
        g_fanKeepaliveRendererEpochSnapshot =
            g_fanKeepaliveRendererEpoch.load(std::memory_order_acquire);
        if (g_fanLeaseKeepaliveWake) SetEvent(g_fanLeaseKeepaliveWake);
    }
    if (!hadLease) return;
    json detail = {{"reason", reason ? reason : "unknown"}};
    // 去重：仅 fan-lifecycle.log（说明见 fan-host-identity-unverified 处）。
    appendFanLifecycleLog("native-lease-keepalive-stopped", detail);
}

static void fanLeaseKeepaliveEnsureThread();

static void fanLeaseKeepaliveArm(const std::string& leaseId, const char* source, ULONGLONG receiptEpoch = 0) {
    if (!isFanLeaseIdValid(leaseId)) return;
    if (g_exitRequested.load(std::memory_order_acquire) ||
        g_fanLeaseKeepaliveStop.load(std::memory_order_acquire)) return;
    if (!fanHostPowerMayWrite()) return;
    if (g_fanSleepCleanupInFlight.load(std::memory_order_acquire)) return;
    bool first = false;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
        if (receiptEpoch && receiptEpoch != g_monitorFanDisplay.epoch()) return;
        first = g_fanLeaseId.empty();
        changed = !first && g_fanLeaseId != leaseId;
        g_fanLeaseId = leaseId;
        g_fanLeaseKeepaliveArmed.store(true, std::memory_order_release);
        // GP-XBOX-2：Fan 所有权进 recovery 快照（armed ⇒ owned-by-current）。
        g_recoveryFanEverOwned.store(true, std::memory_order_release);
        // ②：武装/重武装时刷新 epoch 快照与 90s 宽限（宽限不因连续 bump 延长）。
        g_fanKeepaliveRendererEpochSnapshot =
            g_fanKeepaliveRendererEpoch.load(std::memory_order_acquire);
        g_fanKeepaliveRendererGraceUntil = GetTickCount64() + FAN_LEASE_RENDERER_GRACE_MS;
        // Bind renewal time to this exact candidate under its owner lock.
        if (ymcc::fan_response::leaseClockMayAdvance(first, changed, source))
            g_fanLeaseKeepaliveLastRenewTick.store(GetTickCount64(), std::memory_order_release);
    }
    fanLeaseKeepaliveEnsureThread();
    if (first || changed) {
        std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
        if (g_fanLeaseKeepaliveWake) SetEvent(g_fanLeaseKeepaliveWake);
    }
    if (!first && !changed) return;
    json detail = {
        {"source", source ? source : "unknown"},
        {"leasePresent", true},
        {"intervalMs", static_cast<int>(FAN_LEASE_KEEPALIVE_INTERVAL_MS)}
    };
    appendFanLifecycleLog(first ? "native-lease-keepalive-armed" : "native-lease-keepalive-refreshed", detail);
    appendNativeLifecycleLog(first ? "native-lease-keepalive-armed" : "native-lease-keepalive-refreshed", detail);
}

static void fanHostNoteMsiModeWrite(unsigned long long generation) noexcept {
    if(generation!=currentPowerGeneration())return;
    generation=currentFanPowerGeneration();
    if (!g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire) ||
        generation != currentFanPowerGeneration() || !fanHostPowerMayWrite() || g_exitRequested.load()) return;
    g_fanMsiModePowerGeneration.store(generation, std::memory_order_release);
    const auto revision = g_fanMsiModeRevision.fetch_add(1, std::memory_order_acq_rel) + 1;
    try { appendFanLifecycleLog("fan-msi-firmware-mode-changed", {{"revision", revision},
        {"powerGeneration", generation}, {"source", "native.msi-shift210"},
        {"notificationPath", "existing-authenticated-keepalive"},
        {"evidenceScope", "mode-write-may-have-occurred; notification-revision-recorded"},
        {"modeChangeVerified", false}, {"notificationDelivery", "not-observed-at-this-boundary"}}); } catch (...) { }
}

static void fanLeaseKeepaliveAddMsiMode(json& payload) {
    const auto modeRevision = g_fanMsiModeRevision.load(std::memory_order_acquire);
    if (modeRevision != 0 && g_fanMsiModePowerGeneration.load(std::memory_order_acquire) == currentFanPowerGeneration())
        payload["msiFirmwareModeRevision"] = modeRevision;
}

// Attach native-owned notification data only; the Host still authenticates the request.
static std::string fanLeaseKeepaliveRendererModeBody(const std::string& body, ULONGLONG revision) {
    constexpr char field[] = ",\"msiFirmwareModeRevision\":";
    const auto revisionText = std::to_string(revision);
    std::string amended;
    amended.reserve(body.size() + sizeof(field) - 1 + revisionText.size());
    amended.append(body, 0, body.size() - 1);
    amended += field;
    amended += revisionText;
    amended.push_back(body.back());
    return amended;
}

static void fanLeaseKeepaliveAddRendererMode(std::string& body, const json& headers, ULONGLONG receiptEpoch) noexcept {
    try {
        const auto revision = g_fanMsiModeRevision.load(std::memory_order_acquire);
        if (revision == 0 || body.empty() || body.size() > 64u * 1024u || !headers.is_object()) return;
        const auto generation = g_fanMsiModePowerGeneration.load(std::memory_order_acquire);
        if (!g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire) || !fanLeaseKeepaliveMayRun() ||
            generation != currentFanPowerGeneration() || receiptEpoch != g_monitorFanDisplay.epoch()) return;
        bool sessionPresent = false;
        for (const auto& [name, value] : headers.items()) {
            if (ascii_lower(name) != "x-yeman-fan-session") continue;
            sessionPresent = value.is_string() && !value.get_ref<const std::string&>().empty();
            break;
        }
        if (!sessionPresent) return;
        // The official adapter emits only this ASCII lease object. Keep the
        // generic parser for whitespace, escapes, extra fields and legacy callers.
        constexpr char leasePrefix[] = "{\"leaseId\":\"";
        constexpr auto prefixLength = sizeof(leasePrefix) - 1;
        std::string leaseId;
        std::string amended;
        if (body.size() >= prefixLength + 8 + 2 && body.size() <= prefixLength + 80 + 2 &&
            body.compare(0, prefixLength, leasePrefix) == 0 && body.compare(body.size() - 2, 2, "\"}") == 0) {
            leaseId.assign(body, prefixLength, body.size() - prefixLength - 2);
        }
        if (isFanLeaseIdValid(leaseId)) {
            amended = fanLeaseKeepaliveRendererModeBody(body, revision);
        } else {
            auto payload = json::parse(body, nullptr, false);
            if (!payload.is_object() || payload.contains("msiFirmwareModeRevision") ||
                !payload.contains("leaseId") || !payload["leaseId"].is_string()) return;
            leaseId = payload["leaseId"].get_ref<const std::string&>();
            if (!isFanLeaseIdValid(leaseId)) return;
            payload["msiFirmwareModeRevision"] = revision;
            amended = payload.dump();
        }
        std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
        if (!g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire) || g_fanLeaseId != leaseId ||
            generation != currentFanPowerGeneration() || receiptEpoch != g_monitorFanDisplay.epoch() ||
            !fanLeaseKeepaliveMayRun()) return;
        body = std::move(amended);
    } catch (...) {
        // Optional metadata must leave the original heartbeat reachable on failure.
    }
}


static bool fanLeaseKeepalivePostHeartbeat(const std::string& leaseId, std::string* newLeaseId,
                                          DWORD* statusOut, std::string* errorCodeOut) {
    if (newLeaseId) newLeaseId->clear();
    if (statusOut) *statusOut = 0;
    const auto monitorFanEpoch = g_monitorFanDisplay.epoch();
    if (errorCodeOut) errorCodeOut->clear();
    const auto sessionToken = fanHostReadSessionToken();
    if (sessionToken.empty()) {
        fanHostNoteCredentialUnavailable("native-lease-keepalive");
        return false;
    }
    if (!fanHostExactProcessRunningForKeepalive()) {
        fanHostIdentityNoteUnverified("native-lease-keepalive");
        return false;
    }
    // Keep the existing 650ms phase timeout; the three network phases also
    // share one absolute budget. Small body packets cannot keep extending it.
    const auto deadline = GetTickCount64() + 3ULL * 650ULL;
    HINTERNET session = WinHttpOpen(
        L"YeManCC-FanKeepalive/1.0", WINHTTP_ACCESS_TYPE_NO_PROXY,
        WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, WINHTTP_FLAG_ASYNC);
    if (!session) return false;
    setHttpTimeouts(session, 650);
    HINTERNET connect = WinHttpConnect(session, L"127.0.0.1", 8765, 0);
    HINTERNET request = connect
        ? WinHttpOpenRequest(connect, L"POST", L"/api/heartbeat", nullptr,
                             WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
                             WINHTTP_FLAG_BYPASS_PROXY_CACHE)
        : nullptr;
    bool ok = false;
    DWORD status = 0;
    std::string body;
    std::string hostRequestId;
    bool headerAdded = false;
    if (request) {
        // AsyncRequest owns all three handles, including setup-failure cleanup.
        // Retire the outer raw owners before transfer so no path double-closes.
        const auto ownedSession = std::exchange(session, nullptr);
        const auto ownedConnect = std::exchange(connect, nullptr);
        const auto ownedRequest = std::exchange(request, nullptr);
        try {
            ymcc::http::AsyncRequest transport(ownedSession, ownedConnect, ownedRequest, deadline, [] {
                return g_fanLeaseKeepaliveStop.load(std::memory_order_acquire) ||
                    g_exitRequested.load(std::memory_order_acquire);
            });
            const auto headers = std::wstring(L"Content-Type: application/json\r\n") +
                L"X-YeMan-Fan-Session: " + U2W(sessionToken) + L"\r\n";
            json payload = json::object();
            payload["leaseId"] = leaseId;
            fanLeaseKeepaliveAddMsiMode(payload);
            headerAdded = WinHttpAddRequestHeaders(
                ownedRequest, headers.c_str(), (DWORD)-1, WINHTTP_ADDREQ_FLAG_ADD) != FALSE;
            if (headerAdded) {
                transport.send(payload.dump());
                transport.headers();
                DWORD size = sizeof(status);
                WinHttpQueryHeaders(ownedRequest,
                    WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                    WINHTTP_HEADER_NAME_BY_INDEX, &status, &size, WINHTTP_NO_HEADER_INDEX);
                if (statusOut) *statusOut = status;
                hostRequestId = fanHostResponseRequestId(ownedRequest);
                // FanHost declares ContentLength64 on every JSON response.
                // WinHTTP EOF alone can also mean a truncated connection; a
                // parseable prefix must never become a renewal receipt.
                DWORD expectedBodyBytes = 0, lengthSize = sizeof(expectedBodyBytes);
                const bool lengthDeclared = WinHttpQueryHeaders(ownedRequest,
                    WINHTTP_QUERY_CONTENT_LENGTH | WINHTTP_QUERY_FLAG_NUMBER,
                    WINHTTP_HEADER_NAME_BY_INDEX, &expectedBodyBytes, &lengthSize,
                    WINHTTP_NO_HEADER_INDEX) != FALSE;
                body = transport.readAll(64u * 1024u);
                if (!lengthDeclared || body.size() != expectedBodyBytes)
                    throw std::runtime_error("Fan heartbeat response length unconfirmed");
                const auto parsed = body.empty() ? json::object() : json::parse(body);
                if (parsed.contains("error") && parsed["error"].is_object()) {
                    const auto code = parsed["error"].value("code", std::string{});
                    if (errorCodeOut) *errorCodeOut = code;
                }
                // readAll returns only after EOF; partial/timeout/cancelled
                // bodies never reach the display or lease receipt consumers.
                g_monitorFanDisplay.observe(monitorFanEpoch, status, parsed, static_cast<long long>(sgNowEpoch() * 1000.0));
                ok = ymcc::fan_response::accepted("/api/heartbeat", status, parsed, leaseId);
                if (ok && newLeaseId) *newLeaseId = ymcc::fan_response::keepaliveLease("/api/heartbeat", parsed, leaseId);
            }
        } catch (...) {
            ok = false;
            body.clear(); // An unknown transport result is not a renewal receipt.
        }
    }
    if (request) WinHttpCloseHandle(request);
    if (connect) WinHttpCloseHandle(connect);
    if (session) WinHttpCloseHandle(session);
    if (status == 401 || status == 403) {
        // Authentication refusal remains separately recorded, without tokens.
        fanHostNoteAuthRejected("native-lease-keepalive", "POST", "/api/heartbeat", status,
                                sessionToken, true, "native-sidecar", hostRequestId,
                                fanErrorCodeFromBody(body), fanRequestId("fan-heartbeat"), body,
                                headerAdded);
    } else if (!headerAdded) {
        fanHostNoteRequestHeaderFailed("native-lease-keepalive", "POST", "/api/heartbeat", sessionToken);
    }
    return ok;
}

static void fanLeaseKeepaliveTick() {
    if (!g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire)) return;
    if (!fanLeaseKeepaliveMayRun()) return;
    // ②：渲染器重建边界。epoch 变了说明页面 reload/浏览器进程退出——
    // 宽限内继续续租（渲染器停跳期间所有权不丢）；宽限过期且期间无渲染器活动
    // （ObserveHttp 未重武装）⇒ 判定"渲染器真死"，交回边界保留。
    {
        unsigned long long epochSnapshot = 0;
        ULONGLONG graceUntil = 0;
        {
            std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
            epochSnapshot = g_fanKeepaliveRendererEpochSnapshot;
            graceUntil = g_fanKeepaliveRendererGraceUntil;
        }
        const unsigned long long epochNow =
            g_fanKeepaliveRendererEpoch.load(std::memory_order_acquire);
        if (epochNow != epochSnapshot) {
            const ULONGLONG nowEpoch = GetTickCount64();
            if (graceUntil == 0 || nowEpoch >= graceUntil) {
                fanLeaseKeepaliveDisarm("renderer-epoch-grace-expired");
                return;
            }
            static unsigned long long lastGraceLogEpoch = 0;
            if (lastGraceLogEpoch != epochNow) {
                lastGraceLogEpoch = epochNow;
                json detail = {
                    {"epoch", epochNow},
                    {"graceRemainingMs", static_cast<long long>(graceUntil - nowEpoch)},
                    {"source", "native.ready"}
                };
                // 去重：仅 fan-lifecycle.log（说明见 fan-host-identity-unverified 处）。
                appendFanLifecycleLog("native-lease-keepalive-grace-active", detail);
            }
        }
    }
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG last = g_fanLeaseKeepaliveLastRenewTick.load(std::memory_order_acquire);
    if (last != 0 && now - last < 2000ULL) return;
    if (g_fanLeaseKeepaliveInFlight.exchange(true, std::memory_order_acq_rel)) return;
    // This owner must release on copy/transport/log exceptions as well as returns.
    struct FlightReset {
        std::atomic<bool>& flag;
        ~FlightReset() { flag.store(false, std::memory_order_release); }
    } resetInFlight{g_fanLeaseKeepaliveInFlight};
    std::string leaseId;
    {
        std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
        leaseId = g_fanLeaseId;
    }
    if (!isFanLeaseIdValid(leaseId) || !fanLeaseKeepaliveMayRun()) {
        return;
    }
    std::string renewed;
    DWORD status = 0;
    std::string errorCode;
    // 事件化状态（2026-09-17 基础最低化批 2）：成功续约日志只在状态变化时写；
    // 失败时复位 → 恢复时补一条 success（租约问题可追溯）。
    static std::atomic<bool> keepaliveSuccessLogged{false};
    const bool ok = fanLeaseKeepalivePostHeartbeat(leaseId, &renewed, &status, &errorCode);
    if (ok) {
        {
            std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
            if (!ymcc::fan_response::heartbeatStillCurrent(
                g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire), g_fanLeaseId, leaseId)) return;
            if (isFanLeaseIdValid(renewed)) g_fanLeaseId = renewed;
            g_fanLeaseKeepaliveLastRenewTick.store(GetTickCount64(), std::memory_order_release);
        }
        // This private flag is consumed by the single keepalive worker. All
        // renewal state is committed above; skip only redundant log payloads.
        // Keep construction before the emitting exchange so a failed payload
        // cannot consume the next first/recovered success record.
        if (keepaliveSuccessLogged.load(std::memory_order_acquire)) return;
        json detail = {
            {"status", static_cast<int>(status)},
            {"leasePresent", true},
            {"source", "native.ready"}
        };
        // 去重 + 事件化（2026-09-17 基础最低化批 2）：成功续约**仅在状态变化时**
        // 写一条（首次成功 / 失败→成功恢复）；不再周期写心跳成功。心跳本身的
        // 2s 续约节奏不变（功能参数，见上 2000ms 续约节流）。
        if (!keepaliveSuccessLogged.exchange(true, std::memory_order_acq_rel)) {
            appendFanLifecycleLog("native-lease-keepalive-success", detail);
        }
        return;
    }
    // HC_OPERATION_BUSY/409 is an unsubmitted admission, not loss of this lease.
    // Keep only the candidate; the next normal heartbeat must still prove renewal.
    const bool rejected = (status == 409 && errorCode != "HC_OPERATION_BUSY") || status == 401 || status == 403 ||
        errorCode == "LEASE_INVALID" || errorCode == "LEASE_REQUIRED" ||
        errorCode == "POWER_SUSPENDING" || errorCode == "POWER_SUSPENDED" ||
        errorCode == "POWER_RESUMING" || errorCode == "HOST_CLOSING" ||
        errorCode == "HC_SESSION_UNAVAILABLE";
    // 去重：仅 fan-lifecycle.log（说明见 fan-host-identity-unverified 处）。
    // 事件化（2026-09-17 基础最低化批 2）：失败持续时每 10s 最多一条（同类抑制）；
    // 同时复位成功状态 → 恢复时补一条 success。
    keepaliveSuccessLogged.store(false, std::memory_order_release);
    {
        static ULONGLONG lastMissLogTick = 0;
        const ULONGLONG nowMissLogTick = GetTickCount64();
        if (lastMissLogTick == 0 || nowMissLogTick - lastMissLogTick >= 10000ULL) {
            // Build only the record this gate emits; every refusal still settles below.
            json detail = {
                {"status", static_cast<int>(status)},
                {"errorCode", errorCode},
                {"rejected", rejected}
            };
            lastMissLogTick = nowMissLogTick;
            appendFanLifecycleLog("native-lease-keepalive-miss", detail);
        }
    }
    if (rejected) {
        // Check and retire under one lock; a newer lease cannot slip between them.
        fanLeaseKeepaliveDisarm("heartbeat-rejected", &leaseId);
    }
}

static void fanLeaseKeepaliveThreadProc() {
    // R1（2026-09-17 需求单）：tid → 角色映射（一次性）。
    ymccLogThreadRole("fan-lease-keepalive");
    for (;;) {
        if (g_fanLeaseKeepaliveStop.load(std::memory_order_acquire) ||
            g_exitRequested.load(std::memory_order_acquire)) break;
        if (!g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire)) fanKeepaliveProcessSelection().reset();
        HANDLE wake = g_fanLeaseKeepaliveWake;
        // No lease means no timed work. Auto-reset notifications retain an arm
        // that arrives just before the wait, and shutdown still wakes this owner.
        const DWORD waitMs = g_fanLeaseKeepaliveArmed.load(std::memory_order_acquire)
            ? FAN_LEASE_KEEPALIVE_INTERVAL_MS : INFINITE;
        if (wake) WaitForSingleObject(wake, waitMs);
        else Sleep(FAN_LEASE_KEEPALIVE_INTERVAL_MS);
        if (g_fanLeaseKeepaliveStop.load(std::memory_order_acquire) ||
            g_exitRequested.load(std::memory_order_acquire)) break;
        try {
            fanLeaseKeepaliveTick();
        } catch (...) {
        }
    }
    fanKeepaliveProcessSelection().reset();
}

static void fanLeaseKeepaliveEnsureThread() {
    std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
    if (g_fanLeaseKeepaliveStop.load(std::memory_order_acquire) ||
        g_exitRequested.load(std::memory_order_acquire)) return;
    if (!g_fanLeaseKeepaliveWake) {
        g_fanLeaseKeepaliveWake = CreateEventW(nullptr, FALSE, FALSE, nullptr);
    }
    if (g_fanLeaseKeepaliveThread.joinable()) return;
    try {
        g_fanLeaseKeepaliveThread = std::thread(fanLeaseKeepaliveThreadProc);
    } catch (...) {
        appendFanLifecycleLog("native-lease-keepalive-thread-failed", json::object());
    }
}

// ── FAN-927（2026-09-27 用户批准 §3/§5）：Fan 活动记录 ─────────────────────────
// 唯一目的：让 native 能回答两个问题，而不引入任何周期性扫描或额外请求。
//   ① 本 run 是否已有**已确认的活动控制意图**（自动唤醒第一行的 NoWork 判据）；
//   ② 同一系统启动内主程序非正常退出后，崩溃前那份控制意图是否仍然有效（窄例外恢复）。
//
// 写入方只有一个：native 自己。它已经通过 http.request IPC 观察到全部渲染器发起的
// Fan HTTP 流量（fanLeaseKeepaliveObserveHttp），因此不需要新增任何前端写入 IPC。
// 不读取也不依赖 Host 侧 P2 的 YeManFanHost.control-intent.json。
struct FanActivityRecord {
    bool active = false;
    int revision = 0;
    json curve = json::array();
    std::string deviceClass;
    std::string runToken;
    std::string bootTag;
    std::string packageId;
};
static std::mutex g_fanActivityMx;
static FanActivityRecord g_fanActivity;              // guarded by g_fanActivityMx
static std::atomic<bool> g_fanActivityIntentActive{false};
static bool g_fanActivityRecoverable = false;        // 只在启动早期判定一次
static std::string g_fanActivityPackageId;           // 当前包代（按需解析一次）

static std::wstring fanActivityPath() {
    return fan_host_state_dir() + L"\\fan-activity.json";
}

// 系统启动时刻（秒级桶）。同一启动内恒定（nowMs - uptimeMs 不随时间漂移），
// 跨重启必然改变；用于 §5.2 的"同一系统启动"判据，不新增任何计时器。
static std::string fanActivityBootTag() {
    FILETIME ft{};
    GetSystemTimeAsFileTime(&ft);
    const unsigned long long nowMs =
        ((static_cast<unsigned long long>(ft.dwHighDateTime) << 32) | ft.dwLowDateTime) / 10000ULL;
    const unsigned long long uptimeMs = GetTickCount64();
    const unsigned long long bootMs = nowMs > uptimeMs ? (nowMs - uptimeMs) : 0ULL;
    return std::to_string(bootMs / 1000ULL);
}

// 当前包代。只在需要时读一次小清单（启动早期，不在正常开启路径上）。
static std::string fanActivityCurrentPackageId() {
    if (!g_fanActivityPackageId.empty()) return g_fanActivityPackageId;
    try {
        const std::wstring manifest = POWER_CONTROL_DIR + L"\\fan-host-v2\\YeManFanHost.payload.json";
        std::ifstream in(manifest, std::ios::binary);
        if (!in) return std::string{};
        std::ostringstream ss;
        ss << in.rdbuf();
        const auto parsed = json::parse(ss.str(), nullptr, false);
        if (parsed.is_discarded() || !parsed.is_object()) return std::string{};
        g_fanActivityPackageId = parsed.value("runtimeId", std::string{});
    } catch (...) {
    }
    return g_fanActivityPackageId;
}

// 原子落盘：临时文件 + MoveFileEx 替换。失败只留证据，绝不影响风扇/电源主路径。
static void fanActivityPersistLocked() {
    try {
        json record{
            {"schemaVersion", 1},
            {"active", g_fanActivity.active},
            {"revision", g_fanActivity.revision},
            {"curve", g_fanActivity.curve},
            {"deviceClass", g_fanActivity.deviceClass},
            {"runToken", g_fanActivity.runToken},
            {"bootTag", g_fanActivity.bootTag},
            {"packageId", g_fanActivity.packageId},
        };
        const std::wstring target = fanActivityPath();
        const std::wstring temp = target + L".tmp";
        {
            std::ofstream out(temp, std::ios::binary | std::ios::trunc);
            if (!out) return;
            out << record.dump() << '\n';
        }
        if (!MoveFileExW(temp.c_str(), target.c_str(),
                         MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)) {
            DeleteFileW(temp.c_str());
        }
    } catch (...) {
    }
}

static void fanActivityLoadAtBoot() {
    std::string bootTag;
    bool sameBoot = false;
    bool sameRun = false;
    bool packageMatches = false;
    bool storedActive = false;
    bool storedCurvePresent = false;
    bool storedDeviceClassPresent = false;
    {
        std::lock_guard<std::mutex> lock(g_fanActivityMx);
        try {
            std::ifstream in(fanActivityPath(), std::ios::binary);
            if (in) {
                std::ostringstream ss;
                ss << in.rdbuf();
                const auto parsed = json::parse(ss.str(), nullptr, false);
                if (!parsed.is_discarded() && parsed.is_object()) {
                    g_fanActivity.active = parsed.value("active", false);
                    g_fanActivity.revision = parsed.value("revision", 0);
                    if (parsed.contains("curve") && parsed["curve"].is_array()) {
                        g_fanActivity.curve = parsed["curve"];
                    }
                    g_fanActivity.deviceClass = parsed.value("deviceClass", std::string{});
                    g_fanActivity.runToken = parsed.value("runToken", std::string{});
                    g_fanActivity.bootTag = parsed.value("bootTag", std::string{});
                    g_fanActivity.packageId = parsed.value("packageId", std::string{});
                }
            }
        } catch (...) {
        }
        const std::string packageId = fanActivityCurrentPackageId();
        bootTag = fanActivityBootTag();
        storedActive = g_fanActivity.active;
        storedCurvePresent = g_fanActivity.curve.is_array() && !g_fanActivity.curve.empty();
        storedDeviceClassPresent = !g_fanActivity.deviceClass.empty();
        sameBoot = !g_fanActivity.bootTag.empty() && g_fanActivity.bootTag == bootTag;
        sameRun = !g_fanActivity.runToken.empty() && g_fanActivity.runToken == g_fanPriorRunToken;
        packageMatches = g_fanActivity.packageId.empty() || packageId.empty() ||
            g_fanActivity.packageId == packageId;
        // §5.2 窄例外：前 run 非正常结束 + 记录未被撤销 + 同一系统启动 + 同一 run 令牌
        // + 记录里真有曲线 + 包代**与设备类**均可匹配。任何一条不成立都不自动开启。
        // 设备类为空 ⇒ 无法证明是同一台设备 ⇒ 按不自动开（fail-closed，符合"缺失/不同设备不启动"）。
        g_fanActivityRecoverable = storedActive && g_fanPriorRunUnclean && sameBoot &&
            sameRun && storedCurvePresent && packageMatches && storedDeviceClassPresent;
        g_fanActivityIntentActive.store(false, std::memory_order_release);
    }
    appendFanLifecycleLog("fan-activity-boot", {
        {"storedActive", storedActive},
        {"priorRunUnclean", g_fanPriorRunUnclean},
        {"sameBoot", sameBoot},
        {"sameRun", sameRun},
        {"packageMatches", packageMatches},
        {"deviceClassPresent", storedDeviceClassPresent},
        {"recoverable", g_fanActivityRecoverable},
    });
}

// 本 run 是否已有已确认的活动控制意图（含 §5.2 的可恢复记录）。
static bool fanActivityIntentPresent() {
    if (g_fanActivityIntentActive.load(std::memory_order_acquire)) return true;
    return g_fanActivityRecoverable;
}

static json fanActivitySnapshotJson() {
    std::lock_guard<std::mutex> lock(g_fanActivityMx);
    return json{
        {"schemaVersion", 1},
        {"active", g_fanActivityIntentActive.load(std::memory_order_acquire)},
        {"recoverable", g_fanActivityRecoverable},
        {"revision", g_fanActivity.revision},
        {"curve", g_fanActivity.curve},
        {"deviceClass", g_fanActivity.deviceClass},
        {"packageId", g_fanActivity.packageId},
    };
}

static bool fanControlIntentCancellationReceipt(DWORD status, const std::string& responseBody) {
    if (status < 200 || status >= 300) return false;
    const auto receipt = json::parse(responseBody, nullptr, false);
    return receipt.is_object() && receipt.contains("ok") && receipt["ok"].is_boolean() && receipt["ok"].get<bool>() &&
        receipt.contains("controlIntentCancelled") && receipt["controlIntentCancelled"].is_boolean() &&
        receipt["controlIntentCancelled"].get<bool>() && receipt.contains("state") && receipt["state"].is_object();
}
// 观察渲染器发往 Host 的 Fan 流量，维护活动记录。只有**成功**的写入/撤销才改记录。
static void fanActivityObserve(const std::string& path, const std::string& requestBody,
                              DWORD status, const std::string& responseBody,
                              const json* parsedResponse, ULONGLONG receiptEpoch) {
    const bool success = status >= 200 && status < 300;
    const bool enable = path == "/api/enable" || path == "/api/preset";
    const bool revoke = path == "/api/disable" || path == "/api/cancel-control-intent" ||
        path == "/api/release-control" || path == "/api/restore" || path == "/api/close" || path == "/api/shutdown" ||
        path == "/api/parent-exit";
    const bool stateRead = path == "/api/state";
    if (!success || (!enable && !revoke && !stateRead)) return;
    json fallbackResponse;
    if (!parsedResponse) {
        if (responseBody.size() > 64u * 1024u) return;
        fallbackResponse = json::parse(responseBody, nullptr, false);
        parsedResponse = &fallbackResponse;
    }
    if (!ymcc::fan_response::accepted(path, status, *parsedResponse)) return;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_fanActivityMx);
        if (receiptEpoch && receiptEpoch != g_monitorFanDisplay.epoch()) return;
        if (!g_fanActivity.runToken.empty() && g_fanActivity.runToken != g_fanCurrentRunToken) {
            // 记录属于上一个 run：本 run 的第一次观察把它接管为本 run 的记录。
            g_fanActivity.runToken = g_fanCurrentRunToken;
            g_fanActivity.active = false;
            g_fanActivity.curve = json::array();
        }
        if (stateRead) {
            // 只用于 §5.2 的设备匹配：状态快照里的设备类逐次刷新（不落盘、不新增请求）。
            const auto& parsed = *parsedResponse;
            if (parsed.is_object()) {
                const auto* deviceClass = ymcc::fan_activity::deviceClassReferenceFromReply(parsed);
                if (deviceClass && *deviceClass != g_fanActivity.deviceClass) {
                    g_fanActivity.deviceClass = *deviceClass;
                }
            }
            return;
        }
        // §5.2 的设备匹配要求记录里**确有**设备类：enable/disable 等 2xx 响应同样携带它，
        // 因此在写入记录前同批刷新一次（不新增请求），使"不同设备不自动开"真的可判。
        {
            const auto& parsed = *parsedResponse;
            if (parsed.is_object()) {
                const auto* deviceClass = ymcc::fan_activity::deviceClassReferenceFromReply(parsed);
                if (deviceClass) g_fanActivity.deviceClass = *deviceClass;
            }
        }
        if (enable) {
            const auto parsed = json::parse(requestBody, nullptr, false);
            const auto* nodes = ymcc::fan_replay::nodesForCommittedControl(parsed, *parsedResponse);
            // A committed new preset cannot inherit an unrelated older curve.
            g_fanActivity.curve = nodes ? *nodes : json::array();
            g_fanActivity.active = true;
            g_fanActivity.revision += 1;
            g_fanActivityIntentActive.store(true, std::memory_order_release);
            changed = true;
        } else if (revoke) {
            // 用户明确 disable/关闭控制 ⇒ 撤销自动重放资格（§5.2）。
            g_fanActivity.active = false;
            g_fanActivity.revision += 1;
            g_fanActivityIntentActive.store(false, std::memory_order_release);
            changed = true;
        }
        if (changed) {
            g_fanActivity.runToken = g_fanCurrentRunToken;
            g_fanActivity.bootTag = fanActivityBootTag();
            g_fanActivity.packageId = fanActivityCurrentPackageId();
            fanActivityPersistLocked();
        }
    }
    if (changed) {
        appendFanLifecycleLog("fan-activity-update", {
            {"action", enable ? "enable" : "revoke"},
            {"path", path},
            {"active", enable},
        });
    }
}

// 正常退出撤销下次自动开启资格（§5.2）。异常退出走不到这里，记录保持 active，
// 由下一次启动的 fanActivityLoadAtBoot 结合"前 run 非正常结束"判定是否可恢复。
static void fanActivityRevokeOnCleanExit() {
    {
        std::lock_guard<std::mutex> lock(g_fanActivityMx);
        if (!g_fanActivity.active) return;
        g_fanActivity.active = false;
        g_fanActivity.revision += 1;
        g_fanActivity.runToken = g_fanCurrentRunToken;
        g_fanActivity.bootTag = fanActivityBootTag();
        fanActivityPersistLocked();
    }
    appendFanLifecycleLog("fan-activity-revoked", {{"reason", "clean-exit"}});
}

static void fanLeaseKeepaliveObserveHttp(const std::string& method,
                                         const wchar_t* host,
                                         unsigned short port,
                                         const std::wstring& objectPath,
                                         const std::string& requestBody,
                                         DWORD status,
                                         const std::string& responseBody,
                                         bool sessionHeaderPresent,
                                         const std::string& sessionHeaderValue,
                                         const std::string& hostRequestId,
                                         const json* parsedResponse,
                                         ULONGLONG receiptEpoch) {
    if (port != 8765 || !host || !isLoopbackHost(host)) return;
    const std::string path = fanApiPathFromObject(objectPath);
    // FAN-927 §3/§5：Fan 活动记录仍在已有观察入口维护。先保留认证拒绝证据。
    // 批138（FAN925B §5.1 / F06）：**认证拒绝证据在任何早退之前**落账（限频 + 脱敏）。
    // 本入口覆盖渲染器经 native `ipc http.request` 的**生产路径**（GET/POST 都算）。
    if (status == 401 || status == 403) {
        fanHostNoteAuthRejected("renderer-http", method, path, status,
                                sessionHeaderPresent ? sessionHeaderValue : std::string(),
                                sessionHeaderPresent, "renderer-header", hostRequestId,
                                fanErrorCodeFromBody(responseBody), fanRequestId("fan-renderer"),
                                responseBody, sessionHeaderPresent);
    }
    // This is the epoch captured before the existing HTTP send. An older
    // enable/heartbeat reply cannot recreate intent after a newer OFF/sleep.
    if (receiptEpoch && receiptEpoch != g_monitorFanDisplay.epoch()) return;
    if (sessionHeaderPresent) fanActivityObserve(path, requestBody, status, responseBody, parsedResponse, receiptEpoch);
    if (ascii_lower(method) != "post") return;
    const bool lifecycleStop = path == "/api/close" || path == "/api/suspend" ||
        path == "/api/shutdown" || path == "/api/parent-exit";
    const bool controlStop = path == "/api/disable" || path == "/api/cancel-control-intent" ||
        path == "/api/release-control" || path == "/api/restore";
    if (lifecycleStop) {
        fanLeaseKeepaliveDisarm(path.c_str());
        return;
    }
    if (status < 200 || status >= 300 || !sessionHeaderPresent) return;
    if (!controlStop && path != "/api/heartbeat" && path != "/api/acquire-control" &&
        path != "/api/enable" && path != "/api/preset") return;
    json fallbackResponse;
    if (!parsedResponse) {
        if (responseBody.size() > 64u * 1024u) return;
        fallbackResponse = json::parse(responseBody, nullptr, false);
        parsedResponse = &fallbackResponse;
    }
    const auto requestLease = (path == "/api/heartbeat" || path == "/api/enable" || path == "/api/preset")
        ? parseFanLeaseIdText(requestBody) : std::string{};
    if (!ymcc::fan_response::accepted(path, status, *parsedResponse, requestLease)) return;
    if (controlStop) {
        fanLeaseKeepaliveDisarm(path.c_str());
        return;
    }
    const auto* leaseId = ymcc::fan_response::keepaliveLeaseReference(path, *parsedResponse, requestLease);
    // Never invent a renewal receipt from the request when the reply omitted it.
    if (leaseId && isFanLeaseIdValid(*leaseId)) fanLeaseKeepaliveArm(*leaseId, path.c_str(), receiptEpoch);
}

static void fanLeaseKeepaliveShutdown() {
    g_fanLeaseKeepaliveStop.store(true, std::memory_order_release);
    fanLeaseKeepaliveDisarm("app-exit");
    // FAN-927 §5.2：正常退出撤销"下次自动开启"资格；异常退出不会走到这里。
    fanActivityRevokeOnCleanExit();
    if (g_fanLeaseKeepaliveWake) SetEvent(g_fanLeaseKeepaliveWake);
    joinThreadBoundedForExit(g_fanLeaseKeepaliveThread, 1000, "fan-lease-keepalive");
    {
        // Arm/disarm notify under the same mutex: they must not signal a
        // handle concurrently being closed during normal shutdown.
        std::lock_guard<std::mutex> lock(g_fanLeaseKeepaliveMx);
        if (g_fanLeaseKeepaliveWake) {
            CloseHandle(g_fanLeaseKeepaliveWake);
            g_fanLeaseKeepaliveWake = nullptr;
        }
    }
}

// ── 批140（FAN925B §3.1/§3.2/§3.3）：**原生侧唯一权威的"释放 / 清理 / 物理"三态判定** ──
// 裁决原文要求：`IsOemReleaseSafe`、native 安全判据/退出收据等所有出口**消费同一份定义**，
// 不能各自添加 `hcCloseComplete` 捷径；`hcCloseComplete` 只证明其真实涵盖的 HC 清理条件，
// **单独不足以证明曾写入的曲线已执行释放动作**；有写历史而未有释放动作证据 ⇒ 保留未结算责任。
// 本函数是该定义的**生产唯一实现**（纯函数；自测逐条断言 F01 形状与正例）。
// Native Fan power requests share the existing bounded WinHTTP transport.
// An incomplete response is never a lifecycle/lease receipt; an unknown POST
// submission is observed read-only instead of being blindly repeated.
struct FanBoundaryHttpReply {
    DWORD status = 0;
    std::string body;
    std::string requestId;
    bool headerAdded = false;
    bool submitted = false;
    bool complete = false;
};

static FanBoundaryHttpReply fanHostBoundaryHttpRequest(
    const wchar_t* method, const wchar_t* endpoint,
    const std::string& payload, const std::string& sessionToken) {
    FanBoundaryHttpReply reply;
    const auto deadline = GetTickCount64() + 3ULL * 650ULL;
    HINTERNET session = WinHttpOpen(
        L"YeManCC-FanSleep/1.0", WINHTTP_ACCESS_TYPE_NO_PROXY,
        WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, WINHTTP_FLAG_ASYNC);
    if (!session) return reply;
    setHttpTimeouts(session, 650);
    HINTERNET connect = WinHttpConnect(session, L"127.0.0.1", 8765, 0);
    HINTERNET request = connect
        ? WinHttpOpenRequest(connect, method, endpoint, nullptr,
                             WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
                             WINHTTP_FLAG_BYPASS_PROXY_CACHE)
        : nullptr;
    if (request) {
        const auto ownedSession = std::exchange(session, nullptr);
        const auto ownedConnect = std::exchange(connect, nullptr);
        const auto ownedRequest = std::exchange(request, nullptr);
        try {
            // Sleep/exit handoff must still be sent while the UI is exiting.
            // Its existing absolute budget, rather than g_exitRequested, owns it.
            ymcc::http::AsyncRequest transport(ownedSession, ownedConnect, ownedRequest, deadline, {});
            const auto headers = std::wstring(L"Content-Type: application/json\r\n") +
                L"X-YeMan-Fan-Session: " + U2W(sessionToken) + L"\r\n";
            reply.headerAdded = WinHttpAddRequestHeaders(ownedRequest, headers.c_str(),
                static_cast<DWORD>(-1), WINHTTP_ADDREQ_FLAG_ADD) != FALSE;
            if (reply.headerAdded) {
                reply.submitted = true; // Send failure can still have reached the Host.
                transport.send(payload);
                transport.headers();
                DWORD statusBytes = sizeof(reply.status);
                if (!WinHttpQueryHeaders(ownedRequest,
                    WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                    WINHTTP_HEADER_NAME_BY_INDEX, &reply.status, &statusBytes,
                    WINHTTP_NO_HEADER_INDEX)) throw std::runtime_error("Fan boundary status unavailable");
                reply.requestId = fanHostResponseRequestId(ownedRequest);
                DWORD headerBytes = 0;
                WinHttpQueryHeaders(ownedRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF,
                    WINHTTP_HEADER_NAME_BY_INDEX, nullptr, &headerBytes, WINHTTP_NO_HEADER_INDEX);
                if (headerBytes == 0 || headerBytes > 64u * 1024u)
                    throw std::runtime_error("Fan boundary headers unavailable");
                std::wstring rawHeaders(headerBytes / sizeof(wchar_t) + 1, L'\0');
                if (!WinHttpQueryHeaders(ownedRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF,
                    WINHTTP_HEADER_NAME_BY_INDEX, rawHeaders.data(), &headerBytes,
                    WINHTTP_NO_HEADER_INDEX)) throw std::runtime_error("Fan boundary headers unavailable");
                rawHeaders.resize(headerBytes / sizeof(wchar_t));
                reply.body = transport.readAll(256u * 1024u);
                if (!ymcc::fan_http::responseBodyComplete(W2U(method), reply.status,
                    W2U(rawHeaders), reply.body.size()))
                    throw std::runtime_error("Fan boundary response incomplete");
                reply.complete = true;
            }
        } catch (...) {
            reply.body.clear(); // Never expose a parseable prefix to a classifier.
        }
    }
    if (request) WinHttpCloseHandle(request);
    if (connect) WinHttpCloseHandle(connect);
    if (session) WinHttpCloseHandle(session);
    return reply;
}

struct FanBoundaryEvidence {
    bool telemetryComplete = false;      // 状态对象字段齐全（缺位不得当成功）
    bool expectedTerminalState = false;   // Stopped（或 suspend 边界下的 Suspended）
    bool hcCloseEvidenceAcceptable = true; // 无 scope 的兼容路由或收据自洽
    bool hcCloseEvidenceComplete = false;  // virtualClose + managerStop 两件齐
    bool hcCleanupTerminal = false;        // HC 终态边界（**清理阶段**，不是释放证据）
    bool writesHistory = false;            // hardwareWritesObserved（本周期有过写）
    bool releaseReceipt = false;           // oemRestoreConfirmed（**释放动作的软件合同收据**）
    bool liveWrites = false;               // 当前仍在写
    bool sessionOpen = false;              // open/openEvents 仍持有
    bool unknownState = false;
    bool cleanupPending = false;
    // 物理所有权证据：native **从不持有**（§3.1"物理 owner unknown 不新增为强制门"，
    // 也不得把软件动作合同解读成物理所有权）——固定 false，只为分列可读。
    bool physicalOwnerKnown = false;
    // 释放动作证据：无写历史（诚实对照：本周期不适用释放）**或**释放动作收据。
    // 关键收紧（b140）：HC Close 返回 / DeviceManager Stop 只算清理阶段 ⇒ 不再顶替释放。
    bool releaseEvidence = false;
    // 批141（FAN925B 补充②）：Host 导出的**释放动作分类**（recoveryClaimEvidence.
    // oemReleaseActionKind / oemReleaseActionClass）。native **直接消费**——与 Host
    // FanHostEngine.IsOemReleaseSafe 同名同义，绝不自行用 HC Close / DeviceManager Stop
    // 组"清理即释放"的捷径。旧宿主（无该节）⇒ present=false，回落软件动作合同收据。
    bool hostReleaseActionPresent = false;
    std::string hostReleaseActionKind = "absent";
    std::string hostReleaseActionClass = "absent";
    bool hostReleaseActionProven = false;
};

// 释放动作分类（纯函数，与 Host ParseReleaseAction / IsOemReleaseSafe **同名同义**）：
//   proven-by-scope-receipts / proven-by-host-hc-acpi-fallback ⇒ 有有效传输收据；
//   compat-route-without-scope ⇒ 该已评审路由确实无 scope 能力（保留其原路线合同）；
//   not-applicable-no-write-history 由"无写历史"天然覆盖；unknown / failed ⇒ 未证。
static bool fanReleaseActionKindProven(const std::string& kind) {
    return kind == "proven-by-scope-receipts" ||
        kind == "proven-by-host-hc-acpi-fallback" ||
        kind == "compat-route-without-scope";
}

static FanBoundaryEvidence fanBoundaryEvidenceFromState(const json& state, bool suspendBoundary) {
    FanBoundaryEvidence evidence;
    const auto stateName = state.value("state", std::string{});
    const bool hasCanonicalLiveWrites = state.contains("hardwareWritesEnabled");
    const bool hasLegacyLiveWrites = state.contains("hardwareWrites");
    const bool hasHcVirtualCloseEvidence = state.contains("hcVirtualCloseReturned");
    const bool hasHcDeviceManagerStopEvidence = state.contains("hcDeviceManagerStopCompleted");
    const bool hasAnyHcCloseEvidence = hasHcVirtualCloseEvidence || hasHcDeviceManagerStopEvidence;
    evidence.hcCloseEvidenceComplete = hasHcVirtualCloseEvidence && hasHcDeviceManagerStopEvidence;
    evidence.telemetryComplete =
        state.contains("state") &&
        (hasCanonicalLiveWrites || hasLegacyLiveWrites) &&
        state.contains("hardwareWritesObserved") &&
        state.contains("oemRestoreConfirmed") &&
        state.contains("unknownState") &&
        state.contains("hcCloseCleanupPending") &&
        state.contains("openCalled") &&
        state.contains("openEventsCalled");
    evidence.liveWrites = hasCanonicalLiveWrites
        ? state.value("hardwareWritesEnabled", false)
        : state.value("hardwareWrites", false);
    evidence.writesHistory = state.value("hardwareWritesObserved", false);
    evidence.releaseReceipt = state.value("oemRestoreConfirmed", false);
    evidence.unknownState = state.value("unknownState", false);
    evidence.cleanupPending = state.value("hcCloseCleanupPending", false);
    evidence.sessionOpen = state.value("openCalled", false) ||
        state.value("openEventsCalled", false);
    const bool virtualCloseReturned = state.value("hcVirtualCloseReturned", false);
    const bool deviceManagerStopCompleted = state.value("hcDeviceManagerStopCompleted", false);
    evidence.hcCleanupTerminal = suspendBoundary
        ? (stateName == "Suspended" && virtualCloseReturned)
        : (stateName == "Stopped" && virtualCloseReturned && deviceManagerStopCompleted);
    evidence.expectedTerminalState = suspendBoundary
        ? stateName == "Suspended"
        : stateName == "Stopped";
    evidence.hcCloseEvidenceAcceptable = !hasAnyHcCloseEvidence ||
        (virtualCloseReturned && (suspendBoundary || deviceManagerStopCompleted));
    // 批141（FAN925B 补充②）：Host 的释放动作分类是**唯一释放权威**（同名同义消费）。
    const auto claimIt = state.find("recoveryClaimEvidence");
    const bool claimIsObject = claimIt != state.end() && claimIt->is_object();
    auto claimString = [&claimIsObject, &claimIt](const char* key) -> std::string {
        if (!claimIsObject) return "absent";
        const auto it = claimIt->find(key);
        if (it == claimIt->end() || !it->is_string()) return "absent";
        return it->get<std::string>();
    };
    evidence.hostReleaseActionPresent = claimString("oemReleaseActionKind") != "absent";
    if (evidence.hostReleaseActionPresent) {
        evidence.hostReleaseActionKind = claimString("oemReleaseActionKind");
        evidence.hostReleaseActionClass = claimString("oemReleaseActionClass");
    }
    evidence.hostReleaseActionProven = fanReleaseActionKindProven(evidence.hostReleaseActionKind);
    // 唯一释放判据：无写历史 ⇒ 不适用（诚实对照）；有写历史 ⇒ 必须证明"释放动作"本身。
    // 新宿主 ⇒ 直接消费 Host 导出的释放动作分类；旧宿主 ⇒ 回落既有软件动作合同收据
    // （oemRestoreConfirmed，仍是 fail-closed，**绝不**回落到"清理完成"）。
    evidence.releaseEvidence = !evidence.writesHistory ||
        (evidence.hostReleaseActionPresent ? evidence.hostReleaseActionProven
                                           : evidence.releaseReceipt);
    return evidence;
}

static bool fanBoundaryIsSafe(const FanBoundaryEvidence& evidence) {
    if (!evidence.telemetryComplete || !evidence.expectedTerminalState) return false;
    if (!evidence.hcCloseEvidenceAcceptable) return false;
    if (evidence.unknownState || evidence.cleanupPending) return false;
    if (evidence.liveWrites || evidence.sessionOpen) return false;
    // 释放动作证据：缺位 ⇒ 不判安全（cleanup / Close 返回 / 物理未知都不能补）
    if (!evidence.releaseEvidence) return false;
    return true;
}

static json fanBoundaryEvidenceDetail(const FanBoundaryEvidence& evidence) {
    return json{
        {"telemetryComplete", evidence.telemetryComplete},
        {"expectedTerminalState", evidence.expectedTerminalState},
        {"hcCloseEvidenceAcceptable", evidence.hcCloseEvidenceAcceptable},
        {"hcCloseEvidenceComplete", evidence.hcCloseEvidenceComplete},
        {"hcCleanupTerminal", evidence.hcCleanupTerminal},
        {"writesHistory", evidence.writesHistory},
        {"releaseReceipt", evidence.releaseReceipt},
        {"hostReleaseActionPresent", evidence.hostReleaseActionPresent},
        {"hostReleaseActionKind", evidence.hostReleaseActionKind},
        {"hostReleaseActionClass", evidence.hostReleaseActionClass},
        {"hostReleaseActionProven", evidence.hostReleaseActionProven},
        {"releaseEvidence", evidence.releaseEvidence},
        {"liveWrites", evidence.liveWrites},
        {"sessionOpen", evidence.sessionOpen},
        {"unknownState", evidence.unknownState},
        {"cleanupPending", evidence.cleanupPending},
        {"physicalOwnerKnown", evidence.physicalOwnerKnown}};
}

static bool fanHostEmergencyPost(const wchar_t* endpoint, const char* reason,
                                 int maxAttempts = 2,
                                 bool requireSafeState = true,
                                 DWORD* lastResponseStatus = nullptr,
                                 unsigned long long generation = 0,
                                 const char* source = nullptr,
                                 std::string* responseBodyOut = nullptr,
                                 std::string* hostRequestIdOut = nullptr,
                                 bool* headerAddedOut = nullptr,
                                 bool* resultUnknownOut = nullptr) {
    maxAttempts = (std::max)(1, maxAttempts);
    if (lastResponseStatus) *lastResponseStatus = 0;
    if (responseBodyOut) responseBodyOut->clear();
    if (resultUnknownOut) *resultUnknownOut = false;
#ifdef YMCC_FAULT_INJECT
    // 仅注入构建：退出交接自测期按故障文件改写该端点的结果（生产编译期剔除）。
    {
        DWORD forcedStatus = 0;
        std::string forcedBody;
        if (fiExitHandoffForcedPost(endpoint, &forcedStatus, &forcedBody)) {
            if (lastResponseStatus) *lastResponseStatus = forcedStatus;
            if (responseBodyOut) *responseBodyOut = forcedBody;
            if (hostRequestIdOut) hostRequestIdOut->clear();
            if (headerAddedOut) *headerAddedOut = true;   // 注入不模拟"加头失败"
            return forcedStatus >= 200 && forcedStatus < 300;
        }
    }
    // 仅注入构建：resume 恢复夹具（2026-09-23 裁决 B / P-2）。同样只改写输入，
    // 让生产判据自行裁决；响应体在需要时交由调用方解析。
    {
        DWORD forcedStatus = 0;
        std::string forcedBody;
        if (fiResumeForcedPost(endpoint, &forcedStatus, &forcedBody)) {
            if (lastResponseStatus) *lastResponseStatus = forcedStatus;
            if (responseBodyOut) *responseBodyOut = forcedBody;
            return forcedStatus >= 200 && forcedStatus < 300;
        }
    }
#endif
    const auto sessionToken = fanHostReadSessionToken();
    if (sessionToken.empty()) {
        traceLog("fan Host boundary skipped endpoint=%ls reason=%s missing-session-token",
                 endpoint, reason ? reason : "unknown");
        fanHostNoteCredentialUnavailable(reason ? reason : "emergency-post");   // 批138：不得静默
        return false;
    }
    for (int attempt = 0; attempt < maxAttempts; ++attempt) {
        // Never send the session token merely because something happens to
        // listen on 8765. The executable identity is checked for every retry.
        if (!fanHostExactProcessRunning()) {
            fanHostIdentityNoteUnverified(reason ? reason : "emergency-post");
            return false;
        }
        json requestBody = json::object();
        if (generation > 0) {
            requestBody["generation"] = generation;
            requestBody["source"] = source && *source ? source : "native.power";
            requestBody["reason"] = reason && *reason ? reason : "unknown";
        }
        const auto reply = fanHostBoundaryHttpRequest(L"POST", endpoint, requestBody.dump(), sessionToken);
        const DWORD status = reply.status;
        const auto& body = reply.body;
        const auto& hostRequestId = reply.requestId;
        if (lastResponseStatus) *lastResponseStatus = status;
        if (responseBodyOut) *responseBodyOut = body;
        if (hostRequestIdOut) *hostRequestIdOut = hostRequestId;
        if (headerAddedOut) *headerAddedOut = reply.headerAdded;
        const bool resultUnknown = reply.submitted && !reply.complete;
        if (resultUnknownOut) *resultUnknownOut = resultUnknown;
        if (status == 401 || status == 403) {
            fanHostNoteAuthRejected(reason ? reason : "emergency-post", "POST",
                W2U(endpoint), status, sessionToken, true, "native-sidecar",
                hostRequestId, fanErrorCodeFromBody(body), fanRequestId("fan-post"), body, reply.headerAdded);
        } else if (!reply.headerAdded) {
            fanHostNoteRequestHeaderFailed(reason ? reason : "emergency-post", "POST", W2U(endpoint), sessionToken);
        }
        bool safe = false;
        if (reply.complete && status >= 200 && status < 300) {
            if (!requireSafeState) safe = true;
            else if (!body.empty()) {
                try {
                    const auto response = json::parse(body);
                    const auto state = response.value("state", json::object());
                    const bool suspendBoundary = _wcsicmp(endpoint, L"/api/suspend") == 0;
                    const auto boundary = fanBoundaryEvidenceFromState(state, suspendBoundary);
                    safe = fanBoundaryIsSafe(boundary);
                    if (!safe) {
                        json detail = fanBoundaryEvidenceDetail(boundary);
                        detail["endpoint"] = W2U(endpoint);
                        detail["reason"] = reason ? reason : "unknown";
                        detail["status"] = static_cast<unsigned long>(status);
                        detail["attempt"] = attempt + 1;
                        detail["policy"] = "cleanup-must-not-substitute-release;no-physical-claim";
                        detail["exitSessionId"] = g_exitSessionId;
                        appendFanLifecycleLog("fan-boundary-unproven", detail);
                    }
                } catch (...) { }
            }
        }
        // The Host may already own this transaction. Preserve 401/403 status,
        // but never retry a submitted request whose response was incomplete.
        if (resultUnknown || status == 401 || status == 403) return false;
        if (safe) {
            traceLog("fan Host sleep boundary endpoint=%ls reason=%s attempt=%d status=%lu safe=1",
                     endpoint, reason ? reason : "unknown", attempt + 1,
                     static_cast<unsigned long>(status));
            return true;
        }
        if (attempt + 1 < maxAttempts) Sleep(40);
    }
    traceLog("fan Host sleep boundary endpoint=%ls reason=%s safe=0",
             endpoint, reason ? reason : "unknown");
    return false;
}

// ── Q1（FAN-204 s31 补充裁决 2026-09-23）：状态读取（GET /api/state）──
// 观察阶段**只读**状态：与 POST 同一条身份/令牌/超时路径（不新增第二条生命周期 owner，
// 也不重发任何控制/生命周期请求）。返回 false = 传输/状态码不可证明（按"宿主不可达"记账）。
static bool fanHostEmergencyGetState(std::string* bodyOut,
                                     DWORD* lastResponseStatus = nullptr) {
    if (lastResponseStatus) *lastResponseStatus = 0;
    if (bodyOut) bodyOut->clear();
#ifdef YMCC_FAULT_INJECT
    // 仅注入构建：resume 观察夹具按故障文件给出状态序列（生产编译期剔除）。
    {
        DWORD forcedStatus = 0;
        std::string forcedBody;
        if (fiResumeForcedStateProbe(&forcedStatus, &forcedBody)) {
            if (lastResponseStatus) *lastResponseStatus = forcedStatus;
            if (bodyOut) *bodyOut = forcedBody;
            return forcedStatus >= 200 && forcedStatus < 300 && !forcedBody.empty();
        }
    }
#endif
    const auto sessionToken = fanHostReadSessionToken();
    if (sessionToken.empty()) {
        fanHostNoteCredentialUnavailable("resume-observe");   // 批138：不得静默
        return false;
    }
    if (!fanHostExactProcessRunning()) {
        fanHostIdentityNoteUnverified("resume-observe");
        return false;
    }
    const auto reply = fanHostBoundaryHttpRequest(L"GET", L"/api/state", {}, sessionToken);
    if (lastResponseStatus) *lastResponseStatus = reply.status;
    if (bodyOut) *bodyOut = reply.body;
    if (reply.status == 401 || reply.status == 403) {
        fanHostNoteAuthRejected("resume-observe", "GET", "/api/state", reply.status,
            sessionToken, true, "native-sidecar", reply.requestId,
            fanErrorCodeFromBody(reply.body), fanRequestId("fan-observe"), reply.body, reply.headerAdded);
    } else if (!reply.headerAdded) {
        fanHostNoteRequestHeaderFailed("resume-observe", "GET", "/api/state", sessionToken);
    }
    return reply.complete && reply.status >= 200 && reply.status < 300 && !reply.body.empty();
}

static bool fanHostEmergencySuspend(const char* reason,
                                    unsigned long long generation) {
    DWORD suspendStatus = 0;
    bool resultUnknown = false;
    if (fanHostEmergencyPost(L"/api/suspend", reason, 2, true, &suspendStatus,
                             generation, "native.power", nullptr, nullptr, nullptr, &resultUnknown)) return true;
    // Only an explicit legacy 404/405 proves that the Host has no suspend
    // route. A timeout/409/5xx is ambiguous: the first request may still be
    // inside the serialized HC gate. Sending /api/close in that case creates
    // the same concurrent lifecycle race that previously caused false OEM
    // acknowledgements. Keep the single native-tagged suspend transaction
    // serialized in the resident Host; do not create another close owner.
    if (resultUnknown || (suspendStatus != 404 && suspendStatus != 405)) {
        traceLog("fan Host suspend not confirmed status=%lu; no concurrent close fallback",
                 static_cast<unsigned long>(suspendStatus));
        return false;
    }
    // Legacy Hosts without /api/suspend still get the original close safety
    // boundary, but only after the route absence is explicit.
    return fanHostEmergencyPost(L"/api/close", reason, 1);
}

/**
 * Main-process exit must never wait indefinitely for firmware. First ask the
 * verified resident Host to block new writes and take recovery ownership.
 * Its parent watchdog remains a second independent trigger after YeManCC
 * exits. A successful close is still preferred, but is not a prerequisite for
 * terminating the UI process.
 */
// 退出交接三态（2026-09-18 裁决书第 1 条，枚举见文件前部前置声明）。
static const char* fanExitHandoffName(FanExitHandoffResult result) {
    switch (result) {
        case FanExitHandoffResult::AiMockCloseConfirmed: return "ai-mock-close-confirmed-not-physical";
        case FanExitHandoffResult::RestoreConfirmed: return "restore-confirmed";
        case FanExitHandoffResult::RecoveryHandedOff: return "recovery-handed-off";
        default: return "recovery-unverified";
    }
}

// 有界等待（裁决书第 4 条）：只在"进程已确认且镜像匹配、但 8765 端口暂未就绪"
// 时给一个短窗口；绝不在 parent-exit 在飞时并发发送 /api/close。
static FanHostIdentityProbe fanHostProbeWithBoundedPortWait(bool* waitedOut, unsigned long long* waitedMsOut) {
    constexpr int kMaxSteps = 6;          // 250ms × 6 = 1.5s 上限
    constexpr DWORD kStepMs = 250;
    auto probe = fanHostIdentityProbe();
    bool waited = false;
    unsigned long long waitedMs = 0;
    if (probe.processFound && probe.imageMatched && !probe.portFound) {
        for (int step = 0; step < kMaxSteps && !probe.portFound; ++step) {
            Sleep(kStepMs);
            waitedMs += kStepMs;
            waited = true;
            probe = fanHostIdentityProbe();
        }
    }
    if (waitedOut) *waitedOut = waited;
    if (waitedMsOut) *waitedMsOut = waitedMs;
    return probe;
}

// ── 批141（FAN925B §5.1 / CP-03）：交接接受的**绑定**判定（纯函数，可逐条断言）──
// 2xx 本身**不是**"交接被接受"：必须由**处理该请求的 Host 实例**在**这一次**响应里绑定
// "接受实例 + 已接受恢复周期"。预先 GET /api/state 成功不能防止之后 owner 变化，
// 更不能单独等于交接接受；旧宿主（无绑定字段）⇒ unbound（诚实不确定、fail-closed）。
struct FanHandoffBinding {
    bool httpOk = false;             // 传输层 2xx
    bool ackOk = false;              // 响应体 ok==true && recoveryAccepted==true
    bool accepted = false;           // 唯一"交接被接受"判据：ackOk + 实例 + 周期
    bool unbound = false;            // ackOk 但缺实例/周期（旧宿主形态）
    std::string hostInstanceId = "absent";
    std::string recoveryCycleId = "absent";
    std::string acceptanceScope = "absent";
    bool queuedNow = false;
    bool hostWillRemainResident = false;
};

static FanHandoffBinding fanHandoffBindingFromReceipt(const std::string& body, bool httpOk) {
    FanHandoffBinding binding;
    binding.httpOk = httpOk;
    json receipt = json::object();
    if (!body.empty()) {
        const auto parsed = json::parse(body, nullptr, false);
        if (!parsed.is_discarded() && parsed.is_object()) receipt = parsed;
    }
    auto receiptString = [&receipt](const char* key) -> std::string {
        const auto it = receipt.find(key);
        if (it == receipt.end() || !it->is_string()) return "absent";
        return it->get<std::string>();
    };
    auto receiptBool = [&receipt](const char* key) -> bool {
        const auto it = receipt.find(key);
        return it != receipt.end() && it->is_boolean() && it->get<bool>();
    };
    binding.ackOk = httpOk && receiptBool("ok") && receiptBool("recoveryAccepted");
    binding.hostInstanceId = receiptString("acceptingHostInstanceId");
    binding.recoveryCycleId = receiptString("acceptedRecoveryCycleId");
    binding.acceptanceScope = receiptString("acceptanceScope");
    binding.queuedNow = receiptBool("queuedNow");
    binding.hostWillRemainResident = receiptBool("hostWillRemainResident");
    const bool instanceBound = binding.hostInstanceId != "absent" && !binding.hostInstanceId.empty();
    const bool cycleBound = binding.recoveryCycleId != "absent" && !binding.recoveryCycleId.empty();
    binding.accepted = binding.ackOk && instanceBound && cycleBound;
    binding.unbound = binding.ackOk && !binding.accepted;
    return binding;
}

static FanExitHandoffResult fanHostCleanupForAppExit() {
    if (g_aiFanMockSession.enabled) {
        const DWORD pid = g_aiFanMockHost.livePid();
        if (!pid) return FanExitHandoffResult::RecoveryUnverified;
        const auto creation = g_aiFanMockHost.creationTime();
        DWORD status = 0; std::string body;
        const bool httpOk = fanHostEmergencyPost(L"/api/close", "ai-mock-app-exit", 1, false, &status, 0, nullptr, &body);
        const auto response = json::parse(body, nullptr, false);
        bool confirmed = httpOk && ymcc::ai_fan::mockCloseReceiptAllowed(response);
        confirmed = confirmed && g_aiFanMockHost.owns(pid) && g_aiFanMockHost.creationTime() == creation;
        appendFanLifecycleLog("fan-ai-mock-exit-close", json{{"confirmed", confirmed}, {"status", status}, {"pid", pid},
            {"creationTime100ns", std::to_string(creation)}, {"physicalEvidence", false}, {"exitSessionId", g_exitSessionId}});
        if (!confirmed) return FanExitHandoffResult::RecoveryUnverified;
        DWORD shutdownStatus = 0;
        (void)fanHostEmergencyPost(L"/api/shutdown", "ai-mock-app-exit", 1, false, &shutdownStatus);
        return FanExitHandoffResult::AiMockCloseConfirmed;
    }

    bool waited = false;
    unsigned long long waitedMs = 0;
    const auto probe = fanHostProbeWithBoundedPortWait(&waited, &waitedMs);
    // 批138（FAN925B §5.1 / §2(6)(7)）：退出侧的每一条 fan 行都带**本次退出唯一 ID** 与
    // **三要素分列**（进程 / 凭据版本 / HC 会话）。此前只能靠时间戳近似对齐，于是
    // "无 Host / 已交接 / 认证被拒 / 交接被拒"无法逐次结算。
    const json exitIdentitySplit = fanHostInstanceSplit(probe.matchedPid, fanHostReadSessionToken());
    auto mergeExitIdentity = [&exitIdentitySplit](json detail) {
        for (auto& [key, value] : exitIdentitySplit.items()) detail[key] = value;
        detail["exitSessionId"] = g_exitSessionId;
        return detail;
    };
    // 门明细（三条件 + 候选进程 + 8765 监听行）——无论成败都留痕（事件级）。
    appendFanLifecycleLog("fan-exit-identity",
                          mergeExitIdentity(fanHostIdentityDetail(probe, waited, waitedMs)));
    if (!(probe.processFound && probe.imageMatched && probe.portFound)) {
        traceLog("fan Host app-exit cleanup: no verified resident Host (gates process=%d image=%d port=%d waitedMs=%llu)",
                 probe.processFound ? 1 : 0, probe.imageMatched ? 1 : 0, probe.portFound ? 1 : 0, waitedMs);
        appendFanLifecycleLog("fan-exit-recovery-unverified",
                              mergeExitIdentity(json{
                                  {"reason", "no-verified-resident-host"},
                                  {"gates", json{{"process", probe.processFound},
                                                 {"image", probe.imageMatched},
                                                 {"port", probe.portFound}}},
                                  {"waitedMs", waitedMs}}));
        return FanExitHandoffResult::RecoveryUnverified;
    }
    DWORD handoffStatus = 0;
    std::string handoffBody;
    std::string handoffRequestId;
    bool handoffHeaderAdded = false;
    bool handoffResultUnknown = false;
    const bool handoffHttpOk = fanHostEmergencyPost(
        L"/api/parent-exit", "app-exit", 1, false, &handoffStatus, 0, nullptr, &handoffBody,
        &handoffRequestId, &handoffHeaderAdded, &handoffResultUnknown);
    // §5.1（批141 / CP-03）：交接被接受的证据必须绑定"处理该请求的 Host 实例"与"已接受的
    // 恢复周期"，且只能来自**这一次**响应。2xx 本身不是接受；旧宿主（无绑定字段）⇒ unbound
    // （诚实不确定、fail-closed）——绝不用本机 pid / 凭据版本冒充"接收实例"。
    const auto handoff = fanHandoffBindingFromReceipt(handoffBody, handoffHttpOk);
    json parentExitDetail = mergeExitIdentity(json{
        {"attempted", true},
        {"httpOk", handoff.httpOk},
        {"accepted", handoff.accepted},
        {"unbound", handoff.unbound},
        {"status", static_cast<unsigned long>(handoffStatus)},
        {"headerAdded", handoffHeaderAdded},
        {"bodyBytes", static_cast<unsigned long long>(handoffBody.size())}});
    parentExitDetail["hostRequestId"] = handoffRequestId.empty()
        ? std::string("absent-in-response") : handoffRequestId;
    parentExitDetail["acceptingHostInstanceId"] = handoff.hostInstanceId;
    parentExitDetail["acceptedRecoveryCycleId"] = handoff.recoveryCycleId;
    parentExitDetail["acceptanceScope"] = handoff.acceptanceScope;
    parentExitDetail["queuedNow"] = handoff.queuedNow;
    parentExitDetail["hostWillRemainResident"] = handoff.hostWillRemainResident;
    parentExitDetail["acceptanceRule"] =
        "httpOk-and-ok-and-recoveryAccepted-and-instance-and-cycle";
    parentExitDetail["bindingScope"] = "accepted-by-that-host-instance-for-that-recovery-cycle";
    appendFanLifecycleLog("fan-exit-parent-exit", parentExitDetail);
    if (handoff.accepted) {
        // /api/parent-exit owns the recovery worker. Do not immediately send
        // /api/close: that races the worker for the same HC gate and was the
        // source of false close success/transport failures. The resident Host
        // remains available to finish restore and the parent watchdog will
        // close its listener afterwards.
        traceLog("fan Host app-exit cleanup: recovery handed off=1; OEM restore not yet confirmed; no concurrent close; UI exit continues");
        // The endpoint acknowledgement proves only that the resident Host
        // accepted ownership of the recovery task. It is deliberately not a
        // physical OEM-restore acknowledgement.
        appendFanLifecycleLog("fan-exit-recovery-handed-off",
                              mergeExitIdentity(json{
                                  {"status", static_cast<unsigned long>(handoffStatus)},
                                  {"acceptingHostInstanceId", handoff.hostInstanceId},
                                  {"acceptedRecoveryCycleId", handoff.recoveryCycleId},
                                  {"acceptanceScope", handoff.acceptanceScope}}));
        return FanExitHandoffResult::RecoveryHandedOff;
    }
    // A transport failure is ambiguous: the request may have reached the Host
    // even though its response was lost. Never issue a second close in that
    // case. Only an explicit legacy 404/405 proves that parent-exit is absent.
    if (handoffResultUnknown || (handoffStatus != 404 && handoffStatus != 405)) {
        traceLog("fan Host app-exit cleanup: parent-exit not confirmed status=%lu; no concurrent close; recovery remains delegated",
                 static_cast<unsigned long>(handoffStatus));
        // 401 只表示"这一次认证未获接受"：**不是**旧代的证据，也**不是**走无认证 legacy
        // close / 重写 sidecar / 杀端口 owner / 起第二 owner 的许可 —— 已验证的 Host 仍是
        // 唯一恢复 owner。2xx 但缺实例/周期绑定（旧宿主形态）同样只是"未证明被接受"。
        const char* unverifiedReason = handoffStatus == 401 ? "parent-exit-auth-rejected"
            : (handoff.unbound ? "parent-exit-unbound-ack" : "parent-exit-ambiguous");
        appendFanLifecycleLog("fan-exit-recovery-unverified",
                              mergeExitIdentity(json{
                                  {"reason", unverifiedReason},
                                  {"authCategory", fanAuthCategory(handoffStatus)},
                                  {"status", static_cast<unsigned long>(handoffStatus)},
                                  {"unbound", handoff.unbound},
                                  {"matchedPid", static_cast<unsigned long>(probe.matchedPid)},
                                  {"gates", json{{"process", probe.processFound},
                                                 {"image", probe.imageMatched},
                                                 {"port", probe.portFound}}},
                                  {"responseErrorCode", fanErrorCodeFromBody(handoffBody)}}));
        return FanExitHandoffResult::RecoveryUnverified;
    }
    DWORD closeStatus = 0;
    std::string closeBody;
    const bool closeConfirmed = fanHostEmergencyPost(
        L"/api/close", "app-exit", 1, true, &closeStatus, 0, nullptr, &closeBody);
    appendFanLifecycleLog("fan-exit-legacy-close",
                          mergeExitIdentity(json{
                              {"attempted", true},
                              {"confirmed", closeConfirmed},
                              {"status", static_cast<unsigned long>(closeStatus)}}));
    if (!closeConfirmed) {
        traceLog("fan Host app-exit cleanup: legacy close not confirmed; UI exit continues");
        appendFanLifecycleLog("fan-exit-recovery-unverified",
                              mergeExitIdentity(json{
                                  {"reason", "legacy-close-unconfirmed"},
                                  {"status", static_cast<unsigned long>(closeStatus)},
                                  {"responseErrorCode", fanErrorCodeFromBody(closeBody)}}));
        return FanExitHandoffResult::RecoveryUnverified;
    }
    // Shutdown only follows a confirmed close. It is a process-lifetime
    // optimization, never a prerequisite for declaring hardware safe.
    DWORD shutdownStatus = 0;
    if (!fanHostEmergencyPost(L"/api/shutdown", "app-exit", 1, false, &shutdownStatus)) {
        traceLog("fan Host app-exit cleanup: close confirmed; shutdown deferred");
    }
    appendFanLifecycleLog("fan-exit-legacy-close",
                          mergeExitIdentity(json{
                              {"shutdownStatus", static_cast<unsigned long>(shutdownStatus)}}));
    appendFanLifecycleLog("fan-exit-restore-confirmed",
                          mergeExitIdentity(json{
                              {"status", static_cast<unsigned long>(closeStatus)}}));
    return FanExitHandoffResult::RestoreConfirmed;
}

#ifdef YMCC_FAULT_INJECT
// ── 仅注入构建：退出交接六例自测（--fan-exit-handoff-selftest）──
// 每次调用执行一例（故障文件由 runner 逐例改写），结论落盘 %TEMP% 供 runner 断言。
static int fanExitHandoffSelfTest() {
    fiExitHandoffLoadConfig();
    const auto result = fanHostCleanupForAppExit();
    json record{
        {"gate", g_fiExitGate},
        {"parentExit", g_fiExitParentExit},
        {"close", g_fiExitClose},
        {"result", fanExitHandoffName(result)}};
    std::ofstream out(fspath::temp_directory_path() / L"fan-exit-handoff-selftest.json",
                      std::ios::trunc);
    if (out) out << record.dump() << '\n';
    return 0;
}

// ── 仅注入构建：resume 恢复序列自测（--fan-resume-selftest）──
// 每次调用执行一例（故障文件由 runner 逐例改写）。断言对象是**真实写入
// fan-lifecycle.log 的本轮事件**（按文件偏移 + 本轮 pid 切片），并同批落盘
// %TEMP% 供 runner 判定；不做任何真实 /api/resume 网络调用（夹具改写输入）。
static int fanResumeRecoverySelfTest() {
    fiResumeLoadConfig();
    const std::wstring logPath = yemancc_data_dir() + L"\\fan-lifecycle.log";
    long long offsetBefore = 0;
    {
        std::ifstream probe(logPath, std::ios::binary | std::ios::ate);
        if (probe) offsetBefore = static_cast<long long>(probe.tellg());
    }
    g_powerGeneration.store(2, std::memory_order_release);
    fanHostEmergencyResume(2);
    json events = json::array();
    {
        std::ifstream in(logPath, std::ios::binary);
        if (in) {
            in.seekg(offsetBefore);
            std::string line;
            const DWORD self = GetCurrentProcessId();
            while (std::getline(in, line)) {
                try {
                    const auto parsed = json::parse(line);
                    if (static_cast<DWORD>(parsed.value("pid", 0u)) != self) continue;
                    const auto name = parsed.value("event", std::string{});
                    if (name.rfind("fan-host-resume", 0) != 0 &&
                        name != "resume-recovery-exhausted") continue;
                    events.push_back(parsed);
                } catch (...) {
                }
            }
        }
    }
    json record{
        {"mode", g_fiResumeMode},
        {"generation", 2},
        {"eventCount", events.size()},
        {"events", events}};
    // FAN-926R 执行单 §6.2：结果落**测试数据根**（由 --test-data-root 在启动最早处绑定），
    // 不再写真实用户 Temp；无覆盖时与既有 LOCALAPPDATA\YeManCC 行为一致。
    std::ofstream out(fspath::path(yemancc_data_dir()) / L"fan-resume-recovery-selftest.json",
                      std::ios::trunc);
    if (out) out << record.dump() << '\n';
    return 0;
}
#endif

// The sole production F4 sender. The Windows callback performs only atomic
// de-duplication and worker creation, then returns immediately; the worker
// sends the generation-tagged native.power command to the resident Host. The
// renderer observes this boundary but must never race it with another suspend
// request. Native retries are transport retries for this one authority, not a
// second lifecycle owner.
static void fanHostScheduleEmergencySuspend(const char* reason,
                                            unsigned long long sharedGeneration) {
    const auto generation=g_fanPhysicalWake.confirmedSuspend(sharedGeneration);
    if(generation)fanHostQueueSuspend(reason,generation);
}
static void fanHostQueueSuspend(const char* reason,unsigned long long generation) {
    // Invalidate the renderer before queueing a single Close worker. No HTTP in callback.
    fanLeaseKeepaliveDisarm("power-suspend");
    if(!generation || !g_fanPhysicalWake.current(generation))return;
    ipc_emit("fan.suspending", {{"generation",generation},{"scope","fan-only"}});
    if(!g_fanPhysicalWake.beginClose(generation))return;
    g_fanSleepCleanupInFlight.store(true,std::memory_order_release);
    SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED);
    try {
        std::thread([reasonText=std::string(reason?reason:"unknown"),generation] {
            auto next=generation;
            do {
                const auto current=next;
                g_fanSleepCleanupGeneration.store(current,std::memory_order_release);
                bool safe=false;
                if(!g_exitRequested.load(std::memory_order_acquire))
                    safe=fanHostEmergencySuspend(reasonText.c_str(),current);
                traceLog("fan Host async sleep cleanup generation=%llu safe=%d",current,safe?1:0);
                next=g_fanPhysicalWake.completeClose(current);
            } while(next && !g_exitRequested.load(std::memory_order_acquire));
            SetThreadExecutionState(ES_CONTINUOUS);
            g_fanSleepCleanupInFlight.store(false,std::memory_order_release);
            if(g_hwnd)PostMessageW(g_hwnd,WM_FAN_PHYSICAL_WAKE_READY,
                static_cast<WPARAM>(currentFanPowerGeneration()),0);
        }).detach();
    } catch (...) {
        // Scheduling failure remains blocked. Do not manufacture a Close receipt.
        SetThreadExecutionState(ES_CONTINUOUS);
        g_fanSleepCleanupInFlight.store(false,std::memory_order_release);
        g_fanPhysicalWake.abandonClose(generation);
        traceLog("fan Host async sleep cleanup scheduling failed generation=%llu",generation);
    }
}

// ③（2026-09-17 M2″-v3，HC 对齐）：唤醒重建由进程自身触发——HC MainWindow.xaml.cs
// L909-922 的 `new Task(Open → OpenEvents)` 位于 `if (prevStatus == SystemPending)`
// 之外，每次 SystemReady 都尝试；YMCC 的对应动作 = POST /api/resume。
// 2026-09-23（FAN-204 s31 裁决 B / P-2 → 补充裁决 Q1 取代）：旧实现为"同步等待 + 有界
// 重试"（最多 3 次、总窗口 ≤3 s，退避 0/250/750 ms）；真机证明该窗口比宿主重建（10.2 s）
// 短得多，只能拿到传输失败。Q1 改为"快速接受 + 有界观察"（见下），旧 200 = 成功 的判读
// 一并废弃：只有 Ready 且无 FaultLocked/unknownState/hcCloseCleanupPending 才算真恢复。
// leaseId 仍从成功响应解析以重武装 native 续租（此刻 phase 可能尚未 Ready，arm 会 no-op，
// 由渲染器恢复后的既有 ObserveHttp 路径接手）。渲染器 F5 保持幂等兜底（Host PowerIngress 去重）。
// 2026-09-23（FAN-204 s31 补充裁决 Q1）：**接受与后台重建分离 + 有界观察**。
// 真机事实：唤醒后宿主 HC 重建 ≈10.2 s，而旧契约把同步等待挂在 HTTP 上 ⇒ 调用方在
// 窗口内只能拿到传输失败（status=0/500），无法区分"宿主忙"与"宿主不在"。新契约：
//   ① 接受：POST /api/resume 只做**有界**传输重试（≤3 次，退避 0/250/500 ms，单次 650 ms），
//      接受响应只表示"已接纳"（resumeAccepted/resumePhase/generation/retryAfterMs）；
//   ② 观察：同一 generation 只读 GET /api/state，最多 kFanResumeObserveWindowMs=15 s；
//      只有 Ready 且 !unknownState 且 !hcCloseCleanupPending 才算恢复完成；
//   ③ 终态：Recovered / noop（合法空恢复：宿主明确无可恢复，或 await-user）/
//      exhausted{host-rebuild-timeout|host-report-fault-locked|host-rebuild-failed|host-unreachable}/
//      superseded（被新睡眠取代）；不做永久 latch——下一次 resume-ready 仍可重新触发；
//   ④ 不并发第二个 Resume/Close/Restore：观察阶段只读；单飞守卫仍在序列入口。
// leaseId 仍从成功响应解析以重武装 native 续租（此刻 phase 可能尚未 Ready，arm 会
// no-op，由渲染器恢复后的既有 ObserveHttp 路径接手）。渲染器 F5 保持幂等兜底。
// 2026-09-23（FAN-204 s31 补充裁决 Q1）：**接受与后台重建分离**的诚实判读。
// /api/resume 的接受响应只表示"已接纳"（resumeAccepted=true + resumePhase + generation +
// retryAfterMs + 快照），**不**表示恢复完成；完成由调用方按同一 generation 有界读取
// /api/state（kFanResumeObserveWindowMs ≤15 s）判定：只有 Ready 且 !unknownState 且
// !hcCloseCleanupPending 才算恢复完成。旧宿主（同步等待实现）的 {ok,state} 终态形状继续
// 兼容判读；POWER_RESUMING 可进入观察，明确失败/认证拒绝/superseded/expired 各自终态。
// 返回 false 表示响应缺失/不可解析（不得据此判成任何成功）。
using FanResumeHostReply = ymcc::fan_session::ResumeReply;
static bool fanResumeParseReply(const std::string& body, FanResumeHostReply* out) {
    if (!out) return false;
    *out = FanResumeHostReply{};
    try {
        const auto root = json::parse(body);
        if (!ymcc::fan_session::parseResumeReplyValue(root, out)) return false;
        // Reuse this parsed body. A malformed optional legacy lease must not
        // invalidate otherwise usable lifecycle evidence or a later manual retry.
        try { out->leaseId = extractFanLeaseIdFromJson(root); } catch (...) { }
        return true;
    } catch (...) { return false; }
}

// 观察窗（补充裁决拍板：最多 15 s，同一 generation）。观察阶段**只读**状态。
static constexpr unsigned long long kFanResumeObserveWindowMs = 15000;
static constexpr int kFanResumeObserveIntervalDefaultMs = 250;
static constexpr int kFanResumeObserveIntervalMinMs = 100;
static constexpr int kFanResumeObserveIntervalMaxMs = 1000;
static constexpr int kFanResumeUnreachableProbeLimit = 5;
static constexpr int kFanResumeObserveLogLimit = 16;

using FanResumeVerdict = ymcc::fan_session::ResumeVerdict;
static FanResumeVerdict fanResumeClassify(const FanResumeHostReply& reply, unsigned long long generation) {
    return ymcc::fan_session::classifyResumeReply(reply, generation);
}

static void fanHostEmergencyResume(unsigned long long generation) {
    if (generation == 0) return;
    // FAN-955: newer Ready edges survive an in-flight older recovery, with
    // exactly one owner. Duplicate/older edges cannot create another writer.
    if (!g_fanResumeRequestOwner.begin(generation)) {
        appendFanLifecycleLog("fan-host-resume-coalesced", json{
            {"generation", generation}, {"pendingGeneration", g_fanResumeRequestOwner.pending()},
            {"reason", "single-owner-newer-wake-retained"}});
        return;
    }
    struct OwnerScope {
        unsigned long long generation;
        ~OwnerScope() noexcept {
            const auto next = g_fanResumeRequestOwner.finish(generation);
            if (!next || g_exitRequested.load(std::memory_order_acquire) ||
                next != currentFanPowerGeneration() || !fanActivityIntentPresent()) return;
            const auto phase = g_powerLifecycle.load(std::memory_order_acquire);
            if (!fanHostPowerMayResume()) return;
            try {
                appendFanLifecycleLog("fan-host-resume-coalesced-drain", json{
                    {"completedGeneration", generation}, {"generation", next}, {"scope", "fan-only"}});
                fanHostScheduleFanResume(next);
            } catch (...) { }
        }
    } ownerScope{generation};
    g_fanResumeRecoveryGeneration.store(generation, std::memory_order_release);
    const ULONGLONG startedTick = GetTickCount64();
    // 接受阶段：只做**有界**的传输重试；接受本身不再等待重建（Q1）。
    const DWORD acceptBackoffMs[3] = {0, 250, 500};
    DWORD lastStatus = 0;
    bool lastOk = false;
    int acceptAttempts = 0;
    int probeCount = 0;
    int loggedProbes = 0;
    int unreachableProbes = 0;
    ULONGLONG lastObserveLogTick = 0;
    FanResumeHostReply last{};
    auto elapsedMs = [&]() { return static_cast<long long>(GetTickCount64() - startedTick); };
    auto finish = [&](const char* terminal, const char* reason, bool exhausted) {
        appendFanLifecycleLog("fan-host-resume-native-trigger", json{
            {"generation", generation},
            {"status", static_cast<int>(lastStatus)},
            {"ok", terminal[0] == 'r' || terminal[0] == 'n' ? true : false},
            {"leasePresent", false},
            {"attempts", acceptAttempts},
            {"probes", probeCount},
            {"terminal", terminal},
            {"resumeAccepted", last.accepted},
            {"phase", last.phase.empty() ? last.stateName : last.phase},
            {"hostState", last.stateName},
            {"hostOpStatus", last.opStatus},
            {"elapsedMs", elapsedMs()}});
        if (exhausted) {
            appendFanLifecycleLog("resume-recovery-exhausted", json{
                {"generation", generation},
                {"reason", reason},
                {"attempts", acceptAttempts},
                {"probes", probeCount},
                {"lastStatus", static_cast<int>(lastStatus)},
                {"lastOk", lastOk},
                {"hostState", last.stateName},
                {"hostOpStatus", last.opStatus},
                {"elapsedMs", elapsedMs()},
                {"retrigger", "next-resume-ready"}});
        }
        // OwnerScope releases and drains the newest valid wake on every exit.
    };
    try {
        // ── 阶段 1：接受（快速返回；只有传输/服务端失败才做有界重试） ──
        bool accepted = false;
        for (int attempt = 1; attempt <= 3; ++attempt) {
            if(generation!=currentFanPowerGeneration() || !fanHostPowerMayResume())return;
            if (acceptBackoffMs[attempt - 1] > 0) Sleep(acceptBackoffMs[attempt - 1]);
            if(generation!=currentFanPowerGeneration() || !fanHostPowerMayResume())return;
            acceptAttempts = attempt;
            DWORD status = 0;
            std::string body;
            const auto leaseReceiptEpoch = g_monitorFanDisplay.epoch();
            bool requestResultUnknown = false;
            const bool ok = fanHostEmergencyPost(L"/api/resume", "native.power", 1, false,
                                                 &status, generation, "native.power", &body,
                                                 nullptr, nullptr, &requestResultUnknown);
            // 迟到响应保护：响应回来时若会话已被更新的 generation 接管，绝不消费其结果。
            if (g_fanResumeRecoveryGeneration.load(std::memory_order_acquire) != generation || currentFanPowerGeneration() != generation) {
                appendFanLifecycleLog("fan-host-resume-superseded", json{
                    {"generation", generation},
                    {"attempt", attempt},
                    {"reason", "generation-taken-over"}});
                // OwnerScope releases and drains the newest valid wake on every exit.
                return;
            }
            FanResumeHostReply reply;
            const bool parsed = fanResumeParseReply(body, &reply);
            const bool leasePresent = ok && parsed && !reply.noop &&
                fanResumeClassify(reply, generation) == FanResumeVerdict::Recovered &&
                isFanLeaseIdValid(reply.leaseId);
            if (leasePresent) fanLeaseKeepaliveArm(reply.leaseId, "native.power-resume", leaseReceiptEpoch);
            lastStatus = status;
            lastOk = ok;
            last = reply;
            appendFanLifecycleLog("fan-host-resume-attempt", json{
                {"attempt", attempt},
                {"generation", generation},
                {"status", static_cast<int>(status)},
                {"ok", ok},
                {"parsed", parsed},
                {"resumeAccepted", reply.accepted},
                {"resumeNoop", reply.noop},
                {"phase", reply.phase.empty() ? reply.stateName : reply.phase},
                {"hostReady", reply.ready ? "ready" : (reply.unknown ? "unknown" : "not-ready")},
                {"hostUnknown", reply.unknown},
                {"hostState", reply.stateName},
                {"hostOpStatus", reply.opStatus},
                {"faultLocked", reply.faultLocked},
                {"closeCleanupPending", reply.cleanupPending},
                {"leasePresent", leasePresent},
                {"elapsedMs", elapsedMs()}});
            // 合法 no-op（宿主明确回答"无可恢复"）：单独记录，终止本次序列，不重试。
            if (ok && reply.noop && reply.parsed) {
                if (reply.responseOk == 0 || reply.unknown || reply.faultLocked || reply.cleanupPending || !reply.errorCode.empty()) {
                    finish("exhausted", "host-noop-with-blocking-evidence", true);
                    return;
                }
                finish("noop", "host-explicit-noop", false);
                return;
            }
            // Q1 接受：只表示已接纳——但如果接受快照本身已经是可判定终态
            // （同步完成的空恢复 await-user / 重建已先完成 / 故障），必须立即如实结算，
            // 不得再进观察窗（否则会拿"宿主已无事可做"去撞 15 s 超时）。
            if (ok && reply.accepted) {
                const auto acceptedVerdict = fanResumeClassify(reply, generation);
                if (acceptedVerdict == FanResumeVerdict::Recovered) {
                    finish("recovered", "accepted-ready", false);
                    return;
                }
                if (acceptedVerdict == FanResumeVerdict::NoWork) {
                    finish("noop", "await-user", false);
                    return;
                }
                if (acceptedVerdict == FanResumeVerdict::Failed) {
                    finish("exhausted", "host-fault-locked", true);
                    return;
                }
                if (acceptedVerdict == FanResumeVerdict::Superseded) {
                    finish("superseded", "superseded-at-accept", false);
                    return;
                }
                accepted = true;
                break;
            }
            // 兼容旧宿主（同步等待实现）：终态快照可直接判定；未 Ready 也转入观察
            // （旧宿主可能刚完成重建，状态即将可读；不得把 200 直接当成功）。
            if (ok && parsed) {
                const auto verdict = fanResumeClassify(reply, generation);
                if (verdict == FanResumeVerdict::Recovered) {
                    finish("recovered", "legacy-host-terminal-ready", false);
                    return;
                }
                if (verdict == FanResumeVerdict::NoWork) {
                    finish("noop", "await-user", false);
                    return;
                }
                if (verdict == FanResumeVerdict::Failed) {
                    finish("exhausted", "host-fault-locked", true);
                    return;
                }
                if (verdict == FanResumeVerdict::Superseded) {
                    finish("superseded", "superseded-at-accept", false);
                    return;
                }
                accepted = true;
                break;
            }
            // 明确终态：被新睡眠取代 / 结果过期 ⇒ 不重试、不观察。
            if (!ok && status == 409 &&
                (reply.errorCode == "HC_RESUME_SUPERSEDED" || reply.errorCode == "HC_RESUME_RESULT_EXPIRED")) {
                finish("superseded", reply.errorCode.c_str(), false);
                return;
            }
            // FAN-943: an explicit rejection is not an accepted recovery worker.
            if (ymcc::fan_session::isTerminalResumeRejection(status, reply)) {
                finish("exhausted", reply.errorCode.empty() ? "host-authorization-denied" : reply.errorCode.c_str(), true);
                return;
            }
            // 传输失败 / 5xx / 无响应 ⇒ 有界重试（≤3 次，退避 0/250/500）。
            if (!requestResultUnknown && !ok && (status == 0 || status >= 500)) continue;
            // 其余"可判定"应答（含带原因码的 409/202/2xx）都是"处理中" ⇒ 转入观察。
            accepted = true;
            break;
        }
        // 三次接受全部传输失败：仍按"宿主可能正在自行重建"进入只读观察（不重发控制）。
        (void)accepted;
        // ── 阶段 2：有界观察（≤15 s；同一 generation；只读 /api/state） ──
        int intervalMs = last.retryAfterMs > 0
            ? static_cast<int>(std::min<long long>(last.retryAfterMs, kFanResumeObserveIntervalMaxMs))
            : kFanResumeObserveIntervalDefaultMs;
        intervalMs = (std::max)(intervalMs, kFanResumeObserveIntervalMinMs);
        while (true) {
            // 新 generation 接管（新睡眠/新唤醒）⇒ 立即终止，绝不消费旧结果。
            if (g_fanResumeRecoveryGeneration.load(std::memory_order_acquire) != generation || currentFanPowerGeneration() != generation) {
                appendFanLifecycleLog("fan-host-resume-superseded", json{
                    {"generation", generation},
                    {"reason", "generation-taken-over"},
                    {"elapsedMs", elapsedMs()}});
                // OwnerScope releases and drains the newest valid wake on every exit.
                return;
            }
            // 退出进行中：不再观察（不写伪造终态；由退出路径负责收尾）。
            if (g_exitRequested.load(std::memory_order_acquire)) {
                finish("abandoned", "app-exit", false);
                return;
            }
            if (GetTickCount64() - startedTick >= kFanResumeObserveWindowMs) {
                finish("exhausted", "host-rebuild-timeout", true);
                return;
            }
            DWORD status = 0;
            std::string body;
            const bool ok = fanHostEmergencyGetState(&body, &status);
            ++probeCount;
            // The power edge may have changed while the GET was in flight.
            // A late observation cannot finish or mutate a newer recovery.
            if (g_fanResumeRecoveryGeneration.load(std::memory_order_acquire) != generation ||
                currentFanPowerGeneration() != generation) {
                appendFanLifecycleLog("fan-host-resume-superseded", json{
                    {"generation", generation}, {"reason", "generation-taken-over-during-observation"}});
                return;
            }
            FanResumeHostReply probe;
            const bool responseParsed = fanResumeParseReply(body, &probe);
            const bool parsed = ok && responseParsed;
            if (ymcc::fan_session::isTerminalResumeRejection(status, probe)) {
                finish("exhausted", probe.errorCode.empty() ? "host-observation-authorization-denied" : probe.errorCode.c_str(), true);
                return;
            }
            if (!parsed) {
                if (++unreachableProbes >= kFanResumeUnreachableProbeLimit) {
                    finish("exhausted", "host-unreachable", true);
                    return;
                }
            } else {
                unreachableProbes = 0;
                // Compare only existing observations; no probe or recovery decision depends on this log flag.
                const bool observationChanged = status != lastStatus ||
                    (probe.phase.empty() ? probe.stateName : probe.phase) != (last.phase.empty() ? last.stateName : last.phase) ||
                    probe.stateName != last.stateName || probe.opStatus != last.opStatus ||
                    probe.unknown != last.unknown || probe.cleanupPending != last.cleanupPending;
                lastStatus = status;
                last = probe;
                const auto verdict = fanResumeClassify(probe, generation);
                if (verdict == FanResumeVerdict::Recovered) {
                    finish("recovered", "observed-ready", false);
                    return;
                }
                if (verdict == FanResumeVerdict::NoWork) {
                    finish("noop", "await-user", false);
                    return;
                }
                if (verdict == FanResumeVerdict::Failed) {
                    finish("exhausted",
                           probe.unknown || probe.faultLocked ? "host-report-fault-locked" : "host-rebuild-failed",
                           true);
                    return;
                }
                if (verdict == FanResumeVerdict::Superseded) {
                    finish("superseded", "host-reported-superseded", false);
                    return;
                }
                // First/changed observations stay resident; unchanged 1 Hz probes are detailed.
                // Preserve the existing per-recovery cap and never construct a periodic row with detail off.
                const ULONGLONG now = GetTickCount64();
                const bool eventObservation = loggedProbes == 0 || observationChanged;
                if (eventObservation || now - lastObserveLogTick >= 1000) {
                    if (loggedProbes < kFanResumeObserveLogLimit) {
                        ++loggedProbes;
                        lastObserveLogTick = now;
                        if (eventObservation || domainLogEnabled("virtual")) {
                            try {
                                json observation{
                                    {"generation", generation},
                                    {"probes", probeCount},
                                    {"status", static_cast<int>(status)},
                                    {"phase", probe.phase.empty() ? probe.stateName : probe.phase},
                                    {"hostState", probe.stateName},
                                    {"hostOpStatus", probe.opStatus},
                                    {"unknownState", probe.unknown},
                                    {"closeCleanupPending", probe.cleanupPending},
                                    {"elapsedMs", elapsedMs()},
                                    {"snapshotReason", eventObservation ? "state-change" : "periodic"}};
                                if (eventObservation) appendFanLifecycleLog("fan-host-resume-observe", std::move(observation));
                                else appendDomainLog("virtual", "fan-host-resume-observe", std::move(observation));
                            } catch (...) { /* diagnostic loss cannot terminate recovery */ }
                        }
                    }
                }
            }
            Sleep(intervalMs);
        }
    } catch (...) {
        appendFanLifecycleLog("fan-host-resume-native-trigger", json{
            {"generation", generation},
            {"status", static_cast<int>(lastStatus)},
            {"ok", false},
            {"attempts", acceptAttempts},
            {"probes", probeCount},
            {"terminal", "exception"}});
    }
    // OwnerScope releases and drains the newest valid wake on every exit.
}

static void fanHostPublishPhysicalWake(unsigned long long generation) noexcept {
    try {
        const auto phase=g_powerLifecycle.load(std::memory_order_acquire);
        // Normal accepted user wakes already have their existing Fan F5 owner.
        if (generation!=currentFanPowerGeneration() || !fanHostPowerMayResume()
            || !fanActivityIntentPresent() || !g_fanPhysicalWake.claimReady(generation)) return;
        appendFanLifecycleLog("fan-physical-wake-ready", {{"generation",generation},
            {"sharedGeneration",currentPowerGeneration()},{"source","matched-kernel-506-507"},{"scope","fan-only"},
            {"globalLifecycle",powerLifecycleName(phase)},{"sharedPowerCommitted",false}});
        fanHostScheduleFanResume(generation);
        ipc_emit("fan.resume-ready", {{"generation",generation},
            {"source","fan-physical-wake"},{"scope","fan-only"}});
    } catch (...) { }
}

static void fanHostScheduleEmergencyResume(unsigned long long sharedGeneration) {
    const auto generation=g_fanPhysicalWake.sharedResume(sharedGeneration);
    if(generation){
        fanHostScheduleFanResume(generation);
        if(fanActivityIntentPresent())ipc_emit("fan.resume-ready", {{"generation",generation},{"scope","fan-only"}});
    }
}
static void fanHostScheduleFanResume(unsigned long long generation) {
    if (generation == 0) return;
    // FAN-927 §3（2026-09-27 用户批准）：**意图前置**。本 run 从未确认过活动控制意图
    // （也没有 §5.2 崩溃前仍有效的记录）时，自动唤醒在这里就结束——零 Fan HTTP、
    // 零进程枚举、零 Host 启动、零等待任务，不再"没启用却白等 15 秒"。
    if (!fanActivityIntentPresent()) {
        appendFanLifecycleLog("fan-host-resume-nowork", {
            {"generation", generation},
            {"reason", "no-active-control-intent"},
        });
        return;
    }
    try {
        std::thread([generation] {
            if (g_exitRequested.load(std::memory_order_acquire) || generation != currentFanPowerGeneration()) return;
            const auto phase = g_powerLifecycle.load(std::memory_order_acquire);
            if (!fanHostPowerMayResume()) return;
            fanHostEmergencyResume(generation);
        }).detach();
    } catch (...) {
        appendFanLifecycleLog("fan-host-resume-thread-failed",
                              {{"generation", generation}});
    }
}

