static void reg_gamepad_feedback() {
    // Read-only status/replay; checking a completed setup never opens a hardware reader.
    ipc_on("gamepad.driverSetup.get", [](const json& args) -> json {
        gamepadDriverSetupRequestRead();
        if (args.value("refreshUsbip",false) && !g_exitRequested.load(std::memory_order_acquire) &&
            g_gamepadDriverSetup.refreshUsbipObservation([](const std::wstring& command) {
                if (g_exitRequested.load(std::memory_order_acquire)) return json{};
                const auto run=runCapture(command,5000);
                if (g_exitRequested.load(std::memory_order_acquire) || !run.ran || run.exitCode!=0 || run.out.size()>8192) return json{};
                return json::parse(run.out,nullptr,false);
            }) && !g_exitRequested.load(std::memory_order_acquire)) {
            const auto snapshot=gamepadDriverSetupSnapshot();
            appendNativeLifecycleLog("usbip-status-observation",snapshot);
            ipc_emit("gamepad.driverSetup",snapshot);
        }
        return gamepadDriverSetupSnapshot();
    });
    // HC ControllerPage semantics: Rumble(LargeMotor, SmallMotor) with the
    // VibrationStrength multiplier; lighting follows device DynamicLighting
    // capabilities (ROG Ally: Solid / Breathing / Rainbow / Wheel / Ambilight
    // plus brightness).
    // L2 文件扳机版取代 IPC 版（2026-09-17 用户裁决）：掌机上没有 F12/DevTools
    // Console、前端也没有既有重建入口，原 debug.recreateTargetOnce IPC 已作废
    // ——现由 inputHostConsumeDebugRecreateFlag() 承担（bus tick 1s 节拍 +
    // %LOCALAPPDATA%\YeManCC\debug-recreate-once.flag，pendingDelete）。
    ipc_on("gamepad.feedbackCapabilities", [](const json&) -> json {
        // HC DevicePage gates each lighting control by the device's static
        // capability bits (DynamicLighting / DynamicLightingBrightness plus
        // the DynamicLightingCapabilities LEDLevel set). Two layers are kept
        // apart so the reason stays truthful per machine:
        //   1) familySupportsLighting  — HC 机型库能力位。7.52 P1-T4 起改按
        //      deviceClass 精确判定（ymccDeviceClassSupportsLighting），
        //      family 包装仅兼容 selftest。
        //   2) lightingBackendImplemented — YMCC 实际实现的灯光后端（仅 ROG Aura）
        // The UI grants a panel only when both hold; machines the library says
        // can do lights but whose backend is unimplemented get an explicit
        // backend-not-implemented reason instead of a false "machine-unsupported".
        const std::string& fbDeviceClass = g_machineIdentity.deviceClass;
        const bool familySupportsLighting = ymccDeviceClassSupportsLighting(fbDeviceClass);
        // L1 方案 B（2026-09-16）：后端判定扩展——ROG 走 Aura（内部句柄）；
        // 非 ROG 且能力表命中时经 YeManLightSetter 直驱 HC（子进程在位即
        // 视为后端可用，实际结果由 gamepad.setLed 回执体现）。
        const bool lightSetterPresent =
            GetFileAttributesW(kLightSetterExe.c_str()) != INVALID_FILE_ATTRIBUTES;
        // MSI Claw 原生 HID 后端（方案 A，2026-09-29）：不依赖子进程/exe。
        const bool registeredRogLighting = ymcc::lighting::usesRogAura(fbDeviceClass);
        const bool registeredMsiLighting = ymcc::lighting::usesMsiNativeHid(fbDeviceClass);
        const bool nativeRogLighting = registeredRogLighting && machineIsRogAllyFamily();
        const bool msiNativeLighting = registeredMsiLighting &&
            g_machineIdentity.family == YmccFamily::MsiClaw && familySupportsLighting;
        const bool lightingBackendImplemented =
            registeredRogLighting ? nativeRogLighting : registeredMsiLighting ? msiNativeLighting : lightSetterPresent;
        const bool rogLightingFamily = familySupportsLighting && lightingBackendImplemented;
        const bool ledAvailable = rogLightingFamily &&
            (registeredRogLighting ? g_rog.auraControl != INVALID_HANDLE_VALUE
                                      : (msiNativeLighting || lightSetterPresent));
        const bool brightnessAvailable = rogLightingFamily && ymcc::lighting::brightnessImplemented(fbDeviceClass);
        const bool presetImplemented = ymcc::lighting::presetImplemented(fbDeviceClass);
        json ledPresets = json::array();
        if (rogLightingFamily && presetImplemented)
            for (const auto& preset : ymcc::lighting::kOneXPresets)
                ledPresets.push_back({{"id", preset.id}, {"label", preset.label}});
        const char* lightingBackend = !lightingBackendImplemented ? "none" : nativeRogLighting ? "rog-aura"
            : msiNativeLighting ? "msi-claw-native-hid"
            : lightSetterPresent ? "hc-light-setter" : "none";
        // HC DeviceCapabilities.DynamicLightingSecondLEDColor gates the
        // secondary color picker (DevicePage.xaml SecondColorPickerCard); ROG
        // has no such bit, so the UI hides "副颜色" for the ROG backend.
        const bool supportsSecondColor = ymccDeviceClassSupportsSecondColor(fbDeviceClass);
        // HC DynamicLightingCapabilities LEDLevel set per device class (see
        // ymccDeviceClassLedEffects). Only the ROG backend (lighting backend
        // implemented) actually drives the device here; other capable families
        // report their HC mode list so the UI dropdown stays aligned with the
        // machine library even before a backend lands. Uncapable families get
        // an empty list (fail-closed): no dropdown entries, no wrong modes.
        json ledEffects = json::array();
        if (rogLightingFamily) {
            for (const std::string& effect : ymccDeviceClassLedEffects(fbDeviceClass))
                if (effect != "preset" || presetImplemented) ledEffects.push_back(effect);
        }
        bool physicalConnected=false;
        {std::lock_guard<std::mutex> lock(g_gamepadReadMx);
            const DWORD physical=xinputPhysicalConnectedMask() & (g_xinputPhysicalSourceLocked?g_xinputPhysicalSourceMask:0xFu);
            physicalConnected=g_xinputPrimarySlot<4 && (physical&(1u<<g_xinputPrimarySlot))!=0;
        }
        // GP-MSIG3E-3-R2（E4）：震动能力与后端**共用**当前受管主源记录。MSI DInput 主源
        // （1902/MI_00&COL01）已绑定时，主源就是这个实体接口，不应只因没有 XI 槽而报整机
        // 无震动——震动发向 MSI DInput 实体 HID 后端，而非自家虚拟 XInput 槽。
        HidHideMsiMainSourceRecord fbMsiRecord;
        const bool msiDinputFeedbackOwner = msiDinputManagedMainSourceActive(fbMsiRecord);
        const char* vibrationBackend = msiDinputFeedbackOwner ? "msi-dinput-hid"
            : (physicalConnected ? "xinput" : "none");
        const bool vibrationAvailable = msiDinputFeedbackOwner || physicalConnected;
        json result = {
            {"ledAvailable", ledAvailable},
            {"brightnessAvailable", brightnessAvailable},
            {"ledEffects", ledEffects},
            {"ledPresets", ledPresets},
            {"presetDeclared", presetImplemented || ymcc::lighting::presetDeclaredButUnavailable(fbDeviceClass)},
            {"presetImplemented", presetImplemented},
            {"presetReason", ymcc::lighting::presetDeclaredButUnavailable(fbDeviceClass) ? "preset-transport-not-implemented" : ""},
            {"supportsSecondColor", supportsSecondColor},
            {"vibrationAvailable", vibrationAvailable},
            {"vibrationBackend", vibrationBackend},
            // S0 第 1 条（write ≠ verified）：MSI DInput 后端本机无回读路径 ⇒ 诚实标注
            // "未现场验证"，不以 UI 假绿替代。
            // Endpoint availability is not a measured motor or visible-light response.
            {"vibrationVerified", false},
            {"ledVerified", false},
            {"hardwareWriteIssued", false},
            {"verificationScope", "capability-query-only;physical-response-not-observed"},
            {"physicalPrimarySlot", physicalConnected ? static_cast<int>(g_xinputPrimarySlot) : -1},
            {"familySupportsLighting", familySupportsLighting},
            {"lightingBackendImplemented", lightingBackendImplemented},
            {"machineFamily", ymccFamilyName(g_machineIdentity.family)},
            // Diagnostics: receipts for the feedback page, never user-visible
            // claims. They let a support run report the exact unavailable cause.
            {"ledDiagnostics", {
                {"controlOpen", g_rog.auraControl != INVALID_HANDLE_VALUE},
                {"auraFeatureLen", static_cast<int>(g_rog.auraFeatureLen)},
                {"familyCapable", rogLightingFamily},
                {"familySupportsLighting", familySupportsLighting},
                {"backendImplemented", lightingBackendImplemented},
                {"lightSetterPresent", lightSetterPresent},
                {"msiNativeLighting", msiNativeLighting},
                {"lightingBackend", lightingBackend},
                {"identityMatched", g_rog.identityMatched},
                {"productId", g_rog.productId ? static_cast<int>(g_rog.productId) : 0},
                {"featureLen", static_cast<int>(g_rog.featureLen)},
                {"suppressed", g_rog.suppressed}
            }},
            {"vibrationDiagnostics", {
                {"connectedMask", static_cast<int>(g_xinputConnectedMask)},
                {"admittedMask", static_cast<int>(g_xinputAdmittedMask)},
                {"sourceLocked", g_xinputPhysicalSourceLocked},
                {"primarySlot", static_cast<int>(g_xinputPrimarySlot)},
                {"backend", vibrationBackend},
                {"msiDinputManaged", msiDinputFeedbackOwner},
                {"msiDinputGeneration", static_cast<unsigned long long>(fbMsiRecord.generation)},
                {"msiDinputInterfacePath", fbMsiRecord.interfacePath}
            }}
        };
        if (!ledAvailable)
            result["ledReason"] = !familySupportsLighting ? "machine-unsupported"
                : !lightingBackendImplemented ? "backend-not-implemented"
                : g_rog.auraControl == INVALID_HANDLE_VALUE ? "rog-hid-control-not-open" : "rog-hid-not-matched";
        else
            result["ledReason"] = "ok";
        if (msiDinputFeedbackOwner)
            result["vibrationReason"] = "ok";
        else if (!physicalConnected)
            result["vibrationReason"] = "no-xinput-slots";
        else
            result["vibrationReason"] = "ok";
        // Diagnostic receipt for the feedback page probe: capture exactly what
        // the renderer receives so a "still-locked" report can be traced to
        // native state or the frontend snapshot without guesswork.
        appendNativeLifecycleLog("gamepad.feedbackCaps", {
            {"ledAvailable", ledAvailable},
            {"vibrationAvailable", vibrationAvailable},
            {"vibrationBackend", vibrationBackend},
            // Endpoint availability is not a measured motor or visible-light response.
            {"vibrationVerified", false},
            {"ledVerified", false},
            {"hardwareWriteIssued", false},
            {"verificationScope", "capability-query-only;physical-response-not-observed"},
            {"msiDinputManaged", msiDinputFeedbackOwner},
            {"physicalPrimarySlot", physicalConnected ? static_cast<int>(g_xinputPrimarySlot) : -1},
            {"xinputConnectedMask", static_cast<int>(g_xinputConnectedMask)},
            {"xinputAdmittedMask", static_cast<int>(g_xinputAdmittedMask)},
            {"xinputSourceLocked", g_xinputPhysicalSourceLocked},
            {"rogControlOpen", g_rog.control != INVALID_HANDLE_VALUE},
            {"rogAuraControlOpen", g_rog.auraControl != INVALID_HANDLE_VALUE},
            {"rogLightingFamily", rogLightingFamily},
            {"lightingBackendImplemented", lightingBackendImplemented},
            {"lightingBackend", lightingBackend},
            {"msiNativeLighting", msiNativeLighting},
            {"lightSetterPresent", lightSetterPresent},
            {"machineFamily", ymccFamilyName(g_machineIdentity.family)},
            {"rogIdentityMatched", g_rog.identityMatched},
        });
        return result;
    });

    ipc_on("gamepad.setLed", [](const json& a) -> json {
        const auto* catalogDevice = ymcc::capabilities::find(g_machineIdentity.deviceClass);
        const auto* lightingRoute = ymcc::lighting::resolve(catalogDevice);
        const std::string capabilityId(catalogDevice ? catalogDevice->deviceId : std::string_view{});
        const bool enabled = a.value("enabled", true);
        const std::string mode = a.value("mode", std::string{"solid"});
        const int speed = std::clamp(a.value("speed", 65), 0, 100);
        const int brightness = std::clamp(a.value("brightness", 100), 0, 100);
        const std::string presetId = a.value("presetId", std::string{});
        // Receipt for every setLed outcome — including early returns such as
        // the power-transition gate — merged into the shared
        // native-lifecycle.log stream (same channel as feedbackCaps/vibrate).
        const auto receipt = [&](const json& body) -> json {
            const auto resolvedId = body.value("capabilityId", capabilityId);
            appendNativeLifecycleLog("gamepad-setLed", {
                {"schema", 2}, {"deviceClass", g_machineIdentity.deviceClass}, {"capabilityId", resolvedId},
                {"requestedCapabilityId", capabilityId}, {"capabilityCatalogSha256", ymcc::lighting::kCatalogSha256},
                {"family", ymccFamilyName(g_machineIdentity.family)},
                {"requestedColor", a.value("color", std::string{"#2ea6ff"})},
                {"requestedColor2", a.value("color2", std::string{"#9d7cff"})},
                {"presetId", presetId},
                {"physicalEffectVerified", false}, {"proofScope", "request-and-backend-receipt"},
                {"enabled", enabled}, {"mode", mode}, {"speed", speed},
                {"brightness", brightness},
                {"ok", body.value("ok", false)},
                {"effectApplied", body.value("effectApplied", false)},
                {"brightnessApplied", body.value("brightnessApplied", false)},
                {"reason", body.value("reason", std::string{})},
                {"backend", body.value("backend", std::string{})},
                {"backendNote", body.value("note", std::string{})},
                {"helperReceipt", body.value("helperReceipt", json::object())},
                {"controlOpen", g_rog.auraControl != INVALID_HANDLE_VALUE},
                {"auraFeatureLen", static_cast<int>(g_rog.auraFeatureLen)}
            });
            json routed = body;
            routed["capabilityId"] = resolvedId;
            routed["requestedCapabilityId"] = capabilityId;
            routed["capabilityCatalogSha256"] = ymcc::lighting::kCatalogSha256;
            routed["physicalEffectVerified"] = false;
            return routed;
        };
        if (!hardwareWriteAllowed())
            return receipt(json{{"ok", false}, {"reason", "power-transition"}});
        if (!lightingRoute)
            return receipt(json{{"ok", false}, {"reason", "lighting-capability-unavailable"}});
        if (enabled && mode != "preset" && !ymcc::lighting::supportsColorEffect(*lightingRoute, mode))
            return receipt(json{{"ok", false}, {"reason", "invalid-or-unavailable-effect"}});
        if (enabled && mode == "preset" && !ymcc::lighting::validPreset(*lightingRoute, presetId))
            return receipt(json{{"ok", false}, {"reason", "invalid-or-unavailable-preset"}});
        BYTE r1 = 0, g1 = 0, b1 = 0, r2 = 0, g2 = 0, b2 = 0;
        if (!parseRgbHex(a.value("color", std::string{"#2ea6ff"}), r1, g1, b1) ||
            !parseRgbHex(a.value("color2", std::string{"#9d7cff"}), r2, g2, b2))
            return receipt(json{{"ok", false}, {"reason", "invalid-color"}});

        // The resolved route directly selects the registered writer; a cached Aura handle cannot select a model.
        // MSI Claw：内置原生 HID 后端（方案 A，移植 CTW MsiClawLedController，
        // 直写 0x0DB0 命令接口，无子进程/HidHide 依赖）。
        // 其余机能族：YeManLightSetter 一次性子进程直驱 HC 程序集（方案 B 兜底；
        // 各机型 EC/HID/USB 协议由 HC 处理）。
        if (lightingRoute->provider == ymcc::lighting::NativeProvider::MsiHid) {
            if (g_machineIdentity.family != YmccFamily::MsiClaw)
                return receipt(json{{"ok", false}, {"reason", "lighting-identity-mismatch"}});
            return receipt(msiClawApplyLed(enabled, mode, r1, g1, b1, r2, g2, b2, brightness));
        }
        if (lightingRoute->provider != ymcc::lighting::NativeProvider::RogAura)
            return receipt(ymccLightSetterApply(enabled, mode, r1, g1, b1, r2, g2, b2, speed, brightness, presetId));
        if (!machineIsRogAllyFamily())
            return receipt(json{{"ok", false}, {"reason", "lighting-identity-mismatch"}});

        if (g_rog.auraControl == INVALID_HANDLE_VALUE)
            return receipt(json{{"ok", false}, {"reason", "aura-device-unavailable"}});

        if (!enabled) {
            // HC DynamicLightingManager.UpdateLED() turn-off branch
            // (Managers/DynamicLightingManager.cs:305-310): only when the
            // LEDSettingsEnabled switch is off — SetLedStatus(false),
            // SetLedBrightness(0) and SetLedColor(Black, Black, SolidColor).
            // 0% brightness is NOT an off switch in HC: with the toggle on,
            // UpdateLED still applies the effect and just writes brightness 0
            // (ROG SetLedBrightness range 0..3, 0 = off). The explicit off path
            // must write the brightness-0 feature AND a black solid frame.
            const bool brightnessOff = rogAuraSetBrightness(0);
            const bool blackApplied = rogAuraApplyColor(RogAuraMode::Solid, 0, 0, 0, 0, 0, 0, 0);
            return receipt(json{{"ok", brightnessOff && blackApplied}, {"applied", "off"},
                {"brightnessApplied", brightnessOff}, {"effectApplied", blackApplied}, {"backend", "rog-aura"}});
        }

        bool effectApplied = false;
        if (mode == "ambilight") {
            // HC ROGAlly Ambilight = screen-capture driven left/right colors
            // (DynamicLightingManager). YMCC renders a static two-zone split.
            effectApplied = rogAuraApplyAmbilight(r1, g1, b1, r2, g2, b2);
        } else {
            // HC ROGAlly has no DynamicLightingSecondLEDColor capability, so
            // LEDUseSecondColor is hidden/False and SetLedColor receives
            // (Main, Main, ...): the secondary color is the main color. Mirror
            // that for solid/breathing/rainbow/wheel instead of emitting the
            // UI color2 as a distinct second color.
            const BYTE cr = r1, cg = g1, cb = b1;
            if (mode == "solid") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Solid, cr, cg, cb, cr, cg, cb, speed);
            } else if (mode == "breathing") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Breathing, cr, cg, cb, cr, cg, cb, speed);
            } else if (mode == "rainbow") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Rainbow, cr, cg, cb, cr, cg, cb, speed);
            } else if (mode == "wheel") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Wheel, cr, cg, cb, cr, cg, cb, speed);
            } else {
                return receipt(json{{"ok", false}, {"reason", "invalid-mode"}});
            }
        }
        const bool brightnessApplied = rogAuraSetBrightness(brightness);
        return receipt(json{{"ok", effectApplied && brightnessApplied}, {"effectApplied", effectApplied},
                    {"brightnessApplied", brightnessApplied}, {"mode", mode}, {"backend", "rog-aura"}});
    });

    ipc_on("gamepad.vibrate", [](const json& a) -> json {
        const int strength = a.value("strength", 70);
        const int durationMs = a.value("durationMs", 125);
        const json result = nativeGamepadFeedbackPulse(strength, durationMs);
        // One manual IPC receipt for MSI, XInput and every early failure.
        // Actual pulse/stop mechanics and the response remain unchanged.
        json log = result;
        log["schema"] = 2;
        log["deviceClass"] = g_machineIdentity.deviceClass;
        log["family"] = ymccFamilyName(g_machineIdentity.family);
        log["requestedStrength"] = strength;
        log["requestedDurationMs"] = durationMs;
        log["physicalEffectVerified"] = false;
        log["proofScope"] = "request-and-backend-receipt";
        appendNativeLifecycleLog("gamepad-vibrate-request", log);
        return result;
    });
}

/**
 * R2（FAN-926R 唤醒租约与有界等待裁决 §4.4）：**严格白名单**的有限责任事件。
 *
 * 详细日志开关（g_fanLogEnabled）关闭时，唤醒等待这一类"谁在等、等到什么结果"的
 * 责任链不能整段消失。因此这几个事件名**免门**，并复用既有 `appendFanLifecycleLog`
 * 写入已纳入导出的 `fan-lifecycle.log`。白名单刻意极小：每个恢复等待任务只会有
 * started + 唯一终态各一条（低频），且调用方（fanDiagnostics.fanLifecycleEvidence）
 * 只投递非秘密字段。其余事件名一律**不**因本函数放行。
 */
static bool fanLifecycleEvidenceAlwaysLogged(const std::string& event) {
    if (event == "lifecycle.manual-wake-snapshot-adopted" ||
        event == "lifecycle.manual-wake-snapshot-rejected") return true;
#ifdef YMCC_FAN_LOG_TEST
    // E1b 变异反控（仅测试构建；默认 0 = 生产行为）：2 = 放宽白名单（任何事件都免门）。
    if (g_fanLogMutation == 2) return !event.empty();
#endif
    // R12 T-04/T-05：AI fan mock 的有限失败收据同样免门。事件低频（每次启动/请求至多一条），
    // details 仍经 projectFanLifecycleEvidence 有限投影（只带固定错误码 reason），因此详细
    // 日志默认关闭时"下一次失败"依然落盘可判读，而不是整段消失。其余事件名不因此放行。
    if (event == "ai.mock-start-failed" || event == "ai.mock-request-failed") return true;
    return event == "lifecycle.resume-wait-started"
        || event == "lifecycle.resume-wait-completed"
        || event == "lifecycle.resume-wait-cancelled"
        || event == "lifecycle.resume-wait-terminal-failed"
        || event == "lifecycle.resume-admission-accepting"
        || event == "lifecycle.resume-admission-rejected"
        || event == "lifecycle.resume-wait-queue-reentry"
        || event == "lifecycle.power-boundary-supersede"
        || event == "lifecycle.heartbeat-stale-success-ignored"
        || event == "lifecycle.heartbeat-stale-failure-ignored";
}

/**
 * E1b（FAN-926R 执行单 §6.1）：白名单事件的**有限字段投影**。
 *
 * 白名单只放行"事件名"，绝不能让任意 details 对象成为把秘密/超长/嵌套内容带进
 * 免门文件的通道。因此这里按固定字段表投影：只保留非秘密的 action/代际/次数/耗时/
 * 终态与短标签；字符串按上限截断；非标量（对象/数组/浮点）以 `<rejected>` 标记，
 * 其它键一律丢弃（不是"转存"）。未列入字段表的键即使值很小也不保留。
 */
static const char* const kFanLifecycleEvidenceFields[] = {
    "action", "event", "id", "reason", "detail", "state", "caller",
    "generation", "session", "deadlineMs", "probes", "elapsedMs", "intervalMs",
    "intentRevision", "currentGeneration", "currentIntentRevision",
    "ok", "retryable", "wakeContext",
};
static constexpr size_t kFanLifecycleEvidenceMaxString = 48;

static json projectFanLifecycleEvidence(const json& details) {
    json projected = json::object();
    if (!details.is_object()) return projected;
    for (const char* key : kFanLifecycleEvidenceFields) {
        const auto it = details.find(key);
        if (it == details.end()) continue;
        if (it->is_string()) {
            std::string value = it->get<std::string>();
            if (value.size() > kFanLifecycleEvidenceMaxString) value.resize(kFanLifecycleEvidenceMaxString);
            projected[key] = value;
        } else if (it->is_boolean() || it->is_number_integer()) {
            projected[key] = *it;
        } else {
            // 免门事件只携带有限非秘密标量；对象/数组/浮点一律显式拒绝，便于事后核对。
            projected[key] = "<rejected>";
        }
    }
    return projected;
}

static void writeFanDiagnosticLog(const std::string& event, const json& details) {
    if (!g_fanLogEnabled || g_fanLogFile.empty()) return;
    std::lock_guard<std::mutex> lock(g_fanLogMtx);
    auto parent = fspath::path(g_fanLogFile).parent_path();
    fspath::create_directories(parent);
    SYSTEMTIME st; GetLocalTime(&st);
    char ts[32];
    snprintf(ts, sizeof(ts), "%04d-%02d-%02dT%02d:%02d:%02d.%03d",
             st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
    json line = {
        {"time", ts},
        {"event", event},
        {"details", details.is_object() ? details : json::object()},
    };
    if (g_fanLogEnabled) rotateOneLogFile(g_fanLogFile);
    std::ofstream f(g_fanLogFile, std::ios::app);
    if (f) f << line.dump() << "\n";
}

// 统一详细门联动（2026-09-17 合并批）：详细开关同时驱动 fan 诊断文件与
// FanHost runtime flag（fan-logging-enabled.flag）。状态未变化时不重复写事件；
// flag 存在性始终与门控对齐（关时清理残留，启动时同样调用）。
static void fanDiagnosticsApplyEnabled(bool enabled) {
    g_fanLogFile = yemancc_data_dir() + L"\\fan-api.log";
    fspath::create_directories(fspath::path(g_fanLogFile).parent_path());
    const std::wstring hostLoggingFlag = fan_host_state_dir() + L"\\fan-logging-enabled.flag";
    if (enabled) {
        const bool was = g_fanLogEnabled.exchange(true, std::memory_order_acq_rel);
        {
            std::ofstream flag(hostLoggingFlag, std::ios::trunc);
            if (flag) flag << "enabled";
        }
        if (!fspath::exists(hostLoggingFlag)) {
            writeFanDiagnosticLog("logging-flag-write-failed", json{{"path", W2U(hostLoggingFlag)}});
        }
        if (!was) writeFanDiagnosticLog("logging-enabled", json::object());
    } else {
        if (g_fanLogEnabled.load(std::memory_order_acquire)) {
            writeFanDiagnosticLog("logging-disabled", json::object());
        }
        g_fanLogEnabled.store(false, std::memory_order_release);
        std::error_code flagEc;
        fspath::remove(hostLoggingFlag, flagEc);
        if (flagEc) {
            writeFanDiagnosticLog("logging-flag-remove-failed", json{
                {"path", W2U(hostLoggingFlag)}, {"error", flagEc.message()}});
        }
    }
}

static bool isCoordinatorDiagnosticEvent(const std::string& event) {
    return event.rfind("coordinator.", 0) == 0
        || event.rfind("lifecycle.", 0) == 0
        || event.rfind("api.", 0) == 0;
}

static void writeCoordinatorDiagnosticLog(const std::string& event, const json& details) {
    if (!g_fanLogEnabled || !isCoordinatorDiagnosticEvent(event)) return;
    const std::wstring path = yemancc_data_dir() + L"\\hardware-coordinator.log";
    std::lock_guard<std::mutex> lock(g_fanLogMtx);
    try {
        fspath::create_directories(fspath::path(path).parent_path());
        SYSTEMTIME st; GetLocalTime(&st);
        char ts[32];
        snprintf(ts, sizeof(ts), "%04d-%02d-%02dT%02d:%02d:%02d.%03d",
                 st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
        json line = {
            {"time", ts},
            {"event", event},
            {"details", details.is_object() ? details : json::object()},
            {"pid", GetCurrentProcessId()},
        };
        // 单文件 ≤5MB：旋转切分（保留 .1 旧档），避免重建去重队列覆盖首行时间。
        rotateOneLogFile(path);
        std::ifstream in(path, std::ios::binary);
        std::deque<std::string> lines;
        std::string existing;
        while (std::getline(in, existing)) {
            if (!existing.empty() && existing.back() == '\r') existing.pop_back();
            lines.push_back(std::move(existing));
            while (lines.size() > COORDINATOR_LOG_MAX_LINES - 1) lines.pop_front();
        }
        lines.push_back(line.dump());
        std::string bounded;
        for (auto it = lines.rbegin(); it != lines.rend(); ++it) {
            const size_t extra = it->size() + 1;
            if (bounded.size() + extra > COORDINATOR_LOG_MAX_BYTES) break;
            bounded.insert(0, *it + "\n");
        }
        std::ofstream out(path, std::ios::binary | std::ios::trunc);
        if (out) out.write(bounded.data(), static_cast<std::streamsize>(bounded.size()));
    } catch (...) {
        // Diagnostics must never block or change the hardware lifecycle.
    }
}

static void reg_log() {
    ipc_on("log.setFile", [](const json& a) -> json {
        std::lock_guard<std::mutex> logLock(g_logMtx);
        auto path = a.value("path", std::string{});
        if (path.empty()) {
            // Default to data/app.log
            g_logFile = app_data_dir() + L"\\app.log";
        } else {
            g_logFile = U2W(path);
        }
        // Ensure parent directory exists
        auto parent = fspath::path(g_logFile).parent_path();
        fspath::create_directories(parent);
        return W2U(g_logFile);
    });
    ipc_on("log.write", [](const json& a) -> json {
        auto level = a.value("level", std::string{"info"});
        auto msg   = a.value("message", std::string{});
        writeLog(level, msg);
        return true;
    });
    ipc_on("log.clear", [](const json&) -> json {
        std::lock_guard<std::mutex> logLock(g_logMtx);
        if (g_logFile.empty()) return false;
        std::ofstream f(g_logFile, std::ios::trunc);
        return f.good();
    });
    ipc_on("log.getPath", [](const json&) -> json {
        std::lock_guard<std::mutex> logLock(g_logMtx);
        return g_logFile.empty() ? nullptr : json(W2U(g_logFile));
    });
    // 统一详细门联动（2026-09-17 合并批）：详细开关同时驱动 fan 诊断文件与
    // FanHost runtime flag（fan-logging-enabled.flag）。状态未变化时不重复写
    // 事件；flag 存在性始终与门控对齐（关时清理残留，启动时同样调用）。
    // 裁决 H5（2026-09-19）：
    //   ① **缺少 enabled 键时不得默认覆盖为 false** —— 旧实现用
    //      a.value("enabled", false)，任何不带该键的调用都会把用户刚打开的日志关掉
    //      （双权威互相覆盖的根因之一，真机旁证 logging-enabled→0.45s→logging-disabled）。
    //      缺键 = 无意见 = 纯读回，零副作用。
    //   ② 显式给出布尔时同步**统一门**（g_domainLogEnabled + domainLogsSaveConfig），
    //      使统一详细门成为唯一权威，不再与 fan 设置各写一次互相覆盖。
    ipc_on("fanLog.setEnabled", [](const json& a) -> json {
        if (a.is_object() && a.contains("enabled") && a["enabled"].is_boolean()) {
            const bool enabled = a["enabled"].get<bool>();
            std::lock_guard<std::mutex> maintenanceLock(g_domainLogGateWriteMx);
            g_domainLogEnabled[0].store(enabled, std::memory_order_release);
            g_domainLogEnabled[1].store(enabled, std::memory_order_release);
            domainLogsSaveConfig();
            domainLogGateRecord("fanLog.setEnabled", enabled);
            // Same authoritative detailed gate as logs.domainSetEnabled. Do not
            // leave the sensor detail mirror or the InputHost cost flag stale.
            g_sensorDetailLogging.store(sensorDetailLoggingGate(), std::memory_order_release);
            fanDiagnosticsApplyEnabled(enabled);
            inputHostCostFlagSync();
        }
        return json{{"enabled", g_fanLogEnabled.load()}, {"path", W2U(g_fanLogFile)}};
    });
    ipc_on("fanLog.write", [](const json& a) -> json {
        const auto event = a.value("event", std::string{});
        if (event.empty()) return false;
        const auto details = a.value("details", json::object());
#ifdef YMCC_FAN_LOG_TEST
        // E1b 变异反控（仅测试构建；默认 0 = 生产行为）：1 = 免门分支被移回详细日志开关之后。
        if (g_fanLogMutation == 1 && !g_fanLogEnabled) {
            if (event.empty()) return false;
            writeFanDiagnosticLog(event, details);
            writeCoordinatorDiagnosticLog(event, details);
            return true;
        }
#endif
        // R2（§4.4）：白名单有限责任证据**免门**（严格按事件名匹配；不进 fan-api.log 的
        // 普通诊断面，也不放开任何其它事件）。投递失败由调用方 fire-and-forget 承担，
        // 绝不影响睡眠/退出路径。
        if (fanLifecycleEvidenceAlwaysLogged(event)) {
            // E1b（§6.1）：白名单只放行事件名；details 必须经**有限字段投影**，不得成为
            // 任意对象/秘密/超长内容的免门通道。
#ifdef YMCC_FAN_LOG_TEST
            // 变异反控（仅测试构建）：3 = 绕过字段投影（details 直传）。
            appendFanLifecycleLog(event.c_str(),
                g_fanLogMutation == 3 ? (details.is_object() ? details : json::object())
                                      : projectFanLifecycleEvidence(details));
#else
            appendFanLifecycleLog(event.c_str(), projectFanLifecycleEvidence(details));
#endif
            return true;
        }
        if (!g_fanLogEnabled) return false;
        writeFanDiagnosticLog(event, details);
        writeCoordinatorDiagnosticLog(event, details);
        return true;
    });
    ipc_on("fanLog.getPath", [](const json&) -> json {
        return json(W2U(g_fanLogFile.empty() ? yemancc_data_dir() + L"\\fan-api.log" : g_fanLogFile));
    });
    ipc_on("fanLog.clear", [](const json&) -> json {
        const std::wstring uiPath = g_fanLogFile.empty() ? yemancc_data_dir() + L"\\fan-api.log" : g_fanLogFile;
        const std::wstring hostPath = fan_host_state_dir() + L"\\logs\\yeman-fan-host-runtime.log";
        // 裁决 H5：免门故障账本同属风扇日志，清理必须一并处理（否则"清空日志"会
        // 留下上一轮卡死态的证据，用户看到的现场与导出内容不一致）。
        const std::wstring hostFaultPath = fan_host_state_dir() + L"\\logs\\fan-host-fault.log";
        const std::wstring coordinatorPath = yemancc_data_dir() + L"\\hardware-coordinator.log";
        bool ok = true;
        {
            std::lock_guard<std::mutex> lock(g_fanLogMtx);
            for (const auto& path : { uiPath, hostPath, hostFaultPath, coordinatorPath }) {
                std::error_code existsEc;
                if (!fspath::exists(path, existsEc)) continue;
                std::ofstream file(path, std::ios::trunc);
                if (!file.good()) ok = false;
            }
        }
        return json{{"ok", ok}, {"uiPath", W2U(uiPath)}, {"hostPath", W2U(hostPath)}};
    });
    ipc_on("fanLog.export", [](const json&) -> json {
        const std::wstring uiPath = g_fanLogFile.empty() ? yemancc_data_dir() + L"\\fan-api.log" : g_fanLogFile;
        const std::wstring hostPath = fan_host_state_dir() + L"\\logs\\yeman-fan-host-runtime.log";
        // 裁决 H5：免门故障账本（fan-host-fault.log）必须在导出清单里，否则"卡死态"
        // 证据无法随导出包送出来（导出器是显式文件清单，不做目录通配）。
        const std::wstring hostFaultPath = fan_host_state_dir() + L"\\logs\\fan-host-fault.log";
        const std::wstring coordinatorPath = yemancc_data_dir() + L"\\hardware-coordinator.log";
        std::vector<std::wstring> files;
        for (const auto& path : { uiPath, hostPath, hostFaultPath, coordinatorPath }) {
            std::error_code fileEc;
            if (fspath::is_regular_file(path, fileEc)) files.push_back(path);
        }
        if (files.empty()) return json{{"ok", false}, {"reason", "暂无风扇日志"}};
        // 日志源文件仍固定保存在 %LOCALAPPDATA%\\YeManCC；压缩包按用户操作
        // 约定导出到桌面，便于直接找到并发送给开发者。
        const std::wstring exportRoot = getKnownFolder(FOLDERID_Desktop);
        if (exportRoot.empty()) throw std::runtime_error("无法定位桌面目录");
        SYSTEMTIME now{};
        GetLocalTime(&now);
        wchar_t stamp[64]{};
        swprintf_s(stamp, L"%04u%02u%02u-%02u%02u%02u-%03u",
                   now.wYear, now.wMonth, now.wDay, now.wHour, now.wMinute,
                   now.wSecond, now.wMilliseconds);
        const std::wstring zipPath = exportRoot + L"\\YeMan-fan-logs-" + stamp + L".zip";
        const TarArchiveRetryResult packed = createTarArchiveWithRetry(zipPath, files);
        if (!packed.ok) {
            return json{{"ok", false},
                        {"reason", "archive-failed-after-2-attempts"},
                        {"attempts", packed.attempts},
                        {"lastError", packed.reason},
                        {"win32Error", packed.win32Error},
                        {"cleanupOk", packed.cleanupOk}};
        }
        json names = json::array();
        for (const auto& path : files) names.push_back(W2U(fspath::path(path).filename().wstring()));
        return json{{"ok", true}, {"path", W2U(zipPath)}, {"files", names},
                    {"attempts", packed.attempts}, {"cleanupOk", packed.cleanupOk}};
    });
}

