        auto updateSteamRoot = sofRegSZ(HKEY_CURRENT_USER, L"Software\\Valve\\Steam", L"SteamPath");
        if (updateSteamRoot.empty()) updateSteamRoot = sofRegSZ(HKEY_LOCAL_MACHINE, L"Software\\Valve\\Steam", L"SteamPath");
