            if (vdf.size() <= 1048576) for (const auto& entry : ymcc::steamdeck::libraryPaths(vdf)) {
                auto library = U2W(entry);
                if (updateLibraries.size() >= 64) break;
                if (fspath::path(library).is_absolute()) updateLibraries.push_back(library);
            }
