        std::string updateHookPathsLiteral = "@(";
        for (const auto& path : updateHookPaths) { if (updateHookPathsLiteral.size() > 2) updateHookPathsLiteral += ","; updateHookPathsLiteral += psLiteral(path); }
        updateHookPathsLiteral += ")";
