            f << "$ErrorActionPreference = 'Stop'\n";
            f << "$ownModules = Join-Path $PSHOME 'Modules'\n";
            f << "if ((($env:PSModulePath -split ';')[0]).TrimEnd('\\') -ine $ownModules.TrimEnd('\\')) { $env:PSModulePath = $ownModules + ';' + $env:PSModulePath }\n";
            f << ymcc::deckypackage::maintenanceScript() << "\n";
            f << ymcc::modulepackage::maintenanceScript() << "\n";
            f << ymcc::updaterecovery::script() << "\n";
            f << ymcc::hcruntime::script() << "\n";
            f << ymcc::updatehooks::script() << "\n";
            f << "$updateHookToolPaths = " << updateHookPathsLiteral << "\n";
            f << "$moduleLease = $null; $moduleTransaction = $null\n";
            f << "$deckyTransaction = $null\n";
            f << "$parentPid = " << GetCurrentProcessId() << "\n";
