            f << "$customSteamLibraryDir = " << psLiteral(customSteamLibraryDir) << "\n";
            f << "$customSteamLibraryManifest = Join-Path $customSteamLibrarySource 'package-manifest.json'\n";
            f << "$supportPath = " << psLiteral(supportPath) << "\n";
