// Fixed diagnostic state shared by every template instantiation; no resource ownership.
static bool monitorNoticeNativeLogAdmit(const json& projected,std::uint64_t now) {
 static constexpr const char* stages[]={"native-reserved","native-created","native-create-error","native-retired","native-retire-error","native-close","native-ready","native-closed","native-unavailable"};
 static constexpr std::size_t stageCount=sizeof(stages)/sizeof(stages[0]);
 const auto& stage=projected.at("stage").get_ref<const std::string&>();
 std::size_t slot=0;while(slot<stageCount&&stage!=stages[slot])++slot;
 if(slot==stageCount)return false;
 struct State {std::mutex mutex;json last[stageCount];bool known[stageCount]{};ymcc::noticelog::Budget budget;};
 static State state;
 // This lock is released before the native log writer takes its own lock.
 std::lock_guard<std::mutex> guard(state.mutex);
 if(state.known[slot]&&state.last[slot]==projected)return false;
 if(!state.budget.admit(now))return false; // Existing 256/1000ms diagnostic cap; no timer.
 state.last[slot]=projected;state.known[slot]=true;return true;
}
template <typename BuildFields>
static void monitorNoticeNativeLog(const char* stage,BuildFields buildFields) noexcept {
 try{auto fields=buildFields();fields["stage"]=stage;auto safe=ymcc::noticelog::project(fields);if(safe.is_null())return;
  if(!monitorNoticeNativeLogAdmit(safe,GetTickCount64()))return;
  safe["origin"]="native-receipt";appendNativeLifecycleLog("monitor-notice-native",std::move(safe));
 }catch(...){/* Diagnostics cannot change resource ownership. */}
}
