        if (a.value("update",false) && g_monitorHudPulseNonce!=nonce)return false;
        if (!a.value("enabled",false)) {
            if(g_monitorHudPulseNonce!=nonce)return false;
            KillTimer(g_hwnd,MONITOR_HUD_PULSE_TIMER_ID);g_monitorHudPulseNonce.clear();g_monitorFastFrames.store(false,std::memory_order_release);return true;
        }
