    case WM_ROG_HIDE_ENSURE:
        // The window is already visually hidden. Keep the HID restore on the
        // UI thread for serialization with the existing ROG session, but do
        // it as a follow-up message so it cannot delay the hide itself.
        if (!g_exitRequested.load(std::memory_order_acquire))
            rogEnsureXboxFaceEnabled("window-hidden");
        return 0;
    case WM_SYSCOMMAND:
        if ((w & 0xFFF0) == SC_MAXIMIZE) {
            focusReflowMainWindow();
            scheduleTaskbarLayoutRecheck();
        } else if ((w & 0xFFF0) == SC_MINIMIZE || (w & 0xFFF0) == SC_RESTORE) {
            cancelTaskbarLayoutRecheck();
        }
        // 拦截最小化：工具窗口(WS_EX_TOOLWINDOW)最小化后 DWM 会残留一个缩略图黑块
        // （用户实测「最小化才会出现黑块」）。改为直接隐藏到托盘，不真正最小化。
        if ((w & 0xFFF0) == SC_MINIMIZE && !g_taskbarResident) {
            hideWindowAnimated(h);
            return 0;
        }
        // 任务栏常驻时保留 Windows 原生最小化状态，确保任务栏按钮和
        // HWND 状态一致；非常驻模式才隐藏到托盘。
        break;
