        if (g_webviewRenderReadyGeneration == g_webviewGeneration.load(std::memory_order_acquire) &&
            g_webviewRenderReadyNavigationId == g_webviewNavigationId)
            finalizeWebViewRenderReady(g_webviewRenderReadyGeneration, g_webviewRenderReadyNavigationId,
                                      "input-startup-settled");
        return 0;
